local _, ns = ...

ns.battlePets = {
    ["\"Beware the cool breeze, for it brings trickery.\" - pandaren proverb"] = "«Стережися прохолодного вітерцю, бо він несе підступ.» — пандаренське прислів'я",
    ["\"In this house we don't lay spores in people's ears when they sleep, no matter how funny their face is when they wake up.\""] = "«У цьому домі ми не закладаємо людям спори у вуха, поки вони сплять, хоч би яке кумедне було їхнє обличчя, коли вони прокидаються.»",
    ["\"Little Bo Peep has lost her sheep, and doesn't know where to find them. Leave them alone, and they'll come OH MY GOD THEY'RE INSIDE THE HOUSE!\""] = "«Загубила пастушка овечок своїх і не знає, де їх шукати. Облиш їх — самі прийдуть, ой ЛИШЕНЬКО, ВОНИ ВЖЕ В ХАТІ!»",
    ["'I am Justice itself!'"] = "«Я — сама Справедливість!»",
    ["'The queen had three kittens. The first gave her a juicy rat. The second, a tasty hare. And the white, her favorite, presented the head of her rival.'"] = "«У королеви було троє кошенят. Перше принесло їй соковитого щура. Друге — смачного зайця. А біле, її улюблене, піднесло їй голову суперниці».",
    ["A Darkmoon balloon made to look like a horse."] = "Кулька з ярмарку Даркмун у подобі коня.",
    ["A Darkmoon balloon made to look like a murloc."] = "Кулька з ярмарку Даркмун у подобі мурлока.",
    ["A Darkmoon balloon made to look like a wolf."] = "Кулька з ярмарку Даркмун у подобі вовка.",
    ["A Stormrider's stormrook can not only navigate extreme winds with grace but can also conjure fierce tempests to defend themselves."] = "Буревісник вершника бур не лише граційно долає шалені вітри, а й здатен викликати люті шторми, щоб захиститися.",
    ["A baby octopode is technically referred to as a \"squish.\""] = "Малятко-восьминога науково називають «чавкунчиком».",
    ["A baby version of the mighty Thundering Cloud Serpent that hails from the far lands of Pandaria."] = "Дитинча могутнього Громового Хмарного Змія, що походить із далеких земель Пандарії.",
    ["A beautiful kite brought to life by the scribes of Pandaria."] = "Прекрасний повітряний змій, оживлений писарями Пандарії.",
    ["A brash fel orc once tried to enslave these critters as his personal soldiers. Pieces of him are still scattered across Outland."] = "Один зухвалий сквернотворний орк колись намагався поневолити цих створінь як своїх особистих воїнів. Шматки його досі розкидані по всьому Аутленду.",
    ["A brilliant executive assistant and apprentice, Lord Basilton also loves to stick his nose into piles of anything interesting."] = "Блискучий помічник і учень, лорд Базілтон також полюбляє стромляти носа в купи всього цікавого.",
    ["A brown dream badger is a rare sight. Not so rare a smell though."] = "Бурий сновидний борсук — рідкісне видовище. Хоча не такий уже й рідкісний запах.",
    ["A bug? Wait a minute, no, it's a small friendly spider!"] = "Жук? Стривай-но, ні, це маленький дружній павучок!",
    ["A candle inside of the kite heats the air, causing it to rise into the air without the need for wind."] = "Свічка всередині повітряного змія нагріває повітря, тож він злітає вгору без потреби у вітрі.",
    ["A carrot, a box, a stick, and some string. Wait a few hours and you'll have a hare."] = "Морквина, скринька, паличка і трохи мотузки. Зачекай кілька годин — і матимеш зайця.",
    ["A child of phoenix god Al'ar, the hatchling takes flight immediately after birth."] = "Дитинча бога-фенікса Ал'ара здіймається в небо одразу після народження.",
    ["A chip off the ol' girl's block. Azeriti is fiercely protective and will strike out against anyone wishing to do her mother harm."] = "Викапана матуся. Азеріті люто оберігає її й накинеться на будь-кого, хто захоче скривдити її матір.",
    ["A clear indication why goblin fertilizers should be used sparingly."] = "Наочне свідчення того, чому ґоблінські добрива слід застосовувати помірно.",
    ["A clever tactician, Whiskers will feign death to fool predators and bill collectors."] = "Хитрий тактик, Вусик прикинеться мертвим, щоб обдурити хижаків і збирачів боргів.",
    ["A complex system of burrows protects the prairie dog from its neighbors' massive hooves."] = "Складна система нір захищає лучного собачку від велетенських копит його сусідів.",
    ["A cousin to the Twilight Beetle, this insect has learned to feed on crystals which resonate with ancient energies."] = "Родич сутінкового жука, ця комаха навчилася живитися кристалами, що резонують зі стародавніми енергіями.",
    ["A creature prized by rogues for its venom. Many lived in the many holes and warrens of the Drag, but after the fall these new horrors emerged to menace the survivors."] = "Створіння, яке розбійники цінують за отруту. Багато їх жило в численних норах і лабіринтах Закутка, та після падіння ці нові жахіття вибралися назовні, щоб загрожувати тим, хто вцілів.",
    ["A curious species found only within treasure chests. Harmless enough, unless you happen to be wearing jewelry."] = "Дивний вид, що трапляється лише в скринях зі скарбами. Доволі безпечний, хіба що на тобі надіті прикраси.",
    ["A daring, narcissist insect willing to brave any threat in its pursuit of the spotlight."] = "Зухвала, самозакохана комаха, готова кинути виклик будь-якій загрозі в гонитві за увагою.",
    ["A desert dwelling forager attracted to areas rich with dung."] = "Пустельний збирач, якого вабить до місць, багатих на гній.",
    ["A desert-dwelling insect which defends its eggs by spraying a foul, ogrelike scent."] = "Пустельна комаха, що боронить свої яйця, бризкаючи мерзенним, схожим на оґрячий, смородом.",
    ["A domesticated species, it is quite calm and seems hungry."] = "Одомашнений вид — доволі спокійний і, схоже, голодний.",
    ["A drakonid hatchling is a curious sight, but now is the time for curious things."] = "Дитинча драконіда — дивовижне видовище, та зараз саме час для дивовиж.",
    ["A dream of the memory of fire."] = "Сон про спогад вогню.",
    ["A favored companion of Kirin Tor magi, this reptile makes one wonder whether it's truly a snake or something else altogether."] = "Улюблений супутник магів Кірін-Тор, ця рептилія змушує замислитися: чи це справді змія, чи щось зовсім інше.",
    ["A favorite of children across Azeroth, this tough little toy can withstand even the most aggressive imagination."] = "Улюбленець дітей по всьому Азероту, ця міцна іграшечка витримає навіть найбуйнішу уяву.",
    ["A favorite pet of some poor soul from before the fall of K'aresh, found trapped in stasis."] = "Улюбленець якоїсь бідолашної душі ще до падіння К'арешу, знайдений у пастці стазису.",
    ["A fel-tainted tome whose secrets are so terrible and bizarre that its pages have taken on an eerie semblance of life. Found on many a warlock's nightstand."] = "Зурочений Скверною фоліант, чиї таємниці такі жахливі й химерні, що його сторінки набули моторошної подоби живих. Лежить на тумбочці не одного чорнокнижника.",
    ["A felbat's fire never burns its master."] = "Вогонь сквернокажана ніколи не обпікає свого господаря.",
    ["A fellow message courier to Chip, Dal was always on time until one day when he did not return from his appointed round."] = "Дал, гонець-кур'єр, товариш Чіпа, завжди був пунктуальним — аж до того дня, коли не повернувся зі свого визначеного обходу.",
    ["A fighting robot fueled by delicious red or blue electrolytes."] = "Бойовий робот, що живиться смачними червоними чи синіми електролітами.",
    ["A fragment of the great abyssal Supremus, Abyssius contains enough fiery essence to burn a hole right through your pocket."] = "Уламок великого безодняка Супремуса, Абіссій містить досить вогняної сутності, щоб пропалити дірку просто в твоїй кишені.",
    ["A full-sized stormrook's thunder can be heard for miles. The chirps of this small spark sound like a faulty electrical device."] = "Грім повнорозмірного буревісника чути за милі. Цвірінькання цієї маленької іскри звучить, як несправний електроприлад.",
    ["A fully grown Fangtooth has a bite strong enough to go right through a platinum fishing pole. Watch your fingers."] = "Доросле Іклозубе кусає так сильно, що перегризає платинову вудку наскрізь. Бережіть пальці.",
    ["A gift from the Wildhammer dwarves to the heroes of the Alliance, these hatchlings are descendants of the same gryphons ridden by Falstad and his entourage into Grim Batol."] = "Подарунок дворфів Дикого Молота героям Альянсу, ці малята — нащадки тих самих грифонів, на яких Фалстад зі своїм почтом увірвалися до Ґрім Батолу.",
    ["A gift, found one day and saved for a meaningful occasion, should things ever turn around."] = "Дарунок, знайдений колись і збережений до значущої нагоди, якщо все колись зміниться на краще.",
    ["A glimmerfly can load up nearly fifty percent of its weight as pollen and still retain full agility while flying."] = "Мерехтокрилець здатний нести майже половину власної ваги пилку й зберігати при цьому повну спритність у польоті.",
    ["A gnashing maw of teeth and tongues. This beast bears an uncanny resemblance to Azerothian leeches."] = "Скрегочуча паща з зубів і язиків. Ця тварюка моторошно схожа на азеротських п'явок.",
    ["A goblin alchemist once claimed that the bite of this raccoon gave him the gift of prophecy. Turns out, it was just rabies."] = "Один гоблін-алхімік колись стверджував, що укус цього єнота дарував йому дар пророцтва. Виявилося, це був просто сказ.",
    ["A good friend to Archivist Fane since his earliest days, Janeera is ready for him to let the quill go as she feels he is getting too attached."] = "Джаніра, добра подруга архіваріуса Фейна від самих його початків, хоче, щоб він уже відпустив це перо, бо відчуває, що він надто до нього прив'язується.",
    ["A graceful creature from the isle of Pandaria."] = "Граційне створіння з острова Пандарія.",
    ["A group of teroclaws is known as a fleece."] = "Зграю тероклігтів називають «руном».",
    ["A hardy insect that can dwell in just about any climate, the beetle is known to thrive on battlefields after the fighting has ended."] = "Витривала комаха, що живе майже за будь-якого клімату; жук відомий тим, що буяє на полях битв після того, як бій ущух.",
    ["A key food source during the Feast of Winter Veil."] = "Одне з головних джерел їжі під час Свята Зимової Завіси.",
    ["A lasher by any other name would smell as sweet."] = "Хльосткач під будь-яким іншим іменем пахнув би так само солодко.",
    ["A legendary member of the blue dragonflight."] = "Легендарний представник синьої драконячої зграї.",
    ["A lifetime of servitude to Anub'arak, then the Lich King, and now... you!"] = "Ціле життя служіння Ануб'араку, потім Королю-Лічу, а тепер... вам!",
    ["A lingering remnant of Fryakk's attempt at corrupting Amirdrassil."] = "Уцілілий залишок спроби Фіракка зіпсувати Амірдрассіл.",
    ["A little ambystan that was too big, then too little, and finally just right. He followed you home!"] = "Маленький амбістан, що був завеликий, тоді замалий, а зрештою якраз. Він пішов за тобою додому!",
    ["A living anomaly and Kasreth's most treasured experiment, this pink-furred creature scampers joyfully through conduits and pipes."] = "Жива аномалія й найцінніший дослід Касрета, ця рожевохута істота радісно гасає трубами й каналами.",
    ["A living piece of Arathi's most infamous stone-faced behemoth, Fozruk."] = "Живий уламок найзловіснішого кам'янолицього велетня Араті — Фозрука.",
    ["A lone Ancient of Lore in Darnassus managed to save this Treant in its final actions with a magical aura to prevent the flames from burning it any further."] = "Самотній Прадавень Знань у Дарнасі своїми останніми діями зумів урятувати цього Древня, оповивши його магічною аурою, що не дала полум'ю спалити його остаточно.",
    ["A magical friend created with equal parts adventure and spirit."] = "Магічний друг, створений рівними частинами з пригоди й завзяття.",
    ["A magical wisdom-filled head in a ball bearing Khadgar's visage, it can only answer questions with a few phrases."] = "Сповнена магічної мудрості голова в кулі з лицем Кадґара, яка може відповідати на питання лише кількома фразами.",
    ["A magical wonder, these balloons will never deflate and are traditionally created in batches of ninety-nine."] = "Чарівне диво: ці кульки ніколи не здуваються, і традиційно їх роблять партіями по дев'яносто дев'ять.",
    ["A magically infused emerald sits at the heart of this creature."] = "У серці цієї істоти лежить просякнутий магією смарагд.",
    ["A master of distractions, Brrrgl can steal your heart with a dance, a fish or some friends."] = "Майстер відволікань, Бррргл може вкрасти твоє серце танцем, рибиною чи кількома друзями.",
    ["A master sculptor devoted her life to creating an incomparably beautiful statue, inspired by her love and reverence for Yu'lon.  When the sculptor passed away, Yu'lon breathed a fraction of her essence into the statue, bringing Yu'la into the world."] = "Майстриня-скульпторка присвятила своє життя створенню незрівнянно прекрасної статуї, надихнута любов'ю та шанобою до Ю'лон. Коли скульпторка померла, Ю'лон вдихнула частку своєї сутності в статую, привівши Ю'ла у світ.",
    ["A mastiff bred for rescue, the Alterac brewhound's bloodline is famous for having found and resuscitated many mountain travelers trapped beneath the snow... and then slobbering all over them."] = "Мастиф, виведений для порятунку; рід альтеракського хмільного пса славиться тим, що знаходив і повертав до життя багатьох гірських мандрівників, замети під снігом... а потім обслинював їх із голови до ніг.",
    ["A mechanical squirrel's logic center tells it to collect and store both nuts and bolts for the winter."] = "Логічний центр механічної білки наказує їй збирати й запасати на зиму і горіхи, і гайки.",
    ["A minion of Terestian Illhoof, this tricky imp was left in Karazhan when the portal to the Twisting Nether closed behind it."] = "Поплічник Терестіана Хворокопита, цей хитрий чортик лишився в Каражані, коли портал до Викривленої Порожнечі зачинився за ним.",
    ["A minor diety of wind, lording over the tiny breezes that make you think the heat of the summer season will be bearable for a brief moment."] = "Дрібне божество вітру, що владарює над легенькими повівами, які на коротку мить дарують відчуття, ніби літня спека стане стерпною.",
    ["A newborn bonetusk has no visible tusks, but within weeks their tusks grow to a size proportional to their body."] = "Новонароджений кісткоіклий не має видимих іклів, але за кілька тижнів вони відростають до розміру, пропорційного його тілу.",
    ["A newly hatched Cobra can be just as deadly as a fully grown one, if not more."] = "Щойно вилуплена кобра може бути не менш смертоносною за дорослу, а то й більше.",
    ["A nuisance to most, roaches' incredible survivability sets them apart from other species."] = "Прикрість для більшості, неймовірна живучість тарганів вирізняє їх з-поміж інших видів.",
    ["A parasite that latches onto some of the larger beasts of Maldraxxus and drinks until fully-grown, one wonders how the beasts don't manage to notice."] = "Цей паразит присмоктується до більших звірів Малдраксуса й живиться, доки не виросте остаточно. Лишається тільки дивуватися, як звірі цього не помічають.",
    ["A playful splash from this otter will give you quite a shock."] = "Грайливий сплеск цієї видри добряче вас шокує.",
    ["A playful, purring pyromaniac. Don't pet these kittens without fireproof mittens!"] = "Грайливий муркотливий палій. Не гладьте цих кошенят без вогнетривких рукавиць!",
    ["A popular pet among children, despite frequent accidental gorings."] = "Улюбленець серед дітей, попри часті випадкові настромлювання на роги.",
    ["A product of exposure to wild magical energies, this insect is the unexpectedly colorful result of Azerothian moth species being released into the eco-domes of the Netherstorm."] = "Породження впливу дикої магічної енергії, ця комаха — несподівано барвистий наслідок того, що азеротські види метеликів випустили в екокуполи Нетерсторму.",
    ["A proud supporter of the Horde, this tiny murloc left his clutch to seek out blue-clad foes to slay."] = "Гордий прибічник Орди, цей крихітний мурлок покинув свою кладку, щоб вистежувати й убивати вбраних у синє ворогів.",
    ["A pup of Thrall's frostwolf, Snowsong, besting her in combat has earned you a lifelong companion."] = "Цуценя морозововчиці Тралла, Сніжного Співу. Здолавши її в бою, ти здобув супутника на все життя.",
    ["A quite annoying species. No matter how high you build your walls, these creatures still manage to hop over."] = "Доволі набридливий вид. Хоч би яку високу стіну ти збудував, ці створіння однаково примудряються її перестрибнути.",
    ["A rare auspicious beast in Pandaria. Well-traveled hozen call it a \"mobile luck amplifier.\""] = "Рідкісна сприятлива звірина в Пандарії. Бувалі гозени звуть її «переносним підсилювачем удачі».",
    ["A rare black-furred Eversong lynx kitten, its fur faintly thrumming with arcane energy, bred by Silvermoon's Magisters as both companion and conduit of magical study."] = "Рідкісне чорнохуте рисеня з Вічної Пісні, чиє хутро ледь бринить тайною енергією, виведене магістрами Сільвермуна і як супутник, і як провідник магічних досліджень.",
    ["A rare evolution of chitterspine, with elongated spines to pierce soft flesh and eyes."] = "Рідкісний різновид скрипоголки з видовженими голками, щоб протинати м'яку плоть і очі.",
    ["A rare mutation gives this dredbat its green, ghastly glow making it a sought after gift for pet collectors with eclectic tastes."] = "Рідкісна мутація дарує цьому жахокажану зелене моторошне сяйво, роблячи його жаданим подарунком для збирачів улюбленців з вибагливим смаком.",
    ["A rare mutation gives this dredbat its violet underbelly, making it a sought after gift for pet collectors with eclectic tastes."] = "Рідкісна мутація надала цьому жахокажану фіолетового черевця, через що він стає бажаним подарунком для колекціонерів улюбленців з вишуканим смаком.",
    ["A rare snooter, and hard to find, it's known for burrowing itself deep under wet foliage to nest."] = "Рідкісний нюхаль, якого важко знайти, відомий тим, що зариваєтся глибоко під вологе листя, щоб звити гніздо.",
    ["A rare species of crab found mostly in Nazjatar, it hides easily amongst the ample kelp and coral of the area."] = "Рідкісний вид краба, що трапляється здебільшого в Назджатарі, легко ховається серед буйних водоростей і коралів цих місць.",
    ["A rarely seen family of tigers, many believe (perhaps incorrectly) that some residual magic or other event is responsible for the unique color."] = "Рідкісна родина тигрів; багато хто вважає (можливо, хибно), що за їхній унікальний колір відповідає якась залишкова магія чи інша подія.",
    ["A rarely-seen cinderweb species known for devouring her mate's legs and laying eggs in his still-twitching body, and a lovely purple color."] = "Рідкісний вид жаротканих павуків, відомий тим, що самиця пожирає ноги свого партнера й відкладає яйця в його ще тремтячому тілі, а також своїм гарним фіолетовим забарвленням.",
    ["A rarity among arachnids, these non-venomous critters feed solely on plants and fruit."] = "Рідкість серед павукоподібних — ці неотруйні створіння живляться виключно рослинами та плодами.",
    ["A re-emergence of whelps outside of Grim Batol has the red dragonflight worried -- something is happening in the lost city."] = "Повторна поява дракончиків попід Ґрім Батолом непокоїть червона зграя драконів — щось коїться в загубленому місті.",
    ["A recent debate has risen up about whether Void-Scarred rats are better or worse than plagued rats."] = "Останнім часом точиться суперечка: чи кращі позначені Порожнечею щури за чумних, а чи гірші.",
    ["A recent excavation on Zuldazar obliterated the natural habitat of these creatures and sent them spilling into the wilds."] = "Нещодавні розкопки в Зулдазарі знищили природне середовище цих створінь і вигнали їх у дику природу.",
    ["A robotic frog might seem useless, but once you're attacked by a swarm of mechanical flies, you'll be wishing you had one."] = "Робот-жаба може здатися марним, але щойно на тебе нападе рій механічних мух, ти захочеш такого мати.",
    ["A rodent of usual size."] = "Гризун звичайного розміру.",
    ["A roiling memory drawn to you from the Rift of Aln."] = "Бурхливий спогад, притягнутий до тебе з Розколу Алн.",
    ["A rolling, explosive member of the Zerg swarm, the baneling deals terrible, terrible damage. Very dangerous in close quarters."] = "Котючий, вибуховий представник рою зергів, чумоносець завдає страшної, страшної шкоди. Дуже небезпечний у ближньому бою.",
    ["A runt of the Black Talon, left to guard the whelps."] = "Заморух Чорного Пазура, лишений стерегти дитинчат.",
    ["A ruthless tormenter of the smallest souls. Some say he was known in life as \"Thermaplugg.\""] = "Безжальний мучитель найдрібніших душ. Дехто каже, що за життя він був відомий як «Термаплаґ».",
    ["A shard of a fragment of a piece of a sliver of a piece of crystal, but walking around like it owns the place. Good thing it likes you."] = "Скалка фрагмента шматочка скіпки кристала, але походжає так, наче воно тут господар. Добре, що ти йому подобаєшся.",
    ["A shimmering creature made of pure arcane energy, it is hard to focus your eyes directly on it."] = "Мерехтливе створіння з чистої таємної енергії — важко зосередити погляд просто на ньому.",
    ["A shy creature, the pink elekk will only make its presence known to those that have befriended it, or to anyone too intoxicated to harm it."] = "Сором'язлива істота, рожевий елек виявить свою присутність лише тим, хто з ним заприятелював, або тому, хто надто захмелів, аби завдати йому шкоди.",
    ["A single peacock feather is often laid upon a grave to ward off evil spirits."] = "Одну павичеву пір'їну часто кладуть на могилу, щоб відганяти злих духів.",
    ["A small amount of Cyrukh burns everlasting within this portion of the Cipher. Best keep it close to you."] = "Дещиця Цайрука вічно палає в цьому уривку Шифру. Краще тримати його при собі.",
    ["A small fraction of the titans' power, an even smaller fraction of their size."] = "Дрібка могутності титанів і ще дрібніша частка їхнього зросту.",
    ["A small fragment of Lord Marrowgar, it will NOT stop assaulting your shins."] = "Маленький уламок Лорда Мерехтокоста, який НЕ припиняє товктися об твої гомілки.",
    ["A small remnant of the power of Y'shaarj that spawned the Sha, a single Drop of Y'shaarj can magnify emotional states for thousands of yards, causing entire towns to shut down in fear or doubt."] = "Невеликий залишок сили Й'шаараджа, що породив Ша; єдина крапля Й'шаараджа здатна підсилювати емоції на тисячі ярдів навколо, змушуючи цілі містечка завмирати від страху чи сумніву.",
    ["A small, fierce member of the Zerg swarm, the zergling is not to be trifled with. Very dangerous in high numbers."] = "Маленький, але лютий член рою Зерґів, зерґлінг — це не той, з ким варто жартувати. Дуже небезпечний у великій кількості.",
    ["A smaller gargoyle that is used to divert the flow of rainwater on scourge buildings to prevent mausoleum flooding."] = "Менша ґаргулья, якою відводять стік дощової води з будівель Покари, щоб не затоплювало мавзолеї.",
    ["A solemn reminder of what was lost when the Worldbreaker changed the face of Azeroth."] = "Скорботне нагадування про те, що було втрачено, коли Світоруйнівник змінив обличчя Азероту.",
    ["A soul burdened with the sins of its past."] = "Душа, обтяжена гріхами свого минулого.",
    ["A soul, having faced the sins of the past, wanders lost in the recent turmoil of the Shadowlands."] = "Душа, що зустрілася віч-на-віч з гріхами минулого, блукає, загублена серед недавнього сум'яття Тіньокраю.",
    ["A spark can become an ember. An ember can become a raging fire. This creature was never a spark or an ember, it has only ever been a raging fire."] = "Іскра може стати жариною. Жарина може стати буйним вогнем. Це створіння ніколи не було ні іскрою, ні жариною — воно завжди було лише буйним вогнем.",
    ["A species of wild pest that exists within the Maw, no one is quite sure what it eats or why it exists, but they can't get rid of it."] = "Дикий вид шкідника, що живе в Пащі. Ніхто до пуття не знає, що воно їсть і навіщо існує, але позбутися його не виходить.",
    ["A spore from Zangarra, a central area of the Zangar encroachment that would later bloom into the Zangarmarsh."] = "Спора із Занґарри — осердя наступу Занґару, що згодом розквітне в Занґарські Драговини.",
    ["A spore plucked from the Crimson Fen, an area of Gorgrond that was swallowed when Draenor was torn apart by nether magics."] = "Спора, зірвана в Багряному Багні — місцині Ґорґронду, що її поглинуло, коли магія порожнечі роздерла Дренор.",
    ["A stowaway from Greatfather Winter's workshop, this tiny elemental found himself trapped in a present that was stolen by the Abominable Greench."] = "Заєць із майстерні Великого Батечка Зими, цей крихітний елементаль опинився в пастці подарунка, який викрав Жахливий Бурчун.",
    ["A strange whelp hatched on Netherwing Ledge, it is thought to be blessed by the waning lunar energies of Shadowmoon Valley."] = "Дивне дитинча, що вилупилося на Виступі Драконів Пустки. Кажуть, його благословили спадні місячні енергії Долини Тіньового Місяця.",
    ["A tallstrider's speed on open ground is unrivaled, so predators rely on stealth and pack tactics when hunting them."] = "Швидкість довгонога на відкритій місцевості незрівнянна, тож хижаки під час полювання покладаються на скрадання та зграйну тактику.",
    ["A terror in life. A terror in death."] = "Жах за життя. Жах і по смерті.",
    ["A terror so terrible, you're amazed it could ever be real."] = "Жах настільки жахливий, що ти дивуєшся, як таке взагалі може існувати.",
    ["A timbertooth with lighting inside? Shocking!"] = "Деревозуб з блискавкою всередині? Шокує!",
    ["A tiny admirer of the Alliance, this courageous murloc made his own sword and shield to slay red-clad foes."] = "Крихітний прихильник Альянсу, цей відважний мурлок сам зробив собі меч і щит, щоб убивати вбраних у червоне ворогів.",
    ["A tiny sun seems to burn in its chest."] = "Здається, у його грудях палає крихітне сонце.",
    ["A toad with Krag'wa's bloodline has an average expectancy to leap over seven million times during its lifetime."] = "Жаба з роду Краґ'ви за своє життя в середньому здатна стрибнути понад сім мільйонів разів.",
    ["A troublesome mage named McGwire decided to start a small fire. He summoned a flame which caused him to exclaim: 'This is much more alive than required!'"] = "Клопіткий маг на ім'я Макгвайр вирішив розпалити невелике багаття. Він прикликав полум'я, від чого вигукнув: «Воно куди живіше, ніж потрібно!»",
    ["A true Abyss Angler, certified by Depthdiver Jeju himself."] = "Справжній рибалка Безодні, засвідчений самим Глибонурцем Джеджу.",
    ["A very friendly cosmic being. Direct eye contact will obliterate your soul."] = "Дуже привітна космічна істота. Прямий зоровий контакт знищить твою душу.",
    ["A very rare bird, but this one was intrusted to you."] = "Дуже рідкісний птах, але цього доручили саме тобі.",
    ["A wag of their tail always brings a smile to your face, like clockwork."] = "Помах їхнього хвоста завжди викликає усмішку на твоєму обличчі, як за годинником.",
    ["A walking vault that throws its money at you is not a very secure vault to own."] = "Ходяче сховище, що жбурляє в тебе своїми грішми, — не надто надійне сховище.",
    ["A wandering adventurer saved a small band of murlocs that had lost their homes, and a glimmer of hope was born."] = "Мандрівний шукач пригод урятував невеличку ватагу мурлоків, що втратили домівки, — і так зародився проблиск надії.",
    ["A war-obsessed world turned her into a weapon... but they couldn't break her spirit."] = "Одержимий війною світ перетворив її на зброю... та зламати її дух вони не змогли.",
    ["A warlock won this little guy at an infernal carnival, but it quickly outgrew its aquarium."] = "Чорнокнижник виграв цього малюка на пекельному карнавалі, але той швидко переріс свій акваріум.",
    ["A wealthy pirate captain met with a strange man on the docks of an unknown city and bartered for everlasting life for his faithful companion. As with most monkey-related wishes, something went wrong."] = "Заможний капітан-пірат зустрів дивного чоловіка на пристані невідомого міста й виторгував вічне життя для свого вірного супутника. Як і з більшістю бажань, пов'язаних із мавпами, щось пішло не так.",
    ["A wild dredbat, the crimson pups are tough to tame. Their elusiveness and hardiness set them apart from their kin."] = "Дикий жахокажан; його багряних малят важко приручити. Невловність і витривалість вирізняють їх з-поміж родичів.",
    ["A wyrmlings temperment hinges primarily on how long its been since its fed on mana. Remember to feed your pets."] = "Норов драконеняти залежить передусім від того, скільки минуло, відколи воно живилося маною. Не забувай годувати своїх улюбленців.",
    ["A young animite will rapidly grow if fed in excess. It is suggested that no more than one average soul's worth of anima be consumed per year to keep them docile."] = "Молодий аніміт швидко росте, якщо його перегодовувати. Радять давати йому не більше аніми, ніж є в одній пересічній душі на рік, щоб лишався сумирним.",
    ["A young companion in need of training."] = "Юний супутник, що потребує вишколу.",
    ["A young grovecrawler that has been lovingly cared for by the Hara'ti."] = "Молодий гайоповз, про якого з любов'ю піклувалися хара'ті.",
    ["AND THE HEAVENS SHALL TREMBLE, AND MAN SHALL WEEP, AND THE END OF DAYS SHALL--wait, why are you so tall?"] = "І ЗАДРИЖАТЬ НЕБЕСА, І ЗАРИДАЄ ЛЮДСТВО, І НАСТАНЕ КІНЕЦЬ ЧАСІВ... стривай, чому ти такий високий?",
    ["Abandoned by its master in a secluded room, the little bat has been hibernating in stone for ages."] = "Покинутий господарем у відлюдній кімнаті, маленький кажан уже цілі віки спить у камені.",
    ["Above the vast green plains and rolling hills the slyvern fly, leaving only tiny shadows on the ground to mark their path through the sky."] = "Над безкраїми зеленими рівнинами та пагорбами линуть слайверни, лишаючи на землі крихітні тіні — єдиний слід їхнього шляху небесами.",
    ["Absolutely do not let him bite your bones."] = "У жодному разі не дозволяй йому гризти твої кістки.",
    ["Accidentally created when the Lich King's deathly powers raised Rimefang from undeath."] = "Створений випадково, коли смертоносна сила Короля-Ліча підняла Льодоікла з небуття нежиті.",
    ["According to Tol'vir beliefs, a crocolisk nest that hatches during the Festival of the Sun is said to be blessed by the river guardian, Sa'bak."] = "За віруваннями тол'вірів, гніздо кроколіска, що вилуплюється під час Свята Сонця, благословенне річковим вартовим Са'баком.",
    ["According to the tales of the night elves, the first red-tailed chipmunk was colored so after the theft and consumption of a sacred apple."] = "За переказами нічних ельфів, перший червонохвостий бурундук набув такого забарвлення після того, як украв і з'їв священне яблуко.",
    ["Adult amethyst shale spiders prefer to create their nests against the outer walls of Deepholm."] = "Дорослі аметистові сланцеві павуки полюбляють влаштовувати гнізда під зовнішніми стінами Діпголму.",
    ["Adult nether rays are relatively docile, but their younglings are short-tempered and highly energetic beasts."] = "Дорослі нетерські скати порівняно сумирні, та їхні дитинчата — запальні й надзвичайно енергійні звірята.",
    ["Adventurers have reported rare sightings of a monstrous sized emerald shale spider, which the denizens of Deepholm have come to call the Jadefang."] = "Шукачі пригод подеколи повідомляли про появу велетенського смарагдового сланцевого павука, якого мешканці Діпголму прозвали Нефритоіклом.",
    ["Affectionate and curious, these kittens seem to find the most peculiar hiding places."] = "Лагідні й допитливі, ці кошенята вміють знаходити найдивовижніші схованки.",
    ["After a harpy incursion in Feralas, several hippogryph nesting grounds were attacked. Hundreds of hatchlings were orphaned, and they have been entrusted to the care of the druids on Sardor Isle."] = "Після нападу гарпій у Фераласі кілька гніздовищ гіпогрифів зазнали руйнування. Сотні малят осиротіли, тож їх віддали під опіку друїдам на Острові Сардор.",
    ["After a long night out mages find that their water elementals smell a bit off."] = "Після довгої нічної гульні маги виявляють, що їхні водяні елементалі трохи дивно тхнуть.",
    ["After being rudely stuffed into a gourd in a vain effort to treat a Lightbloom infestation, this sporebat's just grateful to be out."] = "Після того, як цього спорокажана грубо запхали в гарбуз у марній спробі вилікувати зараження Світоцвітом, він просто радий, що вибрався.",
    ["After birth, newborn sharks quickly flee their hungry mothers. Their early independence makes them dangerous, even while young."] = "Одразу після народження малі акули прудко тікають від голодних матерів. Така рання самостійність робить їх небезпечними навіть замолоду.",
    ["After centuries of domestication, these furry critters inhabit nearly every human nation in the Eastern Kingdoms."] = "Після століть приручення ці пухнасті дрібнятка живуть майже в кожному людському краю Східних Королівств.",
    ["After consuming the shin bone of Gul'dan, this fiesty demon hunter was caged for 10000 years by his brother Murkfurion."] = "З'ївши гомілкову кістку Ґул'дана, цього запального мисливця на демонів його брат Мурфуріон ув'язнив на 10000 років.",
    ["After finding a clutch of black proto-whelps, Wrathion took them under his wing."] = "Знайшовши кладку чорних протодраконенят, Вратіон узяв їх під своє крило.",
    ["After getting lost in the thick of battle, this hawkstrider chick needs a new home."] = "Загубившись у гущі битви, це соколострибеня потребує нової домівки.",
    ["After hatching, these twisted reptiles devour the weaker members of their clutches as an act of dominance."] = "Щойно вилупившись, ці зіпсуті плазуни пожирають слабших побратимів зі свого виводку, утверджуючи свою владу.",
    ["After many complaints that taming young boars was a painful experience, engineers came to the rescue with this creepily lifelike model."] = "Після численних скарг, що приборкувати молодих вепрів — боляче, на допомогу прийшли інженери з цією моторошно правдоподібною моделлю.",
    ["After pestering the Dragonscale Basecamp for weeks, Granpap Whiskers discovered a way to catch them and use them to get rid of other more annoying insects."] = "Дошкуляючи Базовому Табору Драконолуски тижнями, Дідусь Вусань знайшов спосіб ловити їх і використовувати, щоб позбутися інших, надокучливіших комах.",
    ["After studying the crocolisk species for several years, the famed angler Nat Pagle determined that baby crocolisks are mostly harmless."] = "Кілька років вивчаючи кроколісків, славетний рибалка Нат Паґл дійшов висновку, що малі кроколіски здебільшого безпечні.",
    ["After swarming around open lava pits during the day, these strange insects emit a fiery glow at night."] = "Удень ці дивні комахи рояться над відкритими лавовими ямами, а вночі випромінюють вогняне сяйво.",
    ["After witnessing your heroism in battle, this gruntling promised you an oath of fealty."] = "Побачивши твою звитягу в бою, це маля-рубака присягнуло тобі на вірність.",
    ["After witnessing your heroism in battle, this squire promised you an oath of fealty."] = "Побачивши твою звитягу в бою, цей зброєносець присягнув тобі на вірність.",
    ["Albino ravens are incredibly rare and highly prized amongst the traders of the Great Sea."] = "Ворони-альбіноси неймовірно рідкісні й вельми цінуються серед торгівців Великого Моря.",
    ["All dogs go to Bastion. \n\nCats go to Revendreth."] = "Усі пси потрапляють до Бастіону. \n\nКоти — до Ревендрету.",
    ["Also known as the Dreamurk, Ysergle slumbered for many long years in the Emrgrled Dream."] = "Відома також як Снурк, Ісерґл багато довгих років дрімала у Смрргадовому Сні.",
    ["Also known as the Lord of Lies, Baa'lial is a master of deceit."] = "Відомий також як Володар Брехні, Баа'ліал — майстер обману.",
    ["Although born in the warm heights of Blackrock Spire, the smolderweb hatchling can survive most environments."] = "Хоч і народжене в теплих височинах Шпиля Блекрок, тліпавутинне дитинча здатне вижити майже в будь-якому довкіллі.",
    ["Although loath to part with Bananas, Landro realized it would be safer if the pet was far from Booty Bay when his father, King Mukla, discovered he was missing."] = "Хоч Ландро й не хотів розлучатися з Бананасом, він розумів: безпечніше, якщо улюбленець буде якнайдалі від Бухти Здобичі, коли його батько, король Мукла, виявить зникнення.",
    ["Although most reptiles enjoy basking in sunlight, these scaly beasts love bathing in the glow of Azeroth's twin moons."] = "Хоча більшість плазунів полюбляє грітися на сонці, ці лускаті звірі люблять купатися в сяйві двох місяців Азероту.",
    ["Although small, pugs are very dangerous when provoked."] = "Хоч і малі, мопси дуже небезпечні, коли їх роздратувати.",
    ["Although the wounds caused by the young quillrat are seldom fatal, most predators seek easier prey."] = "Хоча рани, завдані юним голкощуром, рідко бувають смертельними, більшість хижаків шукає легшу здобич.",
    ["Always 'ready to play,' Landro's Lil' XT is almost indistinguishable from the original. Prone to tantrums and narcolepsy."] = "Завжди «готовий до гри», малий XT Ландро майже не відрізняється від оригіналу. Схильний до нападів люті та нарколепсії.",
    ["Always hungry, and has a shockingly good personality."] = "Завжди голодний і має приголомшливо добру вдачу.",
    ["Always in its brother's shadow."] = "Завжди в тіні свого брата.",
    ["Always on the lookout for a fight or some tasty grass, Zao keeps his head down and eyes forward."] = "Завжди напоготові до бійки чи смачної травички, Зао тримає голову схиленою, а очі — спрямованими вперед.",
    ["Always watching. Always judging."] = "Завжди спостерігає. Завжди судить.",
    ["Always wear a helm in the Redridge Mountains. Buzzards view humanoid hair as excellent nesting material."] = "У Червоногірському хребті завжди носи шолом. Канюки вважають волосся гуманоїдів чудовим матеріалом для гнізд.",
    ["Amador has a big heart and loves to help people, especially children and elders. He also likes belly rubs."] = "Амадор має велике серце й любить допомагати людям, особливо дітям і старим. А ще він любить, коли чухають живіт.",
    ["Amani witch doctors have turned many victims into frogs. Some never recover."] = "Чаклуни Амані перетворили на жаб чимало жертв. Дехто так і не повернувся до тями.",
    ["Amberbarbs often try to provoke larger creatures to attack it. Once their victim strikes them, they will retaliate with the entire hive."] = "Бурштинові колючки часто дражнять більших створінь, щоб ті напали. Щойно жертва вдарить, у відповідь налітає весь рій.",
    ["Ambystans are swift but cowardly creatures. At the first hint of danger, a darter will hide in the nearest hole."] = "Амбістани — прудкі, але боягузливі створіння. За першого ж натяку на небезпеку метушун ховається в найближчу нору.",
    ["Among the Death Knight's forces, the frost wyrm is the most formidable. This whelpling is no different."] = "Серед сил лицаря смерті крижаний вірм — найгрізніший. Це драконятко не виняток.",
    ["Amongst the rudest of the Twilight's Hammer's corrupting activities was binding the elements of small streams and brooks."] = "Серед найбільш мерзенних діянь Сутінкового Молота було сковування стихій малих струмків і потічків.",
    ["An Igneoid is formed when magma makes it to Azeroth's surface and is infused with dark elemental magic. The resulting creature is tiny, fierce, and very cute."] = "Іґнеоїд утворюється, коли магма пробивається на поверхню Азерота й просякається темною елементальною магією. Створіння, що з цього постає, крихітне, люте й дуже миле.",
    ["An adult Snowclaw can rattle the very trees with its roar. A cub can rattle one of the smaller branches."] = "Дорослий Сніголап своїм ревом може здригнути цілі дерева. Ведмежа здатне здригнути хіба що дрібнішу гілочку.",
    ["An adventurous little elemental, Pebble escaped hungry gyreworms in the Crumbling Depths, braved the emptiness of the Twisting Nether, and ultimately found himself rescued from a mailbox."] = "Камінчик, маленький елементаль-шукач пригод, утік від голодних вихрочервів у Тлінних Глибинах, здолав порожнечу Викривленого Нижнього Світу і зрештою був врятований зі скриньки для пошти.",
    ["An anubisath idol from the Temple of Ahn'qiraj, infused with ancient qiraji magic."] = "Анубісатський ідол із Храму Ан'Кіраж, просякнутий прадавньою магією кіражі.",
    ["An astounding find for the scientific community of Azeroth, who have long pondered, often in taverns, what a baby Sea Giant might look like."] = "Приголомшлива знахідка для наукової спільноти Азероту, яка давно гадала — часто в шинках, — як же виглядає малятко морського велетня.",
    ["An early stage of the bilescourge life cycle."] = "Рання стадія життєвого циклу жовчної погибелі.",
    ["An enigmatic species, said to feed off the chaotic energies of the Old Gods."] = "Загадковий вид, який, подейкують, живиться хаотичними енергіями Прадавніх Богів.",
    ["An especially aggressive snooter. Its unpleasant disposition makes it an outcast among other snooters."] = "Особливо агресивний шмиг. Через його неприємну вдачу він став ізгоєм серед інших шмигів.",
    ["An intelligent ape that claims he is from 'the moon'. Does he mean the White Lady, or the Blue Child?"] = "Розумна мавпа, яка твердить, що вона «з місяця». Чи має вона на увазі Білу Пані, чи Блакитне Дитя?",
    ["An old and dangerous discarded toy."] = "Стара й небезпечна викинута іграшка.",
    ["An unlikely leader of murlocs that had to step into the role after the death of his father, Murgian."] = "Малоймовірний ватажок мурлоків, якому довелося обійняти цю роль після смерті свого батька, Мурґіана.",
    ["An unrepentant soul that was once trapped inside Frostmourne, and now flits restlessly between worlds."] = "Нерозкаяна душа, що колись була ув'язнена у Льодоскорботі, а тепер невпинно шугає поміж світами.",
    ["Ancient Gorian blood runs through Garrlok's veins. As far as anyone knows, only his diminutive stature keeps his imperial ambitions in check."] = "У жилах Ґарлока тече прадавня горіанська кров. Наскільки відомо, лише його дрібний зріст тримає в шорах його імперські амбіції.",
    ["Ancient Gorian blood runs through Marrlok's veins. As far as anyone knows, his desire to rest for long stretches of time on a sunny beach keeps his imperial ambitions in check."] = "У жилах Маррлока тече прадавня горіанська кров. Наскільки відомо, лише його бажання довго відпочивати на сонячному пляжі стримує його імперські амбіції.",
    ["Ancient Gorian blood runs through Parrlok's veins. As far as anyone knows, his desire for enjoying pastries and chatting with his friends keeps his imperial ambitions in check."] = "У жилах Паррлока тече прадавня горіанська кров. Наскільки відомо, лише його прагнення поласувати випічкою й побалакати з друзями стримує його імперські амбіції.",
    ["Ancient dinomancers once believed that pure white scales on dinosaurs indicated the influence of celestial bodies.  In their pursuit of balance, the Lun'alai have embraced these superstitions in their efforts to restore the white brutosaur."] = "Давні дайномансери колись вірили, що чисто білі луски на динозаврах свідчать про вплив небесних світил. У своєму прагненні рівноваги лун'алаї перейняли ці забобони, намагаючись відродити білого брутозавра.",
    ["And even if they reach the danish, they'll never get past Rocketfist!"] = "І навіть якщо вони доберуться до данського тістечка, їм нізащо не оминути Ракетокулака!",
    ["And he was all like, Primal Punch!!"] = "А він такий типу: Первісний Удар!!",
    ["And then, woosh! It comes stampeding out of the ocean and like, roars! Raaargh!"] = "А потім — вжух! Він вилітає з океану, гупаючи ногами, і типу реве! Раааргх!",
    ["And you thought turnips at the dinner table were bad."] = "А ви ще думали, що ріпа на вечерю — це погано.",
    ["Angering a spiny terrapin will cause it to withdraw into its shell and begin to spin wildly towards an attacker."] = "Розлючена колюча водяна черепаха ховається в панцир і починає несамовито крутитися в бік нападника.",
    ["Animated by magical means, and chlorophyll."] = "Оживлений магічними засобами та хлорофілом.",
    ["Annoying and destructive, they can be coaxed with enough cheese to become a tolerable companion."] = "Набридливі й руйнівні, вони, якщо дати їм досить сиру, стають стерпними супутниками.",
    ["Annuna's distinctive coloration is due to her eating nothing but orange dragonflies."] = "Прикметне забарвлення Аннуни пояснюється тим, що вона їсть лише помаранчевих бабок.",
    ["Anyone serious about using a mechanical spider in battle knows that you need to buy replacement legs in bulk. Those things are fragile."] = "Кожен, хто серйозно ставиться до використання механічного павука в бою, знає, що запасні ноги слід купувати оптом. Ці штуки крихкі.",
    ["Anything can be a nest, if you try hard enough."] = "Будь-що може стати гніздом, якщо добряче постаратися.",
    ["Appearances of this beloved and ultra-reclusive murloc are sure to draw a crowd."] = "Поява цього улюбленого, та вкрай відлюдкуватого мурлока неодмінно збирає натовп.",
    ["Arakkoa sun worship has resulted in the creation of some strange and monstrous minions."] = "Поклоніння аракоа сонцю породило кількох дивних і потворних поплічників.",
    ["Arcane-infused wyrms are favored familiars of Eversong mages."] = "Просочені тайнощами вірми — улюблені фамільяри магів Вічної Пісні.",
    ["Arrogant from a past life in the stormy Forbidden Reach, pines after the good old days when the elements controlled the land. Bit of a blow hard really."] = "Зарозумілий після минулого життя в буремних Заборонених Теренах, він тужить за добрими давніми часами, коли стихії панували над землею. Як на правду, неабиякий хвалько.",
    ["As a spawn of the most dangerous sha, this little monster has some big plans, but needs to wait a few thousand years first."] = "Як поріддя найнебезпечнішого ша, це маленьке чудовисько має великі плани, та спершу мусить почекати кілька тисяч років.",
    ["As an egg, this proto-drake was struck by a freak bolt of lightning. Years later, the lightning still lives inside."] = "Ще яйцем цього протодрейка вразила сліпа блискавка. Роками пізніше блискавка досі живе всередині.",
    ["As good as gold and better. These little guys are quite frail but exceedingly brave. - Bob Bigheart"] = "Цінніші за золото, а то й більше. Ці малі досить тендітні, але напрочуд хоробрі. - Боб Великосердий",
    ["As handy as this invention is, it was also programmed to absolutely despise hand puns."] = "Хоч який зручний цей винахід, його ще й запрограмували геть зневажати жарти про руки.",
    ["As heir to the Lord of Outland, Maggz has always shared his family's love of violence and power. He just happens to be even more in love with pet treats."] = "Як спадкоємець Володаря Позамежжя, Маґґз завжди поділяв родинну любов до насильства й влади. Просто так сталося, що ласощі для улюбленців він любить ще дужче.",
    ["As if a dark, underwater cave wasn't nightmarish enough, these things exist -- and they love it there."] = "Наче темної підводної печери було недосить, щоб наганяти жах, ще й існують ці тварюки — і їм там подобається.",
    ["As if a mine full of non-ghost spiders wasn't scary enough."] = "Наче копальня, повна звичайних, не-привидних павуків, була недостатньо страшною.",
    ["As long as any fragment of this species is found and planted, it will regrow into the same magnificent species as it once was."] = "Допоки знайдеться бодай уламок цього виду, який можна посадити, він знову виросте в той самий чудовий вид, яким був колись.",
    ["As master of all the ball pit lords, Manny rules over playgrounds with a spirit filled with fun and mischievousness."] = "Як володар усіх повелителів басейну з кульками, Менні править ігровими майданчиками з душею, сповненою веселощів і пустощів.",
    ["As small as it is, it's no wonder this little duckling got lost in time."] = "Зважаючи на його дрібний розмір, не дивно, що це каченятко загубилося в часі.",
    ["As younglings, these critters need a lot of naps. Fortunately, adventurers' backpacks make good napping spots."] = "Замолоду цим створінням потрібно багато дрімати. На щастя, наплічники шукачів пригод — гарне місце для сну.",
    ["Assistant Botanist Leafy is an expert at identifying edible plants... which is all of them."] = "Помічник ботаніка Листяник — знавець у визначенні їстівних рослин... тобто всіх рослин узагалі.",
    ["At a young age Aura donned her magic hat, took her crystal staff, and set off for adventure into the unknown."] = "Замолоду Аура вдягла свій чарівний капелюх, узяла кришталеву патерицю й вирушила в пригоду до невідомого.",
    ["At home in small dens, these little guys wriggle into all sorts of tight spots, even sometimes supply pouches."] = "Почуваючись як удома в невеликих лігвах, ці малюки протискаються в усілякі тісні шпарини, а часом навіть у похідні торбини з припасами.",
    ["At night, the grassland hoppers fill the night with their maddening song. Those unaccustomed to it have spent many a sleepless night serenaded by their mating calls."] = "Уночі лугові стрибунці наповнюють темряву своєю божевільною піснею. Ті, хто до неї не звик, не одну безсонну ніч провели під серенаду їхніх шлюбних покликів.",
    ["Aud'rei will devour just about anything in her path to grow big and strong."] = "Од'рей пожере майже все на своєму шляху, аби вирости великою й сильною.",
    ["Augmented by Adamanthia's Ebon Might, this whelpling is ready to face any challenge."] = "Підсилене Чорною Могуттю Адамантії, це драконеня готове стати на будь-який виклик.",
    ["Awww, aren't her pedipalps adorable?"] = "Ой, хіба її педипальпи не чарівні?",
    ["Awww, aren't it's fuzzy little pedipalps cute?"] = "Ой, хіба її пухнасті маленькі педипальпи не милі?",
    ["Axel likes to chase bees. No one knows why."] = "Аксель любить ганятися за бджолами. Ніхто не знає чому.",
    ["Baby ottuks spend their days swimming, chasing butterflies, and practicing their intimidating roars."] = "Малі оттуки бавлять дні, плаваючи, ганяючись за метеликами й вправляючись у своєму грізному ревінні.",
    ["Based on the size, the mantid appear to be re-growing their swarm, likely due to the presence of a new empress."] = "Судячи з чисельності, мантиди знову нарощують свій рій, імовірно через появу нової імператриці.",
    ["Battle pet trainers are strongly encouraged to wash their hands for at least 30 minutes after playing with the filthling."] = "Дресирувальникам бойових улюбленців наполегливо радять мити руки щонайменше 30 хвилин після гри з бруднюком.",
    ["Baubleworms are highly prized in the Veiled Market, where those featuring few gemstone flaws can fetch extreme prices."] = "Самоцвітні черви високо цінуються на Завуальованому ринку, де ті з них, чиї самоцвіти майже без вад, можуть сягати захмарних цін.",
    ["Baubleworms have no natural predators, and grow their gemstones to attract mates."] = "У самоцвітних червів немає природних хижаків, а самоцвіти вони відрощують, щоб приваблювати пару.",
    ["Baubleworms were found by the Brokers on an unknown world, and so gorgeous were their gems, that quickly the expedition turned against one another."] = "Самоцвітних червів Брокери знайшли на невідомому світі, і самоцвіти їхні були настільки розкішні, що члени експедиції швидко зчепилися між собою.",
    ["Be careful, he might eat all your crops!"] = "Будьте обережні, він може з'їсти весь ваш врожай!",
    ["Be sure to sleep with some grass under your pillow so you can give this critter a snack while you dream."] = "Обов'язково спіть із пучком трави під подушкою, щоб уві сні почастувати це створіння.",
    ["Beakbert's favorite food is a ravenberry."] = "Улюблена їжа Дзьоберта — вороноягода.",
    ["Beautiful and deadly."] = "Прекрасна й смертоносна.",
    ["Beautiful dreamer, wake unto me, Starlight and dewdrops are waiting for thee."] = "Прекрасна сновидо, прокинься враз, зорі й роса вже зачекались нас.",
    ["Because it's her favorite holiday, Hoplet wears her Lunar Festival outfit year-ound."] = "Оскільки це її улюблене свято, Гоплет носить вбрання Місячного фестивалю цілий рік.",
    ["Because their dens tend to be close to drogbar settlements, these snails are both faster and stronger than those on the surface."] = "Оскільки їхні нори зазвичай розташовані поблизу поселень дроґбарів, ці слимаки і швидші, і сильніші за тих, що на поверхні.",
    ["Because they are often attracted to candles, these moths can be a big problem for kobolds."] = "Оскільки їх часто приваблюють свічки, ці молі можуть бути великою проблемою для кобольдів.",
    ["Because you don't want to know what happens when a rat wanders into the Sunwell."] = "Бо ти ж не хочеш знати, що буває, коли пацюк забредає до Сонячного Колодязя.",
    ["Beep. Beep. Beep. Quack."] = "Біп. Біп. Біп. Кря.",
    ["Beetles in the Burning Steppes roll magma into tiny balls and eat them once they cool off."] = "Жуки Полум'яних Степів скочують магму в крихітні кульки і з'їдають їх, коли ті охолонуть.",
    ["Before he was known as one of the Wild Gods, Ursoc roamed the Grizzly Hills as a cub."] = "Перш ніж стати відомим як один з Диких Богів, Урсок ще ведмежам блукав Грізлі-Гіллз.",
    ["Before the Mark II, Varmints were a sorry excuse for an annoying and over-engineered pest. Now, though? They're absolutely infuriating!"] = "До появи Моделі II Капосники були жалюгідною подобою набридливого й переускладненого шкідника. А тепер? Тепер вони геть нестерпні!",
    ["Behold! A pale vorquin."] = "Погляньте! Блідий воркін.",
    ["Being a pirate is alright with me, especially if you've got this thing willing to carry your grog."] = "Бути піратом мене цілком влаштовує, особливо коли маєш отаку штуку, що залюбки тягатиме твій ґроґ.",
    ["Being green is... not easy."] = "Бути зеленим... нелегко.",
    ["Being thrown into a pit of bloodlouse larvae is a painful fate for those that fail the great houses of Maldraxxus."] = "Бути кинутим у яму з личинками кровоблохи — болісна доля для тих, хто підвів великі доми Малдраксуса.",
    ["Bela has learned some humility since you first met her, so she likely won't boss you around too much."] = "Бела стала трохи смиреннішою, відколи ви вперше зустрілися, тож, мабуть, не надто вами командуватиме.",
    ["Best keep him away from any cannons."] = "Краще тримай його подалі від будь-яких гармат.",
    ["Best not to park your mount beneath this one."] = "Краще не залишай свою їздову тварину просто під ним.",
    ["Between battling, bathing, and playing, these ottuks have very busy schedules."] = "Між боями, купанням і забавами в цих оттуків дуже щільний розклад.",
    ["Beware awakening the power of knowledge."] = "Стережіться пробуджувати силу знання.",
    ["Bilescourge mostly feed on the corpses of victims of the Legion. However, since your arrival, it has developed a taste for demon corpses as well."] = "Жовчна погибель здебільшого живиться трупами жертв Легіону. Проте відколи з'явився ти, вона вподобала ще й трупи демонів.",
    ["Biohazard. Handle with gloves."] = "Біологічна загроза. Брати лише в рукавицях.",
    ["Blinky just hatched, and is ready for adventure, but may need a few naps along the way."] = "Блимко щойно вилупився й готовий до пригод, але дорогою йому, можливо, знадобиться кілька дрімот.",
    ["Blub's heart has always been bigger than her tank, but once the rest of her got too big she had to find a new home. Fortunately, she can now travel with you and see all the marvels of the world!"] = "Серце Бульк завжди було більшим за її акваріум, та коли й решта її стала завелика, їй довелося шукати нову домівку. На щастя, тепер вона може мандрувати з вами й бачити всі дива світу!",
    ["Bluedoo's magic and skills in accupuncture will help any in need of relaxation."] = "Магія Блюду й уміння в акупунктурі допоможуть будь-кому, хто потребує розслаблення.",
    ["Born and raised in Sunwing Rookery, this fella loves causing mischief when the tamers aren't looking."] = "Народжений і вирощений у Гніздовищі Сонцекрилих, цей хлопака обожнює бешкетувати, коли приборкувачі не дивляться.",
    ["Born from demonic magic, these petulant little entities corrupt everything they touch with foul energies."] = "Народжені з демонічної магії, ці примхливі малі створіння опоганюють усе, чого торкаються, мерзенними енергіями.",
    ["Born from the crash site of the Xenedar on Argus."] = "Народжений на місці падіння «Зенедара» на Аргусі.",
    ["Born in the jungles of Stranglethorn, unlucky raptor hatchlings are often captured by the Gurubashi and taken to the troll city of Zul'Gurub."] = "Народжені в джунглях Тернистого Шпилю, невдатні пташенята-раптори часто потрапляють у полон до Ґурубаші й опиняються в тролячому місті Зул'Ґуруб.",
    ["Born near the funeral pyre in Solemn Valley, this young eagle's burgundy feathers still carry the scent of smoke and ash. A quiet reminder that even in loss, something new can take wing."] = "Народжений біля поховального вогнища в Урочистій Долині, цей молодий орел досі несе у своєму бордовому пір'ї запах диму й попелу. Тихий нагадок про те, що навіть у втраті щось нове може здійнятися в небо.",
    ["Born of living stone. Reforged by the hands of Wrathion's agents. Sadly much too tiny to make a difference in the black dragons' war against the djaradin."] = "Народжений із живого каменю. Перекований руками агентів Вратіона. На жаль, надто крихітний, щоб щось змінити у війні чорних драконів проти джарадинів.",
    ["Born of sand, these dangerous creatures can form and disperse in the blink of an eye."] = "Народжені з піску, ці небезпечні створіння здатні виникати й розсипатися за одну мить.",
    ["Both heads are equally fearsome on the terrifying chimaera, each capable of its own unique breath attack."] = "Обидві голови жахливої химери однаково страшні, і кожна здатна на власну унікальну атаку подихом.",
    ["Boulderfangs are known to make cozy nests in cabinets, shoes, and other inconvenient places."] = "Валуноікли відомі тим, що звивають затишні гнізда в шафах, черевиках та інших незручних місцях.",
    ["Boulderfist legend recounts a cloud of carrion birds following ogre warriors through the Dark Portal during the Second War; it may be that all two-headed scavengers in Azeroth are their descendants."] = "Легенда клану Кам'яного Кулака оповідає про хмару птахів-падляків, що летіли за воїнами-оґрами крізь Темний Портал під час Другої Війни; можливо, усі двоголові стерв'ятники Азероту — їхні нащадки.",
    ["Brave assassins sometimes capture these critters to use their highly toxic venom to poison weapons."] = "Хоробрі вбивці часом ловлять цих дрібняток, щоб їхньою вкрай отруйною отрутою змащувати зброю.",
    ["Breanni in Dalaran, one of the world's foremost collectors of exotic pets, will only award the mystical Celestial Dragon to fellow collectors whose obsession rivals her own."] = "Бреанні з Даларану, одна з найвидатніших у світі збирачок екзотичних улюбленців, дарує містичного Небесного Дракона лише тим колекціонерам, чия одержимість дорівнює її власній.",
    ["Brightly colored means do not touch. Red is nature's warning light!"] = "Яскраве забарвлення означає «не чіпай». Червоний — це попереджувальний сигнал природи!",
    ["Brilliant spores are very rarely seen, found deep under the waves of Draenor within the darkest corners of the Zangar fungal encroachment."] = "Осяйні спори трапляються вкрай рідко; їх знаходять глибоко під хвилями Дренора, у найтемніших закутках грибкового наступу Занґару.",
    ["Brought to Orgrimmar aboard merchant ships, these short-lived reptiles are considered pests by the city's residents."] = "Привезені до Оґриммара на купецьких суднах, ці недовговічні рептилії вважаються шкідниками серед мешканців міста.",
    ["Built to dig holes by a gnomish farmer, Rooter quickly and predictably went haywire, with disastrous results."] = "Створений гномським фермером, щоб рити ями, Риюн швидко й цілком передбачувано пішов урознос, з катастрофічними наслідками.",
    ["Built with ever-wagging tail technology, Brutus is a mechanically-certified good boy."] = "Споряджений технологією невпинного метляння хвостом, Брут — механічно сертифікований хороший хлопчик.",
    ["Bumbles may not have been the largest bee of the millions within the hive, but that doesn't mean he can't grow into a champion."] = "Дзизько, може, й не був найбільшою з мільйонів бджіл у вулику, та це не означає, що він не виросте в чемпіона.",
    ["Buried amid sand and sediment, these crabs blend right into their environment."] = "Зариваючись у пісок і відклади, ці краби чудово зливаються зі своїм оточенням.",
    ["Burnout always has a supply of well toasted marshmallows."] = "У Вигаринки завжди є запас гарненько підсмажених зефірок.",
    ["Burrows deep into snowbanks to hide from predators."] = "Глибоко зариваються в замети, щоб сховатися від хижаків.",
    ["Butterflies taste with their feet! I tried it once, but I only made a mess."] = "Метелики відчувають смак ногами! Я якось спробував, але тільки все забруднив.",
    ["By far the best way to spread the plague of undeath."] = "Безперечно, найкращий спосіб поширити чуму немертя.",
    ["Camouflaged like moss, the skitterer will hide in trees and leap on their victims from above."] = "Замаскований під мох, дріботун ховається на деревах і стрибає на жертв згори.",
    ["Can sense an opponent's heartbeat through echolocation."] = "Здатний відчувати серцебиття супротивника за допомогою ехолокації.",
    ["Can you believe how cute I am?  Me neither."] = "Ти лиш поглянь, який я милий, аж не віриться! Мені теж.",
    ["Can't quite take over your mind, but capable of giving you a really bad migraine."] = "Заволодіти твоїм розумом він не здатен, зате може влаштувати тобі добрячу мігрень.",
    ["Capable of flying, unlike domesticated types."] = "Здатний літати, на відміну від свійських різновидів.",
    ["Capable of sensing vibrations and tremors nearly a mile away, these young moles tend to burrow at the first sign of mortal danger."] = "Здатні відчувати вібрації й поштовхи майже за милю, ці молоді кроти схильні зариватися при першій ознаці смертельної небезпеки.",
    ["Capable of sitting in even the smallest of boxes, thanks to its ghostly nature."] = "Завдяки своїй примарній природі здатне вміститися навіть у найменшу коробку.",
    ["Captain Nibs was once the leader of an ill-fated sea voyage of slightly-too-smart-for-their-own-good monkeys that quickly capsized."] = "Капітан Нібс колись очолював приречену морську виправу надто розумних собі на лихо мавп, що швидко пішла на дно.",
    ["Careful now, she can get a bit frisky sometimes!"] = "Обережно, часом вона буває трохи невгамовною!",
    ["Carrion feeders often found in large numbers within ancient unearthed tombs; they can survive long periods of time without feeding."] = "Падложери, яких часто знаходять у великій кількості в стародавніх розкопаних гробницях; вони можуть довго виживати без їжі.",
    ["Cats and other curious critters often have short-lived play sessions with this moth that end with a face full of singed hair."] = "Коти та інші цікаві створіння часто недовго бавляться з цим метеликом, і ці забави закінчуються мордочкою, повною обсмаленої шерсті.",
    ["Cave swallows were once plentiful in the early days of Undermine's construction. Now, goblin construction has left the population of these beautiful birds dangerously low."] = "Печерні ластівки колись були численні в перші дні розбудови Андермайну. Тепер ґоблінське будівництво звело популяцію цих прекрасних птахів до небезпечно низького рівня.",
    ["Chestnut once found an acorn larger than he was, ate the whole thing, and doubled in size. It's a good thing he didn't eat a Trunkalumpf."] = "Каштан якось знайшов жолудь, більший за себе, з'їв його цілком і подвоївся в розмірі. Добре, що він не з'їв Хоботлумпфа.",
    ["Chi-Chi tries to inspire hope with her loud squawk and by chasing, and eventually eating, butterflies."] = "Чі-Чі намагається вселяти надію своїм гучним кряканням, а також ганяючись за метеликами та, зрештою, поїдаючи їх.",
    ["Chill out. It's just a spider."] = "Розслабся. Це лише павук.",
    ["Civets are landbound cousins of the otter and are prized for their heady musks."] = "Цивети — суходільні родичі видри, що цінуються за свій п'янкий мускус.",
    ["Claims to be from a long lost land from the remnants of a massive volcano, but that story seems a little shaky."] = "Стверджує, що походить із давно загиблого краю на рештках велетенського вулкана, але ця історія видається трохи хисткою.",
    ["Claudius is known for being brutally honest as well as a great singer. He knows your jewels would look better on him."] = "Клавдій відомий своєю брутальною чесністю, а ще тим, що він чудовий співець. Він знає, що твої коштовності краще пасували б йому.",
    ["Commonly used by sporelings as a light source as they navigate the waterways of Zangarmarsh, this luminescent insect helps them avoid the dangerous bogflare needlers."] = "Споролінги часто послуговуються цією світною комахою як джерелом світла, мандруючи водними шляхами Драговини Зангар: вона допомагає їм уникати небезпечних багнополум'яних колійників.",
    ["Compared to a fully grown dreamborne scarab, this is the lesser of two weevils."] = "Порівняно з дорослим снородженим скарабеєм, це менше з двох лих.",
    ["Considered by most to be a significant improvement to the 4000 series, there were nonetheless serious concerns about the amount of heat they produced."] = "Хоча більшість вважає його суттєвим поліпшенням серії 4000, усе ж лишалися серйозні занепокоєння щодо кількості тепла, яке він виділяв.",
    ["Considered to be lucky, tigers carved of jade are prized, but taming a jade tiger itself is an even greater prize."] = "Тигри, вирізьблені з нефриту, вважаються щасливими й високо цінуються, та приборкати справжнього нефритового тигра — нагорода ще більша.",
    ["Constructed from a seemingly impossible mass of gears, springs, wires, and a little something special, this dragonling embodies the spirit of Pandaria as seen through an engineer's goggles."] = "Зібраний з на позір неможливої купи шестерень, пружин, дротів і дрібки чогось особливого, цей дракончик утілює дух Пандарії, побачений крізь окуляри інженера.",
    ["Constructs designed to assist the titans with sundry small tasks, this example is oddly small. Teeny Titan Orb! Let's Go!"] = "Конструкти, створені, щоб допомагати титанам у різних дрібних справах. Цей екземпляр дивовижно малий. Крихітна Титанова Сфера! Уперед!",
    ["Contrary to its benign appearance, mongoose are dangerous carnivores, well known for their ability to hunt venomous snakes that could kill much larger creatures."] = "Усупереч лагідному вигляду, мангусти — небезпечні хижаки, добре відомі здатністю полювати на отруйних змій, що могли б убити набагато більших створінь.",
    ["Contrary to its name, this little creature shakes nothing as it shuffles from place to place."] = "Усупереч своєму імені, це маленьке створіння нічого не струшує, дріботячи з місця на місце.",
    ["Contrary to popular belief, a terrapin's diet has nothing to do with its shell color."] = "Усупереч поширеній думці, харчування черепахи жодним чином не пов'язане з кольором її панцира.",
    ["Contrary to popular belief, bloodsting wasps do not feed on blood, but love."] = "Усупереч поширеній думці, оси-кровожали живляться не кров'ю, а любов'ю.",
    ["Contrary to their name, these moths are actually quite happy."] = "Усупереч своїй назві, ці молі насправді доволі щасливі.",
    ["Corlain Falcons are trained from birth to be scouts and fighting companions. The few spared from the Heartsbane curse serve the Order of Embers in the same capacity."] = "Корлейнських соколів від народження навчають бути розвідниками й бойовими супутниками. Ті нечисленні, кого оминуло прокляття Серцезгуби, так само служать Орденові Жарин.",
    ["Corpsefly eggs end up everywhere in Maldraxxus, and are easily transported accidentally."] = "Яйця трупної мухи опиняються всюди в Малдраксусі, і їх легко перенести випадково.",
    ["Counting sheep to a dream of springtime."] = "Рахує овець, мріючи про весну.",
    ["Cousin to the Snowy Panda, Mountain Pandas reside in the lower regions of Kun-Lai Summit."] = "Родичка сніжної панди, гірська панда мешкає в нижчих місцинах Піка Кун-Лай.",
    ["Crafted by a great and powerful wizard who refused to wear robes with pockets."] = "Створений великим і могутнім чаклуном, який відмовлявся носити мантії з кишенями.",
    ["Crane chicks of the Timeless Isle sometimes sing a curious song that calms the nerves and soothes the soul."] = "Журавлята Позачасового Острова часом співають дивну пісню, що заспокоює нерви й тішить душу.",
    ["Created by a blood elf apprentice, this broom would be extremely useful if anyone could figure out how to make it stop."] = "Створена учнем-ельфом крові, ця мітла була б надзвичайно корисною, якби хтось зумів збагнути, як її зупинити.",
    ["Created for one purpose and one purpose alone: to punch little critters, as hard as it possibly can."] = "Створений з однією-єдиною метою: лупцювати дрібних створінь так сильно, як тільки може.",
    ["Created to entertain children at the Darkmoon Faire, these magical balloons never lose their floatiness."] = "Створені, щоб тішити дітей на Ярмарку Темного Місяця, ці чарівні кульки ніколи не втрачають здатності літати.",
    ["Crimson swoglets are considered the most scholarly of all swoglets because they're well red."] = "Багряних своґлетів вважають найученішими з-поміж усіх своґлетів, бо вони добряче начитані... тобто почервонілі.",
    ["Crocolisks are six-legged amphibian predators found in coastal waters. Archaeologists believe they may be descended from the diemetradons of Un'Goro Crater."] = "Кроколіски — шестилапі хижаки-амфібії, що живуть у прибережних водах. Археологи вважають, що вони можуть походити від диметродонів кратера Ун'Ґоро.",
    ["Crossing into the spirit world too often can be dangerous for your health."] = "Надто часто переходити у світ духів може бути небезпечно для здоров'я.",
    ["Crysa has collected many exotic avians in her travels, none more rare than this hatchling."] = "За свої мандри Кріза зібрала чимало екзотичних птахів, але жоден із них не такий рідкісний, як це маля.",
    ["Cub of Blazeclaw and valiant courier of Flame's Radiance. Swiftpaw serves the Sacred Flame more ferociously than some Arathi do."] = "Дитинча Полум'якіггя й звитяжний посланець Сяйва Полум'я. Прудколапий служить Священному Полум'ю запекліше за декого з араті.",
    ["Cubbly's extended proximity to time magic has given him powers far beyond the average bear."] = "Тривала близькість Кабблі до магії часу наділила його силами, далеко вищими за пересічного ведмедя.",
    ["Curious and inquisitive, this starry-eyed whelpling has big dreams and a wish to explore every world in the cosmos."] = "Допитливе й цікаве, це зореоке драконеня має великі мрії й бажання дослідити кожен світ космосу.",
    ["Curiously, this hawk uses its razor-sharp talons to peel the bark off trees as it searches for bugs, even though it has no need for sustenance."] = "Цікаво, що цей яструб гострими, мов бритва, кігтями обдирає кору з дерев у пошуках комах, хоча їжі він уже не потребує.",
    ["Cute at this size, the humble scootlefish poses a real threat to ships when it grows larger."] = "Милий за такого розміру, скромний чорнильник стає справжньою загрозою для кораблів, коли виростає більшим.",
    ["Cute enough to eat, but not recommended."] = "Такий милий, що хоч їж, та краще не варто.",
    ["DEFECTIVE; REFUSES TO KILL. MARK FOR IMMEDIATE DESTRUCTION OR SALE TO LESS INTELLIGENT ENTITY."] = "БРАКОВАНИЙ; ВІДМОВЛЯЄТЬСЯ ВБИВАТИ. ПОЗНАЧИТИ ДЛЯ НЕГАЙНОГО ЗНИЩЕННЯ АБО ПРОДАЖУ МЕНШ РОЗУМНІЙ ІСТОТІ.",
    ["Daisy moves at a very leisurely pace, and will happily accept a ride on your shoulders."] = "Дейзі пересувається дуже неквапливо й залюбки прокатається в тебе на плечах.",
    ["Dalaran's drainage is not as good as you think."] = "Каналізація Даларана не така добра, як ти думаєш.",
    ["Dali, bored of his days basking in the comfort of the Solaarian Sunbath, seeks a world of new inspiration. You are that inspiration, and he will bring color to your world."] = "Далі, якому набридло гріти боки в затишку Солаарійської Сонячної Купелі, шукає світ нового натхнення. Ти — те натхнення, і він принесе барви у твій світ.",
    ["Dangerous, toxic spores? What if it was purple?!"] = "Небезпечні, токсичні спори? А що, якби вони були фіолетові?!",
    ["Deadly offspring of the Ancient Mother, Ji-Kun Hatchlings are considered sacred treasures in many cultures."] = "Смертоносні нащадки Прадавньої Матері, пташенята Джі-Кун вважаються священними скарбами в багатьох культурах.",
    ["Deathwing's emergence transformed the whole of Azeroth; not even the ocean-dwelling murlocs were immune to his corrupt influence."] = "Поява Дезвінга змінила весь Азерот; навіть мурлоки з океанських глибин не вціліли перед його згубним впливом.",
    ["Deep beneath the Argent Tournament grounds a clutch of eggs belonging to mates Acidmaw and Dreadscale was found."] = "Глибоко під ареною Срібного Турніру знайшли кладку яєць, що належала парі — Кислотній Пащі та Жахолусці.",
    ["Delicate and dangerous, brilliant and bold, a beauty worth more than gold."] = "Витончена й небезпечна, осяйна й смілива — краса, цінніша за золото.",
    ["Delicate and dangerous, brilliant and bold, a beauty worth more than its weight in gold.  Too bad they are so light."] = "Витончена й небезпечна, осяйна й смілива — краса, цінніша за власну вагу в золоті. Шкода тільки, що вони такі легкі.",
    ["Delicate denizen of Azuremyst Isle, this magical insect has been rumored to possess healing abilities."] = "Тендітний мешканець Острова Лазурного Серпанку, ця чарівна комаха, за чутками, має цілющі здібності.",
    ["Delivers the goods while also looking good."] = "Доставляє товар і має при цьому гарний вигляд.",
    ["Demidos created a great many servants when he was hosting parties for other void lords."] = "Демідос створив чимало слуг, коли влаштовував учти для інших володарів Порожнечі.",
    ["Demonstrating that a little evil goes a long way, this fiendling uses its razor-sharp teeth and gaping maw to devour anything in its path."] = "Доводячи, що навіть дрібка зла здатна на багато що, ця нечисть пускає в хід гострі як бритва зуби й роззявлену пащу, аби пожерти все на своєму шляху.",
    ["Despite being decrepit and undead, geists move with exceptional speed and agility."] = "Попри свою старечу немічність і неживу природу, ґейсти рухаються з винятковою швидкістю та спритністю.",
    ["Despite being made mostly of rock, these creatures can fly. Some attribute this to the strength of their wings, but most agree it's probably just magic."] = "Попри те, що ці істоти складаються здебільшого з каменю, вони вміють літати. Дехто приписує це силі їхніх крил, але більшість погоджується, що це, мабуть, просто магія.",
    ["Despite having a very fine coat of fur, young vulpin do not shed at all."] = "Попри дуже тонке хутро, молоді вульпіни зовсім не линяють.",
    ["Despite its diminutive size, it is impossible to miss a sea pony cutting through the water."] = "Попри крихітний розмір, морського коника годі не помітити, коли він розтинає воду.",
    ["Despite its menacing appearance, the yellow-bellied bullfrog was aptly named."] = "Попри загрозливий вигляд, жовточереву жабу-вола назвали влучно.",
    ["Despite its name, its shell is actually much tougher than chalk."] = "Попри назву, його панцир насправді набагато міцніший за крейду.",
    ["Despite its snapping claws and venom-dripping tail, it is the bite of the diminutive scorpling that is the greatest threat."] = "Попри клацливі клешні й хвіст, з якого скрапує отрута, найбільшу загрозу становить укус крихітного скорпіончика.",
    ["Despite its vulnerable appearance, predators will often avoid attacking a juvenile vombata. It's not known exactly why, but many believe it has to do with the vombata's cute little nose."] = "Попри беззахисний вигляд, хижаки часто уникають нападати на молоду вомбату. Достеменно невідомо чому, але багато хто вважає, що річ у милому носику вомбати.",
    ["Despite the adorable name, the chirp is more of a horrible, spine-tingling shriek."] = "Попри миле ім'я, його «цвірінькання» — то радше жахливий, аж до сиротиння на спині, вереск.",
    ["Despite the name you should absolutely never, ever pet it."] = "Попри назву, його ні в якому разі, аж ніяк не можна гладити.",
    ["Despite their idyllic surroundings, grasslands cottontails hop at surprising speed when evading their pursuers."] = "Попри ідилічне довкілля, степові кролики стрибають із дивовижною швидкістю, тікаючи від переслідувачів.",
    ["Despite their smaller stature, the wolvar are some of the most aggressive creatures in Northrend. This often makes their curious nature intimidating."] = "Попри невеликий зріст, вольвари — одні з найагресивніших створінь Нортренда. Через це їхня допитлива вдача часто здається лячною.",
    ["Despite what the young pandaren may tell you, the windfeather cranes do not actually have feathers made out of wind."] = "Хай там що кажуть юні пандарени, та вітроперні журавлі насправді не мають пір'я, зробленого з вітру.",
    ["Devourers exist throughout the In-Between of various types and levels of power, but always seeking anima."] = "Пожирачі різних видів і ступенів сили існують по всьому Межипросторі, та всі вони повсякчас шукають аніму.",
    ["Did it spend too long near kaja'mite? Did someone give it kaja'cola? Who knows, but the name is great branding."] = "Чи провів він забагато часу біля каджа'миту? Чи хтось дав йому каджа'колу? Хтозна, але назва — чудовий брендинг.",
    ["Didn't play nice with the other plants in the nursery."] = "Не ладнав з іншими рослинами в розсаднику.",
    ["Diemetradons abandon their hatchlings in Un'Goro Crater to fend for themselves. Only the strongest survive."] = "Диметрадони покидають своїх малят у Кратері Ун'Горо, лишаючи їх на самих себе. Виживають лише найсильніші.",
    ["Direbeak falcosaurs are heartier than other falcosaur species, but cannot smell as well. They prefer pungent meals and will often eat carrion that has been sitting in the sun for days."] = "Фалькозаври-лютодзьоби витриваліші за інші види фалькозаврів, але мають слабший нюх. Вони полюбляють їжу з різким запахом і часто живляться падлом, що пролежало на сонці кілька днів.",
    ["Distinct from the sporebats that reside on Draenor and Outland. It's just a coincidence."] = "Відмінний від спорокажанів, що мешкають на Дреноре й Позамежжі. Це лише збіг.",
    ["Distinct from their Azerothian relatives, these critters of Outland make their home in Blade's Edge Mountains."] = "На відміну від своїх азеротських родичів, ці дрібнятка Позамежжя селяться в Горах Леза Клинка.",
    ["Distinct from their cousins found in warmer climes, these hardy critters make their homes in the icy wastes of Northrend."] = "На відміну від рідні з тепліших країв, ці витривалі створіння селяться в крижаних пустках Нортренду.",
    ["Distinct from their plain dwelling relatives, these critters make their homes amidst the war-torn Twilight Highlands."] = "На відміну від рідні, що мешкає на рівнинах, ці створіння селяться серед спустошеного війною Сутінкового нагір'я.",
    ["Distinct from their tree dwelling cousins, these ground squirrels make their homes on the plains of Azeroth and beyond."] = "На відміну від своїх деревних родичів, ці земляні білки селяться на рівнинах Азероту й за його межами.",
    ["Do the hyenas need to wear goggles? Absolutely not. Does it look extremely cool? Incredibly."] = "Чи потрібні гієнам окуляри? Та звісно ж ні. Чи має це вкрай крутий вигляд? Неймовірно.",
    ["Do you dare to open this book of draconic secrets?"] = "Чи насмілитеся ви відкрити цю книгу драконячих таємниць?",
    ["Do you see how they run?"] = "Бачиш, як вони біжать?",
    ["Do you see pity in these blinking, soulless eyes? I didn't think so."] = "Чи бачиш ти жаль у цих кліпаючих, бездушних очах? Я так і думав, що ні.",
    ["Dodger is a bit small relative to other vulpin, but is excellent at playing hide and seek."] = "Доджер трохи дрібніший за інших вульпінів, зате чудово грає в хованки.",
    ["Doesn't remember what it was originally programmed to do, just wants to battle other pets."] = "Не пам'ятає, на що його спершу запрограмували, — просто хоче битися з іншими улюбленцями.",
    ["Dogs can hear her coming from extremely far away."] = "Собаки чують її наближення з неймовірно великої відстані.",
    ["Domesticated elekks are trained as mounts by the draenei people. In the wild they are hunted for their ivory tusks."] = "Приручених елеків дренеї навчають як їздових тварин. У дикій природі на них полюють заради бивнів зі слонової кістки.",
    ["Don't be fooled by Dottie's soft coat and big eyes, her tiny, sharp teeth are for more than just munching on grass."] = "Хай тебе не вводять в оману м'яка шерсть і великі очі Дотті — її крихітні гострі зуби годяться не лише на те, щоб скубти траву.",
    ["Don't call this bird chicken unless you want egg on your face."] = "Не називай цього птаха курчам, якщо не хочеш сісти в калюжу.",
    ["Don't even think about cheating now."] = "Навіть не думай тепер шахрувати.",
    ["Don't let the cuteness fool you, this little monster will jab your ankles the second you're not looking."] = "Хай тебе не вводить в оману його миловидність — це маленьке чудовисько штрикне тебе в кісточку, щойно ти відвернешся.",
    ["Don't let their lack of a face fool you--these slimy critters are angry and just itching for a fight."] = "Хай тебе не обманює те, що в них немає обличчя — ці слизькі дрібнятка злі й аж тремтять од бажання побитися.",
    ["Don't let these eat after midnight, legend has it that it's very dangerous."] = "Не дозволяй їм їсти після опівночі — легенда каже, що це дуже небезпечно.",
    ["Don't line her cage with paper unless you want a fire."] = "Не вистеляйте її клітку папером, якщо не хочете пожежі.",
    ["Don't pet the pointy end. Note: all of the ends are pointy."] = "Не гладь гострий кінець. Зауваж: усі кінці гострі.",
    ["Don't say anything to Cap'n Crackers that you don't want repeated to you every day for the next 20 years."] = "Не кажи Капітанові Крекеру нічого такого, що не хотів би чути щодня впродовж наступних 20 років.",
    ["Don't want to break the bank on that new robot? Have a little helper at half the cost! Come down to Goblin Experimental Engineering Korporation and put in your order! All sales final."] = "Не хочеш розоритися на новенький робот? Заведи маленького помічника за півціни! Завітай до Гоблінської Експериментальної Інженерної Корпорації й зроби замовлення! Повернення не передбачено.",
    ["Donni Anthania invites these cats to her tea parties. But she doesn't serve their favorite drink: the tears of their enemies."] = "Донні Антанія запрошує цих котів на свої чаювання. Та не подає їхній улюблений напій: сльози їхніх ворогів.",
    ["Donni Anthania plans to have a bombay buried with her when she dies. A wise adventurer can put its talents to much better use."] = "Донні Антанія планує, щоб разом із нею поховали бомбейського кота, коли вона помре. Мудрий шукач пригод знайде його талантам куди краще застосування.",
    ["Dragonbreath Chili is nothing compared to the stench coming from the mouth of this thing."] = "Чилі «Драконове Дихання» — то ніщо проти смороду, що йде з пащі цього створіння.",
    ["Dragons come in all types of temporal classification -- timeless, time-lost, and even infinite."] = "Дракони бувають усіх часових різновидів — позачасові, загублені в часі й навіть нескінченні.",
    ["Drawn from an overabundance of pride and wrath these manifestations seek even more to sustain themselves."] = "Породжені надмірною пихою і гнівом, ці втілення прагнуть дедалі більше живитися ними, щоб тривати.",
    ["Drawn to heat and the smell of smoke, the fire beetle's diet consists of ash."] = "Приваблений жаром і запахом диму, вогняний жук живиться попелом.",
    ["Drawn to shiny objects. And darkness. Especially darkness."] = "Тягнеться до блискучих речей. І до темряви. Особливо до темряви.",
    ["Dream on. Dream until your dream comes true!"] = "Мрій далі. Мрій, доки твоя мрія не справдиться!",
    ["Dredgers are the sweat (and sometimes tears) of Revendreth, and their help is absolutely critical to the workings of Revendreth."] = "Копачі — це піт (а часом і сльози) Ревендрета, і їхня допомога абсолютно необхідна для того, щоб Ревендрет працював.",
    ["Druids think silver pigs have a special bond with golden pigs, as both breeds appeared on Azeroth at the same time."] = "Друїди вважають, що срібні поросята мають особливий зв'язок із золотими, адже обидві породи з'явилися в Азероті одночасно.",
    ["Due to recent accidents, the goblin cartels have prohibited anyone from bringing snakes on a zeppelin."] = "Через нещодавні пригоди ґоблінські картелі заборонили будь-кому проносити змій на дирижабль.",
    ["During a special time of year, a secretive clan of murlocs often sends young tadpoles out to explore, adventure, and begin their tale."] = "У особливу пору року потайний клан мурлоків часто відсилає юних пуголовків досліджувати, шукати пригод і починати свою повість.",
    ["During certain times of the day, the sunlight can cause a reflection on the feathers of the red tinted raptors causing them to look more like flames than feathers."] = "У певні години дня сонячне світло відбивається від пір'я червонястих рапторів так, що воно більше скидається на полум'я, ніж на пір'я.",
    ["During frigid nights in the Storm Peaks, these critters use their fluffy tails as a blanket to stay warm."] = "Морозними ночами в Грозових Вершинах ці створіння вкриваються своїми пухнастими хвостами, наче ковдрою, щоб зігрітися.",
    ["During his time in the Firelands, Fandral would often grow bored and work shaping magic on the local flora and fauna."] = "Під час перебування у Вогняних Землях Фандралові часто ставало нудно, і він вправлявся у формотворчій магії на місцевій флорі та фауні.",
    ["During the Third War, thousands of these mystical beings annihilated the demon lord Archimonde."] = "Під час Третьої війни тисячі цих містичних істот знищили володаря демонів Архімонда.",
    ["During the majestic Winter Veil celebration, these faithful companions spread joy throughout the land. The rest of the year, they are busy."] = "Під час величного святкування Зимової Заслони ці вірні супутники сіють радість по всій землі. Решту року вони зайняті.",
    ["During the warm summer months, the noise that these pests make is enough to drive a person mad."] = "У теплі літні місяці гамір, який здіймають ці шкідники, здатен звести людину з розуму.",
    ["During their years-long war with the black dragonflight, the dwarves tried crafting smaller golems that were more difficult to hit."] = "Під час багаторічної війни з чорною драконячою зграєю дворфи намагалися створювати менших големів, у яких важче поцілити.",
    ["Dustites scavenge among the roots of great trees for any small leavings they can find."] = "Пилюнці нишпорять серед коріння великих дерев, шукаючи будь-які дрібні рештки.",
    ["Each of this creature's steps shakes the ground. When enough of them run together it sounds like a raging thunderstorm."] = "Кожен крок цього створіння струшує землю. Коли їх біжить достатньо разом, це звучить як шалена гроза.",
    ["Eagerly attends every cookout. He just wants to grill for gob's sake!"] = "Завзято відвідує кожне барбекю. Він просто хоче смажити, заради всього м'ясного!",
    ["Early attempts to integrate with the ecosystem resulted in multiple specimens being eyeblasted."] = "Перші спроби інтегруватися в екосистему призвели до того, що кількох особин спопелили поглядом.",
    ["Earthen ranchers keep a variety of horned beasts for labor and company. None are so proud as the ramolith."] = "Земельні скотарі тримають розмаїтих рогатих звірів для роботи й товариства. Жоден не такий гордий, як рамоліт.",
    ["Easily mistaken for a common beetle, the sting of a sand scarab will quickly clear up the misconception should you be unlucky enough to be stung by one."] = "Його легко сплутати зі звичайним жуком, та укол піщаного скарабея швидко розвіє цю оману, якщо вам не пощастить бути вжаленим.",
    ["Eels are already slimy. This one is extra slimy."] = "Вугри й так слизькі. А цей — слизький аж надто.",
    ["Efforts to rewire the more desctructive tendencies of the species left this specimen more docile than most, but it was still not a successful endeavor."] = "Спроби перепрограмувати руйнівніші нахили виду зробили цю особину покірнішою за решту, та все ж ця затія не увінчалася успіхом.",
    ["Eight parts legs. Eight parts eyes. One part rope. One part insatiable hunger."] = "Вісім частин лап. Вісім частин очей. Одна частина мотузки. Одна частина невситимого голоду.",
    ["Either Darbel Montrose was a terrible warlock, or she simply adored cute things. Perhaps both."] = "Чи то Дарбел Монтроуз була нікудишньою чорнокнижницею, чи то просто обожнювала все миле. А може, і те, і те.",
    ["Elder shaman have warned that wisps of Ragnaros, loyal servants of the Firelord, have taken to the Molten Front. Vigilance is advised."] = "Старійшини-шамани попереджали, що вогники Раґнароса, вірні слуги Володаря Вогню, оселилися на Розплавленому Фронті. Радимо пильнувати.",
    ["Elmer once ate a whole cake all by himself. It wasn't even his cake."] = "Елмер якось з'їв цілий торт сам-один. Це навіть був не його торт.",
    ["Elune made nightsabers silver and black so they could meld into the shadows on a moonlit night."] = "Елуна зробила нічних шаблезубів сріблясто-чорними, щоб вони могли зливатися з тінями місячної ночі.",
    ["Emberrooks are the rarest and most aggressive of the rook elementals."] = "Жаринники — найрідкісніші й найагресивніші з елементальних круків.",
    ["Energized by the ogre-mages of Highmaul, this mana-hungry creature will drain you dry before you know it."] = "Наснажене оґрами-магами Високого Молота, це жадібне до мани створіння висмокче тебе досуха, ще й не зчуєшся.",
    ["Equipped with extremely sharp claws, these frigid hatchlings dig through thick layers of ice and rock for shelter."] = "Озброєні надзвичайно гострими кігтями, ці крижані пташенята прокопують товсті шари льоду й каменю в пошуках прихистку.",
    ["Eternally cute."] = "Вічно миле.",
    ["Ethereal soul-traders will travel with those who can free the essences they need from unruly hosts."] = "Ефірні торговці душами мандрують із тими, хто здатен вивільнити потрібні їм сутності з норовливих носіїв.",
    ["Even Nirobin, a self-proclaimed genius of the highest caliber, could not deny the cuteness of his arcane creation."] = "Навіть Ніробін, самопроголошений геній найвищого ґатунку, не міг заперечити чарівність свого таємного витвору.",
    ["Even at this size, these raptors can eviscerate an entire cow in less than 10 seconds."] = "Навіть такі дрібні, ці раптори здатні випатрати цілу корову менш ніж за 10 секунд.",
    ["Even at this tiny size, Direhorns are known to wreak havoc on unsuspecting victims."] = "Навіть такі крихітні, жахорогі здатні чинити розгром серед нічого не підозрюючих жертв.",
    ["Even cockroaches were not strong enough to withstand the foul seepage of demonic corruption."] = "Навіть таргани виявилися не досить витривалими, щоб устояти перед мерзенним просоченням демонічної скверни.",
    ["Even hard sediment poses little challenge to the digging claws of these critters."] = "Навіть тверді відклади не надто кидають виклик рийним пазурам цих створінь.",
    ["Even he cannot put out the fire in my heart."] = "Навіть він не здатен загасити вогонь у моєму серці.",
    ["Even in its juvenile stage, this crab's pincers can break bone."] = "Навіть на юній стадії клешні цього краба здатні ламати кістки.",
    ["Even piglets are not safe from the Legion's corruption.  Although, this one seems harmless enough."] = "Навіть поросята не вбезпечені від скверни Легіону. Хоча це, здається, цілком безневинне.",
    ["Even some of the insects have succumbed to the void. They really do adapt and survive through everything."] = "Навіть декотрі комахи піддалися Порожнечі. Вони й справді пристосовуються та виживають за будь-яких обставин.",
    ["Even the rats of Lordaeron fell to the apothecaries' plague, chewing upon the tainted flesh of the dead."] = "Навіть щури Лордерону полягли від чуми аптекарів, гризучи отруєну плоть мертвих.",
    ["Even the smallest bones don't go to waste in Maldraxxus."] = "У Малдраксусі марно не пропадають навіть найдрібніші кістки.",
    ["Even the smallest creatures in the Shadowlands rely on anima to survive."] = "Навіть найменші створіння Тіньокраю не виживуть без аніми.",
    ["Even the terrifying G'huun was, perhaps, once this cute."] = "Навіть жахливий Ґ'хуун, можливо, колись був отакий милий.",
    ["Even the toughest of crabs with the toughest of shells can succumb to the dark mysteries of the shadows."] = "Навіть найміцніший краб із найтвердішим панцирем може піддатися темним таємницям тіней.",
    ["Even very small things can be corrupted, the apocalypse is for everyone."] = "Зіпсувати можна навіть зовсім крихітні створіння — апокаліпсис для всіх.",
    ["Even with its softer juvenile shell, a young prismatic spireshell still glitters like a diamond."] = "Навіть із м'якшою юнацькою мушлею молода призматична шпилемушля все одно виблискує, мов діамант.",
    ["Even young brineshell are drawn to the line in the sky that meets the waves, it calls them."] = "Навіть юних солепанцирних вабить лінія в небі, що зливається з хвилями. Вона їх кличе.",
    ["Ever wanted to cuddle with a gun? Introducing Trigger, the Cuter Shooter."] = "Колись хотів попригортатися до зброї? Знайомтеся: Курок, наймиліший стрілець.",
    ["Ever watchful, never blinking."] = "Завжди насторожі, ніколи не кліпає.",
    ["Every cook's dream wrapped up in a perfect bundle of metal and bolts. Too bad what he cooks up isn't suitable for humanoid consumption. According to Jard's notes, he intends to make this little guy for his friend, Emily Cole."] = "Мрія кожного кухаря, загорнута в ідеальний пакунок металу та болтів. Шкода лиш, що його страви непридатні для споживання гуманоїдами. Згідно з нотатками Джарда, він збирається зробити цього малюка для своєї подруги Емілі Коул.",
    ["Every deathroach is technically considered vile, but these really take the cake."] = "Формально кожен смертотарган вважається мерзенним, але ці б'ють усі рекорди.",
    ["Every time the mandibles on this vibrate slightly, it is because it gave someone a nightmare."] = "Щоразу, коли його жвала ледь помітно вібрують, це означає, що він навіяв комусь жахіття.",
    ["Evolving in the Voidstorm has really made its smaller inhabitants significantly more aggressive."] = "Еволюція у Войдштормі справді зробила її дрібніших мешканців значно агресивнішими.",
    ["Exceptionally squishy, especially after a big meal."] = "Винятково драглистий, а надто після ситного обіду.",
    ["Experiments in mechanization have driven the few remaining critters in Mechagon to hide or flee."] = "Досліди з механізації змусили нечисленних уцілілих звіряток Мехаґону ховатися або тікати.",
    ["Experiments on this roach have grown it to an enormous size. Who would want that?"] = "Досліди над цим тарганом виростили його до велетенських розмірів. Кому таке могло знадобитися?",
    ["Expert Earthen florists are capable of arranging beautiful floral patterns upon the backs of protosheep."] = "Досвідчені земельні флористи здатні викладати прекрасні квіткові візерунки на спинах протовівців.",
    ["Exposure to magic, minerals, and water pressure has left this crab looking very sharp."] = "Вплив магії, мінералів і тиску води зробив цього краба надзвичайно гострим на вигляд.",
    ["Faithful and ferocious, this bakar is a hero's best friend."] = "Вірний і лютий, цей бакар — найкращий друг героя.",
    ["Farmers will often release maidenbugs to battle the pests that threaten their crops. Buggsy was so good at this that she decided to go pro."] = "Фермери часто випускають дівожуків, щоб боротися зі шкідниками, які загрожують їхньому врожаю. Баґзі робила це так добре, що вирішила стати профі.",
    ["Faster. Stronger. And it can double jump."] = "Швидше. Сильніше. І вміє стрибати подвійно.",
    ["Favored pet of the Defias pirates, this colorful bird is handy for remembering passwords, grocery lists, and cracker recipes."] = "Улюбленець піратів Дефаєс, цей барвистий птах стане у пригоді, щоб запам'ятовувати паролі, списки покупок і рецепти крекерів.",
    ["Favored pet of the goblins of Booty Bay, this colorful bird is renowned for its ability to count coins, tally budgets, and lie about contracts."] = "Улюбленець ґоблінів Бухти Здобичі, цей барвистий птах славиться вмінням лічити монети, зводити бюджети й брехати про контракти.",
    ["Fed up with long hours, low pay, and entitled adventurers whining about sub-standard Winter Veil gifts, these nasty little creatures fled their magical workshops to join up with the Abominable Greench."] = "Ситі по горло довгими годинами, мізерною платнею та зарозумілими шукачами пригод, що скиглять про невдалі подарунки Зимового Серпанку, ці капосні маленькі створіння втекли зі своїх магічних майстерень, щоб приєднатися до Мерзенного Бурчуна.",
    ["Feeds on small leaves and grass when full grown."] = "Дорослою живиться дрібним листям і травою.",
    ["Feel the chill nipping at your toes! A menace of Azeroth, now in festive blue and travel-size!"] = "Відчуйте, як холод кусає за пальці! Загроза Азерота, тепер у святковому блакитному й похідному розмірі!",
    ["Fel Snooters have a very good sense of smell. They will often immolate piles of leaves, scrap or snow to find grass and seeds."] = "Скверношмиги мають дуже гострий нюх. Вони часто спалюють купи листя, мотлоху чи снігу, щоб знайти траву й насіння.",
    ["Ferocious species of dragonhawk, often seen diving down on prey from high in the sky."] = "Лютий вид драконоястреба, якого часто видно, як він пікірує на здобич із небесних височин.",
    ["Fetish shaman are empowered by the spirits of their fallen ancestors. These malevolent spirits are bound to the shaman's tribal spear. Control this spear, and you control the shaman."] = "Шамани-фетиші черпають силу з духів полеглих предків. Ці лихі духи прив'язані до племінного списа шамана. Заволодій списом — і заволодієш шаманом.",
    ["Few of these fiery harbingers remain following Ragnaros' defeat in the Firelands."] = "Небагато цих вогняних провісників лишилося після поразки Рагнароса у Вогняних Просторах.",
    ["Few things are as adorable as a young skyfoal."] = "Мало що буває таке чарівне, як юне небесне лоша.",
    ["Fierce and loyal, Xu-Fu loves to hunt by moonlight.  Once during a full moon, he killed and ate an entire Ironfur Great Bull, prompting a two day nap."] = "Лютий і відданий, Сю-Фу любить полювати під місячним сяйвом. Якось у повню він убив і з'їв цілого Залізошкірого Великого Бика, після чого проспав два дні.",
    ["Finally caught a blind cave skipper. He flopped helplessly for twenty minutes and then let out a burp. Great companion he is!"] = "Нарешті спіймав сліпого печерного стрибунця. Він безпорадно бився двадцять хвилин, а потім відригнув. Чудовий з нього компаньйон!",
    ["Finding freshwater pearls with this crab by your side will be a pinch."] = "Шукати прісноводні перли з цим крабом поряд — раз клешнею клацнути.",
    ["Fire hatchlings are born from the ashes of a phoenix. Dark hatchlings emerge from their shadows."] = "Вогняні малята народжуються з попелу фенікса. Темні малята постають із їхніх тіней.",
    ["Fire it up!"] = "Запалюй!",
    ["Firesting wasps are said to have one of the worst bites of any wasp species, causing a pain like a burning blaze."] = "Кажуть, що оси-вогнежалки кусають чи не найболючіше з-поміж усіх ос, спричиняючи біль, мов від палючого вогню.",
    ["First created in the presence of Highmaul runes, this tiny manafiend really packs a punch!"] = "Уперше створений поряд із рунами Високого Молота, цей крихітний мановраг б'є на диво сильно!",
    ["Five things he can never do without: surging, surging, surging, surging, surging."] = "П'ять речей, без яких він не може жити: вирувати, вирувати, вирувати, вирувати й вирувати.",
    ["Flamboyantly colored and more exuberant than most frogs."] = "Яскраво забарвлена й жвавіша за більшість жаб.",
    ["Floofa smells like citrus fruits when its fur is wet."] = "Коли хутро Флуфи намокає, воно пахне цитрусами.",
    ["Following their introduction to the mainland by the goblins, Bush Chickens have become the entre du jour for Pilgrim's Bounty due to their high deliciousness and low intelligence."] = "Відколи ґобліни завезли чагарникових курей на материк, ті стали головною стравою Пілігримового Достатку завдяки своїй високій смакоті й низькому розуму.",
    ["Fond of slithering through tight spaces, these sea creatures lurk in the wreckage of sunken ships."] = "Полюбляючи прослизати крізь тісні щілини, ці морські створіння чигають в уламках затонулих кораблів.",
    ["Fooled aeons ago by the clever loa of death into a bargain of unceasing service, this tiny ancient being carries out his duties eternally red with rage."] = "Обманута віки тому хитрим лоа смерті в угоді про невпинне служіння, ця крихітна прадавня істота виконує свої обов'язки, вічно червоніючи від люті.",
    ["For Sale: Slightly used Alarm-o-Bot. Rebuilt and refurbished. Still annoying."] = "Продається: трохи вживаний Тривого-бот. Перезібраний і відновлений. Так само набридливий.",
    ["For a creature made of rocks it hovers quite effortlessly."] = "Як для істоти з каменю, вона ширяє доволі легко.",
    ["For a pet that's all mouth, where does anything it eats go? Maldraxxus necromancers have dissected many of these pets, and have no answers."] = "Якщо улюбленець — суцільна паща, то куди дівається все, що він їсть? Некроманти Малдраксусу розтяли безліч таких створінь, але відповіді не мають.",
    ["For being an inanimate object for many centuries, this statue sure moves around really well."] = "Як на неживий предмет, що простояв стільки сторіч, ця статуя рухається таки напрочуд добре.",
    ["For every frog, a prince and princess in waiting."] = "За кожною жабою криється принц чи принцеса, що чекають свого часу.",
    ["For ogres, comparing a female's hair to a clefthoof's shaggy coat is a term of great endearment."] = "Для оґрів порівняти волосся жінки з кошлатою шерстю розкопита — велика похвала й знак прихильності.",
    ["For so many years Mathias Shaw had his eyes and ears gathering intelligence around Azeroth. Now at least some eyes have come home."] = "Стільки років очі й вуха Матіаса Шоу збирали відомості по всьому Азероту. Тепер бодай частина очей повернулася додому.",
    ["For some reason, these blue glimmerflies are often afraid of water."] = "Чомусь ці сині мерехтокрильці часто бояться води.",
    ["Forged in the Throne of Thunder, these tiny creations are servants of the great Dark Animus."] = "Викувані в Троні Грому, ці крихітні витвори слугують великому Темному Анімусу.",
    ["Formed by the latent energies from the Singularity Anchor this Behemoth will be loyal till the end."] = "Сформований латентними енергіями Якоря Сингулярності, цей бегемот буде вірний до кінця.",
    ["Formed by the reckless use of elemental magic, the slumbering earth awakens. It is angry."] = "Сформована необачним використанням стихійної магії, дрімотна земля пробуджується. І вона розлючена.",
    ["Formented in the chaos and dust of Voidstorm. It hasn't even learned how to hate yet!"] = "Зароджене в хаосі й пилу Войдшторму. Воно ще навіть не навчилося ненавидіти!",
    ["Fortunately it mainly devours pet treats."] = "На щастя, він пожирає переважно ласощі для улюбленців.",
    ["Found by Taunka as a newborn pup Specter is fiercely loyal. Yet he is beginning to live up to his name as he stalks into the world."] = "Знайдений таунка новонародженим цуценям, Привид страшенно відданий. Та все ж він починає виправдовувати своє ім'я, скрадаючись світом.",
    ["Found in a dusty egg clutch at the back of Maexxna's lair, these creatures are already undead when they hatch."] = "Знайдені в запорошеній кладці яєць у глибині лігва Мексни, ці створіння вже нежиттю вилуплюються.",
    ["Found in the Firelands and the Molten Core, core hounds can trace their lineage back to the alpha male, Magmadar."] = "Зустрічаються у Вогняних Землях і в Розплавленому Ядрі. Ядрогончаки ведуть свій рід від альфа-самця Маґмадара.",
    ["Found munching on a blackened bone in the Black Forge of Blackrock Foundry, this pup really seems to warm up to you quickly."] = "Знайдене за гризінням обвугленої кістки в Чорній Кузні Ливарні Блекрока, це щеня, схоже, швидко до тебе прихиляється.",
    ["Found predominately underground, some of them prefer the surface. But that's none of my business."] = "Здебільшого живуть під землею, та дехто з них віддає перевагу поверхні. Але це вже не моя справа.",
    ["Found wandering in a small blizzard, this lost goren carries a mining pick to show that he is a jack of all trades."] = "Знайдений за блуканням у невеликій хуртовині, цей загублений ґорен носить кайло, аби показати, що він майстер на всі руки.",
    ["Fragments of souls abound in the Maw, searching for meaning, or an end to their torment. But some just want to give you a hand."] = "У Пащі повно фрагментів душ, що шукають сенсу чи кінця своїм стражданням. Та дехто просто хоче подати тобі руку допомоги.",
    ["Francois, a pompous member of the bockgeoisie, whose wealth and influence was born from the exploitation and labor of the peckletariat."] = "Франсуа, пихатий представник курзуазії, чиї статки та вплив зросли на визиску й праці дзьобетаріату.",
    ["Free-range chickens are difficult to take care of in Hallowfall, what with all the shadow monsters and fish people."] = "Вільновигульних курей важко доглядати в Голловфолі — через усіх цих тіньових монстрів і рибо-людей.",
    ["Frenzies in Nazjatar have learned to operate in large schools or face consumption by the many predators of the deeps."] = "Шаленці Назджатару навчилися триматися великими косяками, інакше їх пожеруть численні хижаки глибин.",
    ["From seed to flower, a tiny terror is grown."] = "Із насінини до квітки виростає крихітний жах.",
    ["Frozen fish are Keiths favorite treat. If you've got frozen fish, you've got a new best friend."] = "Морожена риба — улюблений ласощ Кіта. Якщо маєш морожену рибу, маєш нового найкращого друга.",
    ["Fun for the whole family! A self-detonating robot for all occasions!"] = "Розвага для всієї родини! Робот, що сам себе підриває, на будь-яку нагоду!",
    ["Fungal lashers are typically violent and carnivorous. This diminuative variety is better suited to shyly flail its limbs against fellow small fry."] = "Грибні шмагуни зазвичай жорстокі й хижі. Цей малорослий різновид краще пасує до того, щоб сором'язливо махати кінцівками проти такої ж дрібноти.",
    ["Fungal spores awash in the blood of fallen monstrosities."] = "Грибні спори, омиті кров'ю полеглих гидот.",
    ["Fyrn will be the first one to show up at your birthday party and the last to leaf."] = "Фірн першим прийде на ваш день народження і останнім піде... звітривши.",
    ["Get it while it lasts."] = "Хапай, доки не пропало.",
    ["Getting just one of these fragrant beasts damp is the olfactory equivalent to rolling around in a pile of wet dogs."] = "Намочити бодай одну з цих пахучих тварюк — нюховий еквівалент качання в купі мокрих псів.",
    ["Ghosts are voracious readers."] = "Привиди — невситимі читачі.",
    ["Gill'dan earned his great power by drinking the blood of a demon, which would also have turned his scales green had they not already been that color."] = "Ґілл'дан здобув свою велику силу, випивши кров демона, що також зробило б його луску зеленою, якби вона вже не була такого кольору.",
    ["Gill'el stepped down from leading Frostfin clan to commune with the elements. His return has sparked excitement in all."] = "Ґілл'ел склав із себе провід над кланом Морозоплавця, щоб поспілкуватися зі стихіями. Його повернення всіх потішило.",
    ["Given his boisterous behavior, we can only assume that he became imbued with the void from starting a fight. The question remains; who won?"] = "З огляду на його буйну поведінку, лишається тільки припустити, що він просочився Порожнечею, затіявши бійку. Питання лишається відкритим: хто переміг?",
    ["Gizmo is considered a perfect purrkin, perhaps the best that has ever existed. He is also a ruthless murderer of small critters."] = "Ґізмо вважають бездоганним муркіном, можливо, найкращим за всю історію. А ще він безжальний убивця дрібних звіряток.",
    ["Glamrok followed you back to the ship one day after a particularly good plunder, sensing your keen knack for treasure-finding."] = "Одного дня після особливо вдалого грабунку Ґламрок пішов за тобою на корабель, відчувши твій гострий хист до пошуку скарбів.",
    ["Glowing from within, these sprouts have been blessed with a gift from Eonar."] = "Сяючи зсередини, ці паростки благословенні даром Еонар.",
    ["Glows green, occassionally."] = "Час від часу світиться зеленим.",
    ["Gnawing at the roots of magic trees have given this creature the ability to transcend time itself."] = "Гризучи коріння магічних дерев, ця істота здобула здатність долати самий час.",
    ["Goblin engineering at its finest. Blueprints based on the massive fel reaver in Hellfire Peninsula."] = "Гоблінська інженерія у найкращому вигляді. Креслення засновані на велетенському скверножнеці з Півострова Пекельного Вогню.",
    ["Godlike being now in travel size."] = "Богоподібна істота, тепер у дорожньому форматі.",
    ["Gorm find a way to invade just about anywhere, and the Maw is no exception."] = "Ґорми знаходять спосіб вдертися мало не куди завгодно, і Паща — не виняток.",
    ["Gotta be tough with the scruff."] = "Треба бути жорсткішим зі шкідником.",
    ["Graduation from spiderling to fully-fledged spider monster is far off for this young arachnoid."] = "Перетворення з павучатка на повноцінного павука-монстра ще далеко для цього юного павукоподібного.",
    ["Grotto voles are often confused with mice. Never twice."] = "Печерних полівок часто плутають із мишами. Але ніколи двічі.",
    ["Grumplings are created when the tears of a kidnapped child fall upon a mound of new snow."] = "Бурчунці постають, коли сльози викраденої дитини падають на купку свіжого снігу.",
    ["Guess what its bed is. A piece of bread."] = "Угадай, що йому за ліжко. Шматок хліба.",
    ["Guild pages must be fearless since they are called upon to announce their guild's victories over the Horde in battle."] = "Гільдійські пажі мусять бути безстрашними, адже саме їм випадає сповіщати про перемоги гільдії над Ордою в бою.",
    ["Gulp frogs of the Timeless Isle can feast upon prey several times larger than themselves by slowly digesting the victim externally with a toxic slime."] = "Жаби-ковтачі Позачасового Острова здатні поласувати здобиччю в кілька разів більшою за себе, повільно перетравлюючи жертву ззовні отруйним слизом.",
    ["Gummi baubleworms have an abundance of natural predators, as they are known for their rubbery texture and sweet flavors."] = "Гумові черви-витребеньки мають безліч природних хижаків, адже відомі своєю гумовою текстурою та солодким смаком.",
    ["Gummi the Glow Wyrm has an abundance of natural predators, as it is known for their rubbery texture and sweet flavors."] = "Жуйко, сяйливий вірм, має безліч природних хижаків, адже славиться гумовою текстурою й солодким смаком.",
    ["Gurky is a born performer, though she remains elusive, making public appearances only on the rarest of occasions."] = "Ґуркі — артистка від народження, проте лишається невловною й з'являється на людях лише у найрідкісніших випадках.",
    ["Hailing from the Wetlands, this young dragon is just learning how to hunt, breathe fire, and go on cute destructive rampages."] = "Родом із Заболоченого Краю, цей юний дракон щойно вчиться полювати, дихати вогнем і влаштовувати милі руйнівні погроми.",
    ["Half bird, half elemental, the beautiful Stormwing is truly capable of shock and awe."] = "Напівптах, напівелементаль, прекрасний Штормокрил здатен по-справжньому вразити й приголомшити.",
    ["Hard to spot in the dark, these worms have taught many adventureres a lesson, when sticking their fingers where they don't belong."] = "Цих важко помітних у темряві червів дали науку багатьом шукачам пригод, коли ті пхали пальці туди, куди не слід.",
    ["Has been spotted fighting other whelks for prime food sources."] = "Помічений у бійках з іншими черевоногими за найкращі джерела їжі.",
    ["Hatch-queen of the baby murlocs, Murkastrasza spent many years battling her bitter rival, Deathy."] = "Виводкова королева мурлоченят Муркастраза багато років билася зі своєю заклятою суперницею Смертюшкою.",
    ["Hatched from a long-forgotten egg, this scruffy little eagle has decided you're its new flock, whether you're ready or not."] = "Вилупившись із давно забутого яйця, це куйовджене орлятко вирішило, що ти — його нова зграя, готовий ти до цього чи ні.",
    ["Have a hoppy day!"] = "Стрибучого тобі дня!",
    ["Having the bad luck to face many void corruption hostilities, Cappy has persevered. He is one of the few creatures to make it through mostly unscathed."] = "Маючи нещастя стикатися з численними проявами скверни порожнечі, Кеппі вистояв. Він одне з небагатьох створінь, що пройшли крізь усе майже неушкодженими.",
    ["He has a heart of gold. Literally. These shiny good-boys are all the rage with affluent gnomes everywhere."] = "У нього золоте серце. Буквально. Ці блискучі песики — справжній шал серед заможних ґномів усюди.",
    ["He hears little hearts melting. Faster now!"] = "Він чує, як тануть маленькі серця. Швидше!",
    ["He is a lover, not a battler."] = "Він коханець, а не боєць.",
    ["He is a real trooper, faithfully tagging along with Kojo for years. He enjoys hide and seek as well as some serious shell sliding."] = "Справжній молодець, що віддано супроводжує Коджо вже багато років. Полюбляє хованки та солідні ковзання на панцирі.",
    ["He loves to dance and wave and play with you! He melts after Winter Veil, but don't worry; he'll be back again someday!"] = "Він обожнює танцювати, махати й гратися з тобою! Після Свята Зимової Заслони він тане, та не хвилюйся — колись він повернеться знову!",
    ["He loves to play in the mud! Then he likes to give you a hug!"] = "Він обожнює бабратися в багнюці! А потім любить тебе обійняти!",
    ["He may not be the fastest snail, but he has the heart of a champion."] = "Може, він і не найшвидший слимак, та в нього серце чемпіона.",
    ["He seems to be very angry, but it's possible he's just hungry."] = "Він здається дуже сердитим, але цілком можливо, що просто голодний.",
    ["He'll plunder your provolone, turn your ship to swiss, then get your gouda. He's a true muenster and the scourge of the seven bries."] = "Він пограбує твій проволоне, перетворить корабель на швейцарський сир, а тоді добереться до ґауди. Це справжній мюнстер і гроза семи брі.",
    ["He's a little jumpy... especially around the face."] = "Він трохи полохливий... особливо коли йдеться про обличчя.",
    ["He's humble, clairvoyant, and delicious with cranberry sauce."] = "Він скромний, ясновидющий і смачний із журавлиновим соусом.",
    ["He's just a bit tuckered out. He's just a little guy."] = "Він просто трохи втомився. Він же ще малий.",
    ["He's just so happy to be programmed to exist."] = "Він просто страшенно щасливий, що його запрограмували існувати.",
    ["He's one cowardly companion, because he's got no guts..."] = "Цей супутник справжній боягуз, адже в нього немає нутрощів...",
    ["He's scheming. Smirking. Don't trust him."] = "Він замишляє лихе. Шкіриться. Не довіряй йому.",
    ["He's slightly evil but extremely narcoleptic. Keep him away from critters!"] = "Він трохи лихий, зате страшенно сонливий. Тримайте його подалі від дрібноти!",
    ["He's very friendly, but any amount of snuggles is going to result in you getting a nasty shock."] = "Він дуже доброзичливий, але будь-які пестощі обернуться для тебе добрячим ударом струму.",
    ["Hedgehogs are not at all fond of croquet nor flamingos."] = "Їжаки геть не полюбляють ані крокету, ані фламінго.",
    ["Hello. Is it me you're looking for?"] = "Вітаю. Чи не мене ти шукаєш?",
    ["Hides in shell to escape claws of nearby crabs."] = "Ховається в панцир, аби втекти від клешень сусідніх крабів.",
    ["Hiding among the reeds near muck pools, juvenile mire creepers patiently waiting for easy prey to approach."] = "Ховаючись серед очерету біля мулких калюж, молоді багнолази терпляче чекають, доки наблизиться легка здобич.",
    ["Higitus figi- hockity pocki- abracadab- prestidig--oh, pinfeathers!"] = "Гігітус фіґі- гокіті покі- абракадаб- престідіг--ой, пір'їнки б тобі!",
    ["His hate is not diminished by size."] = "Його ненависть не меншає від розміру.",
    ["His name is Mister Toots because of the melodious sounds he can make with his trunk."] = "Його звуть Пан Дудик через мелодійні звуки, які він видає своїм хоботом.",
    ["His pink antlers make him the life of any party."] = "Його рожеві роги роблять його душею будь-якої гулянки.",
    ["His tentacles give you the best hug your brain has ever felt."] = "Його щупальця дарують найкращі обійми, які лише відчував твій мозок.",
    ["His tiny legs make him more aerodynamic."] = "Його крихітні ніжки роблять його обтічнішим.",
    ["Hope, like this phoenix, rises from the ashes of shattered dreams."] = "Надія, як цей фенікс, постає з попелу розбитих мрій.",
    ["Hopes that someday it can grow up to destroy villages, just like mommy."] = "Сподівається, що колись виросте й нищитиме села — точнісінько як матуся.",
    ["How do you kill that which lives in garbage?"] = "Як убити те, що живе у смітті?",
    ["How exactly does one swim through a void? This creature knows, but isn't telling."] = "Як саме плисти крізь порожнечу? Ця істота знає, але не каже.",
    ["How is a vulpin different than a fox? That is a good question."] = "Чим вульпін відрізняється від лиса? Гарне питання.",
    ["How many bogs has it hopped? No one knows."] = "Скільки боліт він перескакав? Ніхто не знає.",
    ["How the Mad Merchant got his hands on one of these otherworldly creatures is unknown. What we do know is, he knows it's valuable."] = "Як Божевільному Торговцю вдалося роздобути одне з цих потойбічних створінь — невідомо. Що ми знаємо напевно, так це що він знає, яке воно цінне.",
    ["How the goblin Landro Longshot initially came into possession of the lichling remains a mystery, but he was all too eager to wager it in a game of cards."] = "Як ґоблін Ландро Лонґшот колись запопав цього лічика — лишається загадкою, та він з надмірною охотою поставив його на кін у грі в карти.",
    ["How this siphonmite snuck its way into a stasis container is anyone's guess."] = "Як цей поглинокліщ примудрився прослизнути в контейнер стазису — лишається тільки гадати.",
    ["Howling Fjord teems with the ever shifting cycle of life. When a creature dies, its body is quickly consumed by maggots, which in turn pass those nutrients on to a number of other creatures."] = "Виючий Фіорд вирує безперервним коловоротом життя. Коли істота гине, її тіло швидко поглинають личинки, які своєю чергою передають поживні речовини низці інших створінь.",
    ["Hundreds of these wisps came together to defend Hyjal from Archimonde and save the world."] = "Сотні таких вогників зібралися разом, щоб захистити Гіджал від Архімонда й урятувати світ.",
    ["Hungry? Try eating your foes!"] = "Зголоднів? Спробуй з'їсти своїх ворогів!",
    ["Hunted by locals for years, this is an extremely rare specimen."] = "Роками вистежуваний місцевими, це надзвичайно рідкісний екземпляр.",
    ["Hunted for its beautifully patterned skin, this majestic species thrives alongside Azeroth's lush rivers."] = "На цей величний вид полюють заради його чудово візерункованої шкіри; він буяє вздовж пишних річок Азероту.",
    ["Hunted to near extinction for its feathers, the kaliri has developed keen senses."] = "Винищені майже до зникнення заради пір'я, каларі розвинули гострі чуття.",
    ["Hunted to near extinction for its feathers, this kaliri has developed keen senses."] = "Винищений майже до зникнення заради свого пір'я, цей каларі розвинув гострі чуття.",
    ["Hunters value these critters more for their companionship than their pelts."] = "Мисливці цінують цих звіряток радше за товариство, ніж за хутро.",
    ["Hunts for food just below the water's surface on the coast of Darkshore."] = "Полює на здобич ледь під поверхнею води біля узбережжя Темнобережжя.",
    ["Hydrath Water Droplets are also an excellent skin moisturizer."] = "Краплі води Гідрат також чудово зволожують шкіру.",
    ["I always feel like somebody's watching me."] = "Мене не полишає відчуття, ніби хтось за мною стежить.",
    ["I am Broot."] = "Я є Брут.",
    ["I jump, Jon. It's what I do."] = "Я стрибаю, Джоне. Таке вже моє ремесло.",
    ["I wish that I could bind the tides and bend them to my will. But in its depths the sea abides and waits for no one still."] = "Хотів би я скувати припливи й підкорити їх своїй волі. Та в глибинах своїх море перебуває й нікого не чекає доволі.",
    ["Ichabod began his existence as a prototype for the fearsome harvest golems terrorizing the farmers of Westfall, but a little gnomish ingenuity has since made him far less likely to attack your knees."] = "Ічабод почав своє існування як прототип грізних жниварських ґолемів, що тероризують фермерів Західного Краю, та завдяки дрібці ґномської винахідливості він тепер куди менш схильний нападати на твої коліна.",
    ["Identified by the signature coloring of their many legs, these spiders are known for elaborate dances used to threaten and confuse foes."] = "Цих павуків упізнають за характерним забарвленням численних лапок, а ще вони відомі вигадливими танцями, якими залякують і збивають з пантелику ворогів.",
    ["If Roland has taught you anything, it's that friendship comes at a price.\n\nThat price is lots and lots of cheese."] = "Якщо Роланд чогось вас і навчив, то того, що дружба має свою ціну.\n\nА ця ціна — багато-багато сиру.",
    ["If a bile larva stays burrowed for an extended period of time they begin to lose their pigment. When they finally do emerge, they can be quite ravenous."] = "Якщо жовчна личинка довго лишається в норі, вона починає втрачати пігмент. А коли нарешті виповзає назовні, буває вкрай ненажерливою.",
    ["If a detached hand claps by itself inside of Torghast, can the Jailer hear it?"] = "Якщо відрубана долоня плескає сама собі в надрах Торгасту, чи чує це Тюремник?",
    ["If a duck quacks in the woods and nobody is around to hear it, does it even exist?"] = "Якщо качка крякає в лісі, а навколо нікого, хто б її почув, то чи існує вона взагалі?",
    ["If a female lizard does not lay her clutch in a well camouflaged area, her eggs will likely be devoured by Lashtail Raptors."] = "Якщо ящірка-самиця не відкладе кладку в добре замаскованому місці, її яйця, найпевніше, пожеруть раптори-батоґхвости.",
    ["If a live maggot eats the dead, what does an undead maggot eat?"] = "Якщо жива личинка їсть мертвих, то що їсть личинка-небіжчик?",
    ["If bananas grew in caves, they would be Rango's favorite food."] = "Якби банани росли в печерах, вони були б улюбленою стравою Ранґо.",
    ["If mana becomes scarce these wyrm look for other sources of energy to feed on."] = "Коли мани стає мало, ці вірми шукають інші джерела енергії, щоб живитися.",
    ["If not for being extremely accident prone, the fjord rat might take over the world."] = "Якби не його надзвичайна схильність до прикрих пригод, фіордовий щур міг би захопити світ.",
    ["If this species spits venom at its prey, is it still technically considered venom, or just really gross?"] = "Якщо цей вид плює отрутою на свою здобич, то це формально все ще отрута чи просто щось дуже бридке?",
    ["If you are diving into the deeps and one of these attaches itself to your leg, don't panic -- they're relatively harmless."] = "Якщо ти пірнаєш у глибини й одна з них чіпляється до твоєї ноги — не панікуй, вони відносно нешкідливі.",
    ["If you can beat them, stitch them!"] = "Кого здолав — того й заший!",
    ["If you count the number of times its wings beat per minute, you can calculate how long it will be until this little terror will sting you."] = "Якщо порахувати, скільки разів за хвилину б'ють його крильця, можна обчислити, за скільки часу це маленьке страховисько тебе вжалить.",
    ["If you ever have an outdoor feast in the Emerald Dream, look out for wild blueloos. A blueloo won't steal your picinic basket, but it will politely ask for some snacks."] = "Якщо ви колись влаштуєте бенкет просто неба у Смарагдовому Сні, стережіться диких блюлу. Блюлу не вкраде ваш кошик для пікніка, але ввічливо попросить трохи перекусити.",
    ["If you feel a slight gust that made you shiver, that was probably Drafty."] = "Якщо ти відчув легкий порив, від якого здригнувся, — це, мабуть, був Протяжко.",
    ["If you go chasing snowshoe rabbits, you know you're going to fall."] = "Як женешся за біляками, то знай — неодмінно впадеш.",
    ["If you have a fish odds are Lil' Chompers will be nearby."] = "Якщо маєш рибу, найімовірніше, Малий Хрумчик буде десь поруч.",
    ["If you have milk tea, keep an eye on it. Brewthieves love to pop out of the shadows and steal tea. Even worse, once in paw they love to show off their newly acquired beverage."] = "Якщо маєш чай з молоком, не спускай з нього очей. Чаєкради полюбляють вискакувати з тіней і красти чай. Ба гірше: щойно напій опиняється в лапах, вони обожнюють хизуватися щойно здобутою здобиччю.",
    ["If you hold this up to your ear, you can hear whispers of the Old Gods. Just like a seashell!"] = "Якщо піднести його до вуха, можна почути шепіт Прадавніх Богів. Зовсім як мушлю!",
    ["If you mat their silvery feathers down very carefully, it almost forms a mirror-like surface."] = "Якщо дуже обережно пригладити їхнє сріблясте пір'я, утвориться майже дзеркальна поверхня.",
    ["If you received points for causing mischief while teleporting around as a tiny adorable vulpin, Renny would be on top of the leaderboard."] = "Якби давали бали за капості, скоєні під час телепортацій в образі крихітного милого вульпіна, Ренні очолив би таблицю лідерів.",
    ["If you think the skunks of the Emerald Dream smell bad, pray that you never smell the skunks of the Emerald Nightmare."] = "Якщо ви думаєте, що скунси Смарагдового Сну смердять, моліться, щоб вам ніколи не довелося понюхати скунсів Смарагдового Жахіття.",
    ["Imagine being so slow moving that moss grows on your back. Couldn't be me."] = "Уяви, що рухаєшся так повільно, що в тебе на спині росте мох. Зі мною такого б не сталося.",
    ["Imagine the size of the birds that eat these bugs."] = "Уявіть, які завбільшки птахи, що їдять цих комах.",
    ["In Draenor, the Zangar Sea seeks to overtake the land by releasing thousands of these spores and slowly growing inland over time."] = "На Дреноре Море Занґар прагне поглинути сушу, випускаючи тисячі цих спор і поволі розростаючись углиб материка.",
    ["In Maldraxxus, plague has a strange habit of finding its way back to you."] = "У Малдраксусі чума має дивну звичку знову й знову повертатися до тебе.",
    ["In a dark place unknown to all, the seabed writhes with the children of Nalaada, a carpet of life and death."] = "У темному, нікому не відомому місці морське дно кишить дітьми Налаади — килимом життя і смерті.",
    ["In a miracle of dreams and wishes, Waxwick awoke and climbed off a kobold's head to pursue her own path."] = "У диві мрій і бажань Воскова Свічка прокинулася й злізла з голови кобольда, щоб піти власним шляхом.",
    ["In a pinch, Venture Co. workers might use these creatures for some impromptu demolition. Get it? Pinch?"] = "У скруту робітники Підприємливої компанії можуть використати цих створінь для імпровізованих підривних робіт. Утямив? У скруту?",
    ["In case of darkness, this little elemental is an infinite source of a soothing green glow."] = "У темряві цей маленький елементаль стане невичерпним джерелом заспокійливого зеленого сяйва.",
    ["In his home realm, he commanded an army of ten million demons. Now his power is yours to command. Go make him fight a chicken!"] = "У рідному світі він командував армією з десяти мільйонів демонів. Тепер його сила підвладна тобі. Іди-но змусь його битися з куркою!",
    ["In its big eyes you can see your own reflection. You also see everything else because its eyes are so big."] = "У його великих очах ти бачиш власне відображення. А ще все інше, бо очі в нього такі великі.",
    ["In life, Gizmo never hurt a soul. Having been brutally murdered, he now considers violence."] = "За життя Ґізмо ніколи й мухи не скривдив. Та після брутального вбивства він тепер замислюється про насильство.",
    ["In life, Kel'Thuzad betrayed the Kirin Tor and created the Cult of the Damned. In death, he serves the Scourge as the Archlich Lord of Naxxramas."] = "За життя Кел'Тузад зрадив Кірін Тор і створив Культ Проклятих. У смерті він служить Погибелі як архіліч, володар Наксрамаса.",
    ["In one invasion of the Haunted Mines, a team of heroes only managed to collect a single skull. The golem that resulted, too small to do much damage to the enemy towers, wandered off into the Nexus, eventually finding its way to Azeroth."] = "Під час одного вторгнення до Примарних Копалень загін героїв спромігся зібрати лише один-однісінький череп. Утворений ґолем, надто малий, щоб завдати ворожим вежам відчутної шкоди, забрів у Нексус і зрештою знайшов дорогу до Азероту.",
    ["In the ancient fables, the first Tolai hare strode across the gulf between the stars before it upset them and they tumbled from the heavens to the world below."] = "У стародавніх казках перший заєць толай ступав через прірву між зорями, доки не сполохав їх, і вони посипалися з небес на світ унизу.",
    ["In the deep forest, even the small creatures must have the ferocity to fend for themselves."] = "У глибокому лісі навіть малі створіння мусять мати лють, аби постояти за себе.",
    ["In the depths of the Endless Sea, strange thalassic horrors lurk. Not this fella, though. He's completely normal."] = "У глибинах Безкрайого Моря зачаїлися дивні таласійські жахіття. Утім, не цей хлопака. Він цілком нормальний.",
    ["In the end, we are all wrought from stardust."] = "Зрештою, усі ми створені зі зоряного пилу.",
    ["In the eternal balance of frost and fire, the raging flames fuel many aggressive fronts."] = "У вічній рівновазі криги й вогню розлючене полум'я живить безліч войовничих фронтів.",
    ["In the eternal balance of frost and fire, the stolid ice forms a defense without measure."] = "У вічній рівновазі криги й вогню незворушний лід утворює незмірний захист.",
    ["In the fathomless depths beyond the Eternal Palace, minds are lost in the blackness."] = "У бездонних глибинах за Вічним Палацом розум губиться в темряві.",
    ["In the fertile grounds of the Wailing Caverns, nothing truly dies."] = "На родючих ґрунтах Печер Стогонів ніщо не вмирає по-справжньому.",
    ["In the jungle, every leaf could conceal a frog. Stop to check and it could be long gone."] = "У джунглях кожен листок може ховати жабу. Спинишся перевірити — а її вже й слід прохолов.",
    ["In the lean times when adrift at sea, the sight of a rat was a welcome one."] = "У голодні часи, коли дрейфуєш у морі, вигляд щура був бажаним видовищем.",
    ["In the lightless caverns, a bright shell color doesn't make you any worse at ambushing."] = "У позбавлених світла печерах яскравий колір панцира анітрохи не заважає влаштовувати засідки.",
    ["In the lightless trenches and chasms of the Great Sea, life still exists."] = "У позбавлених світла западинах і проваллях Великого Моря життя досі існує.",
    ["In the moonlight their wings create a glittering aura, giving the illusion of twinkling starlight."] = "У місячному сяйві їхні крила створюють мерехтливу ауру, що нагадує тремтливе світло зірок.",
    ["In the mountain air, frost lingers upon the grass as a storm rolls in."] = "У гірському повітрі іній чіпляється за траву, поки насувається буря.",
    ["In the ultimate demonstration of stubborness, this once-living nannie simply refused to die."] = "У найвищому вияві впертості ця колись жива кізонька просто відмовилася вмирати.",
    ["In the wrong place at the wrong time."] = "Не в тому місці й не в той час.",
    ["Incredibly lifelike, this enchanted wax statue could pass for a real mole. If petting it didn't cause it to melt, that is."] = "Неймовірно схожа на живу, ця зачарована воскова статуя могла б зійти за справжнього крота. От тільки якщо погладити її, вона розтане.",
    ["Indigenous to the peaks of Kun-Lai Summit, this rare yeti is much more dangerous than it looks."] = "Корінний мешканець вершин Піка Кун-Лай, цей рідкісний єті значно небезпечніший, ніж здається.",
    ["Infamous psionic battering ram of the Protoss, Zeradar is also the only archon that can utilize psionic storm. Power overwhelming!"] = "Сумнозвісний псіонічний таран протоссів, Зерадар — також єдиний архонт, здатний застосувати псіонічну бурю. Нездоланна сила!",
    ["Infested cubs still listen for the telltale buzzing of bees even though they can no longer taste honey."] = "Заражені ведмежата досі прислухаються до промовистого дзижчання бджіл, хоча вже й не відчувають смаку меду.",
    ["Infused etherwyrms can be used as portable anima batteries, but they must be trained not to flee at the sight of combat."] = "Просякнуті ефіровірми можуть правити за переносні батареї аніми, та їх треба привчати не тікати, забачивши бій.",
    ["Infused with the elementium ore used to plate the great dragon Deathwing, and one of the last remnants of the madness that nearly consumed Azeroth."] = "Просочений елементієвою рудою, якою броньовано великого дракона Дезвінга, він є одним з останніх відлунь безумства, що мало не поглинуло Азерот.",
    ["Inspired by the phalynx of Bastion, Engineers have modified the design to be approximately 300% more adorable."] = "Натхненні фаланксами Бастіону, інженери змінили конструкцію так, щоб вона стала приблизно на 300% миліша.",
    ["Introducing the youngest member of the Xuen Dynasty! Daughter of Ban-Lu. Niece of Xu-Fu. Granddaughter of the celestial Xuen... It's Ban-Fu!"] = "Зустрічайте наймолодшу представницю династії Сюень! Донька Бан-Лу. Небога Сюй-Фу. Онука небесного Сюеня... Це Бан-Фу!",
    ["Iron, iron, steel and fire.  Bellows, gears, plates, and wire."] = "Залізо, залізо, сталь і вогонь. Міхи, шестерні, пластини й дріт.",
    ["Ironically, she has a warm personality."] = "Як не дивно, вона має теплу вдачу.",
    ["Is it a snail? Is it a dream? Is it the dream of a sleeping snail?"] = "Це слимак? Це сон? Це сон сплячого слимака?",
    ["Is it normal for a fish to have fangs?"] = "Хіба нормально, щоб у риби були ікла?",
    ["Is it possible to drink bones? Not without a positive mental attitude it's not!"] = "Чи можливо пити кістки? Тільки не без позитивного бойового настрою!",
    ["Is it possible to rise from the ashes of time? Gerald thinks so and he will not be denied."] = "Чи можливо постати з попелу часу? Джеральд певен, що так, і він не дасть собі відмовити.",
    ["Is it three white stripes on a brown tail, or two brown stripes on a white tail?"] = "Це три білі смуги на бурому хвості чи дві бурі смуги на білому хвості?",
    ["Is that a venomous worm in your pocket or... why is that in your pocket?"] = "Це отруйний хробак у твоїй кишені чи... чого він узагалі в твоїй кишені?",
    ["Is the ooze holding the bones in, or are the bones holding the ooze together?"] = "То слиз утримує кістки всередині, чи кістки тримають слиз докупи?",
    ["Is the void glow in addition to their natural glow, or does it replace it? The world may never know."] = "Це сяйво Порожнечі додається до їхнього природного світіння, а чи заступає його? Світ, певно, ніколи не дізнається.",
    ["Isn't baby elderhorn an oxymoron?"] = "Хіба «дитинча-старорог» — не оксиморон?",
    ["Isn't she just the sweetest little helicid?"] = "Хіба ж вона не наймиліший геліцидик?",
    ["It always wakes up dancing. What a happy little tree!"] = "Він завжди прокидається в танці. Яке щасливе деревце!",
    ["It can swallow three times its own body weight in blood."] = "Воно здатне ковтнути крові втричі більше за власну вагу.",
    ["It could become anything. It could become *everything*. In the meantime, it's... this."] = "Воно могло б стати чим завгодно. Воно могло б стати *усім*. А поки що воно... ось таке.",
    ["It disappears as quietly and mysteriously as the mist."] = "Зникає так само тихо й загадково, як туман.",
    ["It doesn't bite. It rips and tears."] = "Воно не кусає. Воно роздирає й шматує.",
    ["It doesn't even bother to chew its food."] = "Воно навіть не завдає собі клопоту жувати їжу.",
    ["It doesn't seem to know where it is, but it's happy to be here!"] = "Схоже, воно не знає, де перебуває, але радіє, що воно тут!",
    ["It doesn't take a very large ooze to eat a gnome."] = "Не треба надто великого слизовика, щоб з'їсти гнома.",
    ["It enjoys long walks on the beach."] = "Вона полюбляє довгі прогулянки пляжем.",
    ["It feeds on fear, but is generally too cute to inspire terror on its own."] = "Воно живиться страхом, але загалом надто миле, щоб самотужки наганяти жах.",
    ["It glides through the air with shadowy wings and a trail of eerie whispers."] = "Воно ширяє в повітрі на тіньових крилах, лишаючи слід з моторошного шепоту.",
    ["It got its name because its favorite food is fondue."] = "Він дістав свою назву, бо його улюблена страва — фондю.",
    ["It has been referred to as \"the flying gem\" due to its similar luster to the finest of sapphires."] = "Його прозвали «летючим самоцвітом» через блиск, схожий на найчистіші сапфіри.",
    ["It has bright feathers. What else is there to say?"] = "У нього яскраве пір'я. Що тут ще скажеш?",
    ["It has no eyes, but it always seems to be staring at you."] = "У нього немає очей, та все ж здається, ніби воно постійно витріщається на тебе.",
    ["It has one solution to all of its problems: give em' a lashing."] = "У нього одне розв'язання для всіх клопотів: відлупцювати язиком.",
    ["It is a riddle wrapped in a mystery inside an enigma."] = "Це загадка, повита таємницею всередині головоломки.",
    ["It is a well-established fact that wasps produce far higher quality honey than bees. Well-established in very, very small circles of wasp farmers."] = "Загальновідомий факт, що оси виробляють набагато якісніший мед, ніж бджоли. Загальновідомий у дуже, дуже вузькому колі осоводів.",
    ["It is almost as if a wooden toy has come to life. Keep this pet away from children."] = "Це майже так, ніби дерев'яна іграшка ожила. Тримай цього улюбленця подалі від дітей.",
    ["It is always C'Thuffer. Always."] = "Це завжди Ц'Туфер. Завжди.",
    ["It is an honor in the Sentinel Army to be entrusted with the care of an owl born from the boughs of the great tree Teldrassil."] = "У війську Вартових велика честь — дістати під опіку сову, народжену в гіллі великого дерева Телдрассіл.",
    ["It is believed that the green coloration and stripes on the tiny green carp serve as camouflage in the waters of the Jade Forest, Valley of the Four Winds and the Krasarang Wilds. Dedicated fishermen can sometimes befriend one."] = "Вважається, що зелене забарвлення та смужки крихітного зеленого коропа слугують маскуванням у водах Нефритового Лісу, Долини Чотирьох Вітрів та Нетрів Красаранґ. Завзяті рибалки часом можуть із такою заприятелювати.",
    ["It is bewildering how the most arrogant and stuck up of the Azerothian Archivists can't help but create the most adorable arcane familiars. Perhaps Nirobin does have a soft side..."] = "Дивовижно, як найбільш зарозумілі та пихаті з Азеротських архіваріусів не можуть утриматися й створюють найчарівніших таємних фамільярів. Можливо, в Ніробіна таки є м'яка сторона...",
    ["It is difficult to believe that Shen-zin Su, on whose shell rests all of the Wandering Isle, began life as a tiny emerald turtle."] = "Важко повірити, що Шень-цзінь Су, на чиєму панцирі спочиває весь Мандрівний Острів, починав життя крихітною смарагдовою черепахою.",
    ["It is not advisable to hug a sludge feeler. Those stains never wash out."] = "Обіймати багномацака не радимо. Ті плями вже ніколи не відіпрати.",
    ["It is rumored that these honey bees can detect the pollen of a newly blossomed plant in northern Stormsong Valley when they are all the way down in Drustvar."] = "Подейкують, що ці медоносні бджоли здатні відчути пилок щойно розквітлої рослини на півночі Долини Штормової Пісні, навіть перебуваючи аж унизу, у Друстварі.",
    ["It is said that from the moment they hatch snapdragons are independent from their parents, though the more recent venture to Nazjatar has seemingly debunked this theory."] = "Кажуть, що з миті вилуплення снапдракони незалежні від батьків, хоча нещодавня вилазка до Назжатару, схоже, спростувала цю теорію.",
    ["It is said that some animals dream in black and white. This animal only dreams in green."] = "Кажуть, що деяким тваринам сняться чорно-білі сни. Цій тварині сняться лише зелені.",
    ["It is said that the Astral Emperor wove these creatures from the stuff of the stars themselves. It is also said that he used only the cutest star-stuff."] = "Кажуть, що Астральний Імператор виткав цих створінь із самої зоряної матерії. А ще кажуть, що він використовував лише найчарівнішу зоряну матерію.",
    ["It is said that the bite of a snapdragon pup is many times stronger and more potent than the adults."] = "Кажуть, що укус щеняти-снапдракона в багато разів сильніший і дошкульніший за укус дорослих особин.",
    ["It is unknown how Lady Vashj empowers these Fen Striders with their mind-bending powers; even at an early age this creature shows significant psychic ability."] = "Невідомо, як пані Вашш наділяє цих болотоходів силами, що бентежать розум; навіть у ранньому віці це створіння виявляє неабиякі парапсихічні здібності.",
    ["It is very unclear whether this slime started with all of those eyes inside of it, or if those are \"leftovers\"."] = "Достеменно невідомо, чи цей слиз від початку мав усередині стільки очей, чи це просто «недоїдки».",
    ["It just floats along..."] = "Воно просто пливе собі...",
    ["It keeps looking at me. I think it wants to bite me."] = "Воно весь час на мене дивиться. Гадаю, воно хоче мене вкусити.",
    ["It likes to be petted behind the fins."] = "Він полюбляє, коли його чухають за плавцями.",
    ["It looked up at you with those huge black eyes and seemed to ask, 'Are you my mommy?'"] = "Воно глянуло на тебе тими величезними чорними очима, ніби питаючи: «Ти моя мама?»",
    ["It looks like a duck and it smells like a duck and it quacks like a duck... what's a duck?"] = "Воно схоже на качку, пахне як качка й крякає як качка... а що таке качка?",
    ["It only has two teeth, and they both mean business."] = "У нього лише два зуби, і обидва налаштовані рішуче.",
    ["It really seems to want to touch you, but why?"] = "Воно справді ніби прагне торкнутися тебе, але навіщо?",
    ["It seems like a trick to the eyes, but the eternal strider can walk across water, its small feet never breaking the surface."] = "Це здається обманом зору, але вічний крокун може ходити по воді — його дрібні лапки ніколи не порушують поверхні.",
    ["It seems that mice are completely incapable of resisting cheese even in the face of imprisonment, injury, or death."] = "Схоже, миші геть нездатні встояти перед сиром, навіть якщо це загрожує полоном, каліцтвом чи смертю.",
    ["It sits anywhere it wants to, but it prefers to sit on laps."] = "Воно сідає де завгодно, але найбільше любить сидіти на колінах.",
    ["It thinks you taste like chicken too."] = "Воно теж вважає, що ви на смак як курятина.",
    ["It totally fell into a pit of acid but then it came back ten times stronger! So cool!!!"] = "Він узагалі-то впав у яму з кислотою, але потім повернувся вдесятеро сильнішим! Так круто!!!",
    ["It waits and watches from the shadows. Softly. Softly."] = "Воно чекає й спостерігає з тіней. Тихо. Зовсім тихо.",
    ["It will probably grow bigger. Probably."] = "Він, мабуть, ще підросте. Мабуть.",
    ["It's a bird! It's a cat! It's... biting me..."] = "Це птах! Це кіт! Це... кусає мене...",
    ["It's a bird! It's a gyrocopter! No wait, it's something way worse. Run."] = "Це птах! Це гірокоптер! Ні, стривай, це щось куди гірше. Тікай.",
    ["It's a repulsive creature. No one should want this."] = "Це огидне створіння. Такого ніхто не повинен прагнути.",
    ["It's best not to ask how Grunch acquired all these gifts because you know it's not because he's been nice."] = "Краще не питати, як Ґрунч роздобув усі ці подарунки, бо ти ж знаєш — не за те, що він був чемним.",
    ["It's called a mule because of its big ears. Also been known to transport black market bloodthistle over the border to Quel'Thalas."] = "Його звуть мулом через великі вуха. Відомий ще й тим, що переправляє контрабандний кровочортополох через кордон до Кел'Таласу.",
    ["It's hard to be sure since it has no face, but this thing seems to like you."] = "Важко сказати напевне, адже в нього немає обличчя, та, схоже, ця штука тебе вподобала.",
    ["It's hard to know what's more dangerous: the teeth or the tail."] = "Важко сказати, що небезпечніше: зуби чи хвіст.",
    ["It's just a little mad."] = "Він просто трохи лютий.",
    ["It's just constantly barfing plague fluid. Where does it come from? Where does it go?"] = "Воно безперестанку вивергає чумну рідину. Звідки вона береться? Куди дівається?",
    ["It's just like a regular spider, but fel."] = "Він геть як звичайний павук, тільки сквернений.",
    ["It's lame to have a hunchbacked crony mewl 'yes master' when you can just get a robot to do it for free."] = "Це відстій — тримати горбатого посіпаку, що скиглить «так, господарю», коли можна просто завести робота, який робитиме це безкоштовно.",
    ["It's more cute than spooky."] = "Вона радше мила, ніж лячна.",
    ["It's never too soon to summon this tiny aspect of the dread Firelord."] = "Ніколи не зарано прикликати цю крихітну подобу грізного Володаря Вогню.",
    ["It's not clear who the original owner of this arm was, but they're not getting it back now."] = "Незрозуміло, хто був первісним власником цієї руки, та назад він її вже не отримає.",
    ["It's not easy having red fur during the winter, but in the autumn it's very fashionable."] = "Узимку нелегко мати руде хутро, зате восени це дуже модно.",
    ["It's not really all that savage, just a little crabby."] = "Він насправді не такий уже й лютий, просто трохи буркотливий.",
    ["It's not really an orphan. The name just makes you feel better about abducting it."] = "Насправді воно не сирота. Просто з такою назвою тобі легше на душі від того, що ти його викрав.",
    ["It's not the most original anti-hero name. But it promises to be a compelling crossover."] = "Не найоригінальніше ім'я для антигероя. Але обіцяє стати захопливим кросовером.",
    ["It's only mildly irritated."] = "Воно лише трохи роздратоване.",
    ["It's only somewhat interested."] = "Їй лише ледь цікаво.",
    ["It's popping wings! Run!"] = "У нього виростають крила! Тікай!",
    ["It's quite possible this creature is aging backwards. It looks a bit younger every time you see it."] = "Цілком можливо, що ця істота старіє навпаки. Щоразу вона виглядає трохи молодшою.",
    ["It's really unclear what's 'multi' about them."] = "Геть незрозуміло, що в них «мульти».",
    ["It's red because it like, killed so many bad guys! It's all their blood! And it's on fire too!"] = "Він червоний, бо типу повбивав стільки поганців! Це все їхня кров! А ще він у вогні!",
    ["It's red, so it must fly faster."] = "Він червоний, отже, має літати швидше.",
    ["It's said the feathers glitter like gold when the rising sun shines upon them."] = "Кажуть, його пір'я виблискує, наче золото, коли на нього падає світло вранішнього сонця.",
    ["It's sting is worse than... well nothing, really. Are you sure you want to keep this as a pet?"] = "Його укус болючіший за... та власне ні за що. Ти впевнений, що хочеш тримати його як улюбленця?",
    ["It's tried to cut down, but magic is just so tasty."] = "Воно намагалося стримуватись, але магія просто надто смачна.",
    ["Its eyes can see the flick of a mouse tail from leagues away."] = "Його очі бачать порух мишачого хвоста за цілі милі.",
    ["Its eyesight is better than its hearing."] = "Її зір кращий за слух.",
    ["Its friends call it \"Slappy.\""] = "Друзі звуть його «Ляпко».",
    ["Its insides are a raging inferno. Its outside is happy pup."] = "Усередині — лютий вогонь. Зовні — щасливе цуценя.",
    ["Its proximity to crystalline mana clusters has hardened this broodlings body to an almost rocklike state."] = "Близькість до кришталевих скупчень мани загартувала тіло цього виплідка майже до кам'яного стану.",
    ["Its scales are electrified, making it exceedingly tricky to cuddle."] = "Його луска наелектризована, тож пригортати його — справа вкрай ризикована.",
    ["Its sharp eyes can spot a snowshoe rabbit in a snowstorm."] = "Її гострі очі здатні розгледіти зайця-біляка в сніговій бурі.",
    ["Its teeth are razor sharp and will chew through just about anything."] = "Його зуби гострі, мов лезо, і здатні прогризти геть усе.",
    ["Its traveled all the way from New Beavertown."] = "Він дістався сюди аж із Нового Боброграда.",
    ["Ixthal enjoys hide-and-seek when not contemplating the slow devouring of entire worlds by the Void."] = "Ікстал любить гратися в хованки, коли не розмірковує про повільне поглинання цілих світів Порожнечею.",
    ["Jade Oozelings glow in the dark, making them a welcome sight to workers in pitch-black mineshafts."] = "Нефритові слизнята світяться в темряві, тому вони — бажане видовище для робітників у чорних, як смола, штольнях.",
    ["Jade is naturally rich with life and color, making it the perfect raw material for this gentle companion.  It is said the wind created by their wings can soothe the troubled mind."] = "Нефрит від природи сповнений життя та барв, що робить його ідеальною сировиною для цього лагідного супутника. Кажуть, вітер від його крил може заспокоїти стривожений розум.",
    ["Jepetto's top-selling toy this season, the bot's new blue chassis has children across Azeroth scrambling for this feisty battle bot."] = "Найпопулярніша іграшка Джепетто цього сезону: нове блакитне шасі бота змушує дітлахів по всьому Азероту битися за цього завзятого бойового бота.",
    ["Jerrie was once an ordinary rock mouse. He still is, in fact."] = "Джеррі колись був звичайною скельною мишею. Власне, нею й залишається.",
    ["Jimmy's actual name is Morgilito, Spawn of Morgil, Chosen Enemy of Tazavesh, Devourer of K'aresh...but everyone just calls him Jimmy."] = "Справжнє ім'я Джиммі — Морґіліто, Поріддя Морґіла, Обраний Ворог Тазавеша, Пожирач К'арешу... але всі просто звуть його Джиммі.",
    ["Jinyu assassins employ this moth as both a portable decoy and a light source to reveal weak spots in their enemy's armor."] = "Вбивці джинью використовують цього метелика як переносну приманку та джерело світла, щоб виявляти слабкі місця в обладунках ворога.",
    ["Joining with their new residents in Sinfall a few of these juvenile dredbats accompanied Renathal's forces into the maw."] = "Приставши до нових мешканців Гріхопаду, кілька цих молодих копнетопирів супроводжували Ренаталові війська до Пащі.",
    ["Juniper's unique coloration makes it hard to hide from predators in the Emerald Dream's lush green foliage. She therefore made the wise decision to travel with you instead."] = "Унікальне забарвлення Ялівцівки заважає їй ховатися від хижаків у пишному зеленому листі Смарагдового Сну. Тому вона ухвалила мудре рішення натомість мандрувати з вами.",
    ["Just like the rough and tumble sailors who live dockside, the wharf rats are feral, violent creatures."] = "Достоту як грубі й шорсткі моряки, що живуть біля доків, портові щури — дикі, лихі створіння.",
    ["Just one part jelly, but refreshed over and over and over again."] = "Усього одна частина желе, але оновлюваного знову, і знову, і знову.",
    ["Juvenile describes this scuttleback's age, not its maturity."] = "«Молодий» описує вік цього шкрябоспина, а не його зрілість.",
    ["Kaliri hatchlings feast on grubs when they're young, and eventually graduate to anything smaller than themselves."] = "Пташенята калірі замолоду ласують личинками, а згодом переходять на все, що менше за них самих.",
    ["Keep it out of your backpack or it will eat all your food and then take a nap."] = "Не пускайте його у свій наплічник, бо воно з'їсть усю вашу їжу, а потім задрімає.",
    ["Kel'Thuzad once nursed a plague-infected whelp to adulthood, feeding it only the finest liquefied remains."] = "Кел'Тузад колись виростив зараженого чумою дракончика до зрілості, годуючи його лише найвишуканішими розрідженими рештками.",
    ["Key activities include: rolling over, sunning self, whimpering for belly scratches, and enjoying belly scratches."] = "Головні заняття: качатися, грітися на сонці, скиглити, випрошуючи чухання животика, і насолоджуватися чуханням животика.",
    ["Kindled in a ritual of flame and feather, she grows with a restless heat, drawn to the softest morsels and the sharpest scents, her tiny wings carrying both comfort and cinders wherever she flits."] = "Запалена в ритуалі полум'я й пір'я, вона росте в невгамовному жарі, тягнучись до найніжніших ласощів і найгостріших ароматів, а її крихітні крила несуть і втіху, і жарини, куди б вона не пурхнула.",
    ["Kindness gives hope golden wings, and the Heartglow Listener's feathers are with us through every tranquil night."] = "Доброта дарує надії золоті крила, а пір'я Серцесяйного Слухача супроводжує нас крізь кожну тиху ніч.",
    ["Known for its blue eyes. Also considered a delicacy by giant murlocs."] = "Відомий своїми блакитними очима. А ще його вважають делікатесом гігантські мурлоки.",
    ["Known for their powerful legs and keen eyesight."] = "Відомі своїми потужними лапами й гострим зором.",
    ["Known to chomp on the shins of everything from saurids to brutosaurs."] = "Відомий тим, що гризе гомілки всіх підряд — від сауридів до брутозаврів.",
    ["Known to dissolve most materials, use extreme caution when approaching this caustic ooze!"] = "Відомий тим, що розчиняє більшість матеріалів, тож наближайся до цієї їдкої слизі з украй великою обережністю!",
    ["Known to feast on the tasty plants in Krasarang Wilds."] = "Відомий тим, що ласує смачними рослинами Нетрів Красаранга.",
    ["Known to feast on the tasty plants in Valley of the Four Winds."] = "Відомий тим, що ласує смачними рослинами Долини Чотирьох Вітрів.",
    ["Known to flourish in the rainy season, this insect is drawn to lightning storms."] = "Ця комаха буяє в дощову пору й вабиться до грозових бур.",
    ["Known to hide money in its shell."] = "Відомий тим, що ховає гроші у своїй мушлі.",
    ["Known to take a bite out of his owner. Pet cautiously."] = "Відомий тим, що може вкусити власника. Гладь обережно.",
    ["Krag'wa reluctantly sent Tragg to the Talanji Expedition with the hope that they could find someone suitable to escort him on a tour of Azeroth."] = "Краг'ва неохоче відрядив Траґґа до Експедиції Таланджі, сподіваючись, що там знайдеться хтось підхожий, аби супроводити його в мандрівці Азеротом.",
    ["Kromos can often be found napping in sandboxes."] = "Кромоса часто можна застати, коли він дрімає в пісочницях.",
    ["Lab leaks are sometimes dangerous. Sometimes, they're cute. Sometimes, both!"] = "Витоки з лабораторії іноді небезпечні. Іноді милі. А іноді й те, й те!",
    ["Lacking the mines and rockets of its predecessor, this kid-friendly faire prize is a new favorite among Azeroth's children."] = "Позбавлений мін і ракет свого попередника, цей безпечний для дітей ярмарковий приз став новим улюбленцем малечі Азероту.",
    ["Lapbugs were widely prized as domesticated pets before the fall of K'aresh. Copper lapbugs were especially sought-after."] = "До падіння К'арешу колінцежуків високо цінували як свійських улюбленців. Мідні колінцежуки користувалися особливим попитом.",
    ["Larger than other raptor infants, these hatchlings grow into towering reptilian beasts capable of massive devastation."] = "Більші за інших раптореня, ці малята виростають у велетенських рептильних звірів, здатних на нищівне спустошення.",
    ["Larion are prideful beasts, and see anyone that enters their territory as a challenge."] = "Ларіони — горді звірі, і кожного, хто заходить на їхню територію, сприймають як виклик.",
    ["Late in life, if the environmental conditions are correct, a Death Adder may shed its skin and undergo a transformation into an Imperial Python."] = "На схилі життя, якщо умови довкілля сприятливі, смертельна гадюка може скинути шкіру й перетворитися на імперського пітона.",
    ["Layers of rocky skin make Ambershells very tough to hurt."] = "Шари кам'янистої шкіри роблять Бурштинопанцирів дуже складними для поранення.",
    ["Leaving the forest to see the world, which must look so much bigger to such a little guy."] = "Полишає ліс, щоб побачити світ, який такому малюкові має здаватися значно більшим.",
    ["Left to their own devices, carrots will simply lose their minds."] = "Полишена напризволяще, морква просто божеволіє.",
    ["Left to their own devices, these leporids will leap high into the air at the slightest provocation. Sometimes they'll even come down properly, as well."] = "Полишені на самих себе, ці лепориди підстрибують високо вгору за найменшої провокації. Інколи навіть приземляються як годиться.",
    ["Legend has it that a seadragon turtle just like this one grew up to become Shen-zin Su, the Wandering Isle. Perhaps your little turtle will grow into something amazing?"] = "Легенда каже, що така ж морськодраконяча черепаха, як ця, виросла й стала Шень-цзінь Су, Мандрівним Островом. Можливо, і ваша черепашка виросте в щось дивовижне?",
    ["Legend has it that the Necrofin tribe found necromancy on a series of runed tablets at the bottom of the sea."] = "Легенда каже, що плем'я Некроплавців відкрило некромантію на низці рунних табличок на дні моря.",
    ["Legend has it that these purple butterflies came from a place called Devil's Island."] = "Легенда каже, що ці фіолетові метелики прибули з місцини на ім'я Чортів Острів.",
    ["Legend says the Sunfire Kaliri flies into the sun itself when it is ready to die."] = "Легенда каже, що сонцевогняний каларі влітає в саме сонце, коли готовий померти.",
    ["Legends say that if you see a bleak skitterer in your dreams, you are destined to battle one to the death."] = "Легенди кажуть: якщо ти побачиш у снах похмурого метушливця, тобі судилося битися з ним на смерть.",
    ["Legends say that these vibrant emerald beings bring good fortune and safe travels to their owners."] = "Легенди кажуть, що ці яскраві смарагдові створіння приносять своїм власникам удачу й безпечні мандри.",
    ["Less venomous but more aggressive than other breeds of scorpion."] = "Менш отруйний, але агресивніший за інші породи скорпіонів.",
    ["Lightning can be seen flowing across its body, teeth to tail."] = "По його тілу видно, як струмує блискавка — від зубів до хвоста.",
    ["Lightspawn can always be found on the battlefields where light touches, no matter what form it takes."] = "Поріддя Світла завжди можна знайти на полях битв, яких торкається світло, хоч би якої форми воно набувало.",
    ["Lihuvim's geomental creations are the most majestic of walking rock piles."] = "Геоментальні витвори Лігувіма — найвеличніші серед ходячих куп каміння.",
    ["Like Neltharion, this fish went mad listening to whispers of the Old Cods."] = "Як і Нельтаріон, ця риба збожеволіла, дослухаючись до шепоту Прадавніх Тріски.",
    ["Like a campfire, but it wants skritches."] = "Як багаття, але хоче, щоб його почухали.",
    ["Like father, like son."] = "Який батько, такий і син.",
    ["Like his father, Do speaks little but is a friend to almost everyone except those who harm innocents."] = "Як і його батько, До говорить мало, та він друг майже всім, окрім тих, хто кривдить невинних.",
    ["Like many other species, you can get a rough guess of how large the raptor will be as a fully grown adult by the size of its largest claw."] = "Як і в багатьох інших видів, за розміром найбільшого кігтя можна приблизно вгадати, яким завбільшки виросте дорослий раптор.",
    ["Like many species of Krolusk, this variety seems to prefer the isles network of underground caves."] = "Як і багато видів кролусків, цей різновид, схоже, віддає перевагу мережі підземних печер острова.",
    ["Like most young meeksi, Liu has a penchant for finding both trouble and adventure. Unlike other meeksi, Liu can teleport across great distances in search of both."] = "Як і більшість юних мейксі, Лю має схильність знаходити й халепи, і пригоди. На відміну від інших мейксі, Лю вміє телепортуватися на великі відстані в пошуках і того, і того.",
    ["Like other members of the blue dragonflight, these whimsical little critters display an affinity to arcane magic."] = "Як і інші представники синьої зграї драконів, ці примхливі малі створіння мають хист до магії таємних сил.",
    ["Likely to flip out and kill someone."] = "Має схильність зірватися й когось убити.",
    ["Lil' Ashlee quietly bides her time waiting for a power vacuum. Once in power Lil' Ashlee will bring fun, merriment and fire to all!"] = "Мала Попелючка тихо вичікує слушної миті, коли утвориться вакуум влади. Щойно Мала Попелючка опиниться при владі, вона принесе всім розваги, веселощі та вогонь!",
    ["Lil' Bonechewer loves you, even if you were a worm. Especially if you were a worm."] = "Малий Костогриз любить тебе, навіть якби ти був червом. Особливо якби ти був червом.",
    ["Lil' Flameo is ready to drop foolish pets if they get in the way."] = "Малий Полум'ео готовий прибрати дурних улюбленців, якщо ті стануть на заваді.",
    ["Little is known about the true intentions of this murloc, but her followers are among the most devoted."] = "Про справжні наміри цієї мурлочки відомо небагато, але її прибічники — одні з найвідданіших.",
    ["Littlehoof likes: bounding, bouncing, frolicking, and headbutts, in that order."] = "Копитко любить: стрибати, скакати, пустувати й буцатися — саме в такому порядку.",
    ["Living so closely to the water's surface, the puddle terror is not only friend to all aquatic creatures, it is one."] = "Живучи так близько до поверхні води, жах калюж не лише товаришує з усіма водними створіннями — він і сам одне з них.",
    ["Living so deep within the seas has made this species very sensitive to lights."] = "Життя в морських глибинах зробило цей вид дуже чутливим до світла.",
    ["Loatheb's body is covered in small pods capable of spreading blighted fungal spores up to 1000 yards given proper wind conditions."] = "Тіло Лоатеба вкрите дрібними капсулами, здатними розносити чумні грибні спори на відстань до 1000 ярдів за сприятливого вітру.",
    ["Long ago, Mount Hyjal's druids tempered this species to live in peace alongside the region's other creatures."] = "Давним-давно друїди Гори Гіджал утихомирили цей вид, щоб він жив у мирі з іншими створіннями краю.",
    ["Long ago, the population of chickens in Stormsong Valley was so high, there was fear that the chickens would eat all of the corn from the fields and leave the other residents hungry."] = "Колись давно курей у Долині Штормової Пісні було так багато, що люди боялися, аби кури не виїли всю кукурудзу з полів і не лишили решту мешканців голодними.",
    ["Look out! He's comin' right for us! Gradually!"] = "Обережно! Він суне просто на нас! Поступово!",
    ["Look, she likes it! She's smiling, see!"] = "Дивися, їй подобається! Вона усміхається, бачиш!",
    ["Looks like Ben'jin and Maka'fon have kept busy since you last saw them. Maka'jin is ready for adventure but will settle for a large pile of leafy greens."] = "Схоже, Бен'джин і Мака'фон не байдикували, відколи ти бачив їх востаннє. Мака'джин готовий до пригод, але задовольниться й великою купою зелені.",
    ["Lord Stantley will arrive fashionably early to any party that serves shrimp."] = "Лорд Стентлі прийде модно зарано на будь-яку вечірку, де подають креветки.",
    ["Lord Woofington was given his title after the rest of the denizens of Havenswood succumbed to madness."] = "Лорд Гавкінгтон дістав свій титул після того, як решта мешканців Гейвенсвуду піддалася божевіллю.",
    ["Lost on Argus and overtaken by darkness, this playful fox can shrug off the void just by being by your side."] = "Загублений на Аргусі й охоплений темрявою, цей грайливий лис здатен відганяти Порожнечу, просто будучи поруч із тобою.",
    ["Loves to herd imps, roll around in lava, and snuggle with elemental lords."] = "Обожнює пасти дияволят, качатися в лаві й пригортатися до володарів стихій.",
    ["Loves to rest inside footwear of unsuspecting travelers during the night."] = "Любить ночами відпочивати у взутті нічого не підозрюваних мандрівників.",
    ["Loves: Broccoli, playing, and smashing things. Hates: Meat, sleeping, and mean titan keepers who won't let you smash things."] = "Любить: броколі, гратися та трощити речі. Ненавидить: м'ясо, спати та злих хранителів-титанів, які не дають трощити речі.",
    ["Loyal to the Sunreavers from creation, these pint-sized constructs can still pack a punch."] = "Віддані Санріверам від самого створення, ці малесенькі конструкти все одно вміють добряче дати здачі.",
    ["Lucky squeals when he's angry or when he's eating. Either way, you don't want to bother him."] = "Щасливчик верещить, коли сердиться або коли їсть. Та хай там як, краще його не турбувати.",
    ["Lucy was sent to Revendreth, as all cats are, and somehow escaped. When questioned, local dredgers blamed it on her being a cat."] = "Люсі відправили до Ревендрету, як і всіх котів, але вона якось утекла. На розпити місцеві землекопи відмахнулися: «А що ви хочете — це ж кішка».",
    ["Luma knows all kinds of tricks such as \"sit,\" \"stay,\" and \"steal.\""] = "Лума знає всілякі трюки, як-от «сидіти», «чекати» й «красти».",
    ["Luminescent body used to attract mates."] = "Світний тулуб слугує для приваблення пари.",
    ["Lurking beneath dark waters with needle sharp teeth. You can bite and drink their blood too, though. It's allowed."] = "Зачаїлося під темними водами із зубами, гострими як голки. Втім, ти теж можеш його вкусити й випити його кров. Це дозволено.",
    ["Lurky's charming disposition and lively antics are guaranteed to soothe frustration and lighten even the darkest moods."] = "Чарівлива вдача й жваві витівки Леркі гарантовано втамують роздратування й розвіють навіть найпохмуріший настрій.",
    ["Made from bits and pieces of vanquished battle pets, dark magic, and just a pinch of love."] = "Зроблений із решток подоланих бойових улюбленців, темної магії та дрібки любові.",
    ["Made from the bits and pieces of vanquished abominations, light magic, and just a pinch of nostalgia."] = "Зроблений зі шматочків подоланих гидот, магії світла й дрібки ностальгії.",
    ["Mages seek these manafiends to absorb their ley energies."] = "Маги шукають цих мановрагів, щоб поглинути їхні енергії силових ліній.",
    ["Magic-addicted elves too small and frail to serve in Kil'Jaeden's army were relegated to servant roles for the higher-class demons."] = "Залежних від магії ельфів, надто малих і кволих, щоб служити в армії Кіл'джедена, відсунули до ролі слуг для вищих демонів.",
    ["Magisters love to turn on their enchanted brooms before heading off to work, only to find it stuck in a corner of their Silvermoon apartment."] = "Магістри полюбляють вмикати свої зачаровані мітли перед виходом на роботу, аби потім знайти їх застряглими в кутку свого сільвермунського помешкання.",
    ["Maldraxxus is full of mighty and terrifying creatures, causing most denizens to be abnormally calm when around the indigenous species of giant spiders."] = "Малдраксус повний могутніх і жахливих створінь, тож більшість його мешканців напрочуд спокійно ставляться до місцевого виду велетенських павуків.",
    ["Maloriak was nothing if not resourceful, not letting even small scraps of flesh go to waste."] = "Малоріак був надзвичайно винахідливим і не дозволяв пропасти навіть найменшим клаптикам плоті.",
    ["Mana wyrm used to thrive on Argus many millennia ago, but lots has changed since those halcyon days."] = "Багато тисячоліть тому мана-вірми буяли на Аргусі, та відтоді багато що змінилося.",
    ["Many a drunken Brewfest goer has told the tale of this mysterious creature, but few remember that tale in the morning."] = "Не один захмелілий гуляка Пивного фестивалю переповідав історію про це загадкове створіння, та мало хто згадає її вранці.",
    ["Many a young gnomish inventor has made up for the death of a beloved pet by creating a mechanical friend in its image."] = "Не один юний гном-винахідник пережив смерть улюбленця, створивши механічного друга за його подобою.",
    ["Many advancements have been made to the initial prototype homing beacon over the years."] = "За багато років початковий прототип самонавідного маяка зазнав чимало вдосконалень.",
    ["Many an explorer has been entranced by the adorable nature of the alpine chipmunk, failing to notice its small teeth on frostbitten digits."] = "Не одного дослідника зачаровувала мила вдача альпійського бурундука, тож вони й не помічали його дрібних зубів на своїх обморожених пальцях.",
    ["Many ancient tribes revered these enormous beetles."] = "Чимало давніх племен шанували цих велетенських жуків.",
    ["Many arachnids are left to fend for themselves after hatching. It's a common topic in spider therapy."] = "Багато павукоподібних після вилуплення лишаються виживати самотужки. Це поширена тема на павучій терапії.",
    ["Many assume 'Wiggles' refers to the motion of this pig's posterior. They discover the true meaning when they see their own entrails."] = "Багато хто гадає, що «Вертун» стосується погойдування заду цього кабанця. Справжнє значення вони осягають, коли бачать власні нутрощі.",
    ["Many believe (incorrectly) that goldfish have no memories. Trainers who have worked with them know this is clearly not the case and have the bruises to prove it."] = "Багато хто (помилково) вважає, що золоті рибки не мають пам'яті. Дресирувальники, які з ними працювали, добре знають, що це не так, і мають синці на доказ.",
    ["Many believe that the quillrat is able to shoot its spines at aggressors."] = "Багато хто вірить, що голкощур здатен метати свої голки в нападників.",
    ["Many have asked where these creatures came from, and how they made it to the Maw, but none that researched them have ever been heard from again."] = "Багато хто питав, звідки взялися ці створіння й як вони потрапили до Пащі, але про жодного з тих, хто їх досліджував, більше ніхто ніколи не чув.",
    ["Many have mocked this cat before battle. Their last words are usually, 'Here, kitty, kitty.'"] = "Багато хто кепкував із цього кота перед боєм. Їхніми останніми словами зазвичай були: «Сюди, кицю, кицю».",
    ["Many have tried to boop the cute little noses of creatures like this. Most have lost fingers."] = "Багато хто намагався тицьнути в милі носики таких створінь. Більшість позбулася пальців.",
    ["Many of Stormwind's youth joined the Argent Crusade as squires, hoping to one day serve the Holy Light in battle."] = "Багато юнаків зі Стормвінда вступили до Срібного Хрестового Походу зброєносцями, сподіваючись колись послужити Святому Світлу в бою.",
    ["Many owls nest high in the stone structures of Darnassus, hunting any pests that enter the night elves' city."] = "Багато сов гніздяться високо в кам'яних спорудах Дарнасуса, полюючи на будь-яких шкідників, що заходять до міста нічних ельфів.",
    ["Many sailors believe that harming an albatross will bring terrible luck upon their voyage."] = "Багато моряків вірять, що скривдити альбатроса — накликати на свою подорож страшне безталання.",
    ["Many salamanthers have interesting colorations, but this salamanther has the coolest one."] = "У багатьох саламандр цікаве забарвлення, але в цієї — найкльовіше.",
    ["Many years ago, an ogre tried to use a leatherhide runt as kickball.  He was forever known as Onefoot afterwards."] = "Багато років тому один оґр спробував поганяти заморуха-шкірошкура замість м'яча. Відтоді його довіку звали Одноногом.",
    ["Many young raccoons rail against their strict curfews, complaining that dawn is way too early to go to bed."] = "Багато юних єнотів повстають проти суворого режиму, нарікаючи, що світанок — то надто рано лягати спати.",
    ["Master of poking, stabbing, thrusting, jabbing, and gouging."] = "Майстер тицяння, штрикання, штурхання, шпиняння й колупання.",
    ["Maybe a bit too enthusiastic."] = "Можливо, трохи аж надто завзятий.",
    ["Maybe give up! Maybe surrender!"] = "Може, здайся! Може, капітулюй!",
    ["Mechanical Cockroaches are less likely to survive an apocalypse than an actual living cockroach, making this one of the more questionable feats of engineering."] = "Механічні таргани мають менше шансів пережити апокаліпсис, ніж справжні живі таргани, що робить їх одним із сумнівніших досягнень інженерії.",
    ["Mechanical Toads can hop over seven million times before their gears begin to wear out."] = "Механічні жаби можуть зробити понад сім мільйонів стрибків, перш ніж їхні шестерні почнуть зношуватися.",
    ["Meet your new best mech-friend, Maya. Maya loves a good, tight wind-up so she can spring into action."] = "Знайомся зі своєю новою найкращою мех-подругою, Майєю. Майя любить, коли її добре, туго заводять, щоб вона могла кинутися в дію.",
    ["Mega-Mecha Gorilla possesses the strength of not one, but FIVE gorillas."] = "Меґа-Меха-Горила має силу не однієї, а аж П'ЯТЬОХ горил.",
    ["Miloh likes naps. Also snacks."] = "Майло любить подрімати. А ще перекусити.",
    ["Mmm... Pizza!"] = "Ммм... Піца!",
    ["Modeled after the huge titan prototype in Ulduar, this volatile little construct plays hard with its toys."] = "Створений за подобою величезного титанського прототипу в Ульдуарі, цей вибуховий малий конструкт грається своїми іграшками без жалю.",
    ["Mogu sorcerers, keepers of the secret to bringing stone to life, prefer these stolid companions over more beastly familiars."] = "Чаклуни могу, охоронці таємниці оживлення каменю, надають перевагу цим незворушним супутникам над звіриними прислужниками.",
    ["Mongoose pups prefer long grass where only their mothers can find them."] = "Мангустенята полюбляють високу траву, де лише їхні матері можуть їх знайти.",
    ["Moonfang's cubs grow into massive, slavering, black-furred killing machines...except for Moon Moon."] = "Цуценята Місяцезуба виростають у могутні, слинаві, чорношерсті машини для вбивства... крім Місь-Місь.",
    ["Moonkin are blessed by Elune and spread nature's grace wherever they travel. The festive fowls are always in the mood for a dance."] = "Місяцекіни благословенні Елуною і несуть благодать природи всюди, куди прямують. Ці святкові птахи завжди не проти потанцювати.",
    ["More horrifying than its appearance is that the infected squirrels of the Plaguelands no longer hoard nuts, instead collecting rotten, decaying flesh."] = "Ще жахливіше за їхній вигляд те, що заражені білки Чумних земель більше не запасають горіхи, а натомість збирають гниле, розкладене м'ясо.",
    ["More than a typical turtle, he's a hero in a half shell!"] = "Не просто звичайна черепаха — це героїня в половинці панцира!",
    ["Mortal enemies with silver dragonhawks; on pretty good terms with golden dragonhawks."] = "Смертельні вороги срібних драконоястребів; з золотими драконоястребами в досить добрих стосунках.",
    ["Mosswools appreciate a seasonal shear."] = "Моховівці радіють сезонному стриженню.",
    ["Most bats are not blind, except this one.  This one is blind."] = "Більшість кажанів не сліпі, окрім цього. Цей сліпий.",
    ["Most brightly colored frogs are incredibly poisonous. The Roseate Hoppers are different because they are only credibly poisonous."] = "Більшість яскраво забарвлених жаб неймовірно отруйні. Рожеві Стрибунці інакші, бо вони отруйні лише в межах правдоподібного.",
    ["Most creatures cannot withstand a fraction of the harsh conditions that roaches can thrive in."] = "Більшість створінь не витримали б і дещиці тих суворих умов, у яких буяють таргани.",
    ["Most felstalkers are fiercesome and ravenous. This one, however, seems to be feeling a bit lonely."] = "Більшість скверноловів люті й ненаситні. Цей же, схоже, почувається трохи самотнім.",
    ["Most of Violet's numerous forest strider hatchlings are turned into Faire fare by Stamp Thunderhorn, though a few are raised as mounts or purchased by adventurers looking for a petite purple pet."] = "Більшість численних малят лісоступа Віолетти Стамп Громоріг перетворює на ярмаркові страви, проте кількох вирощують як їздових тварин або купують шукачі пригод, що шукають маленького фіолетового улюбленця.",
    ["Most of Zereth Mortis' aurelids are content to swim, but some are born to fly!"] = "Більшість ауреліди Зерет Мортіса задоволені плаванням, але деякі народжені, щоб літати!",
    ["Most people do not know the difference between a squirrel and a chipmunk. Most don't care."] = "Більшість людей не знають різниці між білкою і бурундуком. Більшості байдуже.",
    ["Most people don't find congealed blood particularly appetizing. Bloodticks, though..."] = "Більшості людей застигла кров не здається надто апетитною. А от кровокліщам...",
    ["Most people have never read this book."] = "Більшість людей ніколи не читали цієї книги.",
    ["Most people only see gazelles from the rear."] = "Більшість людей бачать газелей лише ззаду.",
    ["Most predators favored the soft parts of their prey to attack first.  Lil' Tika prefers to go for the face."] = "Більшість хижаків спершу нападають на м'які частини здобичі. Мала Тіка ж воліє цілити в обличчя.",
    ["Most squirrels hoard acorns for sustenance. Nuts, on the other hand, hoards acorns to stock its supply of ammunition."] = "Більшість білок запасають жолуді на харч. А ось Горішок запасає жолуді, щоб поповнити свій боєзапас.",
    ["Mountain cottontails can leap up a steep incline with speed you would not believe."] = "Гірські кролики можуть вистрибувати на крутий схил з неймовірною швидкістю.",
    ["Mr. Chilly's appearance evokes a more civilized era, when duelists battled in tuxedos."] = "Вигляд пана Мерзлячка нагадує про більш цивілізовану добу, коли дуелянти билися у фраках.",
    ["Mr. Crabs was victorious in a lengthy brawl amongst nearly a dozen other hermit crabs to claim his current shell."] = "Пан Крабс вийшов переможцем із тривалої бійки проти майже дюжини інших раків-самітників, щоб здобути свою теперішню мушлю.",
    ["Mr. Smite kept this in his trunk, but always seemed to prefer his hammer. Seems like a mistake in hindsight."] = "Пан Покара тримав це у своїй скрині, але завжди ніби надавав перевагу молоту. Як виявилося згодом, це була помилка.",
    ["Much like how a squid can squirt ink to escape in the water, a glitterwing can shake the dust off of its wings and similarly vanish."] = "Так само, як кальмар бризкає чорнилом, щоб зникнути у воді, мерехтокрил може струсити пилок з крил і так само щезнути.",
    ["Much like other faerie dragons, these playful and mystical flyers are born with a natural defense against magic."] = "Як і інші феєрні дракони, ці грайливі й містичні літуни народжуються з природним захистом від магії.",
    ["Much quieter than a real dragon."] = "Куди тихіший за справжнього дракона.",
    ["Muckbreath is just like other crocolisks, except he has an excellent sense of humor."] = "Багнодих такий самий, як інші кроколіски, от тільки має чудове почуття гумору.",
    ["Murki is one of the world's rarest species of murloc."] = "Муркі — один із найрідкісніших у світі видів мурлоків.",
    ["Murkimus is the most fearsome of all murloc arena warriors. And for a time, the only one."] = "Муркімус — найгрізніший з усіх мурлокських воїнів арени. А якийсь час — і єдиний.",
    ["Murkimus is the most fearsome of all murloc arena warriors. And the only one."] = "Муркімус — найстрашніший з усіх мурлоцьких воїнів арени. І єдиний.",
    ["N'Zoth's corruption spread across many beings, including this little Anubisath."] = "Скверна Н'Зота поширилася на безліч істот, зокрема й на це маленьке анубісатеня.",
    ["Named for their apparent dancelike behavior when skimming aquatic surfaces, the species uses erratic movements to avoid being devoured by fish and other underwater predators."] = "Названі так за свою позірно танцювальну поведінку, коли вони ковзають по водній гладі; цей вид рухається безладно, аби не бути зжертим рибами та іншими підводними хижаками.",
    ["Nations tremble under his shadow - the Destroyer, the one-time Aspect of Earth, and the monster responsible for breaking Azeroth asunder.  Now in a convenient travel-size!"] = "Народи тремтять під його тінню — Руйнівник, колишній Аспект Землі, і чудовисько, винне в розколі Азероту.  Тепер у зручному дорожньому форматі!",
    ["Native to Azeroth's desert regions, these resilient reptiles can survive for weeks without water."] = "Родом із пустельних країв Азероту, ці витривалі плазуни можуть тижнями виживати без води.",
    ["Native to Duskwood, these eight-legged critters are often used as ingredients in alchemy potions."] = "Корінні мешканці Сутінкового Лісу, ці восьминогі дрібнятка часто йдуть на складники алхімічних настоянок.",
    ["Native to the Terokkar Forest, nether rays spawn during the rainy season. Out of the hundreds of offspring resulting from one hatching, very few survive to adulthood."] = "Родом із Лісу Терокар, нетер-скати з'являються на світ у сезон дощів. Із сотень нащадків одного виводка до дорослого віку доживають лічені одиниці.",
    ["Native to the ashen soils of the Firelands, the lasher was transplanted to Azeroth with the help of the Guardians of Hyjal."] = "Корінний мешканець попелястих ґрунтів Вогняних Просторів, бичар був перенесений до Азероту за допомогою Вартових Гіджалу.",
    ["Natural burrowing tendencies were programmed into these critters, and now they perform vital functions breaking down the great piles of scrap."] = "У цих звіряток запрограмували природну схильність до риття, і тепер вони виконують важливу роль, розбираючи величезні купи брухту.",
    ["Nearly invisible, this creature leaps from tree to snow-covered tree."] = "Майже невидиме, це створіння перестрибує з дерева на засніжене дерево.",
    ["Nefarian's reanimated bone constructs were an effective way to combat the many adventurers that plagued him, and especially their mages."] = "Оживлені кістяні конструкти Нефаріана були дієвим засобом проти численних шукачів пригод, що дошкуляли йому, а надто проти їхніх магів.",
    ["Nestled in his cozy cave, this little mandrake sprout was one of the last. Over time though his favorite mushrooms stopped growing in his cave. So he decided to sleep... waiting for his favorite spores to blow in again."] = "Затишно вмостившись у своїй печері, цей малий паросток мандраґори був одним з останніх. Та з часом його улюблені гриби перестали рости в печері. Тож він вирішив заснути... чекаючи, поки знову навіє його улюблені спори.",
    ["Never say \"oink\" in its presence."] = "Ніколи не кажи «хрю» в його присутності.",
    ["Never take your eye off of it."] = "Ніколи не спускай з нього очей.",
    ["New species of murloc are discovered around Azeroth all the time, owing to their invasive nature and varied diet."] = "Нові види мурлоків відкривають по всьому Азероту повсякчас — завдяки їхній інвазивній натурі та різноманітному раціону.",
    ["Newsy delivers mail all around the Dragon Isles. She is so quick and reliable that the small holes on the letters she delivers are negligible."] = "Ньюзі розносить пошту по всіх Драконових Островах. Вона така прудка й надійна, що дрібними дірочками в листах, які вона приносить, можна знехтувати.",
    ["Night elf children are given an owl feather on their first birthday as a token of good luck."] = "Дітям нічних ельфів на перший день народження дарують совине перо як знак удачі.",
    ["No longer lost or lonely, your faithful companion has decided that by your side is the best place to be."] = "Більше не загублений і не самотній, твій вірний компаньйон вирішив, що поруч із тобою — найкраще місце на світі.",
    ["No longer lost, it's now considering a name change."] = "Більше не загублене — тепер подумує про зміну імені.",
    ["No matter how much he screams, never give him demon blood."] = "Хоч би як він верещав, ніколи не давай йому демонічної крові.",
    ["No one in their right mind has ever seen a Mawtouched Geomental. Even so, plenty of people have seen Mawtouched Geomentals."] = "Жодна людина при здоровому глузді ніколи не бачила Пащеторкненого геоментала. І все ж безліч людей бачили Пащеторкнених геометалів.",
    ["No one is quite sure where Reginald got his or her name, but what we do know is they don't answer to anything else."] = "Ніхто до пуття не знає, звідки Реджинальд узяв своє ім'я, та ми точно знаємо одне: на жодне інше він не відгукується.",
    ["No one knows how Lil' Coalee got his name. Was it his black heart? Was it his love for a warm fire? Was it simply that one of his parents were Big Coalee. Asking him yields no answers, only rage."] = "Ніхто не знає, звідки Малий Вуглик отримав своє ім'я. Через його чорне серце? Через його любов до теплого вогню? Чи просто через те, що одним з його батьків був Великий Вуглик? Питати в нього — марно, у відповідь дістанеш лише лють.",
    ["No one knows what deep part of Blackwing Descent the Lanticore was kept in, but it probably smelled pretty awful."] = "Ніхто не знає, в якій глибокій частині Сходження Чорнокрилих тримали Лантикора, але смерділо там, мабуть, доволі бридко.",
    ["No one knows where the devourers came from, but it is theorized that they flourish on several lost land masses in the In-Between."] = "Ніхто не знає, звідки взялися пожирачі, та припускають, що вони розплоджуються на кількох загублених материках у Поміжжі.",
    ["No one knows where this haunted tiki mask came from, or why its so angry all the time. It seems to like you though!"] = "Ніхто не знає, звідки взялася ця примарна маска-тікі й чому вона повсякчас така люта. Але тебе вона, схоже, вподобала!",
    ["No one knows who first started dressing up crabs in Azeroth, and it won't be stopping any time soon."] = "Ніхто не знає, хто перший почав вбирати крабів в Азероті, і скоро це не припиниться.",
    ["No one knows who made these mechanical spiders, but everyone hates them."] = "Ніхто не знає, хто зробив цих механічних павуків, та всі їх ненавидять.",
    ["No size jokes, please."] = "Без жартів про розмір, будь ласка.",
    ["Nobody calls this poultrid 'chicken.'"] = "Ніхто не наважується назвати цього птаха «куркою».",
    ["Nobody is sure what sort of powder is coming off of these moths, and everyone is too terrified to find out what it actually is."] = "Ніхто не знає напевно, що то за пудра обсипається з цих метеликів, і всі надто бояться з'ясовувати, що це насправді.",
    ["Nobody is sure why someone thought making a miniature version of the machines in Gnomeregan was a good idea, but they sure are fun to play with."] = "Ніхто до пуття не знає, чому комусь спало на думку зробити мініатюрні версії машин Гномреґану, та гратися з ними справді весело.",
    ["Nobody knows why all of these skeletal hands are from the left hand. Where did the right hands go?"] = "Ніхто не знає, чому всі ці кістляві долоні — ліві. Куди ж поділися праві?",
    ["Normally just a plain white in color, their skin reflects whatever they have eaten and gains wonderful spots of color depending on the organs digested."] = "Зазвичай вони звичайнісінького білого кольору, та їхня шкіра відображає все, що вони з'їли, і вкривається чудовими барвистими плямами залежно від перетравлених органів.",
    ["Not a squid, nor a kid, the scootlefish prefers to keep its ink to itself except under dire circumstances."] = "Ні кальмар, ні дитинча — чорнильник воліє тримати чорнило при собі, хіба що за вкрай скрутних обставин.",
    ["Not all moths spin silk. These moths spin lies."] = "Не всі молі плетуть шовк. Ці молі плетуть брехню.",
    ["Not even death would stop this kitten's insatiable curiosity."] = "Навіть смерть не спинила невгамовну цікавість цього кошеняти.",
    ["Not much is known about the great snake Merektha and the many eggs in the Temple of Sethraliss, but the residents of Zandalar all seem to have a distinct amount of both respect and fear for these serpents."] = "Про велику змію Мерехту та численні яйця в Храмі Сетраліс відомо небагато, проте всі мешканці Зандалару, схоже, відчувають до цих змій водночас чималу повагу й страх.",
    ["Not much is known about this otherworldly minion."] = "Про цього потойбічного прислужника відомо небагато.",
    ["Not only is it quick, it's loud too!"] = "Він не лише швидкий, а й галасливий!",
    ["Not quite alive, not quite dead, simply an arm, with no head."] = "Не зовсім живий, не зовсім мертвий — просто рука, без голови, та й по всьому.",
    ["Not to be kept indoors if you live in a wooden house."] = "Не тримати в приміщенні, якщо живеш у дерев'яному будинку.",
    ["Not to worry; the combat mechanisms and homing logic have been disabled on this unit, I think. --Oglethorpe Obnoticus"] = "Не хвилюйтеся: бойові механізми й систему наведення на цьому пристрої вимкнено. Здається. — Оґлторп Обнотікус",
    ["Not yet the fearsome creatures they grow to in adulthood, the Cenarion hatchlings have an almost harmless appearance that has caught novice trainers of the Cenarion Circle off guard."] = "Ще не ставши грізними створіннями, якими вони будуть дорослими, ценаріонські пташенята мають майже безневинний вигляд, що не раз заставав зненацька недосвідчених наставників Кола Ценаріуса.",
    ["Notable for its wide eyes and sassy slide."] = "Прикметне широко розплющеними очима й зухвалим ковзанням.",
    ["Nothing is known for certain, though some believe it calls the night sky its home."] = "Напевно нічого не відомо, хоч дехто вважає, що його домівка — нічне небо.",
    ["Nothing sparked joy in Ambre's heart until it found the perfect match."] = "Ніщо не запалювало радості в серці Амбри, доки вона не знайшла ідеальну пару.",
    ["Now that he's no longer sneezing through time, Zhusa is ready to accompany you on your future adventures! Or past adventures! Or future adventures!"] = "Тепер, коли він більше не чхає крізь час, Жуса готовий супроводжувати вас у майбутніх пригодах! Або в минулих пригодах! Або в майбутніх пригодах!",
    ["Now that is one spicy bee!"] = "Оце так гостра бджола!",
    ["Now this is one, spicy, mean, ball."] = "Ось це справді гострий, лютий клубок.",
    ["Now, where are its parents? You monster."] = "Ну, і де ж його батьки? Ти чудовисько.",
    ["Nuh-uh! Yellow is coolest! It's themed after the original, who's totally gonna beat that stupid gorilla!"] = "Нє-а! Жовтий найкрутіший! Він зроблений за оригіналом, який точно віддубасить ту дурну горилу!",
    ["Occasionally sneaks bites of food from kills made by much larger animals."] = "Час від часу крадькома підхоплює шматки їжі з-під здобичі набагато більших тварин.",
    ["Oddly enough, you met this fish drifting through the air."] = "Як не дивно, ти зустрів цю рибу, коли вона ширяла в повітрі.",
    ["Oddly, he was named Crispin even before the incident."] = "Дивно, та його звали Хрустиком ще до того випадку.",
    ["Of all of the creatures in Mechagon, the roaches seem the most unaffected by all of the changes."] = "З усіх створінь Мехаґону таргани, схоже, найменше зачеплені всіма цими змінами.",
    ["Of all snooters, this one has the scruffiest and warmest fur. It is a very friendly snooter but use extreme caution when petting it."] = "З усіх шмигів цей має найкуйовдженіше й найтепліше хутро. Це дуже привітний шмиг, та гладь його з великою обережністю.",
    ["Of all snooters, this one has the softest fur. Ironically, it does not like to be pet very much."] = "З усіх нюхалів цей має найм'якше хутро. За іронією долі, він не дуже любить, коли його гладять.",
    ["Of all the shades and colors of ducklings that come forth in the spring, the most prized are the pink ones. There are many theories about why, but it's likely just because pink is awesome."] = "З усіх відтінків і барв каченят, що з'являються навесні, найбільше цінують рожевих. Існує безліч теорій про те, чому, але найпевніше просто тому, що рожевий — це круто.",
    ["Of course there are hatchlings, they're called Lovebirds aren't they?"] = "Звісно, що є пташенята, їх же не дарма звуть нерозлучниками, чи не так?",
    ["Of the many frightening things that lurk in the deeps, a chitterspine nest is really up there."] = "З-поміж усіх страхіть, що чаяться в глибинах, гніздо скрипоголок таки серед найгірших.",
    ["Offspring of the Imperial Quilen."] = "Нащадок Імператорського квілена.",
    ["Offspring of the black sheep, the black lamb is only found in the forests of Elwynn."] = "Нащадок чорної вівці, чорне ягня трапляється лише в лісах Елвіну.",
    ["Offspring of the nether drakes of Outland, this young dragon is still growing into its role as hunter, protector, and adorable terror of the skies."] = "Нащадок нетер-драків Аутленду, цей юний дракон ще тільки вростає у свою роль мисливця, захисника й чарівного жаху небес.",
    ["Often caught chewing on things they shouldn't be, goats were initially blamed for the crash of the Exodar."] = "Кіз, яких часто ловлять за жуванням того, чого не слід, спершу звинуватили в катастрофі «Екзодара».",
    ["Often confused by miners as a rare gem, the geode initially makes its presence known by emitting melodic reverberations."] = "Шахтарі нерідко плутають жеоду з рідкісним самоцвітом; спершу вона виказує себе мелодійним відлунням.",
    ["Often it is red-footed after it catches its prey."] = "Часто, спіймавши здобич, він має червоні лапи.",
    ["Oh snap!! Lizard!"] = "Ой леле!! Ящірка!",
    ["Olivetail is a bit of misnomer, as its whole body is just brown..."] = "«Оливохвіст» — назва трохи оманлива, бо все його тіло просто буре...",
    ["On the prairie there are numerous rodents and other small creatures, but none more common than the mouse."] = "У преріях безліч гризунів та інших дрібних створінь, але немає поширенішого за мишу.",
    ["On very rare occasions glowflies synchronize their flashing creating a spectacular sight for any adventurer lucky enough to catch this phenomenon."] = "Вкрай рідко світлянки синхронізують своє мерехтіння, утворюючи видовищне дійство для будь-якого мандрівника, якому пощастить застати це явище.",
    ["Once a holy artifact used by draenei priests to calm spirits, it has become animated by anguished souls and drawn to locations of death and corruption."] = "Колишній священний артефакт, яким жерці-дренеї заспокоювали духів, нині оживлений змученими душами й тягнеться до місць смерті та скверни.",
    ["Once a manafiend consumes enough ley energy, it becomes more aggressive and twisted.  Approach with extreme caution."] = "Щойно мановраг поглине досить енергії силових ліній, він стає агресивнішим і викривленішим. Підступай із вкрай великою обережністю.",
    ["Once a mighty warrior of the n'raqi, Zur'aj's power was stolen and absorbed by an unknown rival."] = "Колись могутній воїн н'раків, Зур'адж позбувся своєї сили, яку викрав і ввібрав невідомий суперник.",
    ["Once bred and raised by the green dragon Itharius, this unique breed of dragon has settled in the jungles of Feralas."] = "Колись виведена й вирощена зеленим драконом Ітаріусом, ця унікальна драконяча порода оселилася в джунглях Фераласу.",
    ["Once its tentacles take hold there is no escape, much like its love for you."] = "Щойно його щупальця тебе схоплять — порятунку немає, так само як і від його любові до тебе.",
    ["Once native to the northern regions of the Eastern Kingdoms, this species of seal is now only common in Northrend after being hunted for food and leather during the Second War."] = "Колись цей вид тюленів мешкав у північних краях Східних Королівств, та після того, як під час Другої війни на нього полювали заради м'яса й шкіри, нині він поширений лише в Нордсколі.",
    ["Once prized by dragonhawk breeders in Silvermoon. Stands out at night to predators, making it necessary to gain awareness at an early age."] = "Колись цінувалося заводчиками драконоястребів у Сільвермуні. Уночі добре помітне для хижаків, тож пильність доводиться розвивати змалечку.",
    ["Once protected by the thick forests of the isle, these smaller and less aggressive krolusks have had to rapidly adapt to their recently deforested home."] = "Колись захищені густими лісами острова, ці менші й менш агресивні кролуски змушені були швидко пристосуватися до своєї нещодавно вирубаної домівки.",
    ["Once tenacious and terrible, the riverpaw slaughtered weaker enemies without hesitation."] = "Колись завзятий і жахливий, річколап без вагань різав слабших ворогів.",
    ["One hero's trash is another kobold's treasure. This unfortunately does not work in reverse."] = "Що для одного героя сміття, те для іншого кобольда скарб. На жаль, у зворотному напрямку це не діє.",
    ["One kobyss's meal is another adventurer's bestie."] = "Обід одного кобіса — найкращий друг іншого шукача пригод.",
    ["One more thing... Show my hound some respect."] = "Ще одне... вияви трохи поваги до мого пса.",
    ["One of Ash'alah's litter, entrusted to you by the Dreamweavers."] = "Одне з виводка Аш'али, довірене тобі Сноткачами.",
    ["One of Plague Deviser Marileth's first creations, Shy Melvin was too timid for the demands placed on slimes by the House of Plagues."] = "Одне з перших творінь Чумотворця Марілета, Сором'язливий Мелвін виявився надто боязким для вимог, які Дім Чуми ставить перед слизами.",
    ["One of Razorgore's eggs that miraculously survived in Blackwing Lair."] = "Одне з яєць Лезогора, що дивом уціліло в Лігві Чорнокрилих.",
    ["One of innumerable ghouls summoned by the Lich King in his final battle, left to roam the world for eternity."] = "Один із незліченних вурдалаків, яких прикликав Король-Ліч у своїй останній битві, приречений вічно блукати світом.",
    ["One of several indistinguishable pets, all named Chompy."] = "Один із кількох нерозрізнюваних улюбленців, усіх на ім'я Хрумчик.",
    ["One of the Darkmoon Race's most obnoxious obstacles, now in the palm of your hand!"] = "Одна з найдошкульніших перешкод Перегонів Самоцвітного Місяця — тепер у тебе на долоні!",
    ["One of the beasts left on the Timeless Isle when it shifted through time, most likely sacrificed by the Ordon to their demigod, Ordos."] = "Одна зі звірюк, що лишилася на Позачасовому Острові, коли він змістився крізь час; найімовірніше, принесена ордонами в жертву їхньому напівбогу Ордосу.",
    ["One of the earliest recorded victories in a large battle on Zandalar depicted mighty warriors riding into battle on armored raptors. The legend has it that the warrior did not choose their raptor, but that the raptor would choose the warrior."] = "Один із найдавніших записів про велику перемогу в битві на Зандаларі зображує могутніх воїнів, що мчать у бій на броньованих рапторах. Легенда каже, що не воїн обирав собі раптора, а раптор обирав собі воїна.",
    ["One of the microbots used to guard the city of Rustbolt, now purchasable for a reasonable price."] = "Один із мікроботів, що охороняли місто Іржоболт, тепер його можна придбати за помірну ціну.",
    ["One of the rarest creatures, this kaliri is set apart from others by its brilliant plumage and the lengths hunters will go to capture them."] = "Одне з найрідкісніших створінь, цей калірі вирізняється сяйливим оперенням і тим, на що готові піти мисливці, аби його впіймати.",
    ["One of the stranger nuisances to horticulturalists, garden frogs can cause untold damage to gardens."] = "Одна з химерніших напастей для садівників — садові жаби можуть завдати садам незліченної шкоди.",
    ["One of this cat's nine lives has returned to haunt the living by yowling loudly when you're trying to sleep."] = "Одне з дев'яти життів цього кота повернулося, щоб мучити живих гучним нявчанням, коли ти намагаєшся спати.",
    ["One ogre ritual involves cupping a bone wasp in their hands and shaking vigorously.  The venom increases strength and invokes vivid imagery."] = "Один оґрський ритуал полягає в тому, щоб затиснути в долонях кістяну осу й енергійно її трясти. Її отрута збільшує силу й викликає яскраві видіння.",
    ["One part beak, two parts wings, one part inability to stop, one part unwillingness to stop."] = "Одна частина дзьоба, дві частини крил, одна частина нездатності спинитися, одна частина небажання спинятися.",
    ["One part duplication, two parts duplication, four parts duplication... oops."] = "Одна частина роздвоєння, дві частини роздвоєння, чотири частини роздвоєння... ой.",
    ["One part facial sphere, one part cube manufactory, one part successful curiosity."] = "Одна частина лицьової сфери, одна частина кубофабрики, одна частина вдалої цікавинки.",
    ["One part focus, one part core, zero parts coherent or stable shape."] = "Одна частина фокусу, одна частина осердя, нуль частин зв'язної чи стійкої форми.",
    ["One part gills, one part haste, one part whatever it needs to be."] = "Одна частина зябер, одна частина прудкості, одна частина того, чим воно мусить бути.",
    ["One part rocks, two parts bigger rocks, three parts smaller rocks, one part ability to move anyway."] = "Одна частина каменів, дві частини більших каменів, три частини менших каменів, одна частина здатності рухатися попри все.",
    ["One part shell. One part claw. As many parts resilience as need be."] = "Одна частина панцира. Одна частина клешні. Стільки частин витривалості, скільки треба.",
    ["One part slippery skin, one part powerful legs, one part vocal sac, one part complete self-acceptance."] = "Одна частина слизької шкіри, одна частина потужних лап, одна частина голосового мішка, одна частина цілковитого самоприйняття.",
    ["One particular Broker has taken a liking to the skrat species, kept this rare specimin as a pet, and inherited the smell as a souvenir."] = "Один Брокер уподобав скратів, тримав цей рідкісний екземпляр як улюбленця й успадкував їхній сморід на згадку.",
    ["One shudders to imagine whether the name was based off of what it is... or what it does."] = "Аж здригаєшся, уявляючи, на чому ґрунтувалося ім'я — на тому, чим воно є... чи на тому, що воно робить.",
    ["Only a being of immense power could scar such an adorable creature, unless this hare was already approaching the darkness..."] = "Лише істота незмірної сили могла спотворити таке миле створіння — хіба що цей заєць уже й сам наближався до темряви…",
    ["Only found on the shores of Kezan, this lovely sea creature can be a bit snarky."] = "Цю чарівну морську істоту можна зустріти лише на берегах Кезану, і вона буває трохи дошкульною.",
    ["Only heroes who have proven their valor through great acts are gifted one of these mystical serpentine creatures."] = "Лише герої, що довели свою доблесть великими діяннями, отримують у дар одне з цих містичних зміїстих створінь.",
    ["Only magical wishes make magical crawdads. If you wish for a fish, fish for a wish."] = "Лише чарівні бажання творять чарівних раків. Хочеш рибу — лови бажання, хочеш бажання — лови рибу.",
    ["Only newly synthesized tunneling vombata have been seen. The rest are probably happily digging underground, never to be seen again."] = "Бачили лише щойно синтезованих риючих вомбат. Решта, мабуть, радісно копають під землею, і їх більше ніколи не побачать.",
    ["Only the dimwitted or insane would mount an infected deer head on their wall. The good news is they'll fit right in with their new undead friends."] = "Лише недоумкуватий чи божевільний повісив би на стіну голову зараженого оленя. Добра новина — він якраз припаде до душі своїм новим друзям-нежиті.",
    ["Only the rarest of murlocs is able to successfully cross dimensional barriers. Fewer still return with the kind of advanced armor and weaponry possessed by Grunty."] = "Лише найрідкісніші з мурлоків здатні успішно долати міжвимірні бар'єри. Ще менше з них повертаються з таким передовим обладунком і озброєнням, як у Ґрунті.",
    ["Oooh, shiny!"] = "Оооо, блискуче!",
    ["Opponents that face this fierce chromatic monstrosity just hope it doesn't have Time Stop!"] = "Супротивники, що стають проти цього лютого хроматичного страховиська, лиш сподіваються, що воно не володіє Зупинкою Часу!",
    ["Orcish children have a tradition where they sneak up on a mud jumper and whisper a secret they wish to come true.  If the mud jumper doesn't jump, the wish will come true."] = "В орчих дітей є звичай: підкрастися до баговинного стрибунця й прошепотіти заповітне бажання. Якщо стрибунець не стрибне, бажання справдиться.",
    ["Originally bred by the Sandfury trolls as pets, these feral and savage felines prowl the deserts of Tanaris."] = "Спершу виведені тролями Піщаної Люті за улюбленців, ці дикі й люті котячі нишпорять пустелями Танарісу.",
    ["Originally bred to make milk more palatable for gnomes."] = "Спершу виведені, щоб зробити молоко смачнішим для ґномів.",
    ["Originally built by Dr. DELVER to compete with renowned treasure hunter Brann Bronzebeard. Never really panned out though, so now he just helps out."] = "Спершу збудований доктором ДЕЛВЕРОМ, щоб змагатися з уславленим шукачем скарбів Бранном Бронзобородом. Але з цього так нічого й не вийшло, тож тепер він просто допомагає.",
    ["Originally built by an irate goblin to annoy neighbors with an early morning wake-up call."] = "Спершу зроблений розлюченим ґобліном, щоб дратувати сусідів ранковою побудкою.",
    ["Originally created by the engineers in the bowels of Gnomeregan, the Fluxfire Feline is a marvel of modern engineering."] = "Створений інженерами в надрах Ґномреґану, флюксвогняний котик — диво сучасної інженерії.",
    ["Other frogs like to play, but this one is feeling too blue."] = "Інші жаби люблять гратися, але цій надто сумно.",
    ["Otters swim by propelling themselves with their powerful tails and flexing their long bodies. Very fast in the water."] = "Видри пливуть, відштовхуючись потужними хвостами та згинаючи свої довгі тіла. Дуже швидкі у воді.",
    ["PRIMARY DIRECTIVE: ENGAGE IN HEROICS.\nPREFERRED HEROICS: THRILLING.\nSECONDARY DIRECTIVE: BECOME HERO.\nPREFERRED HERO: BIG."] = "ПЕРВИННА ДИРЕКТИВА: ЧИНИТИ ГЕРОЇЗМ.\nБАЖАНИЙ ГЕРОЇЗМ: ЗАХОПЛИВИЙ.\nВТОРИННА ДИРЕКТИВА: СТАТИ ГЕРОЄМ.\nБАЖАНИЙ ГЕРОЙ: ВЕЛИКИЙ.",
    ["Paleshell cave crabs are said to be the tastiest variety. Perhaps that's why they're the hardest to find."] = "Кажуть, печерні краби блідопанцирні — найсмачніший різновид. Можливо, саме тому їх найважче знайти.",
    ["Pallibrius is an amazing book because of its wealth of arcane knowledge. Also because of all the pie recipes its previous owner scribbled in the margins."] = "Палібріус — дивовижна книга через свою скарбницю таємних знань. А ще через усі рецепти пирогів, які попередній власник нашкрябав на берегах.",
    ["Parley is a rather serious and grumpy bird. If you value your eyeballs, it's best not to ask if Parley wants a cracker."] = "Парлей — доволі серйозний і буркотливий птах. Якщо тобі дорогі очі, краще не питай, чи хоче Парлей крекер.",
    ["Parrots can mimic speech, but have difficulty with meaningful conversation."] = "Папуги можуть наслідувати мову, та з осмисленою розмовою у них труднощі.",
    ["Parrots can't get enough of the fresh fish the Bloodscalp trolls eat. They're less interested in dry flatbreads."] = "Папуги ніяк не наїдяться свіжою рибою, яку їдять тролі Кривавого Скальпу. А ось сухими коржами вони цікавляться менше.",
    ["Part lean, mean candle-throwing machine. Part adventurer wannabe. All kobold."] = "Почасти худа, зла машина для метання свічок. Почасти невдаха-шукач пригод. Цілковито кобольд.",
    ["Part of the wildlife of Ardenweald, they sometimes sleep while standing straight up in the water."] = "Ці створіння — частина дикої природи Арденвельду, і часом вони сплять, стоячи стовпчиком прямо у воді.",
    ["Part owl, part bear... and part stag, which handily avoids potential lawsuits."] = "Почасти сова, почасти ведмідь... а почасти й олень, що зручно дозволяє уникнути можливих судових позовів.",
    ["Particularly partial to coastal scrub grasses, this hardy species has survived many years in uncharted lands."] = "Маючи особливу слабкість до прибережних чагарникових трав, цей витривалий вид вижив багато років у незвіданих землях.",
    ["Pay attention to deer crossings. Even a fawn will total a goblin trike."] = "Стережися переходів оленів. Навіть оленятко вщент розіб'є ґоблінський триколісник.",
    ["Peck. Peck. Zap!"] = "Дзьоб. Дзьоб. Бзззт!",
    ["People get turned into rats sometimes. It's not that weird."] = "Людей іноді перетворюють на щурів. Це не так уже й дивно.",
    ["Perhaps you'd like to see how snakelike it can be!"] = "Може, ви хотіли б побачити, яким зміїним воно може бути!",
    ["Perks its head up when hearing conversation as it likes to stay current on world affairs."] = "Нашорошує голову, зачувши розмову, бо полюбляє бути в курсі світових подій.",
    ["Pets often look a lot like their owners, which is especially true if the owner was a saberon."] = "Улюбленці часто дуже схожі на своїх господарів — і це особливо справедливо, якщо господар був сабероном.",
    ["Pistachio got her name in exactly the way you would expect."] = "Фісташка отримала своє ім'я саме так, як ти й очікуєш.",
    ["Plaguefeather and her brood feed well on the carrion the battle for Stromgarde has left scattered across the Highlands."] = "Чумоперо та її виводок добре годуються падлом, яке битва за Стромгард розкидала по всьому нагір'ї.",
    ["Playing fetch with a ray is always fun.  You don't even have to aim."] = "Гратися в апорт зі скатом завжди весело. Навіть цілитися не треба.",
    ["Please keep your blightbud on a leash at all times! They are notorious for the havoc they can wreak on unprotected gardens."] = "Будь ласка, завжди тримай свою порчебруньку на повідці! Вони сумнозвісні тим, що можуть улаштувати погром у незахищених садах.",
    ["Plucking a feather from a steward is considered a sin worthy of a trip to Revendreth."] = "Вирвати перо в стюарда вважається гріхом, гідним подорожі до Ревендрету.",
    ["Poda was just a small part of the larger business, always trying to live up to the standards of his older brother Coda."] = "Пода був лише дрібною часткою більшої справи й завжди намагався дорівнятися до свого старшого брата Коди.",
    ["Poking a tiny gormlng in the side makes a very satisfying, squishy noise. It is NOT advisable to poke one too many times."] = "Якщо штрикнути крихітного ґормлінга в бочок, він видає напрочуд приємний хлюпкий звук. Та штрикати його забагато разів НЕ радимо.",
    ["Poro cannot fly, but enjoys a long lifespan hopping along the ground and shaking the fruits from trees."] = "Поро не вміє літати, та живе довге життя, стрибаючи по землі й обтрушуючи плоди з дерев.",
    ["Posidriss is excited to go on adventures with you, but maybe let them have a nap first?"] = "Посідрісс у захваті від мандрів із вами, але, може, спершу дайте їй подрімати?",
    ["Possibly explosive, definitely adorable. Keep away from open flame."] = "Можливо, вибухова, та безперечно чарівна. Тримати подалі від відкритого вогню.",
    ["Powerful artillery of the Terran army. The Thor is always the first one in and the last one out!"] = "Потужна артилерія терранської армії. «Тор» завжди перший у бій і останній з нього!",
    ["Prefers flying during foggy nights, which are common in Azuremyst Isle."] = "Полюбляє літати туманними ночами, що часті на Острові Лазурного Серпанку.",
    ["Prefers flying during thunderstorms, which are common in Azuremyst Isle."] = "Полюбляє літати під час гроз, що часті на Острові Лазурного Серпанку.",
    ["Prefers to dwell along desert streams, wells or watering holes and feed on Whiptail nectar."] = "Полюбляє селитися біля пустельних струмків, криниць чи водопоїв і живитися нектаром батожинку.",
    ["Prefers to dwell in cool, forested areas and feed on Mageroyal nectar."] = "Воліє селитися у прохолодних, лісистих місцях і живитися нектаром магокоролівнику.",
    ["Prefers to dwell in corrupted woodlands and feed on Purple Lotus nectar."] = "Воліє селитися у спаплюжених лісах і живитися нектаром багряного лотоса.",
    ["Prefers to dwell in dark caves and feed on Heartblossom nectar."] = "Полюбляє селитися в темних печерах і живитися нектаром серцецвіту.",
    ["Prefers to dwell in humid, tropical areas and feed on Kingsblood nectar."] = "Воліє селитися у вологих, тропічних місцях і живитися нектаром королівнику.",
    ["Prefers to dwell in the shadow of Nordrassil and feed on Stormvine nectar."] = "Полюбляє селитися в тіні Нордрассилу й живитися нектаром штормолози.",
    ["Prefers to dwell in wet, muddy areas and feed on Sorrowmoss nectar."] = "Воліє селитися у вологих, багнистих місцях і живитися нектаром сумнику.",
    ["Previous owners of the crate have reported the disappearance of other pets from their collection."] = "Попередні власники цієї скрині повідомляли про зникнення інших улюбленців зі своєї колекції.",
    ["Primary responsibilities include dusting Medivh's many magical artifacts, an activity which has claimed the life, sanity, or physical composition of the many caretakers preceding Moroes."] = "Серед головних обов'язків — витирати пил із численних магічних артефактів Медіва; ця справа коштувала життя, розуму чи цілості тіла багатьом доглядачам, що були до Мороеса.",
    ["Princess Vorquistrasza wants you to know that she appreciates you coming to her birthday party, but is underwhelmed by your gift."] = "Принцеса Воркістрасза хоче, щоб ви знали: вона цінує, що ви прийшли на її день народження, але ваш подарунок її не вразив.",
    ["Prized by gem crafters, the undamaged carapace of a topaz hatchling can be used to create stunning inlays for rings and bracelets."] = "Цінований ювелірами, непошкоджений панцир топазового пташеняти можна використати для приголомшливих інкрустацій перснів і браслетів.",
    ["Prized for their ability to spin cocoons of silk, in the wild, to the untrained eye, they can be difficult to discern."] = "Цінуються за здатність прясти шовкові кокони; у дикій природі недосвідченому оку їх буває важко розгледіти.",
    ["Probably best not to touch it."] = "Мабуть, краще цього не торкатися.",
    ["Projections showed a less than one percent chance of successful integration, but this one is too cute to eliminate."] = "Прогнози показали менш ніж однопроцентний шанс успішної інтеграції, та цей надто милий, щоб його позбутися.",
    ["Prolonged exposure to Shaohao's tranquil mists has calmed these spirits, which act as peaceful companions to the Mistweavers."] = "Тривалий вплив спокійних туманів Шаохао заспокоїв цих духів, і тепер вони слугують мирними супутниками туманотворцям.",
    ["Protorams leave behind stony dust as they frolic, battle, and rest."] = "Протобарани лишають по собі кам'янистий пил, коли пустують, б'ються й відпочивають.",
    ["Protosheep spend winters bereft their flowers. When the seasons turn, the plains are filled with a variety of earthy, sweet scents."] = "Протовівці проводять зими без своїх квітів. Коли змінюються пори року, рівнини сповнюються розмаїттям землистих, солодких ароматів.",
    ["Proximity to Antorus makes these larva hyper agressive."] = "Близькість до Анторуса робить цих личинок украй агресивними.",
    ["Pterrordax eggs are incubated underneath the fossils of their forebears, allowing the hatchlings to absorb their ancestors' ferocity and intelligence."] = "Яйця птеродактів виношують під скам'янілостями предків, щоб пташенята вбирали лютість і кмітливість своїх пращурів.",
    ["Puddlehoppers are known to eat bugs almost as large as they are. In one gulp!"] = "Калюжостриби відомі тим, що їдять комах майже з себе завбільшки. Одним ковтком!",
    ["Pulled from a horrific vision of Orgrimmar these toads are soaked in void energy."] = "Вирвані з жахливого видіння Оґриммару, ці жаби просякнуті енергією Порожнечі.",
    ["Purrkins are a traditional pet of the Brokers and the two have a mutually beneficial relationship -- a necessity in Broker culture."] = "Муркіни — традиційні улюбленці Брокерів, і між ними панують взаємовигідні стосунки — необхідність у культурі Брокерів.",
    ["Puts the fan in fanatic!"] = "Справжній фанат своєї справи!",
    ["Quack."] = "Кря.",
    ["Queen Azshara's curse over the denizens of Azsuna did not only affect the night elves. This shark is doomed to an eternity of bottomless hunger."] = "Прокляття королеви Азшари, накладене на мешканців Азсуни, торкнулося не лише нічних ельфів. Ця акула приречена на вічність бездонного голоду.",
    ["Quest: Mega-Mecha Gorilla|nZone: Undermine"] = "Квест: Меґа-Меха-Горила|nЗона: Підрудня",
    ["Quilen were the favored companions of the ancient Mogu race due to their loyal nature."] = "Квілени були улюбленими супутниками прадавнього народу могу завдяки своїй відданій вдачі.",
    ["Quoth the raven: the last word you said. It gets old."] = "Промовив крук: останнє ваше слово. Це швидко набридає.",
    ["RELAXATION MODE: ENGAGED.\nRELAXATION LEVEL: MAXIMUM.\nINTERNAL TEMPERATURE: LOW."] = "РЕЖИМ ВІДПОЧИНКУ: УВІМКНЕНО.\nРІВЕНЬ ВІДПОЧИНКУ: МАКСИМАЛЬНИЙ.\nВНУТРІШНЯ ТЕМПЕРАТУРА: НИЗЬКА.",
    ["Raindrops whip around this creature with frightening speed, ripping and tearing anything that touches it. Experts say the best way to avoid injury is to give it a treat and some snuggles."] = "Краплі дощу шмагають навколо цієї істоти з лячною швидкістю, шматуючи й роздираючи все, що її торкнеться. Знавці кажуть, що найкращий спосіб уникнути поранень — почастувати її ласощами та трохи попестити.",
    ["Raised as living tanks for Anub'azal's army, Rak-Ush's battleshells are surprisingly affectionate. Who's a good beetle?"] = "Виплекані як живі танки для армії Ануб'азала, бойові панцирники Рак-Уша на диво ласкаві. Хто тут гарний жучок?",
    ["Raised by the few dealers still willing to trade in Netherstorm."] = "Вирощене тими нечисленними торгашами, що досі готові вести справи в Нетерстормі.",
    ["Raised in the verdant groves of Ardenweald, these kits are infused with the essence of rebirth."] = "Виплекані в зелених гаях Арденвельду, ці лисенята просякнуті сутністю відродження.",
    ["Rarely captured alive, syphoners are some of the most dangerous of the mana wyrms. This one happened to have been distracted while binging on a particularly juicy spell book in the Karazhan library."] = "Рідко спіймані живими, сифонери — одні з найнебезпечніших манячервів. Цього випадково відволікли, поки він об'їдався особливо соковитою книгою заклять у бібліотеці Каражану.",
    ["Rarely leaves nest until maturity. Enjoys conducting pranks on the nearby Razormaw nest."] = "Рідко полишає гніздо до змужніння. Полюбляє влаштовувати капості сусідньому гнізду Гостропащів.",
    ["Rarely raised in captivity, Tallstrider's are extremely territorial. A small clutch of eggs was found during a hunt, and a tauren trainer came to Orgrimmar to show them off. However, after the fall, they have become deadly once more. So far, no one has been able to direct their corrupted forms."] = "Високоступів рідко вирощують у неволі, бо вони надзвичайно територіальні. Під час полювання знайшли невелику кладку яєць, і дресирувальник-таврен привіз їх до Оґриммара похизуватися. Та після падіння вони знову стали смертоносними. Поки що нікому не вдалося приборкати їхні зіпсовані форми.",
    ["Rarely, one of these kits is born to a golden-furred vulpin. It is considered a sign of distress in the pack."] = "Зрідка таке лисеня народжується у вульпіна із золотим хутром. Зграя вважає це знаком прийдешньої біди.",
    ["Ravaged by the invading naga, many hawkstriders died in the area of Daggerspine Point. It is rare to find any of their young yet alive."] = "Багато соколострибів загинуло в околицях Мисливки Кинджалоспинних, спустошених навалою наг. Рідко вдається знайти їхнє молоде ще живим.",
    ["Ravagers are favored ogre snacks when they are small and less deadly."] = "Спустошувачі — улюблені огрячі ласощі, поки малі й менш смертоносні.",
    ["Razeshi B. is known for her short temper, quick wit and sharp barbs. The B. stands for \"Best check yourself.\""] = "Разеші Б. відома гарячою вдачею, гострим розумом і дошкульними кпинами. Б. означає «Бережись».",
    ["Razeshi C. is known for her understanding tempermant, measured responses and a love for gossip. The C. stands for \"Class act.\""] = "Разеші Ш. відома своєю поблажливою вдачею, виваженими відповідями й любов'ю до пліток. Ш. означає «шляхетна особа».",
    ["Razormaw eggs are protected fiercely by their mothers. Their cuteness belies their inherited ferocity."] = "Яйця Гострозубів люто оберігають їхні матері. Миловидність малят приховує вроджену лютість.",
    ["Razzashi raptors are among the cleverest predators in the jungle, making them favored by the Gurubashi trolls."] = "Раптори Раззаші — одні з найрозумніших хижаків джунглів, тому їх так цінують тролі Ґурубаші.",
    ["Reaching for what you thought was a pile of plunder turned out to be Sparklesnap's treasure-laden shell. After mistakenly petting his back, he now eagerly follows you."] = "Потягнувшись до того, що ти вважав купою награбованого, ти намацав укритий скарбами панцир Іскрохруста. Коли ти випадково погладив його спину, він тепер завзято ходить за тобою.",
    ["Reaching out from some vast unknown corner of the void... to give you a hug."] = "Тягнеться з якогось безмежного незвіданого закутка Порожнечі... щоб тебе обійняти.",
    ["Really much more tolerable when he's not riding on your head."] = "Його справді набагато легше терпіти, коли він не сидить у тебе на голові.",
    ["Red for the fires in which it was born."] = "Червоний — як вогонь, у якому він народився.",
    ["Reduces the likelihood of being eaten by monsters when you enter pitch-black places."] = "Зменшує ймовірність бути з'їденим монстрами, коли заходиш у геть темні місця.",
    ["Remornia has been exposed to untold amounts of evil and sin, and will siphon power from any available source to fuel its desires."] = "Реморнія зазнала незліченної кількості зла й гріха і висмоктуватиме силу з будь-якого доступного джерела, щоб живити свої жадання.",
    ["Rescued from the Druids of the Flame's onslaught upon the Emerald Dream, this juvenile faerie dragon has taken a liking to you -- and to your food. Don't leave your snacks unattended!"] = "Урятований від навали Друїдів Полум'я на Смарагдовий Сон, цей юний феєричний дракон пройнявся симпатією до вас — і до вашої їжі. Не лишайте свої наїдки без нагляду!",
    ["Restoring hope to those lost in the darkness comes with its just rewards. Like cute frog friends."] = "Повернення надії тим, хто загубився в темряві, має свою заслужену винагороду. Як-от милі жаб'ячі друзі.",
    ["Ride with the moon (and this furry, whiskered witch) in the dead of night!"] = "Мчи з місяцем (і цією пухнастою вусатою відьмою) глупої ночі!",
    ["Rigorously trained from birth these young boars eat, fight and sleep in their armor."] = "Суворо натреновані від народження, ці молоді кабани їдять, б'ються і сплять у своїх обладунках.",
    ["Rikki has a talent for sneaking in and out of all manner of small spaces, if bribed properly with figs."] = "Ріккі має хист прослизати в усілякі тісні закутки й вибиратися назад — якщо його гарненько підкупити інжиром.",
    ["River otters start growing whiskers at a very young age and never stop.  By the time they are fully grown and reach old age, they have more whiskers on their face than any other known creature."] = "Річкові видри починають відрощувати вуса змалечку й ніколи не припиняють. До старості, коли вони вже геть дорослі, вусів на їхній мордочці більше, ніж у будь-якої іншої відомої істоти.",
    ["Rock martins make their nests out of scavenged pebbles."] = "Скельні ластівки звивають гнізда зі знайденої гальки.",
    ["Roggy is the kind of snail that never gives up, no matter how hard things get."] = "Роґґі — той слимак, що ніколи не здається, хоч би як важко було.",
    ["Rogues often kept a few of these in their pockets in times of emergency. Don't ask me why."] = "Розбійники у скрутну хвилину часто тримали кілька таких у кишенях. Не питай чому.",
    ["Rolls into a protective ball when it feels threatened. Or when its mother calls."] = "Згортається у захисну кульку, коли почувається в небезпеці. Або коли його кличе мати.",
    ["Roofus is ready to lend a paw for any construction project. Treats aren't required, but are appreciated."] = "Дахус готовий підставити лапу для будь-якого будівельного проєкту. Ласощі не обов'язкові, та завжди до вподоби.",
    ["Rook never speaks, and little about them is known."] = "Рук ніколи не говорить, і про нього мало що відомо.",
    ["Roosting in the grounds of Castle Nathria, The Count did not foresee falling into an eternal stone slumber."] = "Угніздившись у володіннях замку Натрія, Граф і не передбачав, що порине у вічний кам'яний сон.",
    ["Roosting over Sinfall, Battie was roused one evening by the music of the first Ember Court. She has not missed a single one since."] = "Угніздившись над Гріхопадом, Беті одного вечора прокинулася від музики першого Двору Жароцвіту. Відтоді вона не пропустила жодного.",
    ["Roseshells are known to be very agressive, but aren't very fast. So if you mess with one, prepare to be bitten in about five seconds."] = "Рожевопанцирі відомі своєю агресивністю, але не надто прудкі. Тож якщо зачепите такого, готуйтеся, що вас вкусять секунд за п'ять.",
    ["Rub its belly more than twice and you're just asking to be pounced on."] = "Почухай йому черевце більше двох разів — і сам напрошуєшся, щоб на тебе стрибнули.",
    ["Rumor has it that some beasts that were touched by the void exist in a space between this world and the next."] = "Подейкують, що деякі звірі, торкнуті Порожнечею, існують у просторі між цим світом і потойбіччям.",
    ["Rumored to be the familiar of a ren'dorei mage that escaped to the wilds of Voidstorm and became even more void infused."] = "Подейкують, що це фамільяр мага рен'дорай, який утік у нетрі Войдшторму й просочився Порожнечею ще дужче.",
    ["Rusty's powerful nose could smell a needle in a haystack."] = "Потужний ніс Расті відчув би голку в копиці сіна.",
    ["Rusziona's newfound courage means she can accompany you on adventures! Nothing in all of Azeroth can stop her! Not even a duck!"] = "Новонабута відвага Рузіони означає, що вона може супроводжувати вас у пригодах! Ніщо в усьому Азероті не спинить її! Навіть качка!",
    ["Said to bring good fortune when spotted in autumn.  Known to hide from unfamiliar creatures."] = "Кажуть, що побачити його восени — на щастя. Відомий тим, що ховається від незнайомих створінь.",
    ["Sapnibblers are always up for a game of hide and squeak."] = "Сокогризи завжди не проти зіграти в хованки з писком.",
    ["Saurolisk scales are a surprisingly flexible but durable material that are often used to reinforce or mend things that are broken or worn through."] = "Луска сауроліска — напрочуд гнучкий, але міцний матеріал, який часто використовують, щоб укріпити чи полагодити зламані або зношені речі.",
    ["Scholars have debated at length about how fireflies glow, but the leading hypothesis is \"magic\"."] = "Дослідники довго сперечалися, як саме світяться світляки, але провідна гіпотеза — «магія».",
    ["Scientists, engineers, and gamers of Undermine must keep their desks clean lest they be visited by the underroaches."] = "Науковці, інженери та геймери Підрудні мусять тримати столи чистими, бо інакше до них завітають підрудні таргани.",
    ["Scout came to the Dragon Isles for adventure and excitement. After finding you, he got both."] = "Скаут прибув на Драконові Острови по пригоди та хвилювання. Знайшовши вас, він отримав і те, й інше.",
    ["Scrap metal hunks hauling junk."] = "Купи металобрухту, що тягають брухт.",
    ["Scruffles' lust for battle runs deep."] = "Жага бою у Кошлая глибоко вкорінена.",
    ["Scuttle was named after the ships he destroys, not his movement patterns, and don't you forget it."] = "Шкряботуна назвали так за кораблі, що він пускає на дно, а не за манеру руху, — і не смій про це забувати.",
    ["See reflections on the water? There's more than darkness in the depths."] = "Бачиш відблиски на воді? У глибині є не лише темрява.",
    ["Seedles burrow beneath plants in the emerald dreams and nibble at their roots."] = "Насінчики зариваються під рослини у Смарагдовому Сні й гризуть їхнє коріння.",
    ["Seeing these kites soaring above Northrend's shores is a clear sign that tuskarr are nearby."] = "Якщо побачиш цих повітряних зміїв, що ширяють над берегами Нортренду, — це певна ознака, що десь поруч тускари.",
    ["Seeks out the light of the stars. Even in the daytime."] = "Шукає світло зірок. Навіть удень.",
    ["Seems odd that he doesn't like flies... right?"] = "Дивно, що вона не любить мух... правда ж?",
    ["Senega is always ready for a ley crystal snack."] = "Сенеґа завжди готова поласувати лей-кристалом.",
    ["Sent through the Twisting Nether by the great Archimonde the Defiler to terrorize tiny civilizations with their medium-sized stomping noises."] = "Послані крізь Викривлену Порожнечу великим Архімондом Осквернителем, щоб тероризувати крихітні цивілізації своїм середнього розміру тупотінням.",
    ["Separated from his mother when they were captured. Chubs is sad but fierce. He takes pride when he can bite his Twilight Blade handlers hands at feeding time."] = "Розлучений з матір'ю, коли їх схопили. Пухкань сумний, але лютий. Він пишається, коли може вкусити руки своїх доглядачів зі Сутінкового Клинка під час годівлі.",
    ["Several adventurous miners have gone after the jade quilen in search of riches, but none have ever been heard from again."] = "Кілька завзятих шахтарів подалися за нефритовим квіленом у пошуках багатств, та про жодного з них більше ніхто не чув.",
    ["Sha has warped this hippogryph hatchling into an adorable but fearsome creature. The big emotions that flow through this creature make it an adorable harbinger of doom."] = "Ша спотворив це пташеня гіпогрифа на чарівну, але грізну істоту. Сильні емоції, що вирують у цьому створінні, роблять його чарівним передвісником загибелі.",
    ["Sha-lings reflect the emotional state of their handler, becoming agitated, depressed, fearful, or doubtful depending on the magnitude of negative thoughts around them."] = "Ша-малята відображають емоційний стан свого господаря, стаючи збудженими, пригніченими, наляканими чи сповненими сумнівів залежно від сили негативних думок навколо.",
    ["Shack crabs are the only species of hermit crabs known to regenerate limbs if torn off in battle."] = "Краби-халупники — єдиний відомий вид раків-самітників, здатний відрощувати кінцівки, відірвані в бою.",
    ["Sharp crystal needles protrude from this creature's back, and yet it still wants you to pet it somehow."] = "Гострі кристалічні голки стирчать зі спини цієї істоти, та все ж вона якось хоче, щоб ви її погладили.",
    ["Sharptalon falcosaurs can subsist entirely on a diet of small nuts and berries, and use their talons mostly for defense."] = "Фалькозаври-гострокігті можуть жити виключно на дрібних горіхах і ягодах, а кігті використовують переважно для захисту.",
    ["She hates head pats, hence the spiky armor."] = "Вона ненавидить, коли її гладять по голові, звідси й колюча броня.",
    ["She just wanted to get away. Find a nice shell. Sit on a beach. Now she's your pet."] = "Вона лише хотіла втекти. Знайти гарну мушлю. Посидіти на пляжі. А тепер вона твоя улюблениця.",
    ["She likes the company of friends. Seventy-five of them, to be precise."] = "Вона любить товариство друзів. Сімдесяти п'яти, якщо бути точним.",
    ["She loves tummy rubs. Just watch out for splinters."] = "Вона обожнює, коли їй чухають черевце. Тільки стережися скалок.",
    ["She sees you when you're sleeping."] = "Вона бачить вас, коли ви спите.",
    ["She'll try spinning, that's a good trick."] = "Вона спробує крутитися — це непоганий трюк.",
    ["She's got a schnoz for sniffin'!"] = "У неї добрий нюх на винюхування!",
    ["She's the devil on your shoulder, whispering in your ear."] = "Вона — той біс на твоєму плечі, що шепоче тобі на вухо.",
    ["Shimmermoths don't actually shimmer in the sunlight. Nobody knows who named these, but they have a lot to answer for."] = "Мерехтливі метелики насправді зовсім не мерехтять на сонці. Ніхто не знає, хто дав їм таку назву, але цій людині є за що відповідати.",
    ["Shrugs off boiling oil and eleven secret herbs and spices. Just don't introduce it to rust."] = "Не зважає на киплячу олію й одинадцять таємних трав та спецій. Тільки не знайом його з іржею.",
    ["Siege training begins early for kodo calflings that show a lack of inhibition towards breaking things. Mind your shins."] = "Облогове навчання починається рано для кододнят, що виявляють брак стриманості до руйнування речей. Бережи свої гомілки.",
    ["Silver dust sparkling on each of this spider's legs attracts prey; unwittingly drawn into an inescapable web."] = "Срібний пил, що виблискує на кожній нозі цього павука, приваблює здобич, яка несвідомо потрапляє в безвихідне павутиння.",
    ["Since Amirdrassil's emergence, many faerie dragons have taken refuge in Belameth. But many others continue to call Kalimdor home."] = "Відколи постав Амірдрассіл, багато чарівних драконів знайшли прихисток у Беламеті. Та багато інших і досі звуть домівкою Калімдор.",
    ["Since synthesized creatures come into being fully grown, why would anyone design an immature helicid?"] = "Якщо синтезовані створіння постають уже дорослими, навіщо комусь проєктувати недозрілого геліцида?",
    ["Since you rescued her from Larodar, this grateful little doe hasn't stopped following you around."] = "Відколи ви врятували її від Лародара, ця вдячна маленька оленичка не перестає ходити за вами.",
    ["Siphonmites generally feed on the energies of dying worlds, but this one is perfectly content with getting some scritches from researchers instead."] = "Поглинокліщі зазвичай живляться енергією вмираючих світів, але цей цілком задоволений тим, що його натомість чухають дослідники.",
    ["Six legs, two claws, multiple eyes, spiked body? This thing has it all!"] = "Шість ніг, дві клешні, безліч очей, шипасте тіло? Ця істота має все!",
    ["Skaarn likes to coil up inside of your backpack."] = "Скаарн любить згортатися у вашому наплічнику.",
    ["Skrats are an especially invasive species, in that they can reproduce with only a sole skrat, and consume almost anything."] = "Скрати — надзвичайно інвазивний вид: вони можуть розмножуватися з одного-єдиного скрата й поїдають майже все.",
    ["Skrats are poisonous, venomous, and unusually damp -- everything you want in a pet."] = "Скрати отруйні, отруйно-кусючі й напрочуд вологі — усе, чого хочеться від улюбленця.",
    ["Skunks are known as solitary creatures for reasons which are hopefully obvious."] = "Скунси відомі як самітні створіння — з причин, які, сподіваймося, очевидні.",
    ["Skyfin can be observed in a wide variety of colors. Biologists believe the vibrancy of those colors both help attract mates and ward predators."] = "Небоплавів можна побачити в найрізноманітніших барвах. Біологи вважають, що яскравість цих кольорів водночас допомагає приваблювати партнерів і відлякувати хижаків.",
    ["Skyfin can fly from birth and there are some observed cases of mothers giving birth midflight!"] = "Небоплави вміють літати від народження, і відомі випадки, коли самиці народжували просто в польоті!",
    ["Sleeping is this cat's second favorite activity. The first is yawning."] = "Сон — друге улюблене заняття цього кота. Перше — позіхати.",
    ["Slimy sea slugs secrete slimy sea slug slime on the slimy sea floor."] = "Слизькі слимаки спускають слизький слимачий слиз на слизьке морське дно.",
    ["Slimy, yet also gritty. It would not make a good meal."] = "Слизький, але водночас піщанистий. Поганий би вийшов обід.",
    ["Slippery Saul loves to slide around the ground or the sea looking for fish."] = "Слизький Сол обожнює ковзати по землі чи по морю в пошуках риби.",
    ["Slow and steady wins the race."] = "Тихіше їдеш — далі будеш.",
    ["Sly snuck aboard for a trip into the Maw. He's not scared, he just really wants to stay in your backpack for a while."] = "Слай прокрався на борт у подорож до Пащі. Він не боїться — просто йому дуже хочеться ще трохи посидіти в твоєму наплічнику.",
    ["Small elemental saplings grow into treants, fierce defenders of forests and groves."] = "Маленькі елементальні паростки виростають у трентів — затятих захисників лісів і гаїв.",
    ["Small, snappy, and with a temper as explosive as its name. Handle with caution!"] = "Маленьке, кусюче, з вибуховою вдачею, що цілком відповідає його імені. Поводься обережно!",
    ["Smoochums loved life in Glenbrook, it was full of people to play with and places to sleep, and also where unspeakable acts happen at the most innocent of tea parties."] = "Цьомчик обожнював життя в Ґленбруку: там було повно людей, з якими можна гратися, і місць, де можна спати, а ще там коїлися невимовні речі під час найбезневинніших чаювань.",
    ["Snapdragon pups that were abandoned on the shores have become infused with the energies of the Seafury Tempest, as the other Siren Isle creatures have."] = "Щенята-снапдракони, покинуті на берегах, просякли енергіями Морелютого Шторму, як і інші створіння Острова Сирен.",
    ["Snooters have a very good sense of smell and can easily find grass and seeds buried under snow or scrap."] = "Нюхалі мають дуже гострий нюх і легко знаходять траву й насіння, поховані під снігом чи мотлохом.",
    ["Snoots has a supernatural sense of smell. It's not any better than normal, it's just supernatural."] = "Снутс має надприродний нюх. Він не кращий за звичайний, він просто надприродний.",
    ["Snoozles was once given a choice between life in the timeless beautiful snowfields and life in a warm home with pet treats. We know which one he chose."] = "Дрімунчику колись запропонували вибір між життям у позачасових прекрасних снігових полях і життям у теплій домівці з ласощами. Ми знаємо, що він обрав.",
    ["Snowfeather falcosaur hatchlings instinctively flee to nearby adults when threatened. The species is particularly fond of large prey."] = "Малята фалькозаврів сніжного пера інстинктивно тікають до дорослих, що поряд, коли їм загрожує небезпека. Цей вид особливо полюбляє велику здобич.",
    ["So cute, yet so epic."] = "Таке миле, та водночас таке епічне.",
    ["So long as one of his Sproutlings remains, Branchlord Aldrus will never truly die."] = "Доки лишається бодай один із його Паростків, Гілковолодар Алдрус ніколи по-справжньому не загине.",
    ["So much holiday spirit inside an itty-bitty amount of snow, it only makes sense to share it with the world!"] = "Стільки святкового настрою в малесенькій жменьці снігу, що просто гріх не поділитися ним з усім світом!",
    ["So pretty you could eat it. But don't. It's poisonous."] = "Таке гарне, що аж з'їв би. Але не варто. Воно отруйне.",
    ["So wrinkly!! So scrunchy!!"] = "Такий зморшкуватий!! Такий зіжмаканий!!",
    ["Softshell turtle meat is considered a delicacy and is the key ingredient in soothing turtle bisque."] = "М'ясо м'якопанцирної черепахи вважається делікатесом і є головною складовою заспокійливого черепахового бісквіту.",
    ["Solid and dependable, Iggy is always ready for a fierce battle or a gentle metaphor."] = "Надійний і твердий, Іґґі завжди готовий до запеклого бою або лагідної метафори.",
    ["Some Pandaren believe G'nathus to be an ancient Zandalari Loa left behind to guard the waters south of Lei Shen's island citadel."] = "Деякі пандарени вірять, що Ґ'натус — прадавній лоа зандаларі, лишений стерегти води на південь від острівної цитаделі Лей Шена.",
    ["Some argue that the beard is what grants a spell caster their power, but they're wrong. The hat is where the magic is really from."] = "Дехто запевняє, що силу чаклунові дає борода, але вони помиляються. Насправді вся магія — у капелюсі.",
    ["Some druids say pandaren and raccoons are distant cousins, but never when a pandaren can hear them."] = "Дехто з друїдів каже, що пандарени та єноти — далекі родичі, але ніколи тоді, коли пандарен може їх почути.",
    ["Some fragments of Deathwing's blood live on to this day, deep within the lost places of the world, forever seeking their lost host."] = "Деякі частки крові Дезвінга живуть і донині, у загублених закутках світу, вічно шукаючи свого втраченого володаря.",
    ["Some frenzies have been touched by whispers in the deep, and seek to turn the tides red with blood."] = "Деяких шаленців торкнувся шепіт глибин, і тепер вони прагнуть забарвити приплив кров'ю.",
    ["Some hawkstriders are destined to be great. Others are destined to be Egbob."] = "Деяким соколиськам судилася велич. Іншим судилося бути Еґбобом.",
    ["Some leporids are docile and cute. Others are... still cute."] = "Деякі лепориди сумирні й милі. Інші... все одно милі.",
    ["Some of the few remaining fleshy creatures on Mechagon, they provide food and even companionship for the citizens of Rustbolt."] = "Одні з небагатьох уцілілих створінь із плоті на Мехаґоні, вони дають мешканцям Іржоболту їжу й навіть товариство.",
    ["Some of the more adventurous denizens of Zereth Mortis consider venomous bufonids to be a delicacy."] = "Дехто з відважніших мешканців Зерет Мортіса вважає отруйних буфонідів делікатесом.",
    ["Some of the more timid leporids live deep underground. They emerge only to gather food before returning to their burrows."] = "Деякі несміливіші лепориди живуть глибоко під землею. Вони виходять лише по їжу, а тоді повертаються до своїх нір.",
    ["Some of the smaller scarabids of Zereth Mortis have metallic outer shells to protect themselves. It also makes them look fabulous."] = "Деякі дрібніші скарабіди Зерет Мортіса мають металеві зовнішні панцири для захисту. А ще завдяки їм вони мають розкішний вигляд.",
    ["Some predators in Maldraxxus collect spines as trophies, and some of them don't stop moving even then."] = "Деякі хижаки Малдраксуса збирають хребти як трофеї, і дехто з тих хребтів навіть після цього не припиняє ворушитися.",
    ["Some say it's the pup of Riplimb and Rageface, others say 'I don't want to think about that.'"] = "Дехто каже, що це цуценя Рваноногого та Лютоморди, а інші відказують: «Не хочу про це й думати».",
    ["Some say this clever bird can be taught to speak--but it's smart enough to keep its beak shut."] = "Дехто каже, що цього кмітливого птаха можна навчити говорити — та він достатньо розумний, щоб тримати дзьоба на замку.",
    ["Some species of red bees are known to lead solitary lives. Still, this busy bee seems happy to make time for you."] = "Деякі види червоних бджіл відомі тим, що ведуть самотнє життя. Та все ж ця працьовита бджілка, схоже, рада приділити тобі час.",
    ["Some tarachnids prefer to lie in wait for their prey. These prefer to chase it, disable it, and devour it whole."] = "Деякі тарахніди полюбляють чигати на здобич. А ці воліють її переслідувати, знешкоджувати й ковтати цілою.",
    ["Some think this creature is smoldering because it is on fire. In truth it's because of its burning gaze."] = "Дехто думає, що це створіння тліє, бо палає. Насправді — через свій палючий погляд.",
    ["Some very clever wizard or dragon or other magical being thought they were being clever when they decided to color an ice elemental purple for a very elaborate bit of wordplay. They were probably right."] = "Якийсь дуже розумний чарівник, чи дракон, чи інша магічна істота вважала себе дуже дотепною, коли вирішила пофарбувати крижаного елементаля у фіолетовий заради надміру вигадливої гри слів. Мабуть, вона мала рацію.",
    ["Some young and rambunctious hozen are trained from an early age to use boxing gloves so they don't accidentally kill their tribe members, and more importantly, to keep them from picking their noses."] = "Деяких юних і норовливих гозенів змалку привчають носити боксерські рукавиці, щоб вони ненароком не повбивали одноплемінців, а ще важливіше — щоб не колупалися в носі.",
    ["Someday, his heavy footfalls and ferocious roar will match his name. Until then, Thunder remains a bolt of cuteness and loyalty."] = "Колись його важка хода й люте ревіння відповідатимуть його імені. А поки що Грім лишається грудочкою чарівності та відданості.",
    ["Somehow pretty and gross at the same time."] = "Якимось чином гарне й гидке водночас.",
    ["Somehow this creature manages to be hot, rocky, and slimy all at the same time."] = "Якимось чином це створіння примудряється бути гарячим, кам'янистим і слизьким водночас.",
    ["Someone once mistook Fringe for an azerite node. He's too young to remember azerite, though."] = "Якось хтось переплутав Облямівку з покладом азериту. Хоча він замолодий, щоб пам'ятати азерит.",
    ["Someone put this mechanical gorilla on the island to monitor the species, but who, and why?"] = "Хтось залишив цю механічну горилу на острові, щоб стежити за тваринами, але хто і навіщо?",
    ["Something about this creature looks familiar..."] = "Щось у цьому створінні видається знайомим...",
    ["Sometimes it is best to leave what strange creature you found in a mysterious jar in the depths of Torghast alone."] = "Інколи дивне створіння, знайдене в загадковому глеку в надрах Торгасту, краще лишити в спокої.",
    ["Sometimes sins of great souls are so powerful that they animate the very stones they are placed on."] = "Іноді гріхи великих душ настільки могутні, що оживляють самі камені, на які їх покладено.",
    ["Sometimes the void's call is faint, so smaller, younger voidwalkers heed its call."] = "Іноді поклик порожнечі ледь чутний, тож дрібніші, молодші порожнехідці дослухаються до нього.",
    ["Sometimes you can see blue light flickering deep inside the gems that make up this strange creature."] = "Іноді можна побачити, як блакитне світло мерехтить глибоко в самоцвітах, з яких складається ця дивна істота.",
    ["Somnius is legendary for her ability to sleep through everything except suppertime."] = "Сомнія легендарна своєю здатністю проспати все, окрім часу вечері.",
    ["Soon after you put down this slyvern's decay-twisted mother, you learned the hard way both how it got its name and why Zon'Wogi asked you to care for it."] = "Невдовзі після того, як ти прикінчив зотлілу від гнилі матір цього слайверна, ти на власній шкурі дізнався і як він дістав своє ім'я, і чому Зон'Воґі попросив тебе про нього подбати.",
    ["Spawn of Onyxia, this young dragon has decided that it doesn't want to follow in its grandfathers' cataclysmic footsteps."] = "Поріддя Онуксії, цей юний дракон вирішив, що не хоче йти катаклізмічними стопами свого діда.",
    ["Spawn of the nefarious Shrieker Scarabs of Ahn'Qiraj, the hatchlings are much more docile (and quiet) than their parents."] = "Нащадки лиховісних верескливих скарабеїв Ан'Кіражу, ці малята набагато сумирніші (й тихіші) за своїх батьків.",
    ["Specimen 97 escaped from his cage before being fully mechanized. Now, he seeks revenge."] = "Зразок 97 утік зі своєї клітки, перш ніж його повністю механізували. Тепер він прагне помсти.",
    ["Spineclaw crabs of Pandaria have existed for thousands of years and remain one of the continent's oldest creatures."] = "Колючоклешневі краби Пандарії існують уже тисячі років і лишаються одними з найдавніших створінь континенту.",
    ["Spireshells produce a softer shell when young which will be grown out of quickly."] = "Шпилемушлі замолоду мають м'якшу мушлю, з якої швидко виростають.",
    ["Spriggans are tricky foes that live in Ardenweald and torment the Night Fae. This one has decided to play the ultimate trick--joining you."] = "Спригани — підступні вороги, що живуть в Арденвельді й мучать Нічних Фей. А цей вирішив утнути найбільшу витівку — приєднатися до тебе.",
    ["Spring rabbits symbolize fertility, and they love to demonstrate why."] = "Весняні кролики символізують плодючість і обожнюють демонструвати, чому саме.",
    ["Spunky, funky, and just a little clunky -- she's a Gnomish engineer to a T!"] = "Завзята, химерна й трішки незграбна — справжнісінька ґномська інженерка!",
    ["Squeeeeeeeawk!"] = "Кря-я-я-я-як!",
    ["Squibbles is engineered to never leave your side."] = "Сквіблса сконструйовано так, щоб він ніколи не відходив від тебе.",
    ["Stagshells crave violence. Or at least simulated representations of violence."] = "Оленепанцирники жадають насильства. Або принаймні вдаваних подоб насильства.",
    ["Standing next to a brinestone algan will remind you of the smell of the sea, mixed with rotting kelp."] = "Стоячи поряд із солекам'яним алґаном, ти пригадаєш запах моря впереміш зі смородом гнилих водоростей.",
    ["Star just hatched and is ready for adventure. Sometimes napping is the greatest adventure of all."] = "Зірочка щойно вилупилася й готова до пригод. Іноді дрімота — найбільша пригода з усіх.",
    ["Staring at one of these creates a deep void of emotion at the very core of your being, then fills it with a sense of dread."] = "Якщо вдивлятися в одне з них, у самісінькій глибині твоєї сутності утворюється бездонна емоційна порожнеча, що згодом наповнюється відчуттям жаху.",
    ["Stars walk among us in the shape of a baby brutosaur."] = "Зірки ходять серед нас у подобі малятка брутозавра.",
    ["Stewards looking to move up in steward society know to fluff up their feathers, give out tons of juice, and always be hooting."] = "Розпорядники, які прагнуть піднятися в розпорядницькому суспільстві, знають: треба настовбурчити пір'я, роздавати море соку й завжди ухкати.",
    ["Still a little clumsy, this tiny winged lion is learning how to be the best mount it can be!"] = "Ще трохи незграбний, цей крихітний крилатий лев учиться стати найкращим їздовим звіром, на якого тільки здатен!",
    ["Still learning how to fly."] = "Ще вчиться літати.",
    ["Still not quite old enough to leave the nest."] = "Усе ще замолоде, щоб покинути гніздо.",
    ["Stinker uses his aroma to repel predators and attract cats. He's much more successful with the former than the latter."] = "Смердючка користується своїм ароматом, щоб відлякувати хижаків і приваблювати кішок. З першим йому щастить значно більше, ніж з другим.",
    ["Stop me if you've heard this one before: they fell into a vat of radioactive acid."] = "Зупини мене, якщо ти вже це чув: вона впала в чан з радіоактивною кислотою.",
    ["Stormwind's Trade District sees many goods and animals pass through its auction house. Once the parrots of Stranglethorn were an expensive luxury. Now those present when N'zoth took over are a scourge."] = "Через аукціонний дім торгового кварталу Стормвінда проходить безліч товарів і тварин. Колись папуги Тернистого Долу були дорогою розкішшю. Тепер ті, що були поряд, коли владу захопив Н'Зот, стали справжньою напастю.",
    ["Stranglethorn's Gurubashi trolls often capture these powerful beasts to keep as pets... or to cook as meals."] = "Тролі Ґурубаші з Тернистого Шпилю часто ловлять цих могутніх звірів, щоб тримати за улюбленців... або зварити на обід.",
    ["Strega the Hag didn't like carrying her own torches.  One quick enchantment, and the thing would dutifully follow her into the night."] = "Відьма Стреґа не любила носити свої смолоскипи. Одне швидке чарування — і та річ слухняно йшла за нею в ніч.",
    ["Strega the Hag enchanted her cauldron to prevent it from tipping over and spilling hot soup.  She never expected it to achieve sentience and attempt to murder her."] = "Відьма Стреґа зачарувала свій казан, щоб той не перекидався й не розливав гарячу юшку. Вона й гадки не мала, що той набуде свідомості й спробує її вбити.",
    ["Strega the Hag, tired of writing thank you notes, used her magic to automate the task.  Unfortunately, the pen had a dark side and all the recipients received strongly worded letters..."] = "Відьма Стреґа, втомившись писати подячні листи, скористалася магією, щоб цей клопіт робився сам. На жаль, перо мало темний бік, і всі адресати отримали різко сформульовані послання...",
    ["Striders glow brightest during spring, hence the name."] = "Бродяги світяться найяскравіше навесні, звідси й назва.",
    ["Struggle all you want, it will just grip harder."] = "Пручайся скільки завгодно — він лише міцніше стисне.",
    ["Subsisting on the residual anima in the waste of the Endmire, these mire creepers are withering away, yet in their famished state they are doubly dangerous."] = "Живлячись рештками аніми в пустці Кінцевого Багна, ці багнолази повільно чахнуть, та в зголоднілому стані вони вдвічі небезпечніші.",
    ["Such a good boy."] = "Який же хороший хлопчик.",
    ["Such toof. Such snaggle."] = "Які зубки. Які кривульки.",
    ["Suddenly there came a tapping..."] = "Раптом почулося постукування...",
    ["Sure are a lot of these around the Broken Shore."] = "На Зламаному Березі їх справді чимало.",
    ["Sure it's just a rock, but how much can it lift?"] = "Звісно, це лише камінь, але скільки він може підняти?",
    ["Surprisingly quick when provoked, but easily calmed with a meal of Nagrand arrowbloom."] = "Напрочуд швидкий, коли його дражнять, та легко вгамовується трапезою з награндського стрілоквіту.",
    ["Swarmlings of Gu'chi spin an ancient, and very powerful, form of silk that has not been seen in Pandaria in ages."] = "Роїнята Ґу'чі тчуть прадавню, дуже могутню форму шовку, якої в Пандарії не бачили цілі віки.",
    ["Sweet is the black blood. It tastes of wars past, and wars to come."] = "Солодка чорна кров. Вона має смак минулих воєн і воєн прийдешніх.",
    ["THE BEES ARE ON FIRE NOW?"] = "ТЕПЕР БДЖОЛИ ЩЕ Й ГОРЯТЬ?",
    ["Taking after her mother, Dame Bloodshed, the Princess is armed with the sharpest of claws and the furriest of ears."] = "Удавшись у свою матір, пані Кровопролиття, Принцеса озброєна найгострішими кігтями й найпухнастішими вухами.",
    ["Talbuk grow their horns to full size at an early age."] = "Талбуки відрощують роги до повного розміру ще змалечку.",
    ["Talented engineers have crafted an exact replica of a wood frog, at only ten times the cost of buying the real thing."] = "Талановиті інженери змайстрували точну копію лісової жаби — лише вдесятеро дорожче за справжню.",
    ["Tales say that the stewards were created to aid the denizens of Bastion in their eternal duties. They don't seem to mind."] = "Перекази кажуть, що розпорядників створили на допомогу мешканцям Бастіону в їхніх вічних обов'язках. Схоже, вони не проти.",
    ["Taptaf is loyal beyond a doubt, as long as food is provided."] = "Таптаф беззаперечно відданий — доки його годують.",
    ["Teele's grandparents told him they were the mice that discovered Azeroth. They were also champion fibbers."] = "Дідусь і бабуся Тіле розповідали йому, що саме вони були тими мишами, які відкрили Азерот. Вони також були неперевершеними брехунами.",
    ["Tell them that I am free of my father's madness, and I will be free of them as well. I am to be left alone: this will be my first and only warning. - Wrathion"] = "Скажіть їм, що я вільний від батькового божевілля і буду вільний від них також. Мене слід лишити в спокої: це моє перше й останнє попередження. - Вратіон",
    ["Ten thousand years spent floating in a time stasis is quite a bit of time to work on material."] = "Десять тисяч років, проведених у часовому застої, — це чимало часу, щоб попрацювати над матеріалом.",
    ["Tenacious and terrible, the mighty Hogs slaughters weaker enemies without hesitation."] = "Упертий і жахливий, могутній Кабан без вагань нищить слабших ворогів.",
    ["Tends to avoid crossing roads, regardless of motivations."] = "Уникає перетинати дороги, хоч би які були спонуки.",
    ["Terky is as shy as she is adorable, preferring the company of close friends over new ones."] = "Теркі настільки ж сором'язлива, наскільки й чарівна, і надає перевагу товариству близьких друзів над новими знайомствами.",
    ["Terrapins prefer any sort of berry as their primary source of food, though they will eat almost anything."] = "Черепахи найбільше полюбляють всілякі ягоди, хоча їстимуть майже все, що трапиться.",
    ["That eerie feeling you get when the shadows seem to shift and follow you isn't just a feeling, it's usually one of these."] = "Те моторошне відчуття, ніби тіні ворушаться й крадуться слідом за тобою, — то зовсім не вигадка: зазвичай це одне з них.",
    ["That place on your back you can't quite scratch? Get the help of this little guy. Problem solved."] = "Знаєте те місце на спині, до якого ніяк не дотягнутися почухати? Покличте на допомогу цього малюка. Проблему вирішено.",
    ["The \"hissing\" of this crab can be heard underwater, and is actually it rapidly clicking its smaller claws."] = "«Сичання» цього краба чути під водою, а насправді це він швидко клацає своїми меншими клешнями.",
    ["The 'door ditch' prank is not as effective when the house can chase you."] = "Витівка «подзвони й тікай» не така вдала, коли будинок може за тобою погнатися.",
    ["The Abyssal Eels are able to swallow and digest something up to twice the width of their body."] = "Безодняні вугри здатні ковтати й перетравлювати здобич удвічі ширшу за власне тіло.",
    ["The Alarm-O-Dog was built for security purposes, but people really wanted one for their home because they are so darn cute."] = "Пес-Сигналізатор створили для охорони, та люди страх як хотіли мати його вдома, бо ж він до біса милий.",
    ["The Albatross is capable of flying further than any other species of bird on all of Azeroth."] = "Альбатрос здатен літати далі за будь-який інший вид птахів у всьому Азероті.",
    ["The Ashleaf Sprites of the Timeless Isle tirelessly protect the vegetation of the island from the burning fury of Ordos and his minions."] = "Попеленолисті феї Позачасового Острова невтомно боронять рослинність острова від палючої люті Ордоса та його поплічників.",
    ["The Bronze Proto-Whelps have been discovered only in the most peculiar of timelines."] = "Бронзових протодраконят виявляли лише в найхимерніших часових лініях.",
    ["The Bronze Whelpling was lost in time until an unusual event allowed her to escape."] = "Бронзове дракеня загубилося в часі, доки незвичайна подія не дала їй змогу втекти.",
    ["The Direhorn species is among the toughest and strongest of all things that walk on Azeroth. They can seem like gentle giants, but be cautious that you don't find yourself in front of one when they are on a warpath."] = "Лютороги належать до найвитриваліших і найсильніших створінь, що ходять Азеротом. Вони можуть здаватися сумирними велетами, але стережися опинитися перед таким, коли він став на стежку війни.",
    ["The Dreadticks have grown to be a very invasive and dominant species wherever they wind up, they are incredibly quick to assault any new species until they find a weakness to exploit."] = "Кліщі Жаху стали вкрай навальним і панівним видом усюди, де опиняються. Вони неймовірно швидко накидаються на будь-який новий вид, доки не знайдуть слабке місце, яке можна використати.",
    ["The Drustvar people learned over time that when burying someone or some thing that there are sadly a number of shady people looking to exhume and reanimate whatever they can find."] = "З часом мешканці Друствару зрозуміли, що, ховаючи когось чи щось, завжди, на жаль, знайдуться темні людці, ладні викопати й оживити будь-що.",
    ["The Engine of Nalak'sha is defended by many mighty beings, and many tiny beings."] = "Двигун Налак'ші охороняють багато могутніх істот і багато крихітних.",
    ["The Eye of the Jailer, diffused, is now merely an all-seeing magical bauble."] = "Око Тюремника, знешкоджене, тепер не більше ніж усевидюща магічна цяцька.",
    ["The Fullbelly meeksi will often put their own safety at risk if they smell food. Nothing brings them happiness like a cup of tea and a warm meal."] = "Мейксі-ситопузи часто ризикують власною безпекою, якщо занюхають їжу. Ніщо не дарує їм такої радості, як чашка чаю й тепла страва.",
    ["The Gallagio is well-known in Undermine for unexpectedly animating piles of valuables in unexpected places."] = "Ґалладжіо славиться у Підрудні тим, що несподівано оживляє купи коштовностей у несподіваних місцях.",
    ["The Imperial Lynx hails from the shore of the far-flung Arathi Empire, where they serve as fierce and loyal companions and mounts for citizens."] = "Імперська рись родом з узбережжя далекої Аратійської імперії, де ці звірі служать громадянам лютими й відданими компаньйонами та верховими тваринами.",
    ["The Imperial Lynx is known for being stubborn and moody, but fiercely loyal to those they form bonds with."] = "Імперська рись відома впертою й примхливою вдачею, але вона страшенно віддана тим, з ким зав'язує зв'язок.",
    ["The Jade Cragviper's favorite food is broccoli. Actually, sorry. I just made that up."] = "Улюблена страва Нефритової Скельної Гадюки — броколі. Хоча ні, вибачте. Я це щойно вигадав.",
    ["The Jade Forest's mountain hozen fear these venomous reptiles and often hunt them out of pure spite."] = "Гірські гозени Нефритового лісу бояться цих отруйних плазунів і часто полюють на них із чистої злості.",
    ["The Jade Forest's pandaren consider these reptiles distant relatives of the revered Jade Serpent, Yu'lon."] = "Пандарени Нефритового лісу вважають цих плазунів далекими родичами шанованого Нефритового Змія, Ю'лон.",
    ["The Jadefire Spirit is thought to be a living embodiment of Yu'lon's own jade breath."] = "Вважається, що нефритовогняний дух — живе втілення нефритового подиху самої Ю'лон.",
    ["The Jademist Dancers of the Timeless Isle have a curious attraction to the steam vents of the northwestern shore."] = "Танцюристи нефритового туману з Позачасового Острова мають дивну приваб до парових жерл північно-західного узбережжя.",
    ["The Lich King tore the spirits of Sindragosa's lost whelps into undeath in front of her skeletal form as a final affront to the great dragon."] = "Король-Ліч повергнув у нежить душі загиблих драконят Синдрагоси просто перед її кістяним тілом — як останню наругу над великою драконицею.",
    ["The Mechantula was created by an unknown gnomish Engineer. Rumor has it when the original schematic was found, it was in a room covered with dusty old webbing, but neither the original Mechantula or the engineer who drafted the schematic could be found."] = "Механтулу створив невідомий гном-інженер. Подейкують, що оригінальну схему знайшли в кімнаті, обснованій старим запорошеним павутинням, проте ні самої першої Механтули, ні інженера, який накреслив схему, відшукати не вдалося.",
    ["The Pandaren Brewmasters accidentally brought a barrel of Uncle Gao's last sentient batch of brew with them to Brewfest."] = "Пандаренські хмільмайстри випадково привезли на Хмільфест барило останньої свідомої партії дядькового Ґаового вариво.",
    ["The Postmaster is often described as esoteric, mystical, even inexplicable. For the precious little known about the enigmatic mail-master, perhaps none outside of the wax seal can confirm the existence of the fantastical letter-loving Mailemental."] = "Поштмейстера часто описують як істоту езотеричну, містичну, ба навіть незбагненну. Про загадкового володаря пошти відомо так прикро мало, що, окрім воскової печатки, навряд чи хтось здатен підтвердити саме існування дивовижного, закоханого в листи Поштементаля.",
    ["The Purrkin hunt the invasive skrats in the Veiled Market, keeping the population just high enough that they are still needed."] = "Муркіни полюють на інвазивних скратів на Завуальованому ринку, тримаючи їхню чисельність якраз настільки високою, щоб самих муркінів і далі потребували.",
    ["The Sanctum of Domination accepts mawsworn of all shapes, sizes, and levels of corporeality."] = "Святилище Панування приймає пащезаприсяжених будь-яких форм, розмірів і ступенів тілесності.",
    ["The Scourge of the Aspects is consumed by rage and filled with a hunger to consume. Its presense is a sign of an unpredictable and erratic future for any form of dragonkin."] = "Згубу Аспектів пожирає лють, і її переповнює голод до поглинання. Її поява — це знак непередбачуваного й тривожного майбутнього для будь-якої зграї драконів.",
    ["The Sentinel Owls of Darkshore are forever protective of their homeland."] = "Сови-Вартові Даркшору повсякчас оберігають свою рідну землю.",
    ["The Sky-Bo was originally designed by the infamous Millie Watt as a toy for her cat.  The cat just slept in the box next to it."] = "Небо-Бо спершу створила сумнозвісна Міллі Ватт як іграшку для своєї кішки. Кішка ж просто спала в коробці поряд із ним.",
    ["The Soul of the Aspects is said to be possessed of mercurial moods ranging from stoic and deliberate to unpredictable and erratic, to loving and deeply pensive."] = "Кажуть, ніби Душа Аспектів має мінливу вдачу: від стриманої й розважливої до непередбачуваної й норовливої, а ще до лагідної й глибоко замисленої.",
    ["The Tidestone would empower minions of both the storm and the sea, and is sought after by both parties."] = "Камінь Приливів здатен наснажити прислужників і шторму, і моря, тож його жадають обидві сторони.",
    ["The Twisting Nether is an infinite abyss of terrors and one small corner of extreme cuteness."] = "Викривлена Порожнеча — нескінченна безодня жахіть з одним маленьким куточком неймовірної милості.",
    ["The Zandalari are masters of magic and communications with the spirits, and they often imbued items with powers to strengthen their bonds with the spirit world."] = "Зандаларці — майстри магії та спілкування з духами, і вони часто наділяли предмети силами, щоб зміцнити свій зв'язок зі світом духів.",
    ["The Zandalari breed specific Direhorn species for their small size for use as mounts."] = "Зандаларі виводять певні породи жахорогів за дрібний розмір, щоб використовувати їх як їздових тварин.",
    ["The acid-green accents add a sporty vibe to this flightless robotic bird thing."] = "Кислотно-зелені акценти додають спортивного вайбу цій нелетючій роботизованій пташиній штукенції.",
    ["The allegiances of the spriggan are as changing as the seasons."] = "Вірність спригана мінлива, як пори року.",
    ["The alluring twin mushroom cap colors of these fungal creatures attracts sentient and beastial victims alike."] = "Звабливі барви подвійних грибних капелюшків цих грибних створінь приваблюють як розумних, так і звіриних жертв.",
    ["The alpine hare can burrow into the permafrost and hibernate for weeks or even months."] = "Альпійський заєць може зариватися у вічну мерзлоту й западати в сплячку на тижні, а то й місяці.",
    ["The ambystan snapper is one of the nicest creatures you can meet in Zereth Mortis... until it isn't."] = "Амбістановий кусач — одне з наймиліших створінь, яких можна зустріти в Зерет Мортісі... доки воно таким бути не перестане.",
    ["The ancient nest guardian was designed with the unthinkable in mind: to hate cats."] = "Прадавнього охоронця гнізда створили з немислимою метою: ненавидіти котів.",
    ["The ancient tribes of Draenor were known to harvest their sharp beaks for crude tools and weapons."] = "Прадавні племена Дренора, як відомо, добували їхні гострі дзьоби для грубих знарядь і зброї.",
    ["The aqir hive has countless numbers of beings in it, all of which are supportive of the ever-present Hivemind."] = "У вулику аквірів незліченна кількість істот, і всі вони служать всюдисущому Роєрозуму.",
    ["The ash lizard gets its name from the way its shed skin looks, with an appearance like burnt cinders."] = "Попеляста ящірка дістала свою назву через вигляд скинутої шкіри, схожої на згорілий жар.",
    ["The bad news is that these bugs are carnivorous. The good news is that they usually just eat other bugs."] = "Погана новина — ці комахи хижі. Гарна новина — зазвичай вони їдять лише інших комах.",
    ["The bane of many an adventurer, to look into its eyes is to truly know madness."] = "Погибель багатьох шукачів пригод; зазирнути йому в очі — означає по-справжньому спізнати божевілля.",
    ["The barbaric centaur over-hunted giraffes for decades, but it was the tauren who saved this species from extinction."] = "Варварські кентаври десятиліттями надмірно полювали на жирафів, та саме таврени врятували цей вид від вимирання.",
    ["The barbed mandibles on this species will dig deep into anything they bite, causing a lot of irritation."] = "Зазубрені жвала цього виду глибоко вгризаються в усе, що він кусає, спричиняючи сильне подразнення.",
    ["The bears of Dun Morogh are prized for their hardiness, loyalty, and combat prowess. Their time among the dwarves does little to curb their ferocity."] = "Ведмедів Дун Морога цінують за витривалість, відданість і бойову вправність. Час, проведений серед дворфів, мало що робить, аби вгамувати їхню лютість.",
    ["The birth of an exceptionally rare Golden Snorf was such an abnormality that not even King Mechagon could force himself to mechanize his beloved, fuzzy friend."] = "Народження надзвичайно рідкісного Золотого Снорфа було такою дивовижею, що навіть король Мехаґон не зміг змусити себе механізувати свого любого пухнастого друга.",
    ["The blood of a crimsonspine flows through the clear crystal structures that make up its body, which causes its unique coloration."] = "Кров багряношипа тече крізь прозорі кристалічні структури, з яких складається його тіло, і саме це надає йому унікального забарвлення.",
    ["The bloodfeather is completely fearless, fanning out its feathers and charging any threat."] = "Кривопер геть безстрашний — розпушує пір'я й кидається на будь-яку загрозу.",
    ["The bond between yak and rat is a strange one, and what the rat gains out of the symbiotic relationship is a mystery."] = "Зв'язок між яком і щуром дивний, і що щур має зі цього симбіозу — загадка.",
    ["The bouncy gurloc is a distant cousin of the murloc."] = "Стрибучий ґурлок — далекий родич мурлока.",
    ["The bright color of the luminous webspinner taunts would-be predators to chase them into their webs."] = "Яскравий колір осяйного павука-ткача дражнить потенційних хижаків, спокушаючи їх кинутися навздогін — прямісінько в павутину.",
    ["The bright coloration of this deep water slug seems to give off a soft, warm glow."] = "Яскраве забарвлення цього глибоководного слимака ніби випромінює м'яке, тепле сяйво.",
    ["The bright glow of a stonewhisker's ears is said to be the result of eating magical cheeses. This may also explain its extremely bad breath."] = "Кажуть, що яскраве сяйво вух каменевуса — наслідок поїдання магічних сирів. Це також може пояснити його вкрай неприємний запах із рота.",
    ["The bright scales of this rare wind serpent soak up the sunlight to keep it warm, even in shade."] = "Яскрава луска цього рідкісного вітряного змія вбирає сонячне світло, щоб гріти його навіть у затінку.",
    ["The bright shells of the hermit crabs of Nazjatar have the jewelry crafters of Azeroth buzzing with excitement."] = "Яскраві панцирі раків-самітників Назджатару змушують ювелірів Азероту аж тремтіти від захвату.",
    ["The bright shells on these crabs makes them easy prey for predators, so they mostly stay to the shadows."] = "Яскраві панцирі цих крабів роблять їх легкою здобиччю для хижаків, тож вони здебільшого тримаються в тіні.",
    ["The brilliant scales of the etherwyrm reflect the bright skies of Bastion."] = "Осяйна луска ефіровірма відображає ясні небеса Бастіону.",
    ["The brown snake is native to Horde-controlled territories. It seems unremarkable until its victims are within range."] = "Бура змія мешкає на територіях, підвладних Орді. Вона видається непримітною, доки її жертви не опиняться на відстані удару.",
    ["The bubbles inside of these ooze creatures make a very satisfying pop noise when they finally surface and rupture."] = "Бульбашки всередині цих слизьких створінь видають надзвичайно приємний «хлоп», коли нарешті спливають на поверхню й лускають.",
    ["The call of the lithengale is unique among birds in that it has a persistent, driving rhythm."] = "Поклик літенгаля унікальний серед птахів тим, що має наполегливий, рушійний ритм.",
    ["The children of Orgrimmar frequently capture these lizards as pets.  The adults of Orgrimmar frequently step on them."] = "Діти Оґриммара часто ловлять цих ящірок за улюбленців. Дорослі Оґриммара часто на них наступають.",
    ["The chitterspine make a distinctive clicking noise when they see prey in the open."] = "Скрипоголки видають характерне клацання, коли помічають здобич на видноті.",
    ["The civets are known to guard their young ferociously."] = "Цивети відомі тим, що люто оберігають своїх дитинчат.",
    ["The claws of a vulpin sharpen themselves naturally when walking around on any sort of cobblestone or rocky surface."] = "Кігті вульпіна загострюються самі собою, коли він ходить бруківкою чи будь-якою кам'янистою поверхнею.",
    ["The cobras of Azeroth are renowned for their fast-acting venom and swift strikes."] = "Кобри Азероту славляться своєю швидкодійною отрутою та блискавичними укусами.",
    ["The cockroach is usually an impulse buy. Its owners have a hard time parting with it even after numerous attempts."] = "Таргана зазвичай купують зопалу. Та потім господарям важко з ним розлучитися, хоч скільки б вони не намагалися.",
    ["The cockroaches of Deepholm can burrow into stone itself to make their nests."] = "Таргани Діпголму можуть вгризатися в сам камінь, аби влаштовувати свої гнізда.",
    ["The coldlight once were quite common across the oceans, to the grumbles of many hunters, but no longer."] = "Холодносвітлі колись були доволі звичні в океанах, на буркотіння багатьох рибалок, та тепер уже ні.",
    ["The coloration of the spiky lizard allows it to blend in seamlessly with the desert sands of Silithus."] = "Забарвлення колючої ящірки дозволяє їй бездоганно зливатися з пустельними пісками Сілітусу.",
    ["The colorful plumage from these birds are highly sought after by collectors. It is rumored that wearing these feathers will bring you good luck."] = "Барвисте пір'я цих птахів дуже цінують колекціонери. Подейкують, що носіння цього пір'я приносить удачу.",
    ["The common folk remedy to a feverbite hatchling's bite is to dance wildly and try to sweat out the toxins before they can take hold."] = "Поширений народний засіб проти укусу малятка пропасниці — несамовито танцювати й намагатися випотіти отруту, перш ніж вона подіє.",
    ["The companion of a night elf sentinel, rarely given out as a gift."] = "Супутник вартової нічних ельфів, його рідко дарують стороннім.",
    ["The convenient part of robots that fight each other is that you can just put them back together. Step two is to attach a giant laser cannon to ensure you win the next battle."] = "Зручність роботів, що б'ються один з одним, у тому, що їх можна просто зібрати докупи. Крок другий — приладнати велетенську лазерну гармату, щоб напевне виграти наступний бій.",
    ["The cooled core of Golemagg, it appears to retain some semi-sentient properties."] = "Це охолоджене осердя Ґолемаґґа, схоже, зберігає певну напівсвідому вдачу.",
    ["The coral adder's venom is so deadly that one bite has been known to kill a full grown kodo beast."] = "Отрута коралової гадюки настільки смертоносна, що, як відомо, один укус здатний убити дорослого кодо.",
    ["The core of a song that all but faded long ago."] = "Осердя пісні, що майже згасла давним-давно.",
    ["The core temperature of an Emberling is hot enough to dissolve anything organic, so make sure to wear gloves if you want to pet it."] = "Температура осердя Жаринки достатня, щоб розчинити будь-що органічне, тож обов'язково вдягніть рукавиці, якщо хочете її погладити.",
    ["The crabs of Nazjatar seem relatively unfazed by the sudden absence of the water."] = "Краби Назджатару, схоже, доволі спокійно поставилися до раптового зникнення води.",
    ["The crimson snake is favored among the Darkspear trolls for not only its vicious nature, but also its steadfast loyalty."] = "Багряну змію тролі Темного Списа цінують не лише за люту вдачу, а й за непохитну відданість.",
    ["The crimson species of octopode grows larger and hardier than others, and is capable of sustaining crushing pressure in the depths."] = "Багряний вид восьминогів виростає більшим і витривалішим за інших та здатен витримувати нищівний тиск глибин.",
    ["The crocolisk's hide and meat are prized by hunters, but the beast is ferocious and seldom taken by surprise."] = "Шкуру й м'ясо кроколіска цінують мисливці, та звір лютий і рідко дається заскочити зненацька.",
    ["The crypts and tombs of Revendreth offer the perfect spider breeding ground, and Tomb Burster's brood has become fiercely territorial of their foothold."] = "Крипти й гробниці Ревендрету — ідеальне місце для розплоду павуків, і виводок Гробориївки люто захищає захоплену ним територію.",
    ["The cubs of Hyjal suffered much during the Cataclysm. On the bright side, the devastation also led to their newfound love of heights and daredevil stunts."] = "Ведмежата Гіджалу зазнали чимало лиха під час Катаклізму. Проте є й світлий бік: розруха пробудила в них нову любов до висоти й відчайдушних трюків.",
    ["The dark fur of the duskytooth allows them to more easily hide in the junkheaps of Mechagon Island."] = "Темне хутро присмерхозубих дозволяє їм легше ховатися у звалищах острова Мехаґон.",
    ["The dark green water in the Black Temple's sewer system gives these hydras their distinctive color."] = "Темно-зелена вода в каналізації Чорного Храму надає цим гідрам характерного кольору.",
    ["The dark pools in Primordius' chamber laid stagnant after the fall of the mogu, and murky thoughts began to coalesce."] = "Темні озерця в палаті Прімордія застоялися після падіння моґу, і там почали зароджуватися каламутні думки.",
    ["The dark wings will cloud and consume the minds of the weak, because they are just so adorable!"] = "Темні крила затьмарять і поглинуть розум слабких, бо вони ж такі чарівні!",
    ["The dark, fel-infused fur of the duskytooth allows them to more easily hide in the forests of Felwood."] = "Темне, просочене скверною хутро присмеркозуба дозволяє йому легше ховатися в лісах Сквернолісся.",
    ["The deep blue Umbrafen would later become home to a tribe of Broken."] = "Темно-синє Тінеболото згодом стало домівкою племені Зламаних.",
    ["The deep sea frenzies of Nazjatar have long been a staple food of the naga."] = "Глибоководні шаленці Назджатару здавна є основною їжею наг.",
    ["The demand for this purple-skinned breed has drastically reduced the raptor population near the Wailing Caverns."] = "Попит на цю породу з багряною шкірою різко скоротив популяцію рапторів поблизу Печер Виття.",
    ["The denizens of Ulduar transformed even small whelps into ironclad monstrosities."] = "Мешканці Улдуару перетворили навіть малих драконят на закуте в залізо чудовисько.",
    ["The distinct roar of the moonkin is one of the most terrifying sounds in nature."] = "Характерний рик місяцекіна — один із найжахливіших звуків природи.",
    ["The distinctive red coloration of scarlet proto avians makes it difficult for them to hide from predators, which ironically means they're very hard to find."] = "Характерне червоне забарвлення багряних протоптахів заважає їм ховатися від хижаків, що, за іронією, означає: знайти їх дуже важко.",
    ["The distinctive red coloration of these viperids serves as a warning to potential predators: 'eat at your own risk!'"] = "Характерне червоне забарвлення цих віперідів служить застереженням потенційним хижакам: «їж на власний ризик!»",
    ["The duck of your dreams... or perhaps someone else's dreams."] = "Качка вашої мрії... або, можливо, чиєїсь чужої мрії.",
    ["The dwarven explorer who first discovered the spotted bell frog could not decide between naming it after the unique spot pattern or the sound of the frog's mating ritual. She chose both."] = "Дворфійська дослідниця, яка вперше відкрила плямисту дзвінку жабу, не могла вирішити, чи назвати її за неповторним візерунком плям, чи за звуком шлюбного ритуалу жаби. Вона обрала і те, і те.",
    ["The eagles of Zul'Aman are a regal species yet they have suffered without Akil'zon watching over them. Faithbreaker Ger'lok has been especially cruel testing his dark magic on the young eaglets."] = "Орли Зул'Амана — царствений вид, та вони потерпали без Акіл'зона, що дбав про них. Віроломець Ґер'лок був особливо жорстоким, випробовуючи свою темну магію на молодих орлятах.",
    ["The earliest prototype of the deadly Foe Reaper."] = "Найперший прототип смертоносного Ворогожнива.",
    ["The early worms get the bird."] = "Хто рано встає, того й пташка з'їсть.",
    ["The earth that's rumbling beneath your feet... is it quaking or laughing, or both?"] = "Земля гуркоче під твоїми ногами... вона двигтить чи сміється? А може, і те, і те?",
    ["The edges of its beak are particularly sharp. Watch your fingers during feeding time!"] = "Краї його дзьоба особливо гострі. Пильнуй пальці під час годівлі!",
    ["The eels of Nazjatar are experts at hiding in the many cracks and rocks of the sea floor."] = "Вугри Назджатару — майстри ховатися в численних розколинах і каменях морського дна.",
    ["The eels that inhabit the trenches and chasms of Nazjatar are a favored food of many creatures that inhabit the area."] = "Вугри, що населяють западини й провалля Назджатару, є улюбленою їжею багатьох тутешніх створінь.",
    ["The eerie magic in Drustvar has caused some unimaginable creatures to show up. Some still lurk in the shadows, others seem to be made out of shadows."] = "Моторошна магія Друствару спричинила появу незбагненних створінь. Одні досі чаяться в тінях, інші ніби й самі зіткані з тіней.",
    ["The elemental shale spider is no true arachnid, but it has durability and ferocity that make it feared even in Deepholm."] = "Елементальний сланцевий павук не є справжнім павукоподібним, але його витривалість і лютість наганяють страх навіть у Глибокій Землі.",
    ["The elemental spirits of Pandaria have been known to plan tricks to play on unsuspecting visitors years in advance."] = "Подейкують, що елементальні духи Пандарії планують витівки проти необачних гостей за роки наперед.",
    ["The elements clash and battle for relics constantly, but few moreso than the Tidestone."] = "Стихії повсякчас стикаються й б'ються за реліквії, та мало за яку так запекло, як за Камінь Приливів.",
    ["The elements of Pandaria can be cute and playful, until their homeland is threatened."] = "Стихії Пандарії можуть бути милими й грайливими, доки їхній рідній землі не загрожує небезпека.",
    ["The emperor crab was named for its regal appearance: the ridges of its shell and its raised claws eerily resembling a crown. One that would pinch your eyes out if you tried to wear it."] = "Краб-імператор дістав свою назву за царствений вигляд: гребені панцира й піднесені клешні моторошно нагадують корону. Таку, що виколола б вам очі, якби ви спробували її надіти.",
    ["The eternal answer to the question 'what's that smell?'"] = "Вічна відповідь на запитання «що це за сморід?».",
    ["The ethereal Rashaad began breeding these enigmatic creatures after learning of their ability to feed on arcane energies."] = "Етерал Рашаад заходився розводити цих загадкових створінь, дізнавшись про їхню здатність живитися чародійними енергіями.",
    ["The exposure to void energy was minimal, however it is already showing signs of new void abilities. Its abilities can be managed with the right training. - Sergeant Vornin"] = "Вплив енергії порожнечі був мінімальним, проте воно вже виявляє ознаки нових здібностей порожнечі. За належного тренування ці здібності можна опанувати. – Сержант Ворнін",
    ["The faded memory of an Onyxian whelpling, this young dragon has decided that it wants to follow in its own footsteps."] = "Зблідлий спогад про оніксійського вилупка, це юне дракеня вирішило, що хоче піти власними слідами.",
    ["The feathers of the cobalt raven glow eerily in the moonlight, making them easy to spot during the night."] = "Пір'я кобальтового ворона моторошно світиться в місячному сяйві, через що його легко помітити вночі.",
    ["The fields of battle teem with Lil'Abom parts, which are perfectly interchangable and easy to put back together."] = "Поля битв аж кишать частинами Малих Абомінацій — цілком взаємозамінними, які легко скласти докупи.",
    ["The fierce wolvar hunt these ill-tempered brutes for their horns, which are then carved into talismans and other trinkets."] = "Люті вольвари полюють на цих злостивих здоровил заради рогів, з яких потім вирізьблюють талісмани та інші дрібнички.",
    ["The fighting in Tol Barad has made it difficult to find these kits, and numerous would-be owners have decimated the fox population there as a result."] = "Через бої в Тол Бараді цих лисенят стало важко знайти, і безліч охочих їх отримати винищили тамтешню популяцію лисиць.",
    ["The final phase of the bilescourge life cycle."] = "Завершальна фаза життєвого циклу жовчної погибелі.",
    ["The fire at the center of the world burns within its carapace."] = "Вогонь у центрі світу палає в його панцирі.",
    ["The first bombling created in the Underhold, Siegecrafter Blackfuse couldn't bear to see it destroyed, and kept it as a friendly, if explosive, pet."] = "Перша бомбочка, створена в Підземній Твердині; Облоговий Майстер Чорнопал не міг дивитися, як її знищують, тож лишив її собі за дружнього, хоч і вибухового, улюбленця.",
    ["The first thing you might notice about this creature is its huge expressive eyes. This is a mistake. Instead focus on its razor-sharp claws."] = "Перше, що ви, можливо, помітите в цій істоті, — її величезні виразні очі. Це помилка. Натомість зосередьтеся на її гострих як бритва пазурах.",
    ["The flames surrounding it burn more intensely during combat. Could even say that pet battles get it stoked."] = "Полум'я навколо нього палає сильніше під час бою. Можна навіть сказати, що бої улюбленців його розпалюють.",
    ["The flickering of these lightbugs is said to bring an unnatural and eerie calm to travelers and predators alike."] = "Кажуть, що мерехтіння цих світляків навіює неприродний і моторошний спокій як на мандрівників, так і на хижаків.",
    ["The forests of Eversong have enjoyed a recent influx of these flying critters."] = "Ліс Вічної Пісні нещодавно зазнали напливу цих летючих звіряток.",
    ["The formula had a bit too much... purple."] = "У формулі було трохи забагато... багряного.",
    ["The frogs of Mechagon had two choices when faced with mechanization: hide or breed. This species chose the former."] = "Перед лицем механізації жаби Мехаґону мали два шляхи: ховатися чи плодитися. Цей вид обрав перше.",
    ["The frogs of Mechagon had two choices when faced with mechanization: hide or breed. This species chose the latter."] = "Перед лицем механізації жаби Мехаґону мали два шляхи: ховатися чи плодитися. Цей вид обрав останнє.",
    ["The front legs of this spider are almost indestructable, allowing it to burrow into almost any surface."] = "Передні лапи цього павука майже незнищенні, тож він може вгризатися чи не в будь-яку поверхню.",
    ["The frostshell pinchers build up layers of ice to give them the extra protection from larger predators."] = "Морозопанцерні щипавки нарощують шари льоду задля додаткового захисту від більших хижаків.",
    ["The fur of the darkshore bears owes to the almost perpetual gloom they live in, and their vision in the darkness is uncanny."] = "Хутро ведмедів Темного Узбережжя завдячує своїм кольором майже вічному мороку, у якому вони живуть, а їхній зір у пітьмі надприродно гострий.",
    ["The fury of the sea in the packge of a puddle."] = "Лють моря в обгортці калюжі.",
    ["The game's afoot. Except when it is time to nap. Afterwards though, it's game on!"] = "Полювання почалося. Хіба що крім часу для дрімоти. Але потому — гра триває!",
    ["The garnetgullet rolls in bright red flowers to enhance its color, serving as a call to similar species and a warning to enemies."] = "Гранатогорлик качається в яскраво-червоних квітах, щоб посилити свій колір — це і поклик до родичів, і застереження ворогам.",
    ["The gemstones on a baubleworm will quickly deteriorate if the worm is killed. Healthy worms are kept as prized pets by wealthy Brokers."] = "Самоцвіти на самоцвітному черві швидко псуються, якщо черв гине. Здорових червів заможні Брокери тримають як коштовних улюбленців.",
    ["The giant woodworm can burrow into almost any surface they crawl on, except solid stone."] = "Велетенський деревоточець здатен угризтися майже в будь-яку поверхню, якою повзе, окрім суцільного каменю.",
    ["The glow eminating from these is both calming and eerie at the same time when in total darkness."] = "Сяйво, що ллється від них у цілковитій темряві, водночас заспокоює й навіює моторош.",
    ["The gold standard for sturdy gnomish design, this mechanical critter is the perfect companion for the lonely engineer on the go."] = "Золотий взірець надійного ґномського дизайну: це механічне створіння — ідеальний супутник для самотнього інженера в дорозі.",
    ["The golden armor on these mawsworn is flimsy and easily bent -- the gilded armor is a punishment."] = "Золотий обладунок на цих пащезаприсяжених крихкий і легко гнеться — позолочена броня є покаранням.",
    ["The golden chirper has managed to stay its pristine self, despite corruption attempts from both the Sha and from the forces of N'Zoth."] = "Золотий цвіркун спромігся зберегти свою бездоганну сутність попри спроби зіпсувати його з боку як ша, так і сил Н'Зота.",
    ["The golden vulpin are notorious for loud, barking yowls that echo across the plains of Bastion."] = "Золоті вульпіни сумнозвісні гучним, гавкітливим виттям, що лунає над рівнинами Бастіону.",
    ["The grand horns of these beasts spark jealousy in other horned grazing animals."] = "Величні роги цих звірів пробуджують заздрість в інших рогатих травоїдних.",
    ["The great big world can be a dangerous place for such a tiny, adorable creature."] = "Великий широкий світ може бути небезпечним місцем для такого крихітного, чарівного створіння.",
    ["The great-great-great-great-great granddaughter of Senegos."] = "Пра-пра-пра-пра-праправнучка Сенеґоса.",
    ["The greatest souvenir available in a dragon's spa in the clouds. Not so good at facials any more, though."] = "Найкращий сувенір з драконячого спа в хмарах. От тільки для догляду за обличчям уже не дуже годиться.",
    ["The green glow of this firefly is seen as an ill-omen for those who travel in darkness."] = "Зелене сяйво цього світлячка вважають лихою прикметою для тих, хто мандрує в темряві.",
    ["The grell are embodiments of the wild side of nature. Tame ones are very rare."] = "Ґрели — втілення дикого боку природи. Приручені трапляються вкрай рідко.",
    ["The grubs of the Plaguelands are a side effect of necromantic corruption and the massive number of corpses there. Mr. Grubbs is from a particularly acrobatic breed."] = "Личинки Чумних земель — побічний наслідок некромантської скверни та незліченних трупів у тих краях. Пан Личинко належить до особливо вправного, акробатичного роду.",
    ["The hardest part to shape was the whelpling's cute little snout."] = "Найважче було вирізьбити милу мордочку драконеняти.",
    ["The heart of an arctic hare beats twice as fast as a common hare."] = "Серце арктичного зайця б'ється вдвічі швидше, ніж у звичайного.",
    ["The hermit crabs of Stormsong Valley will use whatever they can find that fits them for their shell.  If it fits, they sits."] = "Раки-самітники Долини Штормової Пісні беруть собі за мушлю будь-що, аби лише підійшло за розміром. Якщо влізло — там і живуть.",
    ["The hide color of this species is more rare on Korthia, and helps it hide from predators. And mawsworn, in this case."] = "Забарвлення шкури цього виду на Кортії рідкісніше й допомагає ховатися від хижаків. А в цьому разі — і від пащезаприсяжених.",
    ["The hooves of this subgroup of goats have evolved to be equally surefooted on sand or stone."] = "Копита цього підвиду кіз розвинулися так, щоб однаково впевнено ступати і по піску, і по каменю.",
    ["The horns of a crawg grow at a tremendous rate starting almost immediately after they are born, and is among the hardest of natural materials found on a living species."] = "Роги кроґа ростуть із надзвичайною швидкістю майже одразу після народження й належать до найтвердіших природних матеріалів, які можна знайти в живих істот.",
    ["The hydra matriarchs of Nazjatar steal and destroy one another's eggs constantly, so you can never really know what will hatch out of one."] = "Матріархи гідр Назджатару постійно крадуть і нищать яйця одна одної, тож ніколи достеменно не знаєш, хто вилупиться.",
    ["The hydraling can be an expensive pet, as it is capable of eating from three food bowls at the same time."] = "Гідреня може бути недешевим улюбленцем, адже здатне їсти з трьох мисок одночасно.",
    ["The infinite dragonflight is far more diverse than most denizens of Azeroth know."] = "Безкінечна драконяча зграя набагато різноманітніша, ніж відомо більшості мешканців Азероту.",
    ["The influence of the old gods on the aquatic life of Nazjatar is unmistakable, as many simply wander as mindless eyes of N'zoth."] = "Вплив прадавніх богів на водяне життя Назджатару безсумнівний — багато хто просто блукає, як бездумні очі Н'зота.",
    ["The intelligence and caring nature of elekk calves make them a stalwart lifelong companion."] = "Кмітливість і дбайлива вдача елекенят роблять їх відданими супутниками на все життя.",
    ["The intrepid archaeologist Harrison Jones has a well documented fear of rats."] = "Безстрашний археолог Гаррісон Джонс має добре задокументований страх перед щурами.",
    ["The itchy legs! The wiggly antennae! Okay, fine, he's not cute. But he's trying!"] = "Сверблячі лапки! Звивисті вусики! Гаразд, добре, він не милий. Але він старається!",
    ["The jungle trolls train these birds to mimic calls for help in order to lure unsuspecting travelers into traps."] = "Тролі джунглів навчають цих птахів імітувати заклики про допомогу, щоб заманювати необачних мандрівників у пастки.",
    ["The kindleweb spider species is known amongst the island tribes for its warm, threadable webbing."] = "Павуки-жароснувальники відомі острівним племенам своїм теплим, придатним для прядіння павутинням.",
    ["The kunchong are extremely aggressive and will eat just about anything they can as soon as they are able to walk. If they can't eat it, they will smash it instead."] = "Кунчони вкрай агресивні й поїдають геть усе, що тільки можуть, щойно навчаться ходити. А чого не можуть з'їсти — те трощать.",
    ["The lanterns carried by Voidcallers bridge the realms of the living and the dead, and often attract wayward ghosts and spirits."] = "Ліхтарі, які носять закликачі Порожнечі, з'єднують світи живих і мертвих та часто приваблюють заблудлих привидів і духів.",
    ["The large plates on the back of this lizard are made of a mysterious but highly conductive material, making it ideal to charge up and expel massive amounts of electricity."] = "Великі пластини на спині цього ящера зроблені з загадкового, але вкрай провідного матеріалу, що ідеально надається для накопичення й вивільнення величезної кількості електрики.",
    ["The larval form of this moth is world-renowned for creating the finest silk in Azeroth."] = "Личинкова форма цього метелика славиться на весь світ тим, що створює найтонший шовк Азероту.",
    ["The last person who tried to housebreak this cat quickly learned that a soiled rug is better than a shredded everything-else."] = "Остання людина, яка намагалася привчити цього кота до порядку, швидко зрозуміла: забруднений килим кращий за пошматоване геть усе інше.",
    ["The last thing that tried to look in its tiny pack was never seen again."] = "Останнього, хто спробував зазирнути в його крихітну торбинку, більше ніхто не бачив.",
    ["The last thing you'll see is a streak of red."] = "Останнє, що ти побачиш, — червоний спалах.",
    ["The latent energy found throughout Ardenweald's seeds sometimes augments small critters with unnatural abilities."] = "Прихована енергія, що таїться в насінні Арденвельду, інколи наділяє дрібних звіряток неприродними здібностями.",
    ["The legendary ale frog was believed to be extinct until the strange brews at the Darkmoon Faire brought them out of hiding."] = "Легендарну пивну жабу вважали вимерлою, аж доки дивні вариво Ярмарку Темного Місяця не виманили її зі сховку.",
    ["The leopard tree frog was named for the way it pounces from branch to branch."] = "Леопардову деревну жабу назвали за те, як вона стрибає з гілки на гілку.",
    ["The light from each lantern honors the soul of an ancestor spirit. During the Lunar Festival, these ghostly elders pass along their wisdom to the current generation."] = "Світло кожного ліхтаря вшановує душу духа-предка. Під час Місячного Свята ці примарні старійшини передають свою мудрість нинішньому поколінню.",
    ["The light of the new legacy illuminates the path you forge."] = "Світло нової спадщини осяює шлях, який ви торуєте.",
    ["The little wolf told to stay.\nWatching, waiting, for vacant prey.\nToo proud to leave, she slipped away.\nUnburdened now, forever free to play."] = "Вовченя лишитись мало.\nЧекало здобич, виглядало.\nГордо геть піти не вміло — та й тихо в інший світ відплило.\nТепер без тягаря на віки вільне для гри й розваги.",
    ["The long-term effects of the contamination caused by the Exodar are still under observation."] = "Довгострокові наслідки забруднення, спричиненого Екзодаром, досі перебувають під спостереженням.",
    ["The lost magical light of a Dalaran mage, or sentient candle with a positive attitude? You decide."] = "Загублене магічне світло даларанського мага чи свідома свічка з позитивним настроєм? Вирішувати тобі.",
    ["The low tide reveals the colonies of strand crabs and the sound of their clicking dance as they feed upon small creatures hidden in the sand."] = "Відплив відкриває колонії берегових крабів і звук їхнього клацливого танцю, коли вони живляться дрібними створіннями, схованими в піску.",
    ["The loyal snapdragon are the perfect companion to any naga. They adapt well to their environment especially when the environment likes to adapt them."] = "Вірний хапкодракон — ідеальний супутник для будь-якої наги. Вони добре пристосовуються до свого середовища, особливо коли середовище полюбляє пристосовувати їх.",
    ["The machinists of Mechagon may automate many of the tasks of the city, but they also spend a lot of time repairing and maintaining their inventions."] = "Машиністи Мехаґону, може, й автоматизували чимало міських справ, та водночас витрачають багато часу на ремонт і обслуговування своїх винаходів.",
    ["The magical energies released during Skywing's transformation back into his true arakkoa form liberated this poor creature, a fledgling bird imprisoned by Luanga in order to power his fowl curse."] = "Магічна енергія, що вивільнилася під час перетворення Небокрила назад у його справжню подобу аракоа, звільнила це бідолашне створіння — пташеня, ув'язнене Луангою, щоб живити його пернате прокляття.",
    ["The mana wyrm population really picked up after the Arcane Torrent nerf."] = "Популяція мановірмів справді зросла після послаблення Тайного потоку.",
    ["The mane on this tiny foal reflects a majestic indigo color when the light hits it in just the right way."] = "Грива цього крихітного лошати виблискує величним кольором індиго, коли світло падає на неї саме під потрібним кутом.",
    ["The mantid are extremely reliant upon amber for many things, and even use it in some of their magic."] = "Мантиди вкрай залежні від бурштину в багатьох справах і навіть використовують його в дечому зі своєї магії.",
    ["The markings on the carapace of this cockroach closely resemble that of the Death's Head."] = "Візерунок на панцирі цього таргана дуже нагадує мертву голову.",
    ["The master jewelcrafters of the Dragon Isles have perfected their craft so much that their gemmed statues can be brought to life. This whelp forged of obsidian is now not to be trifled with."] = "Майстри-ювеліри Драконових Островів так удосконалили своє ремесло, що їхні самоцвітні статуї можна оживити. З цим дитинчам, викуваним з обсидіану, тепер краще не жартувати.",
    ["The master-crafted gear assembly and precision joints in this robot are clearly made with love."] = "Майстерно зібраний механізм і точні з'єднання цього робота вочевидь зроблені з любов'ю.",
    ["The mechanical frogs of Mechagon Island have evolved to eat various mechanical insects, somehow."] = "Механічні жаби острова Мехаґон якимось чином розвинулися так, щоб поїдати різних механічних комах.",
    ["The meeksi Teatuft Tamers love lounging with their Teatufts and sipping a cup of mystical tea after a long lazy day."] = "Мейксі-приборкувачі чаєжмутиків люблять відпочивати зі своїми чаєжмутиками й сьорбати чашку містичного чаю після довгого лінивого дня.",
    ["The mice of the highlands, perhaps twisted by the Twilight's Hammer, are aggressive and fight for dominance between each other."] = "Миші нагір'я, можливо, спотворені Сутінковим Молотом, агресивні й б'ються між собою за владу.",
    ["The mindbreakers are a rare creature of the deep. Little is known of their true origins but they link back to the days of the Black Empire."] = "Розумоламці — рідкісні створіння глибин. Про їхнє справжнє походження відомо мало, та воно сягає днів Чорної Імперії.",
    ["The molted feathers of these young eagles are used to build comfortable bedding for the Amani."] = "З линялого пір'я цих молодих орлів аманійці роблять зручні постелі.",
    ["The mongoose is prized for its ability to drive off poisonous snakes.  Rikk-tikk-tikki-tikki-tchk!"] = "Мангуста цінується за здатність відганяти отруйних змій. Рікк-тікк-тіккі-тіккі-чк!",
    ["The monkeys of Azeroth are infamous tricksters, and these beloved companions of the Darkmoon Faire have taken that innate cunning to a whole new level."] = "Мавпи Азероту — горезвісні пустуни, а ці улюблені супутники Ярмарку Темного Місяця підняли вроджену хитрість на цілком новий рівень.",
    ["The moonshell crab reflects light so well that they can be picked up and used as a mirror.  Just keep your face away from the claws!"] = "Краб-місяцепанцир так добре відбиває світло, що його можна взяти й використати замість люстерка. Лиш тримай обличчя подалі від клешень!",
    ["The most common of the arachnid family, these critters spin their webs in nearly every corner of Azeroth."] = "Найпоширеніший представник родини павукоподібних, ці дрібнятка плетуть свої тенета майже в кожному закутку Азероту.",
    ["The most delicious of the beetle family."] = "Найсмачніший із родини жуків.",
    ["The most nefarious of the trickster spirits, and the reason why the pandaren invented fireproof pants."] = "Найпідступніший із духів-бешкетників і причина, чому пандарени винайшли вогнетривкі штани.",
    ["The moths of Ardenweald can carry seeds and pods many times their own weight, aiding the Night Fae in their eternal tasks."] = "Метелики Арденвельду здатні переносити насіння й стручки, що в багато разів важчі за них самих, допомагаючи Нічним Феям у їхніх вічних трудах.",
    ["The mountain skunk is most famous for its adventurous nature. No really, that is what it is famous for."] = "Гірський скунс найбільше славиться своєю авантюрною вдачею. Ні, справді, саме цим він і славиться.",
    ["The mucus secreted from inland croakers is so effective at repelling water, the ship builders of Kul Tiras have been using it in the wood sealant for many years."] = "Слиз, який виділяють суходільні квакухи, так добре відштовхує воду, що корабельники Кул-Тіраса вже багато років застосовують його в просоченні для деревини.",
    ["The mummy's wraps serves two purposes, one being to keep everything inside intact, the other is to lessen the fright of people seeing what's really below the wrappings."] = "Пов'язки мумії слугують двом цілям: одна — зберегти все всередині цілим, інша — зменшити жах тих, хто побачив би, що насправді ховається під бинтами.",
    ["The murloc tribe that Murgle belongs to is one of few that have resisted the naga's enslavement."] = "Плем'я мурлоків, до якого належить Мурґл, — одне з небагатьох, що чинило опір поневоленню нагами.",
    ["The mysterious forces that animate this mobile mitt don't seem particularly evil, yet."] = "Таємничі сили, що оживляють цю рухливу п'ятірню, поки що не здаються аж надто лихими... поки що.",
    ["The naga's mix of arcane and void magics have disturbed the mana wyrms around Daggerspine Point making them extremely hostile. The very few manalings remaining in the aftermath of their ritual are showing unique abilities."] = "Суміш тайної магії та магії порожнечі, якою користуються наги, стривожила мановірмів довкола Мисливки Кинджалоспинних, зробивши їх украй ворожими. Ті нечисленні мановірмлята, що лишилися після їхнього ритуалу, виявляють унікальні здібності.",
    ["The nails of the mawrat can inflict one of several afterlife-ending illnesses."] = "Кігті пащевого щура можуть наслати одну з кількох хвороб, що обривають навіть потойбічне життя.",
    ["The name 'Beepbop' followed by the words 'Made by Threadis' are roughly but lovingly scratched into the bottom plate on this tiny nerubian-crafted bot."] = "Ім'я «Біпбоп», а за ним слова «Зроблено Тредісом» грубо, але з любов'ю видряпані на нижній пластині цього крихітного робота нерубіанського виробу.",
    ["The name implies that there were 12 experiments done before this one that were less effective than sticking some guns onto a mechanical tiger. What could those have possibly been?"] = "З назви випливає, що до цього зробили ще 12 експериментів, менш вдалих, ніж навісити кілька гармат на механічного тигра. Цікаво, якими ж вони могли бути?",
    ["The natural habitat of these crabs is so polluted and devoid of shells that they've been forced to take shelter in discarded goblin munitions. Are you gonna keep littering after learning that?"] = "Природне середовище цих крабів настільки забруднене й позбавлене мушель, що вони змушені шукати прихистку в покинутих ґоблінських боєприпасах. Чи продовжуватимеш ти смітити, дізнавшись про це?",
    ["The needle in Pokee's eye isn't exactly comfortable fashion, but he's stuck with it."] = "Голка в оці Покі — не надто зручна мода, але він з нею застряг.",
    ["The needleback porcupines have survived life in island climates by evolving to be extra lucky."] = "Голкоспинні дикобрази вижили в острівному кліматі, розвинувши в собі надзвичайне везіння.",
    ["The nether roach has adapted to the cold vacuum of space and requires no air to survive. Inside it bears almost no resemblance to a common roach."] = "Нетерський тарган пристосувався до холодного вакууму космосу й не потребує повітря, щоб виживати. Усередині він майже нічим не схожий на звичайного таргана.",
    ["The next level of scrapbot technology: pushes the scrap into a heap, then destroys it with flame vents and rockets."] = "Новий рівень технології брухтоботів: згрібає брухт у купу, а потім нищить його струменями полум'я та ракетами.",
    ["The next time you're sitting in the dark and feel something brush against your heel, don't worry! It's just Fuzzy."] = "Наступного разу, коли ти сидітимеш у темряві й відчуєш, як щось торкнулося твоєї п'яти, не хвилюйся! Це лише Пухнастик.",
    ["The odd blue flames found within the Cavern of Lost Spirits have led many unwary adventurers to their doom."] = "Дивне блакитне полум'я, знайдене в Печері Загублених Духів, призвело багатьох необачних шукачів пригод до загибелі.",
    ["The offspring of Tsulong, hidden away before the corruption of the Sha had fully taken hold of the Terrace of Endless Spring."] = "Нащадок Цулона, схований ще до того, як скверна ша повністю охопила Терасу Нескінченної Весни.",
    ["The oft-forgotten offspring of the Big Bad Wolf, found gorged and asleep in a basket of sweets."] = "Часто забуте дитинча Великого Злого Вовка, знайдене ситим і сонним у кошику зі солодощами.",
    ["The only balls this hound chases are diamond-hard, fireproof rocks. Very heavy, not fun to throw."] = "Єдині м'ячі, за якими ганяється цей пес, — тверді, мов діамант, вогнетривкі камені. Дуже важкі, кидати геть не весело.",
    ["The onyx panther is invisible at night, like a stalking shadow, and disappears with the dawn."] = "Уночі оніксова пантера невидима, наче тінь, що скрадається, і зникає з світанком.",
    ["The outer member of the roaches' eggs protect the larva from incineration. It is here in incubation that they gain the ability to resist the fire and heat of the volcanic climate."] = "Зовнішня оболонка яєць тарганів захищає личинку від згоряння. Саме під час інкубації вони набувають здатності опиратися вогню й жару вулканічного клімату.",
    ["The pandaren monk is a fearless traveling companion, constantly training in his art... unless you offer him a drink. He considers it rude to refuse."] = "Пандаренський монах — безстрашний супутник у мандрах, що невпинно вдосконалює своє мистецтво... доки ти не запропонуєш йому випити. Відмовитися він вважає за нечемність.",
    ["The perfect pet if you love stepping on something wet in the middle of the night."] = "Ідеальний улюбленець, якщо ти любиш наступати на щось мокре посеред ночі.",
    ["The platysaur species has been roaming around the lands since before time was even measured. An ancient species that has adapted to walking on the land, and also for some reason has adapted to repeating some short sounds three times in a row."] = "Платизаври блукали цими землями ще до того, як почали лічити час. Це прадавній вид, що пристосувався ходити по суходолу, а ще з якоїсь причини звик повторювати короткі звуки тричі поспіль.",
    ["The playful kicks of these baby moose are enough to knock an orc flat on his back."] = "Грайливих стусанів цих лосенят досить, щоб звалити орка горілиць.",
    ["The power of love can be a dangerous thing, especially when wielded by an airborne, ill-tempered goblin."] = "Сила кохання буває небезпечною штукою, надто коли нею орудує летючий злостивий ґоблін.",
    ["The predatory coral of Nazjatar can grow incredibly quickly given the right conditions."] = "Хижий корал Назджатару за сприятливих умов здатен рости неймовірно швидко.",
    ["The preferred habitat of this creature is woodland areas where it can safely complete its metamorphosis."] = "Це створіння найбільше любить лісисті місцини, де може безпечно завершити свою метаморфозу.",
    ["The pressure of the crushing depths at which these snails exist help to form its distinctive shell."] = "Тиск нищівних глибин, у яких живуть ці слимаки, допомагає сформувати їхню своєрідну мушлю.",
    ["The purple coloration helps this species blend into the rocks and shadows, but the crabs become easy prey for seagulls when they linger too long on the open sand."] = "Фіолетове забарвлення допомагає цьому виду зливатися з камінням і тінями, та коли краби надто довго затримуються на відкритому піску, вони стають легкою здобиччю для чайок.",
    ["The radiation from all of the machinery in Gnomeregan gives these rats a soft green glow when looked at in absolute darkness."] = "Радіація від усіх машин Гномреґану надає цим щурам м'якого зеленавого сяйва, помітного в цілковитій темряві.",
    ["The rage Zovaal harbored for his punished existence echoes through the eye."] = "Лють, яку Зоваал плекав через своє покаране існування, відлунює в цьому оці.",
    ["The raptors of Zandalar have their feathers at a very young age, making them seem like easy prey to an unsuspecting predator. In reality, these little terrors eat everything they want to and are prey to almost no other species."] = "Раптори Зандалару вкриваються пір'ям у дуже юному віці, через що здаються легкою здобиччю необачному хижаку. Насправді ці маленькі страхіття поїдають усе, що їм заманеться, і майже жоден інший вид їм не загрожує.",
    ["The rare albino tickbird is revered amongst the Oracles. It is seen as a sign of heavy rainstorms, good grub harvests, and hibernating wolvar."] = "Рідкісного білого кліщоїда шанують серед Оракулів. Його вважають провісником сильних злив, щедрого врожаю личинок і зимової сплячки вольварів.",
    ["The rats in Redridge grow fat from feasting on the bounty of the village larders."] = "Щури в Червоногір'ї відгодовуються, бенкетуючи в багатих сільських коморах.",
    ["The razor sharp claws will tear into anything with ease, making for an excellent emergency can opener."] = "Гострі, мов лезо, кігті легко роздеруть будь-що, тож із них вийде чудова відкривачка для консервів на крайній випадок.",
    ["The red coloring on this scarabid lets potential opponents know it is not to be trifled with."] = "Червоне забарвлення цього скарабіда сповіщає можливих супротивників, що з ним краще не жартувати.",
    ["The red scales on these fish are believed to be a warning to predators of the Townlong Steppes and the Dread Wastes that their flesh is toxic. Dedicated fishermen can sometimes befriend one."] = "Вважається, що червона луска цих риб попереджає хижаків Степів Танлонґ та Жахливих Пустищ про те, що їхнє м'ясо отруйне. Завзяті рибалки часом можуть із такою заприятелювати.",
    ["The results of King Mechagon's experiments can be seen throughout the city and island."] = "Наслідки дослідів короля Мехаґона видно по всьому місту й острову.",
    ["The reverberating sound of an adult hornswog's belch can be heard for leagues. Less far-reaching, but far more musical, is the dainty sound of a swoglet belching."] = "Лункий звук відрижки дорослого ріжкосвоґа чути на цілі милі. Не такий далекосяжний, але куди мелодійніший — витончений звук відрижки своґеняти.",
    ["The river frogs of Stormsong Valley have been known to try to hypnotize people by staring directly into their eyes and making a low rumbling noise."] = "Річкові жаби Долини Штормової Пісні, як відомо, намагаються загіпнотизувати людей, дивлячись просто їм у вічі й видаючи низьке гарчання.",
    ["The rivers of Draenor are filled with moray.  They are vicious predators, attacking anything that enters the water."] = "Річки Дренору повняться муренами. Це люті хижаки, що нападають на все, хто заходить у воду.",
    ["The roaches of the Dread Wastes dwell in the shadows. Some people swear the shadows travel with them."] = "Таргани Жахливих Пустищ живуть у тінях. Дехто божиться, що тіні мандрують разом із ними.",
    ["The rock-hard carapaces of these spiders allow them to survive in the Searing Gorge's blistering heat."] = "Тверді, мов камінь, панцири цих павуків дозволяють їм виживати в пекучій спеці Палючої Ущелини.",
    ["The rumors of the medicinal uses of the biletoad were believed to have been started by a particularly mischievous apothecary."] = "Кажуть, що чутки про цілющі властивості жовчоропухи пустив один на диво пустотливий аптекар.",
    ["The runeforged sentries of Ulduar march endlessly without the need for rest or recharging."] = "Руноковані вартові Улдуару крокують безкінечно, не потребуючи ні відпочинку, ні підзарядки.",
    ["The runts of Malygos brood, these whelplings are prized for their boundless arcane magics."] = "Заморухи з виводку Малиґоса, ці дитинчата цінуються за свою безмежну містичну магію.",
    ["The sandy petrel flies high above the Windless Isle, safe from landbound predators."] = "Піщаний буревісник ширяє високо над Безвітряним Островом, у безпеці від наземних хижаків.",
    ["The sandyback crawlers get their name from having a slightly sticky outer shell that sand sticks to as they walk around."] = "Піскоспинні плазуни дістали свою назву через злегка липкий зовнішній панцир, до якого пристає пісок, коли вони повзають.",
    ["The saying curiosity killed the cat wasn't written about the Eversong lynx, even if their reckless kittens do find their way to the frontlines. A few rangers have found a lifelong companion stowed away in the supply wagons on campaign."] = "Приказку «цікавість кота згубила» написали не про рись Вічної Пісні, хоч її необачні кошенята таки знаходять шлях на передову. Дехто з рейнджерів знаходив супутника на все життя, що прокрався в обозні вози під час походу.",
    ["The scavenger Loa thinks you can teach this saurid a thing or two. Just don't lose sight of your coin purse."] = "Падложерний лоа вважає, що ти можеш дечого навчити цього саурида. Тільки не спускай очей зі свого гаманця.",
    ["The sea calf has a natural affinity for balancing things."] = "Морське теля має природний хист балансувати різні речі.",
    ["The seagull is a coastal scavenger often found near the docks."] = "Чайка — це прибережний падложер, якого часто бачать біля доків.",
    ["The shadowy creature has been following Sir Finley Mrrgglton around ever since he happened upon it during one of his expeditions. Having grown quite fond of the tenebrous friend, Sir Finley won't part with it easily."] = "Тіньове створіння ходить за сером Фінлі Мрргґлтоном відтоді, як він натрапив на нього під час однієї зі своїх експедицій. Дуже прихилившись до цього темного друга, сер Фінлі нелегко з ним розлучиться.",
    ["The shell on these beetles is quite brittle from the void interference, but it also has a strangely fast regeneration rate."] = "Панцир цих жуків доволі крихкий через вплив Порожнечі, зате відновлюється на диво швидко.",
    ["The shells of this particular group of crabs shimmer like gems on the sand."] = "Панцирі цієї особливої групи крабів мерехтять на піску, наче самоцвіти.",
    ["The sifang otter lives near rivers and is normally friendly and playful."] = "Видра сіфан живе біля річок і зазвичай дружня та грайлива.",
    ["The signature song of the bufonid croaker can be heard across vast distances."] = "Характерну пісню буфонідного квакача чути на величезних відстанях.",
    ["The sin'dorei use hawkstriders as mounts, but this little one was deemed unfit after being diagnosed with numerous anxiety disorders."] = "Сін'дораї використовують яструбоступів як їздових тварин, та це маля визнали непридатним після того, як у нього діагностували численні тривожні розлади.",
    ["The skies may have scorched part of Revendreth, but persistent creatures are still able to exist in these harsh conditions."] = "Небеса, може, й випалили частину Ревендрету, та витривалі створіння здатні існувати навіть у цих суворих умовах.",
    ["The skin of a teal frog sometimes shimmers just right in the sunlight, providing excellent camouflage when on the surface of the water."] = "Шкіра бірюзової жаби часом мерехтить на сонці саме так, що дає чудове маскування на поверхні води.",
    ["The slime on this provides essential nutrients to the hermit crab within, allowing it to go years without eating anything if it chooses."] = "Слиз на цій мушлі забезпечує раку-самітнику всередині потрібні поживні речовини, тож за бажання він може роками обходитися без їжі.",
    ["The slimy coating on this otter provides excellent protection against sunburns."] = "Слизький покрив на цій видрі чудово захищає від сонячних опіків.",
    ["The sludge that can give rise to the dredgers has been known to coalesce and run a muck."] = "Відомо, що твань, з якої постають копачі, часом збивається докупи й влаштовує справжній бедлам.",
    ["The smallest of cuts can be devastating to this species, they start to leak all over the place."] = "Найменший поріз може бути згубним для цього виду — вони починають протікати геть усюди.",
    ["The softest and fluffiest protosheep made of the softest and fluffiest soil."] = "Найм'якіша й найпухнастіша протовівця, зроблена з найм'якішого й найпухнастішого ґрунту.",
    ["The song of late summer nights is the song of toads."] = "Пісня пізніх літніх ночей — це пісня ропух.",
    ["The soul that occupies Mu'dud was a harsh ruler in life, and now he seeks to dominate the most violent kingdom of all."] = "Душа, що оселилася в Му'дуді, за життя була жорстоким правителем, і тепер прагне запанувати над найлютішим королівством з усіх.",
    ["The souls of slain crabs seek vengeance against the murlocs who ate them."] = "Душі вбитих крабів прагнуть помсти мурлокам, які їх з'їли.",
    ["The sound of the troglofrog echoing throughout deep caverns sounds almost like... ragtime music?"] = "Звук трогложаби, що відлунює глибокими печерами, звучить майже як... реґтайм?",
    ["The spawn of Hydross, considered by the elemental community to be the \"Earl of Puddles.\""] = "Поріддя Гідроса, якого стихійна спільнота вважає «Графом Калюж».",
    ["The sprites that inhabit the islands of the Great Sea have thought of many traps to lure in unwary visitors."] = "Феї, що населяють острови Великого Моря, вигадали безліч пасток, щоб заманювати необачних гостей.",
    ["The squeaks used by these tiny insectoids may sound cute, but they're actually screaming for your death."] = "Писк цих крихітних комахоїдів може звучати мило, та насправді вони волають про вашу смерть.",
    ["The stench alone that this thing makes when it burps can easily ruin your day."] = "Сам лише сморід, який видає ця тварюка, коли відригує, легко зіпсує тобі весь день.",
    ["The sting from these gorm is incredibly painful and often inflicts temporary paralysis, even on large targets."] = "Укус цих ґормів неймовірно болючий і часто спричиняє тимчасовий параліч навіть у великих жертв.",
    ["The stinger of a Ravager Wasp can cause intense pain for up to three hours.  Consult a physician immediately if stung."] = "Жало оси-розорювача спричиняє сильний біль, що триває до трьох годин. У разі укусу негайно зверніться до лікаря.",
    ["The stone fiends were created to serve as messengers and spies for the realm of Revendreth, and those of the Court of Harvesters serve that role extremely well."] = "Кам'яних поплічників створили, щоб вони служили гінцями й шпигунами королівства Ревендрет, і ті з них, що належать до Двору Женців, виконують цю роль надзвичайно добре.",
    ["The strand crawler has adapted to the northern cold by hibernating under the island beaches."] = "Береговий повзун пристосувався до північного холоду, впадаючи в сплячку під острівними пляжами.",
    ["The swooping horns of protorams bear the scars of every charge."] = "Вигнуті роги протобаранів несуть шрами кожного нападу.",
    ["The taciturn bandicoon's diet consists mostly of apples."] = "Раціон мовчазного бандикуна складається переважно з яблук.",
    ["The tarantulas that inhabit southern Redridge are smaller than their cousins elsewhere in Azeroth, but make up for their size with speed and ferocity."] = "Тарантули, що населяють південний Редрідж, дрібніші за своїх родичів з інших куточків Азероту, та надолужують це швидкістю й лютістю.",
    ["The taunka collect the feathers of these noble birds of prey to use in crude fortunetelling ceremonies."] = "Таунка збирають пір'я цих шляхетних хижих птахів, щоб використовувати його в нехитрих ворожбитських обрядах.",
    ["The teroclaw is a potent hunter of the small and furry."] = "Терокіготь — вправний мисливець на все дрібне й пухнасте.",
    ["The terror larva seeks a host to feed on their dreams and terrors. Soon the larva will grow into the host's worst fears."] = "Личинка жаху шукає носія, щоб живитися його снами й страхами. Невдовзі вона виросте в найгірші страхіття носія.",
    ["The thick exoskeleton of this adaptable arthropod allows it to thrive in harsh environments."] = "Товстий екзоскелет цього пристосовного членистоногого дозволяє йому буяти в суворих умовах.",
    ["The thick pelt of the otter makes it adaptable to any climate, but it particularly prefers frigid waters where abalone is plentiful."] = "Густе хутро видри дає їй пристосуватися до будь-якого клімату, та найбільше вона любить холодні води, де вдосталь морських вушок.",
    ["The thick snow near Dun Morogh acts as camouflage for snow cubs learning to hunt."] = "Глибокий сніг поблизу Дун Мороґу слугує маскуванням для снігових ведмежат, що вчаться полювати.",
    ["The thicker and more gangly the whiskers, the more devious the rodent. That's just basic biology."] = "Що густіші й розкуйовдженіші вуса, то підступніший гризун. Це проста біологія.",
    ["The thirst for mana is insatiable, luckily this little one doesn't consume a whole lot."] = "Спрага мани невгамовна, та на щастя це малятко споживає її не так уже й багато.",
    ["The thrill of battle and the grip of war have not yet left the bones of Oonar."] = "Запал битви й хватка війни ще не покинули кісток Оонара.",
    ["The tiny harvester collects weeds and small grains that the larger reapers may have missed."] = "Крихітний жнець збирає бур'яни й дрібні зерна, які могли проґавити більші женці.",
    ["The tiny terror of the Dread Wastes, Kovok prefers a steady diet of \"brain food:\" mushan brains, human brains, any brains really. This strange nutritional requirement may be tangentally related to his enormous head."] = "Крихітний жах Жахливих Пустищ, Ковок надає перевагу сталому раціону з «їжі для мозку»: мізки мушанів, людські мізки, та й узагалі будь-які мізки. Ця дивна харчова потреба, мабуть, побіжно пов'язана з його велетенською головою.",
    ["The toes! The huge toe beans! The huge toe beans are not for eating!"] = "Лапки! Величезні подушечки на лапках! Величезні подушечки на лапках не для того, щоб їх їсти!",
    ["The trolls have a long and storied history of summoning hydras. While he might not be the biggest or strongest hydra, Gahz'rooki will bite your fingers quite hard if you get too close."] = "Тролі мають довгу й славну історію прикликання гідр. Хоч Ґаз'рукі й не найбільша та не найсильніша гідра, вона добряче вкусить тебе за пальці, якщо підійдеш надто близько.",
    ["The trolls of Zul'Drak inadvertently created these little beings while summoning water elementals to fight the Scourge."] = "Тролі Зул'Драка ненавмисне створили цих малих істот, прикликаючи водяних елементалів для боротьби з Погибеллю.",
    ["The tusks on these creatures are fused to their skulls in such a manner that they feel no pain when charging or ramming into anything."] = "Ікла цих створінь зрослися з черепом так, що вони не відчувають болю, коли кидаються в атаку чи протаранюють щось.",
    ["The void can consume life or meld with it. The latter often has unpercieved consequences."] = "Порожнеча може поглинати життя або зливатися з ним. Останнє часто має непомітні наслідки.",
    ["The volatile Durotar scorpion is a fierce desert predator. It's known for only occasionally stinging its owner."] = "Норовливий скорпіон із Дуротару — лютий пустельний хижак. Він відомий тим, що жалить власника лише вряди-годи.",
    ["The vorquin of the dragon isles have manes that come in a variety of stunning colors."] = "Воркіни Драконових Островів мають гриви найрізноманітніших приголомшливих кольорів.",
    ["The voru'kar are fiercely loyal to their leader, Vorus'arak, who led them to safety from the Lich King's grasp."] = "Вору'кар люто віддані своєму вождю Ворус'араку, який вивів їх у безпеку з лабет Короля-Ліча.",
    ["The watefly uses the surface of the water to reflect the light from their abdomen to attract mates."] = "Водомушка користується поверхнею води, щоб відбивати світло свого черевця й приваблювати пару.",
    ["The waters of Ruby Lake are colored a strange reddish hue, possibly due to the ruby crystals found deep within the mountains of the Timeless Isle."] = "Води Рубінового Озера мають дивний червонястий відтінок — можливо, через рубінові кристали, що залягають глибоко в горах Позачасового Острова.",
    ["The white fur of the Snowy Panda allows it to hide in the snowbanks of Kun-Lai Summit."] = "Біле хутро сніжної панди дозволяє їй ховатися в заметах Піка Кун-Лай.",
    ["The whooping noise these pets make when hungry will rival any tormented cry you can find in Torghast."] = "Завивання, яке ці улюбленці видають з голоду, посперечається з будь-яким стражденним зойком, що лунає в Торгасті.",
    ["The wily fish has never been caught at the end of an angler's hook. He was caught a completely different way."] = "Хитру рибину ще ніколи не ловили на гачок рибалки. Її спіймали зовсім іншим способом.",
    ["The winged aqir are very fast and agile, and their wings provide a nice breeze on a warm afternoon."] = "Крилаті аквіри дуже швидкі та спритні, а їхні крила створюють приємний вітерець теплого пообіддя.",
    ["The wings of glimmerflies are almost always saturated with some sort of pollen, causing a very steady flow of glittery dust to fall off of them as they fly."] = "Крила мерехтокрильців майже завжди вкриті якимось пилком, тож у польоті за ними тягнеться рівний шлейф блискучого пилу.",
    ["The wings of this butterfly start off with no distinct color, but slowly change to yellow as they spend time in the sunlight."] = "Спершу крила цього метелика не мають певного кольору, але поступово жовтіють, проводячи час під сонцем.",
    ["The wings of this moth glitter like the starry skies above Ardenweald."] = "Крила цього метелика виблискують, мов зоряні небеса над Арденвельдом.",
    ["The wisest engineers of Azeroth all know that the only thing more dangerous than a living evil chicken, is the mind of an evil chicken transplanted into the body of a mechanical chicken."] = "Наймудріші інженери Азероту всі як один знають: єдине, що небезпечніше за живу злу курку, — це розум злої курки, пересаджений у тіло механічної курки.",
    ["The young of Arathi Highlands' plains spiders may kick clouds of barbed abdomen hairs into predators' eyes. All this, and poisonous web-spitters, too."] = "Молодняк рівнинних павуків Араті-Хайлендсу здатен зметнути в очі хижакам хмару колючих волосків зі свого черевця. До того ж вони ще й плюються отруйним павутинням.",
    ["Their deceptively cute looks will lure in their prey, and then greet them with a flurry of devastating swipes. Hug with caution."] = "Оманливо милий вигляд приваблює здобич, а потім зустрічає її шквалом нищівних ударів. Обіймати з обережністю.",
    ["Their deep purple wings are highly sought after by ogre magi believing that they can bring prolonged life when added to potions."] = "Їхні темно-багряні крила дуже цінують оґри-маги, бо вірять, що ті продовжують життя, коли додати їх до зілля.",
    ["Their eerie green light, reminiscent of fel flames, is occasionally seen flitting through the twisted trees of Darkmoon Island."] = "Їхнє моторошне зелене світло, що нагадує сквернотворне полум'я, час від часу майорить серед покручених дерев Острова Темного Місяця.",
    ["Their proximity to the magic of the elves has caused some of them unnatural long life. And in some elfin rabbits...stranger things."] = "Близькість до ельфійської магії дарувала декому з них неприродно довге життя. А деяким ельфійським кролям... і дивніші речі.",
    ["Their white hide would make them vulnerable to sunburn, if it wasn't as thick as plate armor."] = "Їхня біла шкура робила б їх вразливими до сонячних опіків, якби не була завтовшки з латний обладунок.",
    ["Their wings emit a fine powder as a defensive mechanism when it is in danger."] = "У небезпеці їхні крила випускають дрібний пилок як захисний механізм.",
    ["Therazane wore these spunky crimson elementals as jewelry before the azure craze swept through Deepholm."] = "Теразана носила цих завзятих багряних елементалів як прикраси, доки Діпголм не охопила мода на блакить.",
    ["There are few things more annoying for a farmer to find underfoot than a rooster looking for love."] = "Мало що так дратує фермера під ногами, як півень у пошуках кохання.",
    ["There are many creatures lurking in the Cape of Stranglethorn who would be glad to kill you. Misty is just curious to see the rest of the world."] = "На Мисі Холодець багато створінь, які радо тебе вб'ють. А от Імлинці просто цікаво побачити решту світу.",
    ["There are many scholars who question whether it is a toad or not."] = "Чимало дослідників сумніваються, чи це взагалі ропуха.",
    ["There are many terrifying things in Zereth Mortis, but none so terrifying (or adorable) as a vombata protecting its young."] = "У Зерет Мортісі багато моторошного, але нічого настільки моторошного (чи чарівного), як вомбата, що захищає своїх малят.",
    ["There are more sharp pointy things on this species of gorm than there are on a Horde capital city."] = "На цьому виді ґормів більше гострих колючок, ніж їх знайдеш у столиці Орди.",
    ["There are some things too dirty even for rats."] = "Є речі, надто брудні навіть для щурів.",
    ["There is a story told to some children that all winged creatures were unable to fly until Pa'ku provided enough wind to lift them off of the ground."] = "Дітям подекуди розповідають історію про те, що всі крилаті створіння не вміли літати, доки Па'ку не дала достатньо вітру, щоб підняти їх із землі.",
    ["There is no fury quite like that of a mother Blackfeather defending her nest."] = "Немає люті, рівної люті матері-чорнопірки, що боронить своє гніздо.",
    ["There is something deeply unsettling about the tentacle, perhaps it is best not to look at it for too long."] = "У цьому щупальці є щось глибоко тривожне — мабуть, краще не дивитися на нього надто довго.",
    ["There is very little difference between a corrupted nest guardian and an omelette chef."] = "Між зіпсутим хранителем гнізда й кухарем-омлетником різниці зовсім небагато.",
    ["There must always be a Lick King."] = "Завжди має бути Лизкороль.",
    ["There was once a mawsworn so vile that he was killed by his own minions. So great was his malice that a fragment of him lives on in this glove."] = "Колись жив пащезаприсяжений настільки мерзенний, що його вбили власні поплічники. Така велика була його злоба, що фрагмент його й досі живе в цій рукавиці.",
    ["There's a raging debate over whether tanukis are raccoons or dogs, but the distinction seems trivial when they're gnawing on your femur."] = "Точиться запекла суперечка, ким є танукі — єнотами чи псами, та різниця здається дріб'язковою, коли вони гризуть вашу стегнову кістку.",
    ["There's an old vrykul saying that goes, 'Let sleeping worgs lie, unless you don't want your face anymore.'"] = "Є старе врайкульське прислів'я: «Не буди сплячих воргів, хіба що тобі вже не потрібне твоє обличчя».",
    ["There's no mistaking the evidence -- algan breed by budding. We can all put this argument to rest now."] = "Докази незаперечні — алґани розмножуються брунькуванням. Тепер цю суперечку можна закрити.",
    ["These Aqir Scarabs are masters at tunneling through any terrain."] = "Ці скарабеї акірів — справжні майстри прокладати тунелі крізь будь-який ґрунт.",
    ["These Pygmy Camels are often mistaken for Mysterious Camel Figurines."] = "Цих карликових верблюдів часто плутають із Загадковими Верблюжими Фігурками.",
    ["These adorable beasts are both cuddly and huggable, provided you do not enjoy having a face."] = "Ці чарівні звірята милі й охоче дають себе обійняти — за умови, що тобі байдуже до власного обличчя.",
    ["These adorable critters love snuggling with their owners after a long day of brutal, bloody battle."] = "Ці чарівні створіння обожнюють поніжитися зі своїми господарями після довгого дня жорстокої кривавої битви.",
    ["These albatrosses are slightly smaller than those found inland, and they can travel great distances over the sea."] = "Ці альбатроси трохи менші за тих, що трапляються у глибині суходолу, і здатні долати величезні відстані над морем.",
    ["These arachnids use their razor-sharp legs to carve tunnels in the solid rock of the Blade's Edge Mountains."] = "Ці павукоподібні використовують гострі як бритва лапи, щоб прокладати тунелі в твердій породі Гір Леза Гостряка.",
    ["These arthropods line many Azerothian shores and seek to fulfill their one true desire: to pinch."] = "Ці членистоногі заполоняють чимало узбереж Азероту, прагнучи здійснити одне-єдине справжнє бажання: ущипнути.",
    ["These astral phenomena are rarely sighted due to the speed of the slyvern. It is a good omen to have one following you around."] = "Ці астральні явища рідко вдається побачити через швидкість слайвернів. Мати такого, що ходить за вами, — добра прикмета.",
    ["These beautiful drakes can be found across the shores of Northrend."] = "Цих прекрасних драків можна зустріти на узбережжях Нордролу.",
    ["These beautiful, elusive birds have very erratic migratory patterns, which can be difficult to track, leading some explorers to erroneously believe ducks simply didn't exist."] = "Ці прекрасні невловні птахи мають дуже хаотичні шляхи міграції, які важко відстежити, через що деякі дослідники помилково вважали, ніби качок просто не існує.",
    ["These beetles often make their homes in quarries abandoned by the Horde war machine in Durotar."] = "Ці жуки часто оселяються в кар'єрах, покинутих воєнною машиною Орди в Дуротарі.",
    ["These birds often prey on turtles by dropping them from great heights to break open their shell."] = "Ці птахи часто полюють на черепах, скидаючи їх із великої висоти, щоб розколоти панцир.",
    ["These birds use their sharp beaks and dragon-like talons to forage for prey on tree trunks and branches. They communicate with each other by drumming on the trees with their beaks, which makes a sound that can be heard over great distances."] = "Ці птахи послуговуються гострими дзьобами та драконоподібними пазурами, щоб видобувати здобич зі стовбурів і гілок дерев. Вони спілкуються між собою, тарабанячи дзьобами по деревах, і цей звук чути на великих відстанях.",
    ["These blisteringly hot spiders camouflage themselves by blending in with oozing magma."] = "Ці розпечені до краю павуки маскуються, зливаючись із текучою магмою.",
    ["These brightly-colored dragonhawks carry Kael'thas' forces swiftly and unerringly through the nether storm surrounding the Eye."] = "Ці яскраво забарвлені драконясти швидко й безпомильно несуть сили Кель'таса крізь бурю порожнечі, що оточує Око.",
    ["These brightly-colored terrapins are the least commonly seen in the wild. It is considered a sign of luck if you rub the top of its shell."] = "Цих яскравих черепах у дикій природі бачать найрідше. Кажуть, що потерти верх її панцира — на щастя.",
    ["These crabs build their own shells from small fragments of rocks and gems."] = "Ці краби будують собі панцирі з дрібних уламків каміння та самоцвітів.",
    ["These crabs have developed an advanced form of camouflage that causes their skin to appear translucent."] = "Ці краби виробили досконалий різновид маскування, від якого їхній покрив здається напівпрозорим.",
    ["These crafty crustaceans burrow under the mud to avoid being scooped up by larger predators."] = "Ці хитрі ракоподібні зариваються в мул, щоб більші хижаки їх не виловили.",
    ["These creatures are able to control each arm individually, which allows for great multi-tasking, and the ability to give the best hugs."] = "Ці створіння здатні керувати кожною рукою окремо, що дозволяє чудово робити кілька справ водночас, а ще — обіймати найкраще у світі.",
    ["These creatures are highly sought after by hunters looking to make weapons from the sharp crystals on its back."] = "На цих істот дуже полюють мисливці, що прагнуть зробити зброю з гострих кристалів на їхній спині.",
    ["These creatures are silent, save for the occasional sigh of otherworldly despair."] = "Ці створіння мовчазні — хіба що зрідка зітхнуть від потойбічного відчаю.",
    ["These creatures can hunt in almost pure darkness."] = "Ці створіння можуть полювати майже в цілковитій темряві.",
    ["These creatures have developed a chitin armor around its fangs, legs and abdomen."] = "Ці створіння виробили хітиновий панцир навколо іклів, ніг і черевця.",
    ["These creatures live in bushes and near trees, but they sleep so soundly they're practically invisible. If you want to interrupt their dreaming, you'd best bring friends."] = "Ці істоти живуть у кущах і біля дерев, але сплять так міцно, що практично невидимі. Якщо хочете перервати їхні сни, краще приведіть друзів.",
    ["These creatures manifest in the catacombs beneath Revendreth due to vile rituals practiced on souls there."] = "Ці створіння постають у катакомбах під Ревендретом через мерзенні ритуали, яким там піддають душі.",
    ["These creatures were bred to hunt snakes. With a low profile and a long body, Snakebiters are perfect for chasing serpents into their own holes."] = "Цих істот вивели для полювання на змій. Завдяки приземкуватому й довгому тілу Змієкуси ідеально підходять, щоб заганяти гадюк у їхні ж нори.",
    ["These creatures' shells are not literally made of stone, but they're strong enough that they might as well be."] = "Панцирі цих істот не зроблені буквально з каменю, але вони такі міцні, що з тим самим успіхом могли б бути.",
    ["These critters are capable of holding a tremendous amount of food in their cheeks for easy transportation between hiding spaces."] = "Ці звірятка здатні напхати в щоки величезну кількість їжі, щоб легко переносити її між схованками.",
    ["These critters often leave their spawning groups as soon as they can move around on land."] = "Ці створіння часто покидають свою виплодкову зграйку, щойно навчаться пересуватися суходолом.",
    ["These critters' white coats help them hide in the snow when  predators are around."] = "Біле хутро цих звіряток допомагає їм ховатися в снігу, коли поблизу хижаки.",
    ["These cuddly rascals enjoy basking in the sun, sleeping in the sun, and napping in the sun."] = "Ці пухнасті бешкетники полюбляють грітися на сонці, спати на сонці й дрімати на сонці.",
    ["These dazzling hatchlings have a distinctive coat color that has been highly sought after by leatherworkers for generations."] = "Ці сліпучі малята мають своєрідне забарвлення, за яким шкіряники гасають уже багато поколінь.",
    ["These dragonhawks developed in the wilds of Zul'aman, where their green feathers and molt help them hide from hunters and predators."] = "Ці драконосоколи розвинулися в нетрях Зул'Амана, де зелене пір'я та линяння допомагають їм ховатися від мисливців і хижаків.",
    ["These dredbats are built by the Stonewright for the Court of Harvesters. They are bonded to their owners and become fierce fighters."] = "Цих копнетопирів створює Каменотеска для Двору Женців. Вони прив'язуються до своїх господарів і виростають у лютих бійців.",
    ["These drops of Azerite are volatile and prone to explosive reactions when prodded."] = "Ці краплі азериту нестійкі й схильні до вибухових реакцій, якщо їх зачепити.",
    ["These eight-legged critters have lurked in the shadowy cliffs of the Stonetalon Mountains for millennia."] = "Ці восьминогі створіння тисячоліттями чаїлися в тінистих скелях Гір Кам'яного Кігтя.",
    ["These elusive creatures are famous for being hard to find unless you already know where to look. Fortunately, Haniko told you where to look."] = "Ці невловні створіння славляться тим, що їх важко знайти, якщо ти ще не знаєш, де шукати. На щастя, Ганіко підказав тобі, де саме.",
    ["These ensorcelled gauntlets are used by the mawsworn to capture escaping prisoners."] = "Ці зачаровані рукавиці пащезаприсяжені використовують, щоб ловити втеклих в'язнів.",
    ["These eyes were sent to slow and debilitate the wayward souls of the Maw, so that they could be more easily captured."] = "Ці очі наслали, щоб уповільнювати й знесилювати заблукані душі Пащі, аби їх легше було ловити.",
    ["These fast and nimble swimmers are highly desired by pet collectors. Though they can appear friendly, their tail stinger can kill on contact."] = "Цих швидких і спритних плавців дуже жадають збирачі улюбленців. Хоч вони можуть здаватися привітними, їхнє хвостове жало здатне вбити дотиком.",
    ["These ferocious flying creatures scrape their beaks against hard surfaces to sharpen them and intimidate foes."] = "Ці люті летючі створіння труть дзьобами об тверді поверхні, щоб загострити їх і залякати ворогів.",
    ["These fireflies retain their purple glow by eating only purple flowers and nectar."] = "Ці світляки зберігають своє багряне сяйво, бо їдять лише багряні квіти й нектар.",
    ["These flying creatures do not leave feathers out in the wild. If a feather happens to ever detach from their body, the feather glows brilliantly for a moment and then vanishes from sight."] = "Ці летючі створіння не лишають пір'я в дикій природі. Якщо перо колись і відпадає від їхнього тіла, воно на мить яскраво спалахує, а тоді зникає з очей.",
    ["These golden-feathered creatures do not lay golden eggs, for that you would need a golden goose."] = "Ці золотопері створіння не несуть золотих яєць — для цього тобі знадобилася б золота гуска.",
    ["These grubs consume anima-depleted materials of all types. They aren't picky."] = "Ці личинки поїдають вичерпані з аніми матеріали будь-якого ґатунку. Вони не вередливі.",
    ["These gruesome crabs are attracted to the scent of blood and seem to revel in combat."] = "Цих моторошних крабів вабить запах крові, і вони, схоже, упиваються боєм.",
    ["These grumpy, frumpy meeksi only seem to find joy when drinking a boba milk tea with salted caramel and cookie dough."] = "Ці буркотливі, неохайні мікси, схоже, тішаться лише тоді, коли п'ють чай з молоком і кульками боба, солоною карамеллю та печивним тістом.",
    ["These guardians of Torghast are always watching for suspicious activity."] = "Ці вартові Торгасту повсякчас пильнують, чи не діється щось підозріле.",
    ["These hardy bees form the backbone of a great honey and mead industry. For decades, the Tidesages forbade anyone from taking them outside of Stormsong."] = "Ці витривалі бджоли — опора великого медового та медоварного промислу. Десятиліттями Припливомудрі забороняли будь-кому вивозити їх за межі Штормової Пісні.",
    ["These hardy fish can survive in a wide range of climates, from the snow capped mountains of Kun-Lai Summit to the temperate, salty waters of the oceans around Pandaria. Dedicated fishermen can sometimes befriend one."] = "Ці витривалі риби виживають у найрізноманітнішому кліматі — від засніжених вершин Піка Кун-Лай до помірних солоних вод океанів довкола Пандарії. Завзяті рибалки часом можуть із такою заприятелювати.",
    ["These hatchlings entertain themselves by clacking their mandibles together in increasingly complex rhythms."] = "Ці пташенята розважаються, клацаючи жвалами у дедалі складніших ритмах.",
    ["These hedgehogs may be silent, but often are heard the cries of those that foolishly step upon their quills."] = "Ці їжаки, може, й тихі, та часто чути крики тих, хто по-дурному наступив на їхні голки.",
    ["These highly destructive pests are known to destroy crops in Hallowfall."] = "Ці вкрай руйнівні шкідники відомі тим, що нищать урожай у Голловфолі.",
    ["These ill-tempered constructs of flame and rage sometimes rise from the remains of larger infernals who fall in battle."] = "Ці злостиві створіння з вогню та люті часом постають із решток більших інферналів, полеглих у битві.",
    ["These lambs savor a journey to the beaches of Khaz Algar to rest in warm sands."] = "Цим ягнятам до смаку подорож до пляжів Хаз-Алґару, щоб відпочити в теплому піску.",
    ["These little green grubs are native to wilds of Pandaria. Its verdant coloration camouflages it from would-be predators."] = "Ці маленькі зелені личинки родом із нетрів Пандарії. Їхнє зелене забарвлення маскує їх від можливих хижаків.",
    ["These little guys can be found in the waters of the Timeless Isle, or swimming alongside Jewel Danio or Redbelly Mandarin. Dedicated fishermen can sometimes befriend one."] = "Цих малюків можна знайти у водах Позачасового Острова або поряд із самоцвітним даніо чи червоночеревим мандарином. Завзяті рибалки часом можуть із такою заприятелювати.",
    ["These little slugs will try to eat literally anything they scoot over."] = "Ці маленькі слимаки намагаються зжерти буквально все, по чому проповзуть.",
    ["These living blobs of ooze lack even the most rudimentary form of intelligence, but that doesn't mean they can't be your friend."] = "Цим живим грудкам слизу бракує навіть найпростішого розуму, та це не означає, що вони не можуть стати вам другом.",
    ["These look especially magnificent when gliding over the water under a full moon."] = "Вони мають особливо чарівний вигляд, коли ширяють над водою під повним місяцем.",
    ["These magical lanterns are acquired at the Lunar Festival, which celebrates the defeat of the Burning Legion by the free races of Azeroth."] = "Ці чарівні ліхтарі здобувають на Місячному Святі, що вшановує поразку Полум'яного Легіону від вільних народів Азероту.",
    ["These malicious oozes are highly sensitive to Primordius' pheromone signature."] = "Ці злостиві слизі вкрай чутливі до феромонного сліду Прімордія.",
    ["These off-season allies work tirelessly to prepare for the Feast of Winter Veil, and would appreciate not being disturbed the rest of the year."] = "Ці позасезонні союзники невтомно готуються до Свята Зимової Заслони й були б вдячні, якби решту року їх не турбували.",
    ["These pests are known for their cantankerous attitudes and affinity for nesting in the smokestacks of Undermine, much to the locals dismay."] = "Ці шкідники відомі своєю буркотливою вдачею та схильністю гніздитися в димарях Андермайну, на превеликий жаль місцевих.",
    ["These playful feline cubs practice their hunting skills by stalking each other through the Barrens."] = "Ці грайливі котенята вправляються в мисливських навичках, скрадаючись одне за одним по Степу.",
    ["These playful little riverbeasts enjoy scooping up a large mouthful of water and then spitting it at one another."] = "Ці грайливі маленькі річкозвіри люблять набирати повний рот води, а тоді бризкати нею одне в одного.",
    ["These possessed puppets are given a semblance of life by whimsical spirits of the departed."] = "Цим одержимим лялькам надають подобу життя примхливі духи померлих.",
    ["These poultrids are hostile, but never angry. They love every moment of every battle."] = "Ці птахи ворожі, але ніколи не злі. Вони насолоджуються кожною миттю кожного бою.",
    ["These prissy, flightless birds are known to relentlessly groom themselves. Much like their riders."] = "Ці манірні нелетючі птахи відомі тим, що безперестанку чепуряться. Достоту як їхні вершники.",
    ["These pudgy little beings often get themselves into trouble while hunting down their favorite snack: glow caps."] = "Ці пухкенькі малі створіння часто потрапляють у халепу, полюючи на свій улюблений харч — світлошапки.",
    ["These pups are bundles of fur and teeth until they grow up, at which point they are really just teeth."] = "Ці цуценята — клубочки хутра й зубів, доки не виростуть, а тоді від них лишаються самі зуби.",
    ["These rams hone their fighting skills by head-butting twigs and saplings near Loch Modan."] = "Ці барани відточують бойові навички, буцаючи галузки й молоді деревця поблизу Лох Модану.",
    ["These reptiles possess hooked scales, allowing them to slither up Kun-Lai Summit's rocky slopes and steep cliffs."] = "Ці плазуни мають гачкуваті луски, що дозволяють їм видряпуватися кам'янистими схилами та крутими скелями Вершини Кун-Лай.",
    ["These saplings grow unnaturally quickly when given enough anima, and their leaves are razor sharp when fully grown."] = "Маючи вдосталь аніми, ці паростки ростуть неприродно швидко, а коли визрівають, їхнє листя стає гострим, мов лезо.",
    ["These silkie chickens were taken aboard airships by those departing the Arathi Empire in pursuit of their emperor's prophetic vision."] = "Цих курей-шовківниць узяли на борт повітряних кораблів ті, хто покидав Аратійську імперію, прагнучи здійснити пророче видіння свого імператора.",
    ["These skulking little creatures hatch in nests built around the ancient dragon bones of central Northrend."] = "Ці потайливі малі створіння вилуплюються в гніздах, збудованих навколо стародавніх драконячих кісток центрального Нортренду.",
    ["These slimy creatures make the strangest suction noises when they try to climb up a wall. This is a well-known fact in Maldraxxus, for obvious reasons."] = "Ці слизькі створіння видають найдивніші плямкальні звуки, коли намагаються вилізти на стіну. У Малдраксусі це добре відомий факт — з очевидних причин.",
    ["These small bears will not normally attack people, but they have been known to steal the occasional picnic basket."] = "Ці маленькі ведмеді зазвичай не нападають на людей, проте відомі тим, що подеколи крадуть кошики для пікніка.",
    ["These small cubs are as fiesty as they are cuddly."] = "Ці маленькі дитинчата такі ж завзяті, як і ласкаві.",
    ["These small elementals cling to the backs of larger mire beasts, picking off tasty bugs and mites."] = "Ці маленькі елементалі чіпляються за спини більших драговинних звірів, визбируючи смачних комах і кліщів.",
    ["These small krolusks seem to prefer the sandy shoals and high humidity of the isles' many beaches."] = "Ці маленькі кролуски, схоже, віддають перевагу піщаним мілинам і високій вологості численних пляжів островів.",
    ["These small spirits find their undead neighbors to be poor company, so they typically wander Tirisfal Glades alone."] = "Ці малі духи не вважають своїх нежиттєвих сусідів за гідне товариство, тож зазвичай блукають Гаями Тирисфалу самотою.",
    ["These snails are especially prized by many drogbar snail-racers for being fast and looking fantastic."] = "Цих слимаків особливо цінують численні дроґбарські слимако-гонщики за швидкість і чудовий вигляд.",
    ["These snakes are extraordinarily docile creatures.  However, they blend with their environment so well that many adventurers tread too closely to a nest.  Most bites result from totally avoidable incidents."] = "Ці змії — напрочуд сумирні створіння. Та вони так добре зливаються з довкіллям, що багато мандрівників надто близько підступають до гнізда. Більшість укусів стається через цілком уникненні випадки.",
    ["These snakes have been known to swallow gnomes in one gulp."] = "Подейкують, що ці змії ковтають ґномів одним махом.",
    ["These spirits represent the heart of Pandaria's elemental powers."] = "Ці духи уособлюють серце елементарних сил Пандарії.",
    ["These strange critters glimmer like ice, allowing them to hide among Winterspring's snowy expanses."] = "Ці дивні створіння мерехтять, наче лід, що дозволяє їм ховатися серед засніжених просторів Вічнозим'я.",
    ["These stunning creatures, awarded to heroes for victory in battle, represent bravery and strength."] = "Ці приголомшливі створіння, що їх вручають героям за перемогу в битві, уособлюють відвагу й силу.",
    ["These swarms of void energy cannot persist in Beledar's light."] = "Ці рої порожнечної енергії не можуть існувати у світлі Беледара.",
    ["These tiny arthropods are Pandaria natives that call the area of the Windless Isle their home."] = "Ці крихітні членистоногі — корінні мешканці Пандарії, що звуть домівкою край Безвітряного Острова.",
    ["These tiny creatures seem to favor big, fluffy nests, preferably atop an animal-loving dryad."] = "Здається, ці крихітні створіння полюбляють великі пухнасті гнізда, найкраще — на голові дріади, що любить тварин.",
    ["These tiny flame imps roam the Molten Core in large swarms and can replenish their numbers rapidly."] = "Ці крихітні полум'яні дияволята блукають Розплавленим Осердям великими роями й здатні швидко поповнювати свою чисельність.",
    ["These tiny harvesters are often deployed along the coastline during low tide to collect cargo and timbers that have washed ashore from shipwrecks."] = "Цих крихітних збирачів часто запускають уздовж берега під час відпливу, щоб збирати вантаж і деревину, які прибило до берега з кораблетрощ.",
    ["These tiny minions of Zandalar are adept at stowing away within the cargo holds of the enormous Zandalari warships."] = "Ці крихітні поплічники Зандалара вправно ховаються у вантажних трюмах велетенських бойових кораблів зандаларі.",
    ["These toads do not appreciate having their legs pulled off."] = "Ці ропухи геть не цінують, коли їм відривають лапки.",
    ["These vicious fire-breathing whelps escaped Onyxia's lair and fled into the surrounding region. Handle with extreme caution."] = "Ці люті вогнедишні дракончики втекли з лігва Оніксії й розповзлися по навколишньому краю. Поводься з ними вкрай обережно.",
    ["These voracious carnivores first arrived on Azeroth aboard the draenei's dimensional fortress, the Exodar."] = "Ці ненажерливі хижаки вперше прибули до Азероту на вимірній фортеці дренеїв — Екзодарі.",
    ["These voracious whelps grow at an incredible rate and can devour nearly twice their weight in raw meat per day."] = "Ці ненажерливі маленята ростуть із неймовірною швидкістю й можуть проковтнути за день майже вдвічі більше сирого м'яса, ніж важать самі.",
    ["These whelps are frequently captured by the denizens of Jorundall when still young and trainable."] = "Цих дракончиків часто ловлять мешканці Йорундалу, поки ті ще юні й піддаються навчанню.",
    ["These young orcs strive to embody the Argent Crusade's virtues: valor, strength, and integrity."] = "Ці юні орки прагнуть утілювати чесноти Срібного Хрестового Походу: відвагу, силу та доброчесність.",
    ["They are so cute before they develop razor-sharp teeth and venom."] = "Вони такі милі, доки в них не виростуть гострі, як лезо, зуби й не з'явиться отрута.",
    ["They do NOT taste like potatoes. Promise."] = "Вони НЕ на смак як картопля. Обіцяю.",
    ["They eat and eat and eat, until they grow large.  Then they eat some more."] = "Вони їдять, і їдять, і їдять, доки не виростуть великими. А потім їдять іще.",
    ["They feed off of the nutrient-rich fungal spores which gives these crabs the district coloring of their shells."] = "Вони живляться поживними спорами грибів, що й надає панцирам цих крабів характерного забарвлення.",
    ["They loves sand. It's coarse, and it gets everywhere."] = "Він любить пісок. Він шорсткий, і він усюди.",
    ["They only get more beautiful as they age."] = "З віком вони лише гарнішають.",
    ["They say Fleet Admiral Tethys was never without his trusty parrot by his side - or on his shoulder. Tethys could always call him with a whistle."] = "Кажуть, флотський адмірал Тетіс ніколи не розлучався зі своїм вірним папугою, що сидів поруч або на його плечі. Тетіс завжди міг прикликати його свистом.",
    ["They were here long before us and will be here long after we are gone."] = "Вони були тут задовго до нас і будуть тут ще довго після того, як нас не стане.",
    ["They weren't lying, this rat can absolutely get that dang cheese."] = "Вони не брехали, цей щур абсолютно точно може дістати той клятий сир.",
    ["They will cover themselves in seaweed and other ocean foliage to get the upper claw on their prey."] = "Вони вкривають себе водоростями й іншою морською зеленню, щоб мати клешню перевагу над здобиччю.",
    ["This Jelly has seen better days. Now it sees through fifty different eyes."] = "Це Желе бачило кращі дні. Тепер воно бачить крізь п'ятдесят різних очей.",
    ["This Salamanther met itself while lost in time. The two hung out on a rock together for a few hours. It was nice."] = "Ця саламандра зустріла саму себе, загубившись у часі. Удвох вони кілька годин просиділи на камені. Було приємно.",
    ["This adorable little elephant is always there for you."] = "Це чарівне маленьке слоненя завжди поряд із тобою.",
    ["This adorable mass of whirlers, cogs, and sprockets wasn't assembled in Gnomeregan. Where then?"] = "Цей чарівний клубок крутіїв, шестерень і зубчастих коліщат зібрали не в Гномреґані. То де ж?",
    ["This anxious avian has a voracious appetite for fruit."] = "Цей метушливий пернатий має ненаситний апетит до фруктів.",
    ["This appears to be nothing more than the paw of a small primate. A closer inspection shows that the hand has been dried by centuries of exposure to the sands of Uldum."] = "На перший погляд це лише лапа дрібного примата. Та придивившись, помічаєш, що рука висохла за століття під пісками Ульдуму.",
    ["This baby thorntail's favorite activity is splashing in small puddles."] = "Найулюбленіша забавка цього малого колючохвоста — хлюпатися в невеликих калюжах.",
    ["This bear's necessities are fresh batteries and an occasional oil change."] = "Усе, що потрібне цьому ведмедеві, — свіжі батарейки та зрідка заміна мастила.",
    ["This beautiful macaw is awfully far from home, and seeks the company of a more worthy companion than it's previous 'owners'."] = "Цей чудовий ара страшенно далеко від домівки й шукає товариства компаньйона, гіднішого за своїх попередніх «власників».",
    ["This bird is a salty veteran of the endless naval battles surrounding Tol Barad--a veteran whose grown plump from picking through the leftovers, that is."] = "Цей птах — бувалий ветеран нескінченних морських баталій довкола Тол Бараду — ветеран, який добряче розжирів, дзьобаючи недоїдки.",
    ["This boarlet escaped Coldridge Valley in search of adventure and maybe a nice apple if she can find one."] = "Це кабанятко втекло з Долини Холодного Кряжа в пошуках пригод і, можливо, гарного яблука, якщо пощастить його знайти.",
    ["This bold elfhound was born to chase mana wyrms, and mana wyrm-shaped objects... Like unattended sausages."] = "Цей сміливий ельфопес народжений ганятися за мановірмами та речами, схожими на мановірмів... як-от за лишеними без нагляду ковбасками.",
    ["This bubble is way worse than a tank."] = "Ця бульбашка набагато гірша за акваріум.",
    ["This budding ancient is a unique variety in Azeroth, created from the ever-living branches of the Great Tree, and can bloom in any season."] = "Цей бруньковий древній — унікальний різновид в Азероті, створений із вічноживих гілок Великого Дерева, і здатний квітнути будь-якої пори року.",
    ["This bunny is the cutest thing its opponent will ever see. It'll also be the last."] = "Це зайченя — наймиліше, що його супротивник коли-небудь побачить. А також останнє.",
    ["This butterfly is stained red from the blood of its enemies."] = "Цей метелик заплямований червоним від крові своїх ворогів.",
    ["This cat eats anything from random scraps of food to strange glowing cubes of immense power. Be careful in front of its mouth."] = "Цей кіт ладен зжерти будь-що — від випадкових недоїдків до дивних світних кубів незмірної сили. Будь обережний біля його пащі.",
    ["This cat is known for her lies, ignore her sweet meows."] = "Ця кішка відома своєю брехливістю — не зважай на її солодке нявчання.",
    ["This clever toy is equipped with a secret switch to disable its 'tranquil' mode. Luckily, even the engineers who built it don't know how to find it."] = "Ця хитромудра іграшка має таємний перемикач, що вимикає «спокійний» режим. На щастя, навіть інженери, які її змайстрували, не знають, де його шукати.",
    ["This collection of spores exploded one too many times on its previous owner. Maybe you'll have better luck with it."] = "Це зібрання спор разів забагато вибухнуло на попередньому власникові. Можливо, тобі поталанить більше.",
    ["This cosmic ray pup is curious about a great many things. Don't let it get into trouble (again)!"] = "Це малятко космічного ската цікавиться безліччю речей. Не дай йому вскочити в халепу (знову)!",
    ["This crafty raptor was born in the icy wastes of Northrend. Its harsh upbringing gives it strength when many others would perish."] = "Цей хитрий раптор народився в крижаних пустках Нортренду. Сувора юність дала йому силу там, де багато інших загинули б.",
    ["This creature can eat twice its bodyweight at a single meal."] = "Ця істота здатна з'їсти подвійну вагу свого тіла за один раз.",
    ["This creature could sleep through another Cataclysm."] = "Ця істота могла б проспати ще один Катаклізм.",
    ["This creature is usually known to be quite docile, but try to stick a carrot in its face and YOU WILL lose feeling in your fingers."] = "Цю істоту зазвичай вважають доволі сумирною, та спробуйте лишень тицьнути їй морквину під ніс — і ВИ ТОЧНО втратите чутливість у пальцях.",
    ["This creature usually has a muddy appearance, but occasionally you may find one that shines a brilliant red."] = "Ця істота зазвичай має брудно-бурий вигляд, але інколи можна натрапити на таку, що сяє яскраво-червоним.",
    ["This creature was once a normal beaver, but was struck by lightning, a stormwing drake's breath, and a rock all at the same time."] = "Колись це створіння було звичайним бобром, та водночас його вдарили блискавка, подих штормокрилого дрейка й камінь.",
    ["This creature's existence strongly implies the existence of other, more advanced tickle-based aurelids out there."] = "Саме існування цього створіння наполегливо натякає на існування десь інших, досконаліших аурелід на основі лоскоту.",
    ["This creepy eye is looking at everyone, always, and only has to blink once every 10,000 years."] = "Це моторошне око дивиться на всіх, завжди, і мусить кліпати лише раз на 10 000 років.",
    ["This critter is infamous for its ability to unleash a fast and furious eyeball jabbing."] = "Це створіння сумнозвісне здатністю влаштовувати швидке й несамовите штрикання в очі.",
    ["This cub shares many traits with its relatives, but it's in a league of its own with its singing ability."] = "Це малятко має багато спільного зі своїми родичами, але у вмінні співати воно поза конкуренцією.",
    ["This cunning species tunnels beneath Uldum and erupts from the ground to ensnare its prey."] = "Цей підступний вид риє тунелі під Ульдумом і виривається з-під землі, щоб упіймати здобич.",
    ["This curious kitten has been hanging around one too many ritual sites."] = "Це допитливе кошеня вешталося надто близько до місць ритуалів.",
    ["This curious moth is sometimes found interrupting the spells of a wandering mage or warlock."] = "Цей допитливий метелик часом перебиває закляття мандрівного мага чи чорнокнижника.",
    ["This dark-feathered bird of prey is often seen as a harbinger of doom amongst the druids of Teldrassil."] = "Цього темнопірого хижого птаха друїди Тельдрасілу часто вважають провісником лиха.",
    ["This dark-shelled monster thrives in shadows. It's where he does all his best thinking."] = "Цей темнопанцирний монстр процвітає в тінях. Саме там йому найкраще думається.",
    ["This delicate insect's wings are often sewn into clothing and armor."] = "Тендітні крила цієї комахи часто вшивають у одяг та обладунки.",
    ["This dredwing is the most common of the dredbats, seen throughout the entire realm."] = "Це жахокрило — найпоширеніший серед жахокажанів, його можна побачити по всьому королівству.",
    ["This eagle was a favored companion of Kinduru's during his travels through Zul'Aman."] = "Цей орел був улюбленим супутником Кіндуру під час його мандрів Зул'Аманом.",
    ["This energetic kitten changes colors depending on its mood."] = "Це енергійне кошеня змінює колір залежно від настрою.",
    ["This exceptionally loud lapbug's calls were enough to throw the already destabilized elements in the local area into complete disarray. Now it's your turn to get bugged."] = "Вереск цього надзвичайно гучного колінцежука виявився достатнім, щоб остаточно розладнати й без того хитку рівновагу стихій у цій місцевості. Тепер твоя черга мати клопіт.",
    ["This extremely rare species of mana wyrm is prized for its unique coloration and even temperament."] = "Цей надзвичайно рідкісний вид мана-вірма цінують за неповторне забарвлення та врівноважену вдачу.",
    ["This eye has witnessed untold horrors, and these fangs may be responsible for a few of their own."] = "Це око бачило незліченні жахіття, а ці ікла, можливо, причетні до кількох власних.",
    ["This ferocious feline followed the fel forces into Azeroth during the Legion's return."] = "Цей лютий котяра пішов слідом за скверними силами в Азерот під час повернення Легіону.",
    ["This ferocious skunk can spray an attacker from thirty yards away, temporarily blinding them.  Handle with caution!"] = "Цей лютий скунс може оббризкати нападника з тридцяти ярдів, тимчасово засліпивши його. Поводьтеся обережно!",
    ["This fish doesn't seem to respond to your commands at all, or notice that you're there, really."] = "Здається, ця риба геть не реагує на твої команди — та й узагалі не помічає, що ти поруч.",
    ["This foreboding creature stalks the night skies of the Eastern Plaguelands, feeding on carrion."] = "Ця лиховісна істота никає нічними небесами Східних Чумних земель, живлячись падлом.",
    ["This frillfish is a no-frills kind of frillfish."] = "Ця рибка-оборка геть без жодних оборок.",
    ["This frog's peculiar red color appears to have evolved specifically for camouflage in blood. Spooky."] = "Дивний червоний колір цієї жаби, схоже, розвинувся саме для маскування в крові. Моторошно.",
    ["This golden pig honors its ancestors by giving its allies good fortune."] = "Це золоте порося вшановує своїх предків, даруючи своїм союзникам удачу.",
    ["This good girl loves nothing more than the feeling of the warm sun on her coat and freshly dug earth between her paws."] = "Ця добра дівчинка над усе любить відчуття теплого сонця на своїй шерсті та свіжовикопаної землі між лапами.",
    ["This grumpy species of basilisk roams the Blade's Edge Mountains, avoiding contact with other critters whenever possible."] = "Цей буркотливий вид василісків блукає Горами Леза Гостряка, уникаючи зустрічей з іншими створіннями, коли тільки можна.",
    ["This hallowed firefly's glow scours the darkness, a welcome omen for the Arathi living in Hallowfall."] = "Сяйво цього священного світлячка розганяє темряву — добрий знак для аратійців, що живуть у Голловфолі.",
    ["This handsome little robot is the spitting image of his \"Dad\", Blingtron 4000.  As a Blingtron's generosity circuits don't mature until they have been built to maximum specification, you shouldn't expect any free handouts from him."] = "Цей гарненький малий робот — викапаний «татко», Блінґтрон 4000. Оскільки схеми щедрості Блінґтрона дозрівають лише тоді, коли його зібрано за максимальними характеристиками, безкоштовних подарунків від нього годі чекати.",
    ["This hatchling has an unusual sense that allows it to detect and follow along with alpha predators."] = "Це пташеня має незвичайне чуття, що дозволяє йому виявляти альфа-хижаків і триматися їх.",
    ["This hatchling is coveted for its unique coloration. Despite Breanni's loving care, the raptor's feral nature cannot be restrained."] = "Це маля жадане за свій унікальний окрас. Попри турботливий догляд Бреанні, дику натуру раптора годі приборкати.",
    ["This horrific, flesh-eating plant promises it can make all of your wildest wishes come true. If you feed it."] = "Ця жахлива хижа рослина обіцяє здійснити всі твої найшаленіші бажання. Якщо ти її нагодуєш.",
    ["This ill-tempered snake species makes its home around the fiery molten pits of the Burning Steppes."] = "Цей сварливий вид змій оселяється довкола вогняних розплавлених ям Полум'яних Степів.",
    ["This is a huge toad."] = "Це величезна ропуха.",
    ["This is a small frog."] = "Це маленька жаба.",
    ["This is actually three pets in one. You won't know what you'll get until you summon it!"] = "Насправді це три улюбленці в одному. Ти не дізнаєшся, що отримаєш, доки не прикличеш його!",
    ["This is not your grandfather's duck! Or.. maybe it is?"] = "Це не качка твого дідуся! Чи... все-таки вона?",
    ["This is the most pettable pointy creature you will ever meet."] = "Це найгладибельніше колюче створіння, яке ти коли-небудь зустрінеш.",
    ["This is the soul of a forest fire. Though its armor keeps its flames under control, you sometimes notice it gazing longingly at dead trees and dry underbrush."] = "Це душа лісової пожежі. Хоч обладунок і тримає її полум'я під контролем, ви іноді помічаєте, як вона тужливо задивляється на мертві дерева та сухий чагарник.",
    ["This is the terror that flaps o'er the Dragon Isles. This is the winged nightmare that pecks at your emerald dreams. What? No it's not Deathwing, it's a duck!"] = "Це жах, що лопотить крилами над Драконовими Островами. Це крилатий кошмар, що дзьобає твої смарагдові сни. Що? Ні, це не Дезвінг, це качка!",
    ["This is what happens when you try to one-up Pip Quickwit's tall tales of being stuck inside of dangerous creatures."] = "Ось що трапляється, коли намагаєшся переплюнути небилиці Піпа Кмітливця про те, як він застрягав усередині небезпечних створінь.",
    ["This isn't the real Pocopoc, but it provided this replica to you for use outside Zereth Mortis. Its details are so accurate as to be utterly convincing to anyone who hasn't spent lots of time with the real one."] = "Це не справжній Покопок, але він дав тобі цю репліку для використання поза Зерет Мортісом. Її деталі такі точні, що ошукають кожного, хто не провів багато часу зі справжнім.",
    ["This krolusk seems to display an unusual level of intellegence in it's shiny red, reflective eyes."] = "Цей кролуск, схоже, виявляє незвичайний рівень інтелекту у своїх блискучих червоних, відбивних очах.",
    ["This lasher does not come from a black lagoon, or from the stars, or from beyond the moon. It just wants you to feed it."] = "Цей батіжник прийшов не з чорної лагуни, не із зірок і не з-поза місяця. Він просто хоче, щоб ти його нагодував.",
    ["This little cloud serpent's favorite activity is chasing its own tail."] = "Улюблена забавка цього маленького хмарного змія — ганятися за власним хвостом.",
    ["This little dragon is all fired up! It looks like he's got some things to do."] = "Це драконеня просто палає завзяттям! Схоже, у нього є важливі справи.",
    ["This little guy grows an additional eye somewhere on its body every year. It rhymes with..."] = "У цього малюка щороку виростає ще одне око десь на тілі. Римується з…",
    ["This little guy has had a rough start at life, be sure to take good care of him."] = "Цьому малому випав важкий початок життя, тож неодмінно добре про нього дбай.",
    ["This little guy seems to like to hang out at the fringes of cataclysmic events. There is no evidence to suggest he has anything to do with the cause of these events, though - he's probably just an observer. Or maybe he just gets lost on his trek to other places."] = "Цей малюк, схоже, полюбляє вештатися на околицях катаклізмічних подій. Втім, немає жодних доказів, що він якось причетний до їхньої причини — мабуть, він просто спостерігач. А може, він просто загубився дорогою деінде.",
    ["This little guy was exiled and cursed by other watchers of Uldum to spend the rest of its time as a tiny insignificant being."] = "Цього малюка вигнали й прокляли інші вартові Ульдума, прирікши його провести решту віку дрібним нікчемним створінням.",
    ["This little octopode squirts slime out instead of ink."] = "Це маленьке восьминоженя бризкає слизом замість чорнила.",
    ["This little one likes cheese, but most fawn do."] = "Цьому малюку до вподоби сир, як і більшості оленят.",
    ["This little piece of summer smells of warm evenings and lightning storms. If you look closely, you might be able to make out a face."] = "Цей маленький шматочок літа пахне теплими вечорами й грозами. Якщо придивитися, можна навіть розгледіти обличчя.",
    ["This little rabbit is cute from the tip of her button nose to the tips of her deadly claws."] = "Це кроленятко миле від кінчика свого носика-ґудзика до кінчиків своїх смертоносних кігтів.",
    ["This little racing enthusiast has never missed a race and has never met a racer she didn't like."] = "Ця маленька шанувальниця перегонів ніколи не пропускала жодного забігу й ніколи не зустрічала гонщика, який би їй не сподобався.",
    ["This little thorntail just loves to get into scraps and scrapes with its greatest foe: lapbugs."] = "Цей малий колючохвіст просто обожнює сваритися й битися зі своїм найбільшим ворогом: колінцежуками.",
    ["This little yak is far snugglier than most of it's kin. And slightly less smelly!"] = "Цей маленький як набагато тулькіший за більшість своїх родичів. І трохи менше смердить!",
    ["This magical kitty has so much energy that she will sometimes zip around for no reason whatsoever."] = "У цього магічного котика стільки енергії, що він часом ганяє туди-сюди без жодної причини.",
    ["This magical scout can often be found rummaging for arcane treats  in the refuse of long-past adventurers."] = "Цього магічного розвідника часто можна побачити, коли він порпається в покидьках давно зниклих шукачів пригод у пошуках тайних ласощів.",
    ["This marmot has been with you this entire time. He's that good."] = "Цей бабак увесь цей час був поруч із тобою. Ось який він спритний.",
    ["This massive weapon of destruction has been miniaturized for use in the garden.  Moles beware!"] = "Цю масивну зброю руйнування зменшили для використання в саду. Кроти, начувайтеся!",
    ["This mechanical warrior is a favorite gift during Winter Veil. Batteries not included, but rockets definitely are!"] = "Цей механічний воїн — улюблений подарунок на Зимову Заметіль. Батарейки не додаються, зате ракети — авжеж!",
    ["This mischievous gourd likes to pop out of the ground and scare you right out of your pants. Hail to the pumpkin song!"] = "Цей пустотливий гарбуз полюбляє вистрибувати з-під землі й лякати так, що аж жижки трусяться. Слава гарбузовій пісні!",
    ["This model of raptors is produced in the Blade's Edge Mountains.  Their robotic roars are a common sound near Toshley Station."] = "Цю модель раптора виготовляють у Горах Леза. Їхній механічний рик — звична річ біля Станції Тошлі.",
    ["This new arrival to Azeroth was spawned a short time ago. It seeks to thrive while awaiting its next phase of evolution."] = "Цей новоприбулець до Азероту з'явився на світ зовсім нещодавно. Він прагне набратися сил, очікуючи наступної стадії свого розвитку.",
    ["This offspring of Takk the Leaper is incredibly agile and can maneuver through difficult environments with ease."] = "Це нащадок Такка Стрибуна, неймовірно спритний, що з легкістю долає найскладнішу місцевість.",
    ["This one may lack the size and color of it's famed cousin, but it can still pack a punch."] = "Цьому, може, бракує розміру й кольору його уславленого родича, але він усе одно вміє дати чосу.",
    ["This ooze leaves behind a slimy trail as it moves that has a stench that would rival a beast rotting in the dunes of Uldum for a thousand years."] = "Цей слиз лишає за собою липкий слід, сморід якого позмагається з тушею звіра, що тисячу років гнила в дюнах Ульдума.",
    ["This particular drake has oddly retained its age throughout its travels, but its size has certainly changed."] = "Цей дрейк дивним чином зберіг свій вік за всі свої мандри, проте його розмір неабияк змінився.",
    ["This particular tiny tree is infested with strange spores and doesn't seem to mind."] = "Це крихітне деревце вражене дивними спорами, та його це, схоже, анітрохи не турбує.",
    ["This pet has tremendous airborne agility and will always land on its feet, even when flung by a home-made spring-loaded leaper-flinger."] = "Цей улюбленець напрочуд спритний у повітрі й завжди приземляється на лапи — навіть коли його запускає саморобна пружинна стрибкометалка.",
    ["This piglet avoided being turned into sausage at the hands of Roland with the help of a cunning spider."] = "Це порося уникло долі стати ковбасою в руках Роланда завдяки хитрому павукові.",
    ["This pile of animated sand is fun to squish between your fingers, but doesn't really like it when you do that."] = "Цю купку оживленого піску весело розминати між пальцями, та йому не дуже подобається, коли ти так робиш.",
    ["This pint-sized panda cub is highly sought after by adventurers around Azeroth - despite its narcoleptic nature."] = "Це крихітне панденя дуже бажане для шукачів пригод по всьому Азероту — попри свою схильність до нарколепсії.",
    ["This plump red caterpillar is world-renowned for creating the finest silk in Azeroth."] = "Ця пухка червона гусінь славиться на весь світ тим, що створює найтонший шовк Азероту.",
    ["This pocket-sized Lord of Blackrock is too small to call out any classes, but he can still dish up a good insult."] = "Цей кишеньковий Володар Блекроку замалий, щоб чіпляти якісь класи, та все одно вправно сипле дошкульними образами.",
    ["This potadpole is constantly getting stuck in things."] = "Це картолатча постійно десь застрягає.",
    ["This potadpole is grateful for your assistance after having been exposed to the Lightboom."] = "Це картолатча вдячне тобі за допомогу після того, як зазнало впливу Світоспалаху.",
    ["This proto-whelp's distinctive coloration is highly prized by pet trainers."] = "Прикметне забарвлення цього протодраконеняти високо цінують тренери улюбленців.",
    ["This pup is now more than just a bundle of fur and teeth, it is fur, teeth and void."] = "Це цуценя тепер не просто клубок шерсті й зубів — це шерсть, зуби і Порожнеча.",
    ["This rabbit is much stronger than it looks."] = "Цей кролик набагато сильніший, ніж видається.",
    ["This rare bear is bred for its small size and perpetually youthful appearance."] = "Цього рідкісного ведмедя виводять заради малого розміру й вічно юного вигляду.",
    ["This red-nosed bunny is incredibly soft to the touch; just watch your fingers."] = "Цей червононосий кролик неймовірно м'який на дотик — тільки бережи пальці.",
    ["This salamanther wants to be your best friend."] = "Ця саламандра хоче стати твоїм найкращим другом.",
    ["This scarabid's brightly colored shell makes it more interesting to potential mates. Unfortunately, this also makes them interesting to potential predators."] = "Яскравий панцир цього скарабіда робить його привабливішим для потенційної пари. На жаль, це робить його привабливим і для потенційних хижаків.",
    ["This serpent seems used to being at your side, it may have been the companion of one of the other druids of the fang."] = "Цей змій ніби звик бути поряд із кимось — можливо, він був супутником одного з друїдів Ікла.",
    ["This shelled reptile bravely protects the home on its back with an unwaveringly happy disposition."] = "Ця панцирна рептилія хоробро боронить домівку на власній спині, не втрачаючи незмінно радісної вдачі.",
    ["This silithid battle tank evolved prematurely. It will never reach full size, but it is just as ferocious as its larger cousins."] = "Цей бойовий танк-силітид розвинувся передчасно. Він ніколи не досягне повного розміру, проте лютий не менше за своїх більших родичів.",
    ["This slime has a long and confusing lineage."] = "Цей слиз має довгий і заплутаний родовід.",
    ["This slime seems to change color the more you look at it, and then suddenly, it appears to be looking back at you. Perhaps it is time for a rest."] = "Здається, що ця слизь міняє колір тим більше, чим довше на неї дивишся, а тоді раптом — вона ніби дивиться у відповідь на тебе. Мабуть, настав час відпочити.",
    ["This small cub has been influenced by constant storms on Siren Isle. Just petting it's soft fur sends static shocks across your hand."] = "На це маленьке дитинча вплинули постійні шторми на Острові Сирен. Досить лише погладити його м'яку шерсть, як рукою пробігають іскри статики.",
    ["This small globule didn't make it back to Viscidus in time to re-form."] = "Ця маленька грудка не встигла повернутися до Вісцидуса, щоб знову злитися воєдино.",
    ["This snake is often seen sunning on the exposed rocks high in the Badlands."] = "Цю змію часто можна побачити, як вона гріється на сонці на відкритих скелях високо в Пустищах.",
    ["This snuffling loves limes."] = "Цей нюхач обожнює лайми.",
    ["This snuggly kitten loves to frolic, but sometimes it seems to be chasing things that aren't really there."] = "Це лагідне кошеня обожнює пустувати, але часом здається, ніби воно ганяється за тим, чого насправді немає.",
    ["This species has a very distinct set of markings on its back that makes it easy to identify in the unending horrors of the Maw."] = "Цей вид має на спині дуже виразні візерунки, завдяки яким його легко впізнати серед нескінченних жахіть Пащі.",
    ["This species looks through the sand for the buried remains of rotting creatures. It keeps our beaches clean!"] = "Цей вид нишпорить у піску в пошуках зариваних решток гнилих створінь. Завдяки йому наші пляжі чисті!",
    ["This species of insect is drawn to the latent energy in shrines, their luminescent appearance adding to the mystique of the places of power."] = "Цей вид комах вабиться до прихованої енергії святилищ, а їхнє світіння лише додає таємничості цим місцям сили.",
    ["This sweet flower will brighten your day with its warm smile and cheerful song! Also strong against undead."] = "Ця мила квітка осяє твій день теплою усмішкою і веселою піснею! А ще вона сильна проти нежиті.",
    ["This terrifying and highly venomous species leaps onto its prey from the Jade Forest's dense canopy."] = "Цей жахливий і вкрай отруйний вид кидається на здобич із густого лісового шатра Нефритового лісу.",
    ["This thing is equally as evil as it is adorable."] = "Ця істота настільки ж лиха, наскільки й чарівна.",
    ["This tiny breed of dragonhawk is popular for those who prefer to keep their companions travel sized. Just keep them away from curtains."] = "Ця крихітна порода драконосокола популярна серед тих, хто воліє тримати своїх супутників дорожнього розміру. Тільки тримай їх подалі від штор.",
    ["This tiny peacekeeper security bot is often outfitted with the latest arcane nullifiers and crowd pummelers. Not for the environmentally minded."] = "Цей крихітний бот-охоронець-миротворець часто обладнаний найновішими нейтралізаторами таємних сил і розганячами натовпу. Не для прихильників екології.",
    ["This tiny robot specializes in drilling, clamping, and shooting lightning out of its brain. A typical gnome invention."] = "Цей крихітний робот спеціалізується на свердлінні, затисканні та метанні блискавок просто зі свого мозку. Типовий гномський винахід.",
    ["This tiny squid seems to enjoy wearing pants, but where in the world would you find some that fit?"] = "Цей крихітний кальмар, схоже, любить носити штани, та де ж у світі знайти такі, що йому пасуватимуть?",
    ["This tiny tormentor of Torghast relishes in punishing any soul in the tower that can't step on it."] = "Цей крихітний мучитель Торгасту смакує покаранням будь-якої душі у вежі, що не здатна на нього наступити.",
    ["This treasured lynx is a firm supporter of no changes."] = "Ця дорогоцінна рись — переконана прихильниця незмінності.",
    ["This turtle eats bugs, as you'd expect from its name, but you wouldn't believe how large the bugs are."] = "Ця черепаха їсть комах, як і випливає з її назви, але ви не повірите, які ті комахи завбільшки.",
    ["This type of beetle feeds on dragon scales. Its bright coloration warns predators against attack."] = "Цей різновид жука живиться драконячою лускою. Його яскраве забарвлення застерігає хижаків від нападу.",
    ["This unique raptor was born on the island of Zandalar and transported here along with the rest of the Zandalari army."] = "Цей унікальний раптор народився на острові Зандалар і був перевезений сюди разом із рештою війська зандаларі.",
    ["This unique species of faerie dragon is not usually found on Azeroth."] = "Цей унікальний вид чарівного дракона зазвичай не трапляється в Азероті.",
    ["This upper class parrot is only for the most distinguished of sailors."] = "Цей вельможний папуга призначений лише для найвидатніших мореплавців.",
    ["This very elusive creature likes to hide in places where many adventurers don't frequently travel."] = "Це вкрай невловиме створіння полюбляє ховатися там, куди багато мандрівників навідується нечасто.",
    ["This vicious species weaves elaborate webs throughout the dense jungles of Stranglethorn Vale."] = "Цей лютий вид плете вигадливі тенета по всіх густих джунглях Тернистого Долу.",
    ["This watcher's ennui is as eternal as the struggle between the Light and the Void."] = "Нудьга цього споглядача така ж вічна, як боротьба між Світлом і Порожнечею.",
    ["This what your mother always warned you would happen if you ate grass that was struck by lightning."] = "Ось що, як завжди застерігала твоя мати, станеться, якщо з'їси траву, у яку вдарила блискавка.",
    ["This wyrm can't wait to grow up big and strong so it can hunt Prey too!"] = "Цей вірм не може дочекатися, коли виросте великим і сильним, щоб теж полювати на здобич!",
    ["This young crawgling was rescued from a vicious blood troll war camp. With care, and lots of feeding, you earned his trust and Krag'wa asked you to take care of him always."] = "Це юне крогеня врятували з лютого воєнного табору кров'яних тролів. Турботою та рясною годівлею ти здобув його довіру, і Краг'ва попросив тебе завжди про нього дбати.",
    ["This young fledgeling is ready and eager to begin training."] = "Це молоде пташеня готове й прагне почати тренування.",
    ["This young stalker was easily swayed from Sargeras' grasp by a handful of Magical Mini-Treats."] = "Цього молодого скрадайла легко відвернула від хватки Саргераса жменя магічних міні-ласощів.",
    ["This, um, 'adorable' little guy likes to play with critters. Just don't let them get too close."] = "Це, гм, «чарівне» мале створіння любить бавитися з дрібнотою. Тільки не підпускай їх надто близько.",
    ["Thorg No-Legs never paid heed to the old orc saying, 'Don't pull a wyvern's tail.'"] = "Торг Безногий ніколи не зважав на стару орчу примовку: «Не тягни віверну за хвіст».",
    ["Though barely a hatchling, its claws are already sharp enough to pierce the flesh of many smaller critters."] = "Хоч це ледь не пташеня, його пазурі вже досить гострі, щоб протнути плоть багатьох дрібніших звіряток.",
    ["Though eye-catching, their namesake coloration is rubbish for camouflage. The blind skiplings couldn't care less."] = "Хоч і впадає в око, барва, від якої вони дістали назву, геть не годиться для маскування. Сліпим стрибунцям до цього байдуже.",
    ["Though fully-grown maidenbugs are able to fly, Nelle is just a bit too young for that. She's happy to skitter alongside you all the same."] = "Хоч дорослі дівожуки й уміють літати, Нелл іще трохи замолода для цього. Та вона все одно радо дріботить поруч із вами.",
    ["Though generally an expert at taking stage direction, the show had to be stopped on more than one occasion when Tito and Roar would lock eyes, resulting in an extended chase around the Karazhan Opera House."] = "Хоч він загалом і знавець сценічних вказівок, виставу не раз доводилося спиняти, коли погляди Тіто й Рикуна зустрічалися, що оберталося тривалою гонитвою всім Оперним Театром Каражана.",
    ["Though it appears to be a vaguely-related cousin to the Cinder Kitten, the two creatures actually share no ancestry."] = "Хоч воно й видається віддаленим родичем жаринкового кошеняти, насправді ці двоє створінь не мають спільних предків.",
    ["Though it's rare, thunder lizards have been known to bond with centaurs. And their close allies. Lucky you!"] = "Хоч це й рідкість, відомо, що громоящери прив'язуються до кентаврів. І до їхніх близьких союзників. Тобі пощастило!",
    ["Though left behind on the Siren Isle, this old but very good boy proves that some things only get better with age."] = "Хоч його й покинули на Острові Сирен, цей старий, але дуже добрий хлопчина доводить, що дещо з віком тільки кращає.",
    ["Though many creatures of the Dragon Isles are mysterious, the ducks are perhaps the most so. Where did they come from? Where are they going? What are they planning? We may never know."] = "Хоч багато створінь Драконових Островів і загадкові, качки, мабуть, найзагадковіші з усіх. Звідки вони взялися? Куди прямують? Що замислюють? Ми, можливо, ніколи не дізнаємося.",
    ["Though not real rats, they have taken over the back alleys of Mechagon City and carry diseased programs, earning them the name."] = "Хоч це й не справжні щури, вони захопили завулки Мехаґона й переносять заражені програми, чим і заслужили свою назву.",
    ["Though not very fuzzy, this slimy feline is still one of the most adorable things you've ever seen."] = "Хоч і не надто пухнастий, цей слизький котик усе ж лишається одним із найчарівніших створінь, які ви тільки бачили.",
    ["Though she may be fashionably late, Lady Feathersworth will always show up for a party."] = "Хоч леді Перодостойна й приходить модно запізно, вона ніколи не пропустить вечірки.",
    ["Though the spawn of a gorm queen lost within the Maw, this pet appears to be untainted by the Jailer's foul magics."] = "Хоч цей улюбленець і є виплодком ґорм-королеви, загубленої в Пащі, його, схоже, не торкнулася ница магія Тюремника.",
    ["Though their light is sometimes mistaken for the glow of toxic substances or dark magic, nerubians and Arathi alike find these insects hauntingly beautiful."] = "Хоч їхнє світло іноді плутають із сяйвом токсичних речовин чи темної магії, нерубіани й аратійці однаково вважають цих комах моторошно прекрасними.",
    ["Though they are quite squishy while young, the bloodlouse will eventually grow hardened plates around its entire body."] = "Замолоду кровоблоха доволі м'яка, та згодом усе її тіло вкривається твердими пластинами.",
    ["Though they may look fierce, the bloodgazer species of falcosaur has a beak that makes it predisposed to consuming fruits."] = "Хоч вони й мають лютий вигляд, дзьоб фалькозаврів-кровозорів пристосований радше до поїдання плодів.",
    ["Though this little one's flight training has yet to be completed, their playfulness and enthusiasm are already fully grown."] = "Хоча навчання польоту цього малюка ще не завершене, його грайливість і завзяття вже цілком дорослі.",
    ["Thought by many to be nothing more than the subject of children's nursery rhymes, the long-tailed mole is very much real."] = "Багато хто вважає, ніби довгохвостий кріт існує лише в дитячих віршиках, та насправді він цілком реальний.",
    ["Thought to be an original construct of the titans, the clockwork gnome has some gears smaller than the eye can see."] = "Вважається первісним витвором титанів; у механічного ґнома є шестерні дрібніші, ніж може розгледіти око.",
    ["Thought to be lost in a massive explosion, the smartest of engineers were able to rebuild Feathers into a magnificent mechanical creation."] = "Вважалося, що Пір'їнка загинула в потужному вибуху, та найкмітливіші інженери змогли відбудувати її в розкішне механічне творіння.",
    ["Thousands of these skittering nightmares swarm underneath Northrend to this day."] = "Тисячі цих дрібних кошмарів і донині кишать у надрах Нортренду.",
    ["Thousands of years ago, ten magisters were exiled from Highborne society for seeking power in the corrupting darkness. In the wilds, they found hunger, desperation, and Kosumoth."] = "Тисячі років тому десятьох магістрів вигнали з товариства Високородних за те, що ті шукали могутності у спокусливій темряві. У глушині вони знайшли голод, відчай і Косумота.",
    ["Three legs, two arms, three eyeballs, the extras are for emergency situations only."] = "Три ноги, дві руки, три ока — зайві лише на крайній випадок.",
    ["Three parts planning, one part danger, one part noodle."] = "Три частини розрахунку, одна частина небезпеки, одна частина локшини.",
    ["Three years ago this swoglet was a fully grown adult."] = "Три роки тому цей своґлет був цілком дорослим.",
    ["Through experimentation, the mages of Dalaran have discovered that the powered remains of a crimson shale spider will greatly increase the conflagration of their fire spells."] = "Шляхом дослідів маги Даларану виявили, що порошок із решток багряного сланцевого павука значно посилює полум'я їхніх вогняних заклять.",
    ["Thrrrdgl is content with not being a top choice or even a second choice.  Thrrrdgl believes that first and second are the worst and third is the best."] = "Тррркл задоволений тим, що він не перший вибір і навіть не другий. Тррркл переконаний, що перше й друге місце — найгірші, а третє — найкраще.",
    ["Tiny Torq's dad could TOTALLY beat up Flarendo's dad."] = "Тато Малого Торка точно міг би відлупцювати тата Фларендо.",
    ["Tiny flakes of skin seem to perpetually fall off of this horrible creature, leaving behind a trail and a very distinct, foul odor."] = "З цього жахливого створіння, схоже, безперестанку обсипаються дрібні лусочки шкіри, лишаючи по собі слід і вельми виразний, гидотний сморід.",
    ["Tiny, autonomous machines created by the Titans to clean and maintain their mighty edifices."] = "Крихітні самостійні машини, створені Титанами, щоб прибирати й доглядати їхні величні споруди.",
    ["Tiny, incinerated corpses of various insects line its cage."] = "Підлогу його клітки встеляють крихітні спопелілі тільця різних комах.",
    ["To its foes, this Watcher's innocent eyes belie the lethal danger of a prowling Huntress, waiting in the shadows."] = "Для ворогів невинні очі цієї Спостерігачки приховують смертельну небезпеку Мисливиці, що скрадається й чигає в тінях.",
    ["To prevent apprentices from secretly using the familiar to complete their chores, the archmagi placed the ritual required to summon the creature across the pages of several spellbooks hidden throughout Dalaran."] = "Щоб учні нишком не послуговувалися цим фамільяром для виконання своїх обов'язків, архімаги розпорошили ритуал його прикликання сторінками кількох книг заклять, схованих по всьому Даларану.",
    ["To some, this fish speaks eloquently of its survival in the most arduous conditions. To most, it says 'glub.'"] = "Для декого ця риба красномовно розповідає про своє виживання в найважчих умовах. Для більшості вона каже «глюб».",
    ["Tock the Clocker Spaniel is one of the best watch dogs you can ask for."] = "Цок, годинниковий спанієль, — один з найкращих сторожових псів, про яких можна тільки мріяти.",
    ["Tolai hare pups are sent from their dens at a young age to find their own way."] = "Зайченят толай ще змалечку виганяють із нір, щоб вони шукали власну дорогу.",
    ["Too afraid to attempt flying until thrown from a great height."] = "Надто боїться навіть спробувати полетіти, доки його не скинуть з великої висоти.",
    ["Torghast is a tower of hardship and perpetual agony, which is a perfect environment for these creatures."] = "Торгаст — це вежа знегод і вічної агонії, а отже, ідеальне середовище для цих створінь.",
    ["Totally gonna transform into a beautiful winged creature, yup. It just might take a few dozen years."] = "Точно перетвориться на прекрасну крилату істоту, ага. Просто на це може піти кілька десятків років.",
    ["Tottle's one wish is to explore the world at your side!"] = "Єдине бажання Тоттла — досліджувати світ поруч із тобою!",
    ["Touched by lightning, these dangerous rodents should be kept at a safe distance."] = "Зачеплених блискавкою, цих небезпечних гризунів краще тримати на безпечній відстані.",
    ["Tough burrowing claws make it easy for arachnids to get around subterranean areas. But it's a boring life."] = "Міцні рийні пазурі дозволяють павукоподібним легко пересуватися підземними просторами. Але це нудне життя.",
    ["Toxic spores rain down wherever these creatures fly, turning small, unwary critters into a gruesome feast."] = "Куди б не летіли ці створіння, звідти дощем сиплються отруйні спори, перетворюючи дрібних необачних звіряток на моторошний бенкет.",
    ["Trade Prince Gallywix wants you to know that he already owns three of these."] = "Торговий принц Ґаллівікс хоче, щоб ви знали: у нього вже є три таких.",
    ["Trapped in a chest and forgotten for years, this stone fiend is mad and looking for a fight."] = "Замкнений у скрині й забутий на роки, цей кам'яний поплічник аж шаленіє від люті й шукає бійки.",
    ["True royalty among Corgis."] = "Справжня королівська особа серед коргі.",
    ["Truly evil, undeniably powerful... but above all, spectacularly lazy."] = "Воістину лихий, безперечно могутній... але понад усе — на диво лінивий.",
    ["Truly, the most dignified of stinky musken."] = "Воістину, найдостойніший зі смердючих мускенів.",
    ["Trying to live up to her ancestry, this little one is ready to rampage. She is going to start with small spiders and work up from there."] = "Прагнучи бути гідною своїх предків, ця малеча готова до буйства. Вона почне з малих павуків, а далі візьметься за більше.",
    ["Tundra penguins often gather in large groups on the ice for protection against aquatic threats. Unfortunately this makes them easy prey for humanoid hunters seeking meat, skins and other achievements."] = "Тундрові пінгвіни часто збираються великими зграями на кризі, щоб захиститися від водяних загроз. На жаль, це робить їх легкою здобиччю для гуманоїдних мисливців, які шукають м'ясо, шкури та інші досягнення.",
    ["Turtles are feared by the naga, who consider them bad luck and give them a wide berth on the shores of Azshara."] = "Наги бояться черепах, вважають їх лихою прикметою й обходять десятою дорогою на берегах Азшари.",
    ["Twisted by the Twilight Hammer's dark magic, these sinister critters are known to feed on their own young."] = "Спотворені темною магією Сутінкового Молота, ці лиховісні дрібнятка, як відомо, пожирають власних дитинчат.",
    ["Twisters delight in sneaking up on unsuspecting creatures and surprising them with gusts up their nostrils."] = "Вихори тішаться, підкрадаючись до безтурботних створінь і захоплюючи їх зненацька поривами вітру просто в ніздрі.",
    ["Two parts fortress, one part eyestalks, one part slime."] = "Дві частини фортеці, одна частина очей на стеблинках, одна частина слизу.",
    ["Two parts wings, one part beak, two parts talon, one part smugness."] = "Дві частини крил, одна частина дзьоба, дві частини пазурів, одна частина самовдоволення.",
    ["Two parts wings, one part dagger, five parts sadism."] = "Дві частини крил, одна частина кинджала, п'ять частин садизму.",
    ["Undead squirrels have acquired a taste for the strange berries and mushrooms that now grow in Silverpine Forest."] = "Нежиттєві білки призвичаїлися до смаку дивних ягід і грибів, що нині ростуть у Срібнососновому Лісі.",
    ["Under the invitation and tutelage of Doc Nanners many Gray Marmoni have become common, but not always desired guests at the Dragonscale Expedition Basecamp."] = "За запрошенням і опікою Дока Нанерса багато сірих Мармоні стали звичними, хоч і не завжди бажаними гостями в Базовому Таборі Експедиції Драконолуски.",
    ["Undermoths are known to be some of the most intelligent moths on Azeroth. This is not saying much."] = "Тіньомолі відомі як одні з найрозумніших молей Азерота. Хоча це мало про що говорить.",
    ["Unfortunately, it's not a duck."] = "На жаль, це не качка.",
    ["Unique carapace is prized by trinket makers for its texture and strength."] = "Унікальний панцир цінується майстрами дрібничок за свою текстуру й міцність.",
    ["Unkillable dragons, what could go wrong?"] = "Невбивні дракони — що тут може піти не так?",
    ["Unlike its gold counterpart, the blue mini jouster takes a leisurely pace when jabbing its opponent's eyeballs."] = "На відміну від золотого побратима, синій міні-турнірник не поспішає, коли штрикає супротивника в очі.",
    ["Unlike most Voidwalkers in the Voidstorm, Silento prefers the peace and quiet of silence. Even if that means silencing the more chatty of his kin."] = "На відміну від більшості порожнехідців у Войдштормі, Сіленто полюбляє мир і спокій тиші. Навіть якщо для цього доводиться змушувати замовкнути балакучіших родичів.",
    ["Unlike most of Geen the gorloc's 'mysterious eggs,' this one actually contained a living thing."] = "На відміну від більшості «таємничих яєць» Ґіна-ґорлока, у цьому й справді була жива істота.",
    ["Unlike most other bat species, the crimson bats are actually blind and rely entirely on echolocation to get around."] = "На відміну від більшості інших видів кажанів, багряні кажани насправді сліпі й покладаються в орієнтуванні цілковито на ехолокацію.",
    ["Unlike most spiders that drain all the fluids from their prey, the bloodfeaster has developed a taste for blood alone."] = "На відміну від більшості павуків, що висмоктують зі здобичі всі рідини, кровожер уподобав саму лише кров.",
    ["Unlike other snakes that actively hunt, these crafty reptiles hide in thick foliage and ambush their prey."] = "На відміну від інших змій, що активно полюють, ці хитрі плазуни ховаються в густому листі й влаштовують засідки на здобич.",
    ["Unlike other wyrms, blood wyrms drain their foes rather than consuming them whole."] = "На відміну від інших вірмів, кров'яні вірми висмоктують своїх ворогів, а не пожирають їх цілком.",
    ["Unlike the polymorphed variety, trueborn sheep can be quite scary."] = "На відміну від тих, що з'явилися через поліморфізм, справжні природжені вівці можуть бути доволі страшними.",
    ["Unnoticed but to cats and ratcatchers, when Deathwing descended upon Stormwind all the rats beat a hasty retreat from the city. Only of late have they returned."] = "Непомітно ні для кого, крім котів і щуроловів, коли Дезвінг обрушився на Стормвінд, усі щури спішно покинули місто. Лише нещодавно вони повернулися.",
    ["Untouched by the deviate corruption seeping through the Wailing Caverns."] = "Не торкнута девіантною скверною, що сочиться крізь Печери Стогонів.",
    ["Upon exiting the freezing necropolis of Naxxramas, Mr. Bigglesworth promptly found a warm spot in the sun to take a long nap in."] = "Покинувши крижаний некрополь Наксрамас, пан Бігґлсворт одразу ж знайшов тепле місце на сонці, щоб довго подрімати.",
    ["Upon leaving Netherspace, Malchezaar's Abyssals become strangely distorted by Karazhan's magical protections, rendering them tiny, and much less likely to spontaneously erupt in flames."] = "Полишивши Простір Порожнечі, безодняки Малчезаара дивно спотворюються магічним захистом Каражана, що робить їх крихітними й значно менш схильними самочинно спалахувати полум'ям.",
    ["Used as a training mount for young gnomes, the Mechanopeep has none of the speed but all of the charm of its bigger brothers."] = "Механопищик, якого використовують як навчального їздового для юних ґномів, не має жодної краплі швидкості, зате має всю чарівність своїх старших братів.",
    ["Used both in battle and as pack animals when they're larger, at this size they're only a danger to your ankles."] = "Коли вони більші, їх використовують і в бою, і як в'ючних тварин, але за такого розміру вони небезпечні лише для твоїх щиколоток.",
    ["Uuna was found bound to an Ur'zul, and was released into the Shadowlands, where she wandered in the utter darkness."] = "Уну знайшли прикутою до ур'зула й випустили в Тіньокрай, де вона блукала в цілковитій темряві.",
    ["Val'kyr are considered \"sunborne\" when they are honored in the presence of Odyn."] = "Вал'кір вважають «сонценародженими», коли їх вшановують у присутності Одина.",
    ["Val'kyr are considered \"unborn\" until they vanquish a creature of high nobility."] = "Валькір вважають «ненародженими», доки вони не здолають створіння високого шляхетства.",
    ["Vale Marmots are very quick on their feet and are masters of digging holes for their burrows.  Children like to chase them around and try to bop them on the head when they poke their head out to catch some sunlight."] = "Долинні бабаки дуже прудкі й майстерно риють нори. Діти полюбляють ганятися за ними й намагаються лупнути по голові, коли ті висовуються погрітися на сонці.",
    ["Vale flitter normally have incredibly long lifespans.  That was until people found use for them in pet battles."] = "Долинні пурхальці зазвичай живуть неймовірно довго. Так було, доки люди не знайшли їм застосування в боях улюбленців.",
    ["Vampire bats have been trained as scouts and mounts by the Forsaken of the Undercity and the Amani trolls of Zul'Aman."] = "Кажанів-вампірів привчили служити розвідниками й їздовими тваринами Відступники з Андерсіті та тролі Амані із Зул'Амана.",
    ["Vendors at the Darkmoon Faire offer strange and exotic wonders. They also sell wood frogs."] = "Торговці на Ярмарку Темного Місяця пропонують дивні й екзотичні дива. А ще вони продають лісових жаб.",
    ["Venom capable of killing creatures up to 100 times its own body weight."] = "Отрута, здатна вбивати створіння в сто разів важчі за нього самого.",
    ["Very unhappy. Always goes for the jugular. Kind of cute."] = "Дуже нещасний. Завжди цілить у горло. Десь навіть милий.",
    ["Viperids can sit still for hours, silently awaiting their prey."] = "Віперіди можуть годинами завмирати, безшумно чигаючи на здобич.",
    ["Void magic and giant flying insects, a combination nobody ever asked for. Surprisingly effective!"] = "Магія Порожнечі й велетенські летючі комахи — поєднання, якого ніхто ніколи не просив. На диво дієве!",
    ["Vol'dun Quest"] = "Завдання у Вол'дуні",
    ["Voodoo figurines were often empowered by flasks of mojo, troll sweat, and the flesh of tribal enemies."] = "Вудуйські фігурки часто наповнювали силою за допомогою фіалів моджо, тролячого поту й плоті ворогів племені.",
    ["Vulpin actually have very light-colored skin, but their incredibly thick coats hide any color from showing through."] = "Насправді вульпіни мають дуже світлу шкіру, але їхнє неймовірно густе хутро не дає жодному кольору проступити.",
    ["Waddles around in a constant cloud of spores. Harmless? Hard to say--we're still waiting on the research team... or what's left of them."] = "Перевальцем ходить у постійній хмарі спор. Безпечне? Важко сказати — ми досі чекаємо на дослідницьку групу... чи на те, що від неї лишилося.",
    ["Waddles was rejected by the other cave skippers and fell through the cracks, literally, all the way down to Harandar. He's known to follow around people he finds."] = "Дибуна відкинули інші печерні стрибунці, і він провалився крізь щілини, буквально, аж до самого Гарандару. Відомо, що він ходить слідом за людьми, яких зустрічає.",
    ["Warning: It may root against you."] = "Попередження: воно може пустити коріння проти тебе.",
    ["Warning: Wear gloves and goggles while handling disgusting oozeling. DO NOT WASH. Will stain most armor."] = "Увага: вдягайте рукавиці й окуляри, коли тримаєте гидотного слизнятка. НЕ МИТИ. Заплямує майже будь-який обладунок.",
    ["Watch Skippy swim, and then watch him run. The perfect amphibian. Sorry, frogs."] = "Подивися, як Стрибунчик плаває, а потім — як він бігає. Ідеальна амфібія. Вибачайте, жаби.",
    ["Watch out when it spits."] = "Стережися, коли воно плюється.",
    ["Watch your coin purse."] = "Пильнуй свого гаманця.",
    ["Watch your ears."] = "Бережи вуха.",
    ["Water Skimmers use the tension of water and long, hydrophobic legs to help them walk along the water's surface."] = "Водомірки використовують поверхневий натяг води та довгі водовідштовхувальні ноги, щоб ходити по її поверхні.",
    ["Water spirits are especially mischievous, and are known to frequent the canals of the Stormstout Brewery."] = "Водяні духи особливо пустотливі й відомі тим, що вчащають до каналів Броварні Штормоброду.",
    ["Water striders serve an important role in Jinyu culture, acting as a mount, means of sending communications, and even a family pet."] = "Водомірки відіграють важливу роль у культурі джинью, слугуючи їздовою твариною, засобом передавання звісток і навіть домашнім улюбленцем.",
    ["We don't know much about this species, but we do know this: bats aren't bugs."] = "Ми небагато знаємо про цей вид, та одне відомо напевне: кажани — не комахи.",
    ["We're Crusaders from a fable. We dance whene'er we're able. We do routines and chorus scenes, with footwork impeccable!"] = "Ми хрестоносці з казки старі. Танцюєм ми, як лиш в порі. У нас номери й хорові сцени, а кроки — бездоганні всі!",
    ["Wealthy guilds draw the attention of soldiers willing to carry their standards into battle."] = "Заможні гільдії привертають увагу воїнів, готових нести їхні штандарти в бій.",
    ["Wear gloves with this little guy, he loves to bite!"] = "Удягни рукавиці, граючись із цим малюком, — він обожнює кусатися!",
    ["Web ball! Stone of reality! Web ball! Stone of reality!"] = "Павутинна куля! Камінь реальності! Павутинна куля! Камінь реальності!",
    ["Weechi adores attention and what better way to get attention than wearing a costume? Simply seek out a Pet Grooming Station, near any Trading Post, to customize this sweet, wonderous little buddy."] = "Вічі обожнює увагу, а що краще привертає увагу, ніж костюм? Просто знайди станцію догляду за улюбленцями біля будь-якої торгової застави, щоб прикрасити цього милого, дивовижного малюка.",
    ["Weighed down by all the loot he has plundered. He could share the burden he carries but it turns out he's a little shellfish."] = "Обтяжений усією награбованою здобиччю. Він міг би розділити свій тягар, але виявляється, він трохи жадібний, як той краб.",
    ["What Spruce lacks in speed, she makes up for with sheer stubbornness."] = "Те, чого Ялинці бракує у швидкості, вона надолужує неабиякою впертістю.",
    ["What a happy snapling!"] = "Який же радісний хапунчик!",
    ["What are YOU looking at?!"] = "На що це ТИ дивишся?!",
    ["What are they rebelling against? The real question is what are they NOT rebelling against."] = "Проти чого вони бунтують? Справжнє питання — проти чого вони НЕ бунтують.",
    ["What do you feed a cute little duckling? What? No, not cheese and quackers! Quackers aren't healthy for ducks."] = "Чим годувати миле каченятко? Що? Ні, не сиром і кря-кером! Кря-кери качкам не на користь.",
    ["What else is there to say? Slugs love muck."] = "Що тут іще скажеш? Слимаки люблять багно.",
    ["What horrors these eyes have seen in the tower of Torghast, with their unsleeping, unblinking gaze?"] = "Які ж жахіття бачили ці очі у вежі Торгасту своїм недрімним, незмигним поглядом?",
    ["What it lacks in appendages, it makes up for in positive attitude."] = "Брак кінцівок воно надолужує позитивним ставленням до життя.",
    ["What the deep claims, none can reclaim."] = "Що забрала глибина, того ніхто не поверне.",
    ["What vile subtance is jiggling around inside of this creature?"] = "Що за мерзенна субстанція колихається всередині цього створіння?",
    ["What was once a great enemy is now an adorable friend!"] = "Колишній грізний ворог тепер — чарівний друг!",
    ["What's a little corruption between friends?"] = "Що та дрібка скверни поміж друзями?",
    ["What's that smell?"] = "Що це за запах?",
    ["Whatever the story of his mysterious eyepatch is, he's not talking."] = "Хай яка історія криється за його загадковою пов'язкою на оці, він про неї мовчить.",
    ["Whatever you do, don't ask it to carry a bucket of water. We don't talk about what happened to that area of the Shadowlands."] = "Що б ви не робили, не просіть його нести відро з водою. Про те, що сталося з тією частиною Тіньокраю, ми воліємо не згадувати.",
    ["When Alvin said he wanted to be the best anvil ever, everyone doubted him. If anvils could laugh, he'd be the one laughing now."] = "Коли Елвін сказав, що хоче стати найкращим ковадлом усіх часів, усі засумнівалися. Якби ковадла вміли сміятися, він би зараз сміявся.",
    ["When Cyclarus came to Darkshore, small cyclones appeared all over the place. Some of them dissipated over time, others found their way back to Cyclarus and were absorbed into the surrounding winds."] = "Коли Цикларус прийшов до Даркшору, повсюди з'явилися дрібні циклони. Одні з часом розвіялися, інші знайшли дорогу назад до Цикларуса й розчинилися в навколишніх вітрах.",
    ["When Gluth died to a band of brave adventurers, these lil' guys were found in the corpse, gnawing on giant, undead bones."] = "Коли Ґлут загинув від рук гурту хоробрих шукачів пригод, цих малюків знайшли в трупі — вони гризли велетенські кістки нежиті.",
    ["When Whomper wants to play, he'll let you know with a playful headbutt."] = "Коли Гепкало захоче гратися, він дасть тобі знати грайливим стусаном головою.",
    ["When a full moon is visible, streaks of hair on the dreamfoal's mane start to shimmer and glow like shooting stars."] = "Коли в небі повний місяць, пасма гриви сонного лошати починають мерехтіти й сяяти, наче зорі, що падають.",
    ["When a guild earns enough glory by defeating Alliance champions, some orcs will come to share the glory by serving the guild."] = "Коли гільдія здобуває достатньо слави, долаючи чемпіонів Альянсу, деякі орки приходять розділити цю славу, ставши на службу гільдії.",
    ["When a helsquid has devoured most of the food in any area, it can return to its polyp form and begin life anew."] = "Коли гельський кальмар пожере більшість їжі в якійсь місцевості, він може вернутися до форми поліпа й розпочати життя заново.",
    ["When a ram lowers his head, it means he's preparing to charge. Or he could just be tired."] = "Коли баран опускає голову, це означає, що він готується до наскоку. Або просто втомився.",
    ["When alchemy goes wrong... So, so, wrong."] = "Коли алхімія йде не так... Геть, геть не так.",
    ["When being adored, a Living Rose emits beautifully intoxicating aromas. When ignored, those aromas become actually toxic."] = "Коли її обожнюють, Жива Троянда випускає прекрасно п'янкі аромати. Коли ж її ігнорують, ці аромати стають уже по-справжньому токсичними.",
    ["When confronted, helicids will hide in their heavily armored shells. If provoked further, they will lash out with devastating force."] = "У сутичці геліциди ховаються у свої важко броньовані мушлі. Якщо їх дратувати далі, вони відповідають нищівним ударом.",
    ["When demons, nightmares, and magic collide!"] = "Коли стикаються демони, кошмари й магія!",
    ["When does a hatchling become a fledgling if hawkstriders never fledge?"] = "Коли пташеня стає підлітком, якщо соколостриби ніколи не вкриваються пір'ям?",
    ["When enemy combatants fly overhead, there's only one thing to do. Duck."] = "Коли ворожі бійці пролітають над головою, є лише одне рішення. Пригнутися.",
    ["When forging enchanted steel, bits of magic seep into the coals.  Over a period of years, decades even, the unbound energy slowly takes form, creating a tiny elemental being of immense fortitude."] = "Коли кують зачаровану сталь, дещиця магії просочується у вугілля. Роками, а то й десятиліттями, незв'язана енергія поволі набуває форми, утворюючи крихітну стихійну істоту незмірної витривалості.",
    ["When fully-grown, a larion that has grown up with an aspirant will never leave his or her master's side."] = "Дорослий ларіон, що виріс поруч з аспірантом, ніколи не покине свого господаря чи господиню.",
    ["When guilds have accumulated enough wealth, brave soldiers are often called to bear their standards."] = "Коли гільдії накопичують достатньо багатства, до них нерідко закликають хоробрих воїнів нести їхні штандарти.",
    ["When he's not hanging out with Harth Stonebrew or winning competitions at the tavern, Sarge loves to stow away in the backpacks of visiting adventurers."] = "Коли Сардж не байдикує з Гартом Камневаром і не виграє змагання в таверні, він любить ховатися в наплічниках заїжджих шукачів пригод.",
    ["When hunting or evading predators, this snake can travel on the surface of water for short distances."] = "Полюючи або тікаючи від хижаків, ця змія може на короткі відстані рухатися по поверхні води.",
    ["When it senses the impending death of a nearby creature, the skull will emit an ear-piercing cackle."] = "Відчувши близьку смерть якоїсь істоти неподалік, череп видає пронизливий регіт.",
    ["When it was captured and bound to a cage made of enchanted metal, this spirit managed to twist and reshape the metal into the suit of armor it now wears."] = "Коли його впіймали й прив'язали до клітки з зачарованого металу, цей дух зумів зігнути й перетворити метал на обладунок, який тепер носить.",
    ["When it was the wind, this spirit carried scents to every corner of Azeroth. Sometimes you can still smell on it the barest hint of food, smoke, or the carnage of battle."] = "Коли він був вітром, цей дух розносив запахи в усі куточки Азерота. Іноді на ньому досі можна вловити ледь помітний натяк на їжу, дим чи бойню битви.",
    ["When newly-hatched, they start with colorless, white feathers. Within weeks, they flourish into a wide spectrum of beautiful colors."] = "Щойно вилупившись, вони мають безбарвне, біле пір'я. За кілька тижнів воно розквітає широким спектром прекрасних барв.",
    ["When not lazily floating down a river, this Timbertooth is fond of snacks and snuggles."] = "Коли не пливе ліниво річкою, цей Деревозуб полюбляє смаколики й обійми.",
    ["When perched on a tree, this species can be almost invisible to any prey."] = "Сидячи на дереві, цей вид стає майже невидимим для будь-якої здобичі.",
    ["When preparing to travel to distant locations, Pandaren will traditionally capture a mirror strider and safely relocate it to another body of water."] = "Готуючись вирушити в далекі краї, пандарени за традицією ловлять дзеркального ступаля й безпечно переселяють його в іншу водойму.",
    ["When prey wanders into this creature's reach, it rarely wanders out."] = "Коли здобич забредає в межі досяжності цього створіння, назад вона забредає рідко.",
    ["When she grows up, Mitzy wants to guide Greatfather Winter's sleigh just like Metzen, her famous dad. Until then, she's more than happy to come with you on your adventures."] = "Коли виросте, Міці хоче правити санями Великого Батька Зими, як Метцен, її славетний тато. А доти вона з радістю вирушить із вами в пригоди.",
    ["When the Burning Legion invaded Outland, Landro Longshot contributed this design to the war effort. Both the Alliance and Horde passed on production."] = "Коли Палаючий Легіон вдерся до Позамежжя, Ландро Далекостріл запропонував цей задум для воєнних потреб. І Альянс, і Орда відмовилися від його втілення.",
    ["When the Bushbeard clan decided they were going to have a wedding, they chose Petal to be the flower girl. She was spectacular."] = "Коли клан Кущоборід вирішив справити весілля, вони обрали Пелюстку дівчинкою з квітами. Вона була незрівнянна.",
    ["When the Naga invaded Stormsong, they brought their favored pets: Abyssal Eels."] = "Коли наги вторглися до Штормової Пісні, вони привели своїх улюблених тваринок — безодняних вугрів.",
    ["When the locusts swarm, you can hear nothing but the sound of their wings."] = "Коли сарана збивається в рій, не чути нічого, крім шуму її крил.",
    ["When the sun shines on its shell just right, the light scatters in a thousand different directions."] = "Коли сонце світить на її мушлю саме так, світло розсипається в тисячу різних напрямків.",
    ["When the village of Pi'jiu was attacked by the Ordon Yaungol generations ago, the villagers bravely erected a keg in the center of the village. The following morning, after the celebration had died down, the still-drunken Yaungol blearily agreed to a peace treaty."] = "Коли покоління тому на село Пі'джю напали яунґоли Ордону, селяни хоробро встановили барило в центрі села. Наступного ранку, коли святкування вщухло, ще п'яні яунґоли каламутно погодилися на мирну угоду.",
    ["When the waves crashed down around the city, not all were fortunate enough to receive N'zoth's gift."] = "Коли хвилі обвалилися на місто, не всім поталанило отримати дарунок Н'зота.",
    ["When the winds blow just right, howling through the canyons of Ardenweald, you can find these foals running with the wind in a spectacular show of prowess and color."] = "Коли вітри дмуть саме так, як треба, завиваючи в каньйонах Арденвельду, можна побачити цих лошат, що мчать із вітром у захопливому видовищі вправності й барв.",
    ["When these creatures stampede, they sound like a thunderstorm. When these creatures stampede in a thunderstorm, they sound like a cataclysm."] = "Коли ці створіння мчать табуном, це звучить як гроза. Коли ці створіння мчать табуном під час грози, це звучить як катаклізм.",
    ["When these insects move in a swarm they look like a golden fog."] = "Коли ці комахи рухаються роєм, вони скидаються на золотавий туман.",
    ["When these sleepy critters aren't snoozing, they use their massive claws to dig for tasty insect snacks."] = "Коли ці сонливі дрібнятка не дрімають, вони своїми величезними кігтями викопують смачні комашині перекуски.",
    ["When they look into those big brown eyes, some hunters have a hard time pulling the trigger. So they shoot from a distance."] = "Зазирнувши в ці великі карі очі, деякі мисливці насилу натискають на гачок. Тому вони стріляють здалеку.",
    ["When this pet is near, calming chimes fill your mind and remind you of a time long passed."] = "Коли цей улюбленець поруч, заспокійливий передзвін наповнює твій розум і нагадує про давно минулі часи.",
    ["When you feel a chill run down your spine, don't be afraid. It's probably just your pet snowlemental."] = "Коли холодок пробіжить по твоїй спині, не лякайся. Це, мабуть, просто твій улюбленець-сніжелементаль.",
    ["When you have two rabbits, you'll often soon have three."] = "Коли в тебе двоє кролів, незабаром нерідко стане троє.",
    ["When you need a hand, you know who to call."] = "Коли потрібна рука допомоги, ти знаєш, кого кликати.",
    ["When you tell a bad joke, he'll be there to let you know."] = "Коли ти розповіси невдалий жарт, він буде поруч, щоб тобі про це сказати.",
    ["When you're a Maldraxxian stitchcrafter and you have to name a lot of abominations, sometimes you just go with the obvious choice."] = "Коли ти малдраксійський зшивач і тобі доводиться давати імена силі-силенній абомінацій, інколи просто береш найочевидніше.",
    ["When you're a hoarder, but want to stay on the move!"] = "Коли ти запасливий, але хочеш лишатися в русі!",
    ["When you're confronting Murkablo or any of the Prime Murlocs, possession of a soulstone is strongly advised."] = "Коли стаєш проти Мурклабо чи будь-кого з Праотчих Мурлоків, мати при собі камінь душі — украй бажано.",
    ["Whenever his forces would experience setbacks in Azeroth, Kil'jaeden would pull out Micronax and terrorize the local cat-like creatures of Argus to vent his frustrations."] = "Щоразу, коли його війська зазнавали невдач на Азероті, Кіл'джеден діставав Мікронакса й тероризував місцевих котоподібних створінь Аргуса, щоб зігнати свою лють.",
    ["Where did it come from, where does it go? Where did you come from, creepy tentacle?"] = "Звідки воно взялося, куди прямує? Звідки ти взялося, моторошне щупальце?",
    ["Where do all of the bubbles come from? What are they made of? Perhaps some mysteries are best left unexplored."] = "Звідки беруться всі ці бульбашки? З чого вони зроблені? Можливо, деякі таємниці краще лишати нерозгаданими.",
    ["Where does a 350-pound viperid sit? Anywhere it wants."] = "Де сидить віперід вагою у 350 фунтів? Де хоче.",
    ["Where some viperids lie in wait for their prey, this variety stalks their intended meals for hours."] = "Якщо деякі віперіди чигають на здобич, то цей різновид годинами вистежує свою майбутню поживу.",
    ["Where there is carrion, there will always be rats."] = "Де є падло, там завжди будуть щури.",
    ["Whereas some moths are attracted to light, this particular moth seems attracted to warm, fuzzy feelings. Some say the phrase \"butterflies in your stomach\" actually refers to an infestation of Heartseeker Moths."] = "Тоді як одних молей вабить світло, цю конкретну міль, схоже, ваблять теплі, ніжні почуття. Дехто каже, що вислів «метелики в животі» насправді стосується зараження Серцешукальними Молями.",
    ["Wherever it goes, it leaves behind a soft glow that stirs hope in even the darkest places"] = "Куди б воно не йшло, лишає по собі м'яке сяйво, що пробуджує надію навіть у найтемніших місцях.",
    ["Whether in life or the afterlife, some things are universal. Nasty blood-sucking insects are one of those things."] = "Що за життя, що в потойбіччі — деякі речі однакові скрізь. Бридкі кровосисні комахи — одна з таких речей.",
    ["While Yogursa managed to survive the blight infesting many of Hillsbrad's ursines, she was driven mad, and her cubs forever tainted."] = "Хоч Йогурса й пережила пошесть, що вразила багатьох ведмедів Гілсбраду, та збожеволіла, а її ведмежата навіки заплямовані.",
    ["While completely harmless to trolls, the animal life within Nazmir fear these creatures."] = "Цілком безпечні для тролів, ці створіння наганяють страх на всю звірину Назміру.",
    ["While each cub is crafted in the same fashion, tiny imperfections in the gemstones create a unique personality when imbued with life.  They are, however, always playful and friendly."] = "Хоча кожне дитинча виготовляють однаково, дрібні вади самоцвітів надають йому неповторної вдачі, щойно в нього вдихнуть життя. Та всі вони завжди грайливі й дружні.",
    ["While fascinated by flowers, the frolicker has also been known to dance with blades of grass and the occasional weed."] = "Хоч пустунчик і зачарований квітами, його бачили й за танцями з травинками, а часом і з бур'янами.",
    ["While larger proto avians are known to feed on small animals, fledglings mostly eat insects and grubs."] = "Хоч більші протоптахи й живляться дрібними тваринами, пташенята здебільшого їдять комах і личинок.",
    ["While many people believe black cats to be bad luck, black rats are held in higher esteem."] = "Хоча багато хто вважає чорних котів за лиху прикмету, до чорних щурів ставляться з більшою шаною.",
    ["While most of the marsuul on Argus feed on fruits, this particular one prefers the juicy crunch of small rodents."] = "Хоча більшість марсуулів на Аргусі живиться плодами, цей надає перевагу соковитому хрускоту дрібних гризунів.",
    ["While napping in shrubbery, sometimes his snaggletooth gets caught on a leaf."] = "Поки він дрімає в кущах, його кривий зуб іноді чіпляється за листок.",
    ["While not as fast as some of the other snails in the Zaralek Cavern, Bashful makes up for it with sheer power."] = "Хоч Сором'язко й не такий швидкий, як деякі інші слимаки в Печері Заралек, він надолужує це чистою силою.",
    ["While not nearly as destructive as its original master, the Ice Lord Ahune, the frostling has been known to lob chilly snowballs at unsuspecting adventurers."] = "Хоч і далеко не такий руйнівний, як його первісний господар, Крижаний Володар Агуне, морозлинятко не проти жбурнути холодними сніжками в необачних шукачів пригод.",
    ["While not viewed as insightful enough to be a Watcher just yet, he's on the lookout for others to share his vision with."] = "Хоч його ще не вважають достатньо проникливим, щоб стати Споглядачем, він видивляється тих, з ким можна було б поділитися своїм баченням.",
    ["While other species of birds take turns leading the flock during migration, the kingfeather always remains in the lead.  Whether this is an effort to help the rest of the flock conserve energy or out of dominance remains unknown."] = "Тоді як інші види птахів по черзі ведуть зграю під час перельоту, королепер завжди лишається попереду. Чи робить він це, щоб решта зграї берегла сили, чи через прагнення панувати — лишається невідомим.",
    ["While purrkin have a knack for getting lost, none have ever been so talented as this one. Purrfectly unbothered however, this curious creature can thrive in any situation."] = "Хоч муркотуни й мають хист губитися, жоден не був таким обдарованим у цьому, як цей. Та, муркочучи без жодних турбот, ця допитлива істота здатна процвітати в будь-якій ситуації.",
    ["While smaller than the infamous ravens of Gilneas, crows are no less clever or cunning."] = "Хоч і менші за горезвісних круків Ґілнеасу, ворони не менш кмітливі й хитрі.",
    ["While stationary, the plains monitor will continuously flick its tail back and forth. From a distance this mimics the appearance of swaying tallgrass, camouflaging the lizard from aerial predators."] = "Нерухомо стоячи, степовий варан безперестанку махає хвостом туди-сюди. Здалеку це нагадує колихання високої трави, маскуючи ящірку від повітряних хижаків.",
    ["While the markets of Tazavesh are a well-oiled machine, the P.O.S.T. service is a whirlwind of parchment, cartons, and rambunctious livestock. The use of P.O.S.T. assistants to handle dangerous material has saved a great many headaches."] = "Хоч ринки Тазавеша — добре налагоджений механізм, служба П.О.Ш.Т.А. — то справжній вир пергаментів, коробок і непокірної худоби. Використання помічників П.О.Ш.Т.А. для роботи з небезпечними матеріалами позбавило багатьох головного болю.",
    ["While their tiny tusks may not help much in a fight, the trunkalumpfs make up for it in sheer weight."] = "Хоч їхні крихітні бивні й не надто помічні в бійці, хоботлумпфи надолужують це самою лиш вагою.",
    ["While there are many similarities to the warpstalkers from Azeroth, evidence suggests they evolved completely independently from one another. Fascinating!"] = "Хоча вони мають чимало спільного зі сферошукачами з Азероту, дані свідчать, що ці види розвивалися цілком незалежно один від одного. Дивовижно!",
    ["While these gormlings may not be the fastest diggers, they are very efficient and can move long distances underground before tiring."] = "Хай ці ґормлінги й не найшвидші копачі, зате надзвичайно витривалі й здатні долати під землею великі відстані, перш ніж стомитися.",
    ["While these tiny mechanical guardians were created to protect domesticated elekks from pests, they also turned out to be really good at giving back massages."] = "Хоч цих крихітних механічних охоронців і створили для захисту приручених елекків від шкідників, вони виявилися ще й чудовими у масажі спини.",
    ["While young, they have an adorable face and cute little antennae. While grown up, they gain razor sharp pinchers and are unstoppable eating machines. Life is full of compromises."] = "Замолоду вони мають чарівну мордочку й милі вусики. А подорослішавши, обзаводяться гострими, мов лезо, клешнями й перетворюються на невпинні машини для поглинання їжі. Що ж, життя складається з компромісів.",
    ["White Brutosaurs were on the brink of extinction until some enterprising adventurers took action. Lil' Ben'fon may have inherited her father's size, but definitely has her mother's temper!"] = "Білі брутозаври були на межі вимирання, доки кілька завзятих шукачів пригод не взялися до справи. Мала Бен'фон, можливо, успадкувала зріст від батька, але вдачу — безперечно від матері!",
    ["Who knew scribes could make kites?"] = "Хто б знав, що писарі вміють робити повітряних зміїв?",
    ["Who knew these things could eat so much?"] = "Хто ж знав, що ці створіння здатні так багато їсти?",
    ["Who makes them? How do they get there? No one knows, except maybe Greatfather Winter."] = "Хто їх робить? Як вони туди потрапляють? Ніхто не знає — хіба що Великий Батько Зими.",
    ["Who needs a toolbelt when a handy robot can follow you around! Just don't bump into it too hard."] = "Навіщо пояс з інструментами, коли за тобою всюди ходить зручний робот! Тільки не штовхай його надто сильно.",
    ["Who would leave such a cute shark behind? The Iron Horde truly has no soul."] = "Хто б покинув таку милу акулу? У Залізної Орди й справді немає душі.",
    ["Who's ready for a hot stone massage?"] = "Хто готовий до масажу гарячим камінням?",
    ["Who's the cutest little monster? You are!"] = "Хто тут наймиліше монстреня? Ти!",
    ["Why do bunnies lay eggs?"] = "Чому ж кролики несуть яйця?",
    ["Why is it called a nursery spider? Does it prefer to lurk in nurseries? Why would it do that? What does it do there? Oh, dear! Someone check on the kids!"] = "Чому його звуть павуком-дитсадком? Невже він полюбляє ховатися в дитячих кімнатах? Навіщо йому це? Що він там робить? Ой лишенько! Хай хтось гляне, чи з дітьми все гаразд!",
    ["Widely prized as pets, cerulean lapbugs were thought to bring good fortune."] = "Лазурових колінцежуків високо цінували як улюбленців, бо вірили, що вони приносять удачу.",
    ["Widow spiderlings have plenty of time to explore Duskwood once they take care of their pesky family commitments."] = "Павучата-вдовенята мають доволі часу досліджувати Сутінковий Ліс, щойно владнають свої набридливі родинні справи.",
    ["Wild marsh walkers are dangerously aggressive, but they're loyal and affectionate if you manage to tame them."] = "Дикі болотні ходаки небезпечно агресивні, та якщо їх приборкати, вони стають вірними й лагідними.",
    ["Wild sporebats are vicious creatures, but if tamed at a young age, they can be loyal companions."] = "Дикі спорокажани — люті створіння, та якщо приручити їх замолоду, вони можуть стати вірними супутниками.",
    ["Wildhammer dwarves train young gryphons by sending them out to hunt rattlesnakes in the Twilight Highlands."] = "Дворфи Дикомолота навчають молодих грифонів, посилаючи їх полювати на гримучих змій у Сутінковому Нагір'ї.",
    ["Will only lay eggs in bright light."] = "Відкладає яйця лише при яскравому світлі.",
    ["Winter festivities seem to follow Eve wherever she goes."] = "Зимові гуляння, схоже, ходять за Їв, куди б вона не подалася.",
    ["Winterspring cubs are happiest when frolicking in freshly fallen snow."] = "Зимовоключні ведмежата найщасливіші тоді, коли пустують у свіжому снігу.",
    ["Winterspring's furbolg prize the brilliant white feathers of these majestic creatures for ritual purposes."] = "Фурболґи Зимовоснігів'я цінують сліпучо-біле пір'я цих величних створінь для своїх ритуалів.",
    ["With Korthia torn asunder by the Jailer, the few species that remain must be archived."] = "Відколи Тюремник пошматував Кортію, ті нечисленні види, що лишилися, треба заархівувати.",
    ["With a face this lovable Wuffi is sure you'll wind-up being the best of friends."] = "З таким милим личком Вуффі певен, що ви станете найкращими друзями.",
    ["With a nose for secrets, Tobias is ready to be by the side of super sleuths."] = "З нюхом на таємниці Тобіас готовий бути поруч із суперслідцями.",
    ["With boundless energy and unbridled enthusiasm, the foal seeks the skies. It may not be ready, but exercise caution if you try to hold it back."] = "З безмежною енергією та нестримним завзяттям лоша рветься в небо. Можливо, воно ще не готове, та будь обережний, якщо спробуєш його стримати.",
    ["With claws that can crush a platemail gauntlet, it's best to handle with care."] = "З клешнями, здатними розчавити латну рукавицю, краще поводитися обережно.",
    ["With enough of your love, and tiny milk bottles, she will grow strong enough to rejoin the wild."] = "За досить твоєї любові й крихітних пляшечок молока вона виросте достатньо сильною, щоб вернутися в дику природу.",
    ["With her distinctive coloration and impeccable work ethic, Pinkie has propelled herself to the top of the tallstrider fashion world."] = "Завдяки прикметному забарвленню та бездоганній працьовитості Пінкі вибилася на вершину світу моди довгоступів.",
    ["With the extra large surface area of their legs, snowshoe hares are able to effortlessly hop along the snow while their pursuers get bogged down in the drifts."] = "Завдяки особливо широким лапам біляки легко стрибають по снігу, тоді як їхні переслідувачі грузнуть у заметах.",
    ["With war paint on her fur and a growl in her belly, Naloki dreams of one day roaring like Nalorakk."] = "З бойовим розмалюванням на хутрі й гарчанням у животі Налокі мріє колись ревіти так, як Налоракк.",
    ["Woah there pardner. Were you really about to buzz by without saying howdy?"] = "Гей, повільніше, друже. Ти справді збирався прожужжати повз, не привітавшись?",
    ["Wood wasps make nests in dead or hollowed out trees, and are quick to attack anything that threatens their home."] = "Деревні оси будують гнізда в мертвих чи дуплистих деревах і вмить нападають на все, що загрожує їхній домівці.",
    ["Worgs are the favored companions of orcs and are fiercely loyal on the battlefield."] = "Ворги — улюблені супутники орків, які виявляють люту відданість на полі бою.",
    ["Worm Facts"] = "Факти про червів",
    ["Would rather not spend any more time inside a wrapped holiday gift box."] = "Воліло б не проводити більше ні хвилини в загорнутій святковій подарунковій коробці.",
    ["Wyvern whelps are sleepy by nature. The dreams of wyvern whelps are doubly so."] = "Дитинчата віверн сонливі від природи. Сни дитинчат віверн — удвічі сонливіші.",
    ["Xan'tish fearlessly tracks, captures, and trains these noble snakes so they will aid their comrades in battle."] = "Ксан'тіш безстрашно вистежує, ловить і навчає цих шляхетних змій, щоб вони допомагали товаришам у бою.",
    ["Years ago, humans introduced these reptiles into Duskwood to cull the local rat population."] = "Багато років тому люди завезли цих рептилій до Сутінкового Лісу, щоб зменшити місцеву популяцію щурів.",
    ["Yellow Tropical Frog"] = "Жовта тропічна жаба",
    ["Yellow maidenbugs are often mistaken for other yellow insects. This happens even more often to Beetriz, and she doesn't understand why."] = "Жовтих панянок-жучків часто плутають з іншими жовтими комахами. З Бітриз таке трапляється ще частіше, і вона не розуміє чому.",
    ["Yes boss! Yes boss! Yes boss!"] = "Так, бос! Так, бос! Так, бос!",
    ["You better believe he knows what time it is."] = "Можеш не сумніватися: він знає, котра година.",
    ["You can easily locate moths if you wear expensive garments near Ammen Vale. They can't resist the delicious taste of high fashion."] = "Молей легко знайти, якщо вбратися в дороге вбрання поблизу Долу Аммен. Вони не можуть встояти перед смаковитим присмаком високої моди.",
    ["You can identify the cruelest and most vicious of the brood by their reddish hue."] = "Найжорстокіших і найлютіших із виводка можна впізнати за червонястим відтінком.",
    ["You can never have too many fish according to May."] = "На думку Мей, риби забагато не буває.",
    ["You got spinebugged!"] = "Тебе хребтожуком закусали!",
    ["You have never met a pet that is more about chewing."] = "Ти ще ніколи не зустрічав улюбленця, для якого жування важило б більше.",
    ["You have the odd feeling that it wants to kill you."] = "Тебе не полишає дивне відчуття, ніби воно хоче тебе вбити.",
    ["You know how disappointing it is when you return to your beverage and the ice has all melted? This guy's fault."] = "Знаєш, як прикро повернутися до свого напою й виявити, що лід увесь розтанув? Це його провина.",
    ["You met this Slyvern next week from your point of view, but last year from its point of view."] = "З твого погляду, ти зустрів цього слайверна наступного тижня, а з його погляду — торік.",
    ["You might think this fish out of water would be a weak opponent... until you see the intensity that lies within its protective bubble."] = "Можна подумати, що ця риба без води — слабкий супротивник... доки не побачиш, яка лють криється в її захисній бульбашці.",
    ["You saved him, but maybe he saved you."] = "Ти врятував його, та, можливо, це він урятував тебе.",
    ["You stare at her, and she just stares right back. So clever; sometimes it seems as if she's figuring out how to open doors."] = "Ти витріщаєшся на неї, а вона просто витріщається у відповідь. Така кмітлива, що часом здається, ніби вона міркує, як відчиняти двері.",
    ["You wouldn't want to meet this rat in a dark alley. Or anywhere else, for that matter."] = "Ви б не хотіли зустріти цього щура в темному провулку. Та й деінде, як на те пішло.",
    ["You'd think with all those spikes, it might pop its own pustule sac. But no! Its pustule sac is actually really sturdy! Pustule sac!"] = "Здавалося б, з усіма цими шипами воно мало б проколоти власний гнійний міхур. Та ні! Його гнійний міхур насправді доволі міцний! Гнійний міхур!",
    ["You'll always feel like... something is watching you."] = "Тобі завжди здаватиметься... що хтось за тобою стежить.",
    ["You'll find him in his shell, exactly where a snail has to be!"] = "Знайдеш його в мушлі — саме там, де й має бути слимак!",
    ["You'll often find them perched high atop impossibly high and remote stone outcroppings. There are few creatures as sure of foot."] = "Їх часто можна побачити на неймовірно високих і відлеглих кам'яних виступах. Мало хто зі створінь ступає так упевнено.",
    ["You're not entirely sure where this came from, nor do you really want to know, but you are sure that it does eat a tremendous amount of garbage."] = "Ти не зовсім певен, звідки воно взялося, та й не дуже хочеш знати, але ти впевнений, що воно поглинає неймовірну кількість сміття.",
    ["Young apes quickly learn to hang from branches with their feet, leaving both hands free to fling objects at interlopers."] = "Молоді мавпи швидко вчаться звисати з гілок на ногах, щоб обидві руки лишалися вільними кидати всячиною в непроханих гостей.",
    ["Young bone serpents will try to burrow into a living creature's skull and devour their brain.  So you may want to wear a night cap."] = "Молоді кістяні змії намагаються вгризтися в череп живої істоти й пожерти її мозок. Тож, мабуть, варто вдягати нічний ковпак.",
    ["Young gazelles quickly learn to flee when they hear the war cries of tauren hunters in Mulgore.  They don't hear the good hunters, unfortunately."] = "Молоді газелі швидко вчаться тікати, зачувши бойові кличі таврених мисливців у Малґорі. На жаль, добрих мисливців вони не чують.",
    ["Young grovecrawlers are known to curl up around the ankles of its protectors for rest."] = "Молоді гайоповзи зазвичай згортаються калачиком біля кісточок своїх захисників, щоб відпочити.",
    ["Young protorams love to play and bluff charge. They also love to actually charge."] = "Юні протобарани люблять гратися й удавати, ніби нападають. Ще вони люблять нападати по-справжньому.",
    ["Young teroclaws are surprisingly effective hunters and will attempt to bring down prey up to twice their size."] = "Молоді тероклігті — напрочуд вправні мисливці й намагаються завалити здобич удвічі більшу за себе.",
    ["Younger brother to Anax.  Big brother to Cenax and Denax."] = "Молодший брат Анакса. Старший брат Сенакса й Денакса.",
    ["|cFFFFD200Achievement: |rA Champion's Tour: The War Within|n|cFFFFD200Category: |rWorld"] = "|cFFFFD200Досягнення: |rТур чемпіона: The War Within|n|cFFFFD200Категорія: |rСвіт",
    ["|cFFFFD200Achievement: |rA Sly Fox|n|cFFFFD200Category: |rCollect"] = "|cFFFFD200Досягнення: |rХитрий лис|n|cFFFFD200Категорія: |rКолекціонування",
    ["|cFFFFD200Achievement: |rAbhorrent Adversaries of the Afterlife|n|cFFFFD200Category: |rBattle"] = "|cFFFFD200Досягнення: |rОгидні супротивники потойбіччя|n|cFFFFD200Категорія: |rБій",
    ["|cFFFFD200Achievement: |rBattle Safari|n|cFFFFD200Category: |rCollect"] = "|cFFFFD200Досягнення: |rБойове сафарі|n|cFFFFD200Категорія: |rКолекціонування",
    ["|cFFFFD200Achievement: |rBig Rocketeer: Gold|n|cFFFFD200Category: |rDarkmoon Faire"] = "|cFFFFD200Досягнення: |rВеликий ракетник: золото|n|cFFFFD200Категорія: |rЯрмарок Самоцвітного Місяця",
    ["|cFFFFD200Achievement: |rBounty Seeker\n|cFFFFD200Category: |rWar Within"] = "|cFFFFD200Досягнення: |rМисливець за винагородою\n|cFFFFD200Категорія: |rВійна Всередині",
    ["|cFFFFD200Achievement: |rBroken Isles Safari|n|cFFFFD200Category: |rCollect"] = "|cFFFFD200Досягнення: |rСафарі на Розламаних Островах|n|cFFFFD200Категорія: |rЗбирання",
